-- SRV7 W05d: repeated seasonal windows extend the existing event reply.
-- Retain all immutable receipts; the additive codec accepts their absent field 4.
ALTER TABLE game_world_event_query_receipts
    DROP CONSTRAINT game_world_event_query_receipts_result_check,
    ADD CONSTRAINT game_world_event_query_receipts_result_check
        CHECK (octet_length(result) <= 260);

-- SRV7 W05d: the specific A Piece of Cake World occurrence. Event dates are
-- source content; no client command or table installation starts an occurrence.
CREATE TABLE game_seasonal_cake_worlds (
    world_id UUID NOT NULL CHECK (game_node_is_uuid_v7(world_id)),
    event_start BIGINT NOT NULL CHECK (event_start > 0),
    event_end BIGINT NOT NULL CHECK (event_end > event_start),
    state JSONB NOT NULL CHECK (jsonb_typeof(state) = 'object' AND octet_length(state::text) <= 8192),
    PRIMARY KEY (world_id, event_start)
);

-- The exact current native creature occurrence, never a client-provided count.
CREATE TABLE game_seasonal_cake_extractions (
    world_id UUID NOT NULL,
    event_start BIGINT NOT NULL,
    source_occurrence BYTEA NOT NULL CHECK (octet_length(source_occurrence) = 32),
    extracted_at BIGINT NOT NULL CHECK (extracted_at >= event_start),
    counted BOOLEAN NOT NULL,
    PRIMARY KEY (world_id, event_start, source_occurrence),
    FOREIGN KEY (world_id, event_start) REFERENCES game_seasonal_cake_worlds
);

-- Global physical cake identity prevents the same square counting twice across
-- Channels. The specific event owner restores/retains tiles as its window closes.
CREATE TABLE game_seasonal_cake_tiles (
    world_id UUID NOT NULL,
    event_start BIGINT NOT NULL,
    layer SMALLINT NOT NULL CHECK (layer BETWEEN 1 AND 4),
    x INTEGER NOT NULL CHECK (x BETWEEN 33287 AND 33330),
    y INTEGER NOT NULL CHECK (y BETWEEN 32065 AND 32103),
    floor SMALLINT NOT NULL CHECK (floor = 7),
    appearance INTEGER NOT NULL CHECK (appearance IN (12085, 12086)),
    window_start BIGINT NOT NULL CHECK (window_start >= event_start),
    removed BOOLEAN NOT NULL,
    PRIMARY KEY (world_id, event_start, layer, x, y, floor),
    FOREIGN KEY (world_id, event_start) REFERENCES game_seasonal_cake_worlds
);

REVOKE ALL ON game_seasonal_cake_worlds, game_seasonal_cake_extractions, game_seasonal_cake_tiles FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON game_seasonal_cake_worlds, game_seasonal_cake_tiles TO oteryn_game_runtime;
GRANT SELECT, INSERT ON game_seasonal_cake_extractions TO oteryn_game_runtime;
GRANT SELECT ON game_seasonal_cake_worlds, game_seasonal_cake_extractions, game_seasonal_cake_tiles TO oteryn_game_control;

-- SRV7 W05d Cake character errand: per occurrence, five distinct city marks and two claims.
CREATE TABLE game_seasonal_cake_characters (
    character_id UUID NOT NULL REFERENCES game_character_roots(character_id),
    world_id UUID NOT NULL,
    event_start BIGINT NOT NULL,
    started BOOLEAN NOT NULL DEFAULT false,
    isle_armed BOOLEAN NOT NULL DEFAULT false,
    visited_cities SMALLINT NOT NULL DEFAULT 0 CHECK (visited_cities BETWEEN 0 AND 31),
    item_reward_given BOOLEAN NOT NULL DEFAULT false,
    cupcake_reward_given BOOLEAN NOT NULL DEFAULT false,
    PRIMARY KEY(character_id, world_id, event_start),
    FOREIGN KEY(world_id,event_start) REFERENCES game_seasonal_cake_worlds(world_id,event_start),
    CHECK (NOT (item_reward_given OR cupcake_reward_given) OR visited_cities=31)
);
CREATE INDEX game_seasonal_cake_characters_world ON game_seasonal_cake_characters(world_id,event_start);
CREATE TABLE game_seasonal_cake_character_receipts (
    character_id UUID NOT NULL REFERENCES game_character_roots(character_id),
    occurrence BYTEA NOT NULL CHECK (octet_length(occurrence)=32),
    binding BYTEA NOT NULL CHECK (octet_length(binding)=32),
    result JSONB NOT NULL CHECK (jsonb_typeof(result)='object' AND octet_length(result::text)<=2048),
    PRIMARY KEY(character_id,occurrence)
);
REVOKE ALL ON game_seasonal_cake_characters, game_seasonal_cake_character_receipts FROM PUBLIC;
GRANT SELECT,INSERT,UPDATE ON game_seasonal_cake_characters TO oteryn_game_runtime;
GRANT SELECT,INSERT ON game_seasonal_cake_character_receipts TO oteryn_game_runtime;
GRANT SELECT ON game_seasonal_cake_characters, game_seasonal_cake_character_receipts TO oteryn_game_control;

-- BEGIN SRV7 closed carried costs (root owner).
CREATE TABLE game_srv7_item_costs (
 transaction_id UUID PRIMARY KEY CHECK(game_character_is_uuid_v7(transaction_id)),
 event_id UUID NOT NULL UNIQUE CHECK(game_character_is_uuid_v7(event_id)),
 game_session_id UUID NOT NULL REFERENCES game_durability_reconnect_sessions,
 command_id NUMERIC(20,0) NOT NULL CHECK(command_id BETWEEN 1 AND 18446744073709551615),
 character_id UUID NOT NULL REFERENCES game_character_roots,
 world_id UUID NOT NULL,
 channel_id UUID NOT NULL,
 connection_generation NUMERIC(20,0) NOT NULL CHECK(connection_generation>0),
 lease_generation NUMERIC(20,0) NOT NULL CHECK(lease_generation>0),
 scope_generation NUMERIC(20,0) NOT NULL CHECK(scope_generation>0),
 cause_kind TEXT NOT NULL CHECK(cause_kind IN ('npc_cosmetic','cake_substance')),
 source_key TEXT NOT NULL CHECK(octet_length(source_key) BETWEEN 1 AND 256),
 requirements JSONB NOT NULL CHECK(jsonb_typeof(requirements)='array' AND jsonb_array_length(requirements) BETWEEN 1 AND 16),
 inputs JSONB NOT NULL CHECK(jsonb_typeof(inputs)='array' AND jsonb_array_length(inputs) BETWEEN 1 AND 500 AND octet_length(inputs::text)<=1048576),
 occurred_at BIGINT NOT NULL CHECK(occurred_at>0),
 proof_sha256 BYTEA NOT NULL CHECK(octet_length(proof_sha256)=32),
 created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),
 UNIQUE(game_session_id,command_id,cause_kind)
);
CREATE INDEX game_srv7_item_costs_character ON game_srv7_item_costs(character_id);
CREATE INDEX game_srv7_item_costs_xact ON game_srv7_item_costs(created_xact_id);
CREATE TRIGGER game_srv7_item_costs_immutable BEFORE UPDATE OR DELETE ON game_srv7_item_costs
 FOR EACH ROW EXECUTE FUNCTION game_world_reset_history_immutable();
REVOKE ALL ON game_srv7_item_costs FROM PUBLIC;
GRANT SELECT,INSERT ON game_srv7_item_costs TO oteryn_game_runtime;
GRANT SELECT ON game_srv7_item_costs TO oteryn_game_control;
-- END SRV7 closed carried costs schema. Guard extension follows after regression RED.

-- SRV7 W05d: personal bite counters are distinct from the Brutus errand.
CREATE TABLE game_seasonal_cake_bites (
    character_id UUID NOT NULL REFERENCES game_character_roots,
    world_id UUID NOT NULL,
    event_start BIGINT NOT NULL,
    window_start BIGINT NOT NULL CHECK (window_start >= event_start),
    bites SMALLINT NOT NULL CHECK (bites BETWEEN 0 AND 12),
    last_bite BIGINT NOT NULL CHECK (last_bite >= event_start),
    PRIMARY KEY (character_id, world_id, event_start),
    FOREIGN KEY (world_id, event_start) REFERENCES game_seasonal_cake_worlds
);
CREATE INDEX game_seasonal_cake_bites_world ON game_seasonal_cake_bites(world_id,event_start);

CREATE TABLE game_seasonal_cake_deliveries (
    game_session_id UUID NOT NULL REFERENCES game_durability_reconnect_sessions,
    command_id NUMERIC(20,0) NOT NULL CHECK (command_id BETWEEN 1 AND 18446744073709551615),
    character_id UUID NOT NULL REFERENCES game_character_roots,
    world_id UUID NOT NULL,
    event_start BIGINT NOT NULL,
    cost_transaction_id UUID NOT NULL UNIQUE REFERENCES game_srv7_item_costs,
    binding BYTEA NOT NULL CHECK (octet_length(binding) = 32),
    result JSONB NOT NULL CHECK (jsonb_typeof(result) = 'object' AND octet_length(result::text) <= 1024),
    created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),
    PRIMARY KEY (game_session_id, command_id),
    FOREIGN KEY (world_id, event_start) REFERENCES game_seasonal_cake_worlds
);
CREATE INDEX game_seasonal_cake_deliveries_character ON game_seasonal_cake_deliveries(character_id);
CREATE INDEX game_seasonal_cake_deliveries_world ON game_seasonal_cake_deliveries(world_id,event_start);
CREATE TRIGGER game_seasonal_cake_deliveries_immutable BEFORE UPDATE OR DELETE ON game_seasonal_cake_deliveries
    FOR EACH ROW EXECUTE FUNCTION game_world_reset_history_immutable();
REVOKE ALL ON game_seasonal_cake_bites, game_seasonal_cake_deliveries FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON game_seasonal_cake_bites TO oteryn_game_runtime;
GRANT SELECT, INSERT ON game_seasonal_cake_deliveries TO oteryn_game_runtime;
GRANT SELECT ON game_seasonal_cake_bites, game_seasonal_cake_deliveries TO oteryn_game_control;

-- SRV7 S06: current-World NPC acquisition uses the existing Character revision
-- chain and global quest tracks. These immutable receipts do not grant live
-- session authority; the writer separately proves its current gameplay fence.
CREATE TABLE game_npc_cosmetic_receipts (
    transaction_id UUID PRIMARY KEY CHECK(game_character_is_uuid_v7(transaction_id)),
    character_id UUID NOT NULL REFERENCES game_character_roots(character_id) ON DELETE CASCADE,
    account_id UUID NOT NULL,
    game_session_id UUID NOT NULL REFERENCES game_durability_reconnect_sessions(game_session_id),
    command_id NUMERIC(20,0) NOT NULL CHECK(command_id BETWEEN 1 AND 18446744073709551615),
    npc_key TEXT NOT NULL CHECK(npc_key IN('oteryn:npc.amber','oteryn:npc.norma','oteryn:npc.tom','oteryn:npc.cledwyn','oteryn:npc.kesar_the_younger_day')),
    source_key TEXT NOT NULL CHECK(octet_length(source_key) BETWEEN 1 AND 256),
    request_binding BYTEA NOT NULL CHECK(octet_length(request_binding)=32),
    outcome JSONB NOT NULL CHECK(jsonb_typeof(outcome)='object' AND octet_length(outcome::text)<=8192),
    track_changes JSONB NOT NULL CHECK(jsonb_typeof(track_changes)='array' AND jsonb_array_length(track_changes)<=8),
    grant_keys TEXT[] NOT NULL CHECK(cardinality(grant_keys)<=1),
    cost_transaction_id UUID UNIQUE REFERENCES game_srv7_item_costs(transaction_id),
    original_character_revision NUMERIC(20,0) NOT NULL CHECK(original_character_revision>=1),
    committed_character_revision NUMERIC(20,0) NOT NULL CHECK(committed_character_revision=original_character_revision+1 AND committed_character_revision<=18446744073709551615),
    level_before BIGINT NOT NULL,
    level_after BIGINT NOT NULL CHECK(level_after=level_before),
    experience_before BIGINT NOT NULL,
    experience_after BIGINT NOT NULL CHECK(experience_after=experience_before),
    profile_revision TEXT NOT NULL, ruleset_revision TEXT NOT NULL, content_revision TEXT NOT NULL,
    simulation_revision TEXT NOT NULL, evidence_revision TEXT NOT NULL,
    declaration_revision TEXT NOT NULL, policy_revision TEXT NOT NULL, reward_revision TEXT NOT NULL,
    created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),
    UNIQUE(game_session_id,command_id),
    UNIQUE(character_id,committed_character_revision)
);
REVOKE ALL ON game_npc_cosmetic_receipts FROM PUBLIC;
GRANT SELECT,INSERT ON game_npc_cosmetic_receipts TO oteryn_game_runtime;
GRANT SELECT ON game_npc_cosmetic_receipts TO oteryn_game_control;
CREATE TRIGGER game_npc_cosmetic_immutable BEFORE UPDATE OR DELETE ON game_npc_cosmetic_receipts
    FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_npc_cosmetic_no_truncate BEFORE TRUNCATE ON game_npc_cosmetic_receipts
    FOR EACH STATEMENT EXECUTE FUNCTION game_character_reject_truncate();
CREATE TRIGGER game_npc_cosmetic_stamp BEFORE INSERT ON game_npc_cosmetic_receipts
    FOR EACH ROW EXECUTE FUNCTION game_item_stamp_created_xact_id();
CREATE CONSTRAINT TRIGGER game_npc_cosmetic_character_chain AFTER INSERT ON game_npc_cosmetic_receipts
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_character_progression_consistency_guard();

-- Append to the already accepted chain rather than replacing any source arm.
DO $migration$
DECLARE definition TEXT;
BEGIN
    definition:=rtrim(pg_get_viewdef('game_character_hazard_revision_chain'::regclass,true), E';\n ');
    EXECUTE 'CREATE OR REPLACE VIEW game_character_hazard_revision_chain WITH (security_invoker=true) AS '
        ||definition||' UNION ALL SELECT character_id,original_character_revision,committed_character_revision,'
        ||'level_before,level_after,experience_before,experience_after,profile_revision,ruleset_revision,'
        ||'content_revision,simulation_revision,evidence_revision,declaration_revision,policy_revision,reward_revision '
        ||'FROM game_npc_cosmetic_receipts';
END $migration$;

CREATE FUNCTION game_npc_cosmetic_receipt_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE change JSONB; grant_key TEXT; expected JSONB; actual JSONB;
BEGIN
    IF NEW.created_xact_id<>pg_current_xact_id()
        OR NOT EXISTS(SELECT 1 FROM game_character_roots r WHERE r.character_id=NEW.character_id
            AND r.account_id=NEW.account_id AND r.character_revision=NEW.committed_character_revision)
        OR (SELECT count(DISTINCT c->>'key') FROM jsonb_array_elements(NEW.track_changes) c)
            <>jsonb_array_length(NEW.track_changes) THEN
        RAISE EXCEPTION 'NPC cosmetic receipt lacks current Character transition' USING ERRCODE='23514';
    END IF;
    IF NEW.npc_key IS DISTINCT FROM (CASE split_part(NEW.source_key,'/',2)
        WHEN 'amber' THEN 'oteryn:npc.amber'
        WHEN 'norma' THEN 'oteryn:npc.norma'
        WHEN 'tom' THEN 'oteryn:npc.tom'
        WHEN 'cledwyn' THEN 'oteryn:npc.cledwyn'
        WHEN 'kesar' THEN 'oteryn:npc.kesar_the_younger_day' ELSE NULL END) THEN
        RAISE EXCEPTION 'NPC cosmetic source names another NPC' USING ERRCODE='23514';
    END IF;
    IF NEW.grant_keys IS DISTINCT FROM (CASE NEW.source_key
        WHEN 'oteryn:npc-cosmetic/amber/finish' THEN ARRAY['oteryn:appearance-grant/npc/amber/citizen/addon1']
        WHEN 'oteryn:npc-cosmetic/norma/finish' THEN ARRAY['oteryn:appearance-grant/npc/norma/citizen/addon2']
        WHEN 'oteryn:npc-cosmetic/tom/finish' THEN ARRAY['oteryn:appearance-grant/npc/tom/druid/addon1']
        WHEN 'oteryn:npc-cosmetic/cledwyn/addon1' THEN ARRAY['oteryn:appearance-grant/npc/cledwyn/rift_warrior/addon1']
        WHEN 'oteryn:npc-cosmetic/cledwyn/addon2' THEN ARRAY['oteryn:appearance-grant/npc/cledwyn/rift_warrior/addon2']
        WHEN 'oteryn:npc-cosmetic/kesar/council' THEN ARRAY['oteryn:appearance-grant/npc/kesar_the_younger_day/royal_bounacean_advisor/addon2']
        ELSE ARRAY[]::text[] END) THEN
        -- Equivalent existing grants may complete free quest progress without a
        -- second entitlement; paid exchanges always require their exact grant.
        IF NEW.grant_keys<>ARRAY[]::text[] OR NEW.source_key NOT IN
            ('oteryn:npc-cosmetic/amber/finish','oteryn:npc-cosmetic/kesar/council') THEN
            RAISE EXCEPTION 'NPC cosmetic source has another grant' USING ERRCODE='23514';
        END IF;
    END IF;
    expected:=CASE NEW.source_key
        WHEN 'oteryn:npc-cosmetic/amber/start' THEN '{"oteryn:quest-progress/quest/u7_8/citizen_outfits_rook/addon_backpack_rook":1,"oteryn:quest-progress/quest/u7_8/citizen_outfits_rook/mission_backpack_rook":1,"oteryn:quest-progress/outfit_quest/ref":null}'::jsonb
        WHEN 'oteryn:npc-cosmetic/amber/hand-in' THEN '{"oteryn:quest-progress/quest/u7_8/citizen_outfits_rook/addon_backpack_rook":2,"oteryn:quest-progress/quest/u7_8/citizen_outfits_rook/mission_backpack_rook":2,"oteryn:quest-progress/quest/u7_8/citizen_outfits_rook/addon_backpack_rook_timer":null}'::jsonb
        WHEN 'oteryn:npc-cosmetic/amber/finish' THEN '{"oteryn:quest-progress/quest/u7_8/citizen_outfits_rook/addon_backpack_rook":3,"oteryn:quest-progress/quest/u7_8/citizen_outfits_rook/mission_backpack_rook":4,"oteryn:quest-progress/outfit_quest/ref":null}'::jsonb
        WHEN 'oteryn:npc-cosmetic/norma/start' THEN '{"oteryn:quest-progress/quest/u7_8/citizen_outfits_rook/addon_hat_rook":1,"oteryn:quest-progress/quest/u7_8/citizen_outfits_rook/mission_hat_rook":1}'::jsonb
        WHEN 'oteryn:npc-cosmetic/norma/finish' THEN '{"oteryn:quest-progress/quest/u7_8/citizen_outfits_rook/addon_hat_rook":2,"oteryn:quest-progress/quest/u7_8/citizen_outfits_rook/mission_hat_rook":0}'::jsonb
        WHEN 'oteryn:npc-cosmetic/tom/start' THEN '{"oteryn:quest-progress/quest/u7_8/druid_outfits_rook/druid_body_addon_rook":1}'::jsonb
        WHEN 'oteryn:npc-cosmetic/tom/finish' THEN '{"oteryn:quest-progress/quest/u7_8/druid_outfits_rook/druid_body_addon_rook":2}'::jsonb
        WHEN 'oteryn:npc-cosmetic/cledwyn/addon1' THEN '{}'::jsonb
        WHEN 'oteryn:npc-cosmetic/cledwyn/addon2' THEN '{}'::jsonb
        WHEN 'oteryn:npc-cosmetic/kesar/council' THEN '{"oteryn:quest-progress/crystalserver/quest/u15_20/the_order_of_the_stag/kings_council":1}'::jsonb
        ELSE NULL END;
    SELECT COALESCE(jsonb_object_agg(c->>'key',c->'after'),'{}'::jsonb) INTO actual
        FROM jsonb_array_elements(NEW.track_changes) c;
    IF expected IS NULL OR (SELECT array_agg(k ORDER BY k COLLATE "C") FROM jsonb_object_keys(expected) k)
        IS DISTINCT FROM (SELECT array_agg(k ORDER BY k COLLATE "C") FROM jsonb_object_keys(actual) k)
        OR EXISTS(SELECT 1 FROM jsonb_each(expected) e
            WHERE e.value<>'null'::jsonb AND actual->e.key IS DISTINCT FROM e.value) THEN
        RAISE EXCEPTION 'NPC cosmetic source did not write its full donor transition' USING ERRCODE='23514';
    END IF;
    expected:=CASE NEW.source_key
        WHEN 'oteryn:npc-cosmetic/amber/hand-in' THEN '[{"family":"Item","key":"oteryn:item.tibia.i5878","count":100}]'::jsonb
        WHEN 'oteryn:npc-cosmetic/norma/finish' THEN '[{"family":"Item","key":"oteryn:item.tibia.i3374","count":1},{"family":"Item","key":"oteryn:item.tibia.i5890","count":100},{"family":"Item","key":"oteryn:item.tibia.i5902","count":50}]'::jsonb
        WHEN 'oteryn:npc-cosmetic/tom/finish' THEN '[{"family":"Item","key":"oteryn:item.tibia.i5896","count":50},{"family":"Item","key":"oteryn:item.tibia.i5897","count":50}]'::jsonb
        WHEN 'oteryn:npc-cosmetic/cledwyn/addon1' THEN '[{"family":"Item","key":"oteryn:item.tibia.i22516","count":100}]'::jsonb
        WHEN 'oteryn:npc-cosmetic/cledwyn/addon2' THEN '[{"family":"Item","key":"oteryn:item.tibia.i22516","count":100}]'::jsonb
        WHEN 'oteryn:npc-cosmetic/amber/start' THEN '[]'::jsonb
        WHEN 'oteryn:npc-cosmetic/amber/finish' THEN '[]'::jsonb
        WHEN 'oteryn:npc-cosmetic/norma/start' THEN '[]'::jsonb
        WHEN 'oteryn:npc-cosmetic/tom/start' THEN '[]'::jsonb
        WHEN 'oteryn:npc-cosmetic/kesar/council' THEN '[]'::jsonb
        ELSE NULL END;
    IF expected IS NULL OR (expected='[]'::jsonb)<>(NEW.cost_transaction_id IS NULL) THEN
        RAISE EXCEPTION 'NPC cosmetic source has the wrong cost boundary' USING ERRCODE='23514';
    END IF;
    IF NEW.cost_transaction_id IS NOT NULL AND NOT EXISTS(
        SELECT 1 FROM game_srv7_item_costs c WHERE c.transaction_id=NEW.cost_transaction_id
            AND c.character_id=NEW.character_id AND c.game_session_id=NEW.game_session_id
            AND c.command_id=NEW.command_id AND c.source_key=NEW.source_key
            AND c.cause_kind='npc_cosmetic'
            AND c.created_xact_id=pg_current_xact_id()) THEN
        RAISE EXCEPTION 'NPC cosmetic cost is not its same-transaction source' USING ERRCODE='23514';
    END IF;
    IF NEW.cost_transaction_id IS NOT NULL THEN
        SELECT jsonb_agg(jsonb_build_object('family',r->>'family','key',r->>'key','count',(r->>'count')::bigint)
            ORDER BY r->>'key' COLLATE "C") INTO actual
            FROM game_srv7_item_costs c,LATERAL jsonb_array_elements(c.requirements) r
            WHERE c.transaction_id=NEW.cost_transaction_id;
        IF actual IS DISTINCT FROM expected THEN
            RAISE EXCEPTION 'NPC cosmetic source did not pay its exact donor item counts' USING ERRCODE='23514';
        END IF;
    END IF;
    FOR change IN SELECT value FROM jsonb_array_elements(NEW.track_changes) LOOP
        IF NOT EXISTS(SELECT 1 FROM game_character_quest_tracks t
            WHERE t.character_id=NEW.character_id AND t.track_key=change->>'key'
                AND t.quest_key=change->>'quest' AND t.value=(change->>'after')::bigint
                AND t.committed_character_revision=NEW.committed_character_revision) THEN
            RAISE EXCEPTION 'NPC cosmetic track lost its complete transition' USING ERRCODE='23514';
        END IF;
    END LOOP;
    FOREACH grant_key IN ARRAY NEW.grant_keys LOOP
        IF grant_key NOT LIKE 'oteryn:appearance-grant/npc/'||split_part(NEW.npc_key,'oteryn:npc.',2)||'/%'
            OR NOT EXISTS(SELECT 1 FROM game_account_appearance_unlock_receipts g
                JOIN game_account_appearance_unlocks u USING(account_id,unlock_key,grant_occurrence_id)
                WHERE g.account_id=NEW.account_id AND g.granting_character_id=NEW.character_id
                    AND g.unlock_key=grant_key AND g.source_kind='npc'
                    AND g.content_revision='crystal-201189f-npc-cosmetics-v1'
                    AND g.source_event_id=uuid_send(NEW.transaction_id)) THEN
            RAISE EXCEPTION 'NPC cosmetic grant lost its source receipt' USING ERRCODE='23514';
        END IF;
    END LOOP;
    RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_npc_cosmetic_receipt_guard AFTER INSERT ON game_npc_cosmetic_receipts
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_cosmetic_receipt_guard();

-- Existing quest state owners retain every original proof. This arm admits only
-- the exact new source's declared after-value and its same-transaction root step.
DO $migration$
DECLARE definition TEXT; begin_at INTEGER; arm TEXT;
BEGIN
    definition:=pg_get_functiondef('game_character_quest_track_guard()'::regprocedure);
    begin_at:=regexp_instr(definition,E'\\mBEGIN\\M',1,1,0,'i');
    IF begin_at=0 THEN RAISE EXCEPTION 'unexpected NPC quest track guard shape'; END IF;
    arm:=$arm$
        IF EXISTS(SELECT 1 FROM game_npc_cosmetic_receipts r,
            LATERAL jsonb_array_elements(r.track_changes) c
            WHERE r.character_id=NEW.character_id AND r.committed_character_revision=NEW.committed_character_revision
                AND r.created_xact_id=pg_current_xact_id() AND c->>'key'=NEW.track_key
                AND c->>'quest'=NEW.quest_key AND (c->>'after')::bigint=NEW.value
                AND (TG_OP='INSERT' OR (c->>'before')::bigint=OLD.value)) THEN RETURN NULL; END IF;
$arm$;
    EXECUTE overlay(definition placing E'BEGIN\n'||arm from begin_at for 5);
END $migration$;

CREATE FUNCTION game_npc_cosmetic_grant_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.source_kind='npc' AND NEW.content_revision='crystal-201189f-npc-cosmetics-v1' THEN
        IF NOT EXISTS(SELECT 1 FROM game_npc_cosmetic_receipts r
            WHERE r.account_id=NEW.account_id AND r.character_id=NEW.granting_character_id
                AND r.created_xact_id=pg_current_xact_id() AND NEW.unlock_key=ANY(r.grant_keys)
                AND NEW.source_event_id=uuid_send(r.transaction_id)) THEN
            RAISE EXCEPTION 'NPC appearance grant requires its exact source transaction' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_npc_cosmetic_grant_guard AFTER INSERT ON game_account_appearance_unlock_receipts
    DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_cosmetic_grant_guard();
DO $$ DECLARE name TEXT; BEGIN
    FOREACH name IN ARRAY ARRAY['game_npc_cosmetic_receipt_guard','game_npc_cosmetic_grant_guard'] LOOP
        EXECUTE format('ALTER FUNCTION %I() SET search_path=pg_catalog,%I,pg_temp',name,current_schema());
    END LOOP;
END $$;
REVOKE ALL ON FUNCTION game_npc_cosmetic_receipt_guard(),game_npc_cosmetic_grant_guard() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION game_npc_cosmetic_receipt_guard(),game_npc_cosmetic_grant_guard() TO oteryn_game_runtime;

ALTER TABLE game_seasonal_cake_extractions ADD COLUMN created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id();
CREATE TRIGGER game_seasonal_cake_extractions_immutable BEFORE UPDATE OR DELETE ON game_seasonal_cake_extractions
    FOR EACH ROW EXECUTE FUNCTION game_world_reset_history_immutable();

CREATE TABLE game_seasonal_cake_bite_receipts (
    game_session_id UUID NOT NULL REFERENCES game_durability_reconnect_sessions,
    command_id NUMERIC(20,0) NOT NULL CHECK (command_id BETWEEN 1 AND 18446744073709551615),
    character_id UUID NOT NULL REFERENCES game_character_roots,
    world_id UUID NOT NULL,
    channel_id UUID NOT NULL,
    event_start BIGINT NOT NULL,
    layer SMALLINT NOT NULL CHECK (layer BETWEEN 1 AND 4),
    x INTEGER NOT NULL CHECK (x BETWEEN 33287 AND 33330),
    y INTEGER NOT NULL CHECK (y BETWEEN 32065 AND 32103),
    floor SMALLINT NOT NULL CHECK (floor=7),
    window_start BIGINT NOT NULL CHECK (window_start>=event_start),
    appearance INTEGER NOT NULL CHECK (appearance IN (12085,12086)),
    placement BYTEA NOT NULL CHECK (octet_length(placement)=40),
    world_revision_before NUMERIC(20,0) NOT NULL CHECK (world_revision_before>0),
    world_revision_after NUMERIC(20,0) NOT NULL CHECK (world_revision_after=world_revision_before+1),
    created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),
    PRIMARY KEY(game_session_id,command_id),
    FOREIGN KEY(world_id,event_start) REFERENCES game_seasonal_cake_worlds
);
CREATE INDEX game_seasonal_cake_bite_receipts_character ON game_seasonal_cake_bite_receipts(character_id);
CREATE INDEX game_seasonal_cake_bite_receipts_world ON game_seasonal_cake_bite_receipts(world_id,event_start);
CREATE TRIGGER game_seasonal_cake_bite_receipts_immutable BEFORE UPDATE OR DELETE ON game_seasonal_cake_bite_receipts
    FOR EACH ROW EXECUTE FUNCTION game_world_reset_history_immutable();
REVOKE ALL ON game_seasonal_cake_bite_receipts FROM PUBLIC;
GRANT SELECT,INSERT ON game_seasonal_cake_bite_receipts TO oteryn_game_runtime;
GRANT SELECT ON game_seasonal_cake_bite_receipts TO oteryn_game_control;

-- BEGIN SRV7 Cake private live-Node transaction context (root owner).
-- One row per active PostgreSQL backend, overwritten for its next physical
-- transaction; stale backends are removed on arm. Never a player-settable GUC.
CREATE TABLE game_cake_world_node_context (
 backend_pid INTEGER PRIMARY KEY CHECK(backend_pid>0),
 transaction_xid XID8 NOT NULL,
 world_id UUID NOT NULL,
 channel_id UUID NOT NULL,
 generation NUMERIC(20,0) NOT NULL CHECK(generation>0),
 node_id UUID NOT NULL,
 registration NUMERIC(20,0) NOT NULL CHECK(registration>0),
 event_start BIGINT NOT NULL,
 now_seconds BIGINT NOT NULL,
 captured BOOLEAN NOT NULL DEFAULT FALSE,
 inserted BOOLEAN NOT NULL DEFAULT FALSE,
 initial_state JSONB CHECK(initial_state IS NULL OR (jsonb_typeof(initial_state)='object' AND octet_length(initial_state::text)<=8192))
);
REVOKE ALL ON game_cake_world_node_context FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
CREATE FUNCTION game_cake_arm_world_node(p_world UUID,p_channel UUID,p_generation NUMERIC,
 p_node UUID,p_registration NUMERIC,p_secret BYTEA,p_event BIGINT,p_now BIGINT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE existing game_cake_world_node_context%ROWTYPE; local_start TIMESTAMP;
BEGIN
 IF p_event NOT BETWEEN 1 AND 253402300799 OR p_now NOT BETWEEN p_event AND 253402300799 THEN
  RAISE EXCEPTION 'invalid Cake source calendar' USING ERRCODE='23514'; END IF;
 local_start:=to_timestamp(p_event::double precision) AT TIME ZONE 'Europe/Berlin';
 IF extract(month FROM local_start)<>2 OR extract(day FROM local_start)<>21
  OR extract(hour FROM local_start)<>6 OR extract(minute FROM local_start)<>0 OR extract(second FROM local_start)<>0
  OR NOT game_node_prove_current_incarnation(p_node,p_registration,p_secret)
  OR NOT game_runtime_scope_assignment_history_valid() THEN
  RAISE EXCEPTION 'Cake World arm lacks current source calendar/Node possession' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM game_runtime_scope_assignments a
  WHERE a.scope_key='\x01'::bytea||uuid_send(p_world)||uuid_send(p_channel)
   AND a.scope_kind=1 AND a.world_id=p_world AND a.channel_id=p_channel
   AND a.state=1 AND a.ownership_generation=p_generation
   AND a.holder_node_id=p_node AND a.holder_registration_revision=p_registration
  FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Cake World arm has stale Channel owner' USING ERRCODE='23514'; END IF;
 SELECT * INTO existing FROM game_cake_world_node_context WHERE backend_pid=pg_backend_pid() FOR UPDATE;
 IF existing.transaction_xid=pg_current_xact_id() THEN
  IF (existing.world_id,existing.channel_id,existing.generation,existing.node_id,existing.registration,existing.event_start)
    IS DISTINCT FROM (p_world,p_channel,p_generation,p_node,p_registration,p_event)
   OR p_now<existing.now_seconds THEN
   RAISE EXCEPTION 'Cake arm cannot replace a transaction authority or rewind its clock' USING ERRCODE='23514'; END IF;
  -- Preserve the first predecessor for aggregate deferred conservation checks.
  UPDATE game_cake_world_node_context SET now_seconds=p_now WHERE backend_pid=pg_backend_pid();
 ELSE
  DELETE FROM game_cake_world_node_context c WHERE c.backend_pid<>pg_backend_pid()
   AND NOT EXISTS(SELECT 1 FROM pg_stat_activity a WHERE a.pid=c.backend_pid);
  INSERT INTO game_cake_world_node_context(backend_pid,transaction_xid,world_id,channel_id,generation,node_id,registration,event_start,now_seconds)
   VALUES(pg_backend_pid(),pg_current_xact_id(),p_world,p_channel,p_generation,p_node,p_registration,p_event,p_now)
   ON CONFLICT(backend_pid) DO UPDATE SET transaction_xid=EXCLUDED.transaction_xid,
    world_id=EXCLUDED.world_id,channel_id=EXCLUDED.channel_id,generation=EXCLUDED.generation,
    node_id=EXCLUDED.node_id,registration=EXCLUDED.registration,event_start=EXCLUDED.event_start,
    now_seconds=EXCLUDED.now_seconds,captured=FALSE,inserted=FALSE,initial_state=NULL;
 END IF;
END $$;
CREATE FUNCTION game_cake_world_context_is_current(p_world UUID,p_event BIGINT)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT game_node_registration_history_valid() AND game_runtime_scope_assignment_history_valid()
  AND EXISTS(SELECT 1 FROM game_cake_world_node_context c
   JOIN game_runtime_scope_assignments a ON a.scope_key='\x01'::bytea||uuid_send(c.world_id)||uuid_send(c.channel_id)
   JOIN game_node_registrations n ON n.node_id=c.node_id AND n.registration_revision=c.registration
   WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id()
    AND c.world_id=p_world AND c.event_start=p_event
    AND a.scope_kind=1 AND a.world_id=c.world_id AND a.channel_id=c.channel_id
    AND a.state=1 AND a.ownership_generation=c.generation
    AND a.holder_node_id=c.node_id AND a.holder_registration_revision=c.registration
    AND n.state=1 AND NOT EXISTS(SELECT 1 FROM game_node_registration_endings e WHERE e.node_id=c.node_id))
$$;
DO $migration$
DECLARE signature TEXT;
BEGIN
 FOREACH signature IN ARRAY ARRAY['game_cake_arm_world_node(uuid,uuid,numeric,uuid,numeric,bytea,bigint,bigint)',
  'game_cake_world_context_is_current(uuid,bigint)'] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',signature,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',signature);
  EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO oteryn_game_runtime',signature);
 END LOOP;
END $migration$;
-- END SRV7 Cake private live-Node transaction context.


-- BEGIN SRV7 closed carried cost guards (root owner).
CREATE FUNCTION game_srv7_cost_basis(r game_srv7_item_costs) RETURNS JSONB LANGUAGE sql IMMUTABLE AS $$
 SELECT to_jsonb(r)-ARRAY['proof_sha256','created_xact_id']
$$;
CREATE FUNCTION game_srv7_cost_after(r game_srv7_item_costs,e JSONB,i game_item_instances)
RETURNS BOOLEAN LANGUAGE sql IMMUTABLE AS $$
 SELECT i.item_instance_id=(e->>'item')::uuid AND i.last_transaction_id=r.transaction_id
  AND i.quantity=(e->'before'->>'quantity')::bigint-(e->>'count')::bigint
  AND i.lifecycle=CASE WHEN i.quantity=0 THEN 2 ELSE 1 END
  AND (to_jsonb(i)-ARRAY['quantity','lifecycle','last_transaction_id'])=
      ((e->'before')-ARRAY['quantity','lifecycle','last_transaction_id'])
$$;
CREATE FUNCTION game_srv7_cost_admit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE e JSONB; requirement JSONB; i game_item_instances%ROWTYPE; actual BIGINT;
BEGIN
 PERFORM 1 FROM game_durability_reconnect_sessions s
 JOIN game_character_roots r ON r.character_id=s.character_id
 JOIN game_runtime_scope_assignments a ON a.scope_key='\x01'::bytea||uuid_send(NEW.world_id)||uuid_send(NEW.channel_id)
 WHERE s.game_session_id=NEW.game_session_id AND s.character_id=NEW.character_id
  AND s.session_state=2 AND s.current_transport_ref IS NOT NULL
  AND s.current_generation=NEW.connection_generation AND s.character_lease_generation=NEW.lease_generation
  AND s.scope_ownership_generation=NEW.scope_generation AND s.runtime_scope_kind=1
  AND s.world_id=NEW.world_id AND s.runtime_scope_world_id=NEW.world_id
  AND s.runtime_scope_channel_id=NEW.channel_id AND a.scope_kind=1
  AND a.world_id=NEW.world_id AND a.channel_id=NEW.channel_id AND a.state=1
  AND a.ownership_generation=NEW.scope_generation AND r.lifecycle=1
  AND r.account_id=s.account_id AND r.world_id=NEW.world_id
 FOR SHARE OF s,r,a;
 IF NOT FOUND THEN RAISE EXCEPTION 'closed cost lacks current Character/Channel fence' USING ERRCODE='23514'; END IF;
 IF (SELECT count(DISTINCT value->>'item') FROM jsonb_array_elements(NEW.inputs))<>jsonb_array_length(NEW.inputs)
  OR (SELECT count(DISTINCT (value->>'family',value->>'key',value->>'revision')) FROM jsonb_array_elements(NEW.requirements))<>jsonb_array_length(NEW.requirements)
 THEN RAISE EXCEPTION 'closed cost duplicates input or definition' USING ERRCODE='23514'; END IF;
 IF NEW.cause_kind='cake_substance' AND (jsonb_array_length(NEW.requirements)<>1
   OR NEW.requirements->0->>'family'<>'Item'
   OR NEW.requirements->0->>'key'<>'oteryn:item.tibia.i12143'
   OR (NEW.requirements->0->>'count')::bigint NOT BETWEEN 1 AND 200)
 THEN RAISE EXCEPTION 'Cake only consumes remaining source-qualified substances' USING ERRCODE='23514'; END IF;
 FOR requirement IN SELECT value FROM jsonb_array_elements(NEW.requirements) LOOP
  IF requirement->>'family'<>'Item' OR (requirement->>'count')::bigint NOT BETWEEN 1 AND 1000000
  THEN RAISE EXCEPTION 'invalid closed cost requirement' USING ERRCODE='23514'; END IF;
  SELECT coalesce(sum((value->>'count')::bigint),0) INTO actual FROM jsonb_array_elements(NEW.inputs)
   WHERE value->'before'->>'definition_family'=requirement->>'family'
    AND value->'before'->>'definition_production_key'=requirement->>'key'
    AND value->'before'->>'definition_revision_ref'=requirement->>'revision';
  IF actual<>(requirement->>'count')::bigint THEN
   RAISE EXCEPTION 'closed cost does not consume its exact complete requirements' USING ERRCODE='23514'; END IF;
 END LOOP;
 -- Rust locks all matching instances by UUID before locking custody or publishing this row.
 FOR e IN SELECT value FROM jsonb_array_elements(NEW.inputs) ORDER BY value->>'item' LOOP
  SELECT * INTO i FROM game_item_instances WHERE item_instance_id=(e->>'item')::uuid FOR UPDATE;
  IF i.item_instance_id IS NULL OR to_jsonb(i) IS DISTINCT FROM e->'before'
   OR i.world_id<>NEW.world_id OR i.lifecycle<>1 OR i.definition_family<>'Item'
   OR (e->>'count')::bigint NOT BETWEEN 1 AND i.quantity
   OR e->>'kind' NOT IN ('container','nested','equipment')
   OR NOT EXISTS(SELECT 1 FROM game_quest_callback_carried(NEW.character_id,NEW.world_id) c
      WHERE c.item=i.item_instance_id AND c.location=e->'location' AND c.kind=e->>'kind')
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.requirements) q
      WHERE q->>'family'=i.definition_family AND q->>'key'=i.definition_production_key
       AND q->>'revision'=i.definition_revision_ref)
   OR EXISTS(SELECT 1 FROM game_item_keys WHERE item_instance_id=i.item_instance_id)
   OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=i.item_instance_id)
   OR EXISTS(SELECT 1 FROM game_item_texts WHERE item_instance_id=i.item_instance_id)
   OR EXISTS(SELECT 1 FROM game_item_imbuements WHERE item_instance_id=i.item_instance_id)
   OR EXISTS(SELECT 1 FROM game_item_container_entries WHERE parent_item_instance_id=i.item_instance_id)
   OR EXISTS(SELECT 1 FROM game_item_nested_entries WHERE parent_item_instance_id=i.item_instance_id)
  THEN RAISE EXCEPTION 'closed cost lacks exact plain carried predecessor' USING ERRCODE='23514'; END IF;
 END LOOP;
 NEW.created_xact_id:=pg_current_xact_id();
 NEW.proof_sha256:=sha256(convert_to(game_srv7_cost_basis(NEW)::text,'UTF8'));
 RETURN NEW;
END $$;
CREATE TRIGGER game_srv7_cost_admit BEFORE INSERT ON game_srv7_item_costs FOR EACH ROW EXECUTE FUNCTION game_srv7_cost_admit();

CREATE FUNCTION game_srv7_cost_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE e JSONB; i game_item_instances%ROWTYPE; envelope BYTEA; payload BYTEA; proof JSONB;
BEGIN
 IF NEW.created_xact_id<>pg_current_xact_id() OR NEW.proof_sha256 IS DISTINCT FROM
  sha256(convert_to(game_srv7_cost_basis(NEW)::text,'UTF8')) THEN
  RAISE EXCEPTION 'closed cost receipt commitment changed' USING ERRCODE='23514'; END IF;
 FOR e IN SELECT value FROM jsonb_array_elements(NEW.inputs) LOOP
  SELECT * INTO i FROM game_item_instances WHERE item_instance_id=(e->>'item')::uuid;
  IF i.item_instance_id IS NULL OR NOT game_srv7_cost_after(NEW,e,i)
   OR (i.quantity=0 AND EXISTS(SELECT 1 FROM game_quest_callback_carried(NEW.character_id,NEW.world_id) c WHERE c.item=i.item_instance_id))
   OR (i.quantity>0 AND NOT EXISTS(SELECT 1 FROM game_quest_callback_carried(NEW.character_id,NEW.world_id) c
      WHERE c.item=i.item_instance_id AND c.location=e->'location' AND c.kind=e->>'kind'))
  THEN RAISE EXCEPTION 'incomplete atomic closed carried cost' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF NEW.cause_kind='npc_cosmetic' THEN
  PERFORM 1 FROM game_npc_cosmetic_receipts r WHERE r.cost_transaction_id=NEW.transaction_id
   AND r.character_id=NEW.character_id AND r.game_session_id=NEW.game_session_id AND r.command_id=NEW.command_id
   AND r.created_xact_id=pg_current_xact_id();
 ELSE
  PERFORM 1 FROM game_seasonal_cake_deliveries r WHERE r.cost_transaction_id=NEW.transaction_id
   AND r.character_id=NEW.character_id AND r.game_session_id=NEW.game_session_id AND r.command_id=NEW.command_id
   AND r.created_xact_id=pg_current_xact_id();
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION 'closed cost lacks its atomic domain result' USING ERRCODE='23514'; END IF;
 SELECT a.envelope INTO envelope FROM game_item_audit_outbox a
  WHERE a.transaction_id=NEW.transaction_id AND a.event_id=NEW.event_id
   AND a.item_instance_id=(NEW.inputs->0->>'item')::uuid AND a.occurred_at=NEW.occurred_at
   AND sha256(a.envelope)=a.envelope_sha256 AND a.created_xact_id=pg_current_xact_id()
   AND a.transaction_ordinal=1 AND a.transaction_count=1 AND a.publication_state=1 AND a.published_at IS NULL;
 payload:=game_item_action_wire_bytes(envelope,26);
 IF envelope IS NULL OR payload IS NULL OR octet_length(payload)>7936
  OR game_item_action_wire_bytes(envelope,27) IS DISTINCT FROM sha256(payload)
 THEN RAISE EXCEPTION 'closed cost lacks its committed native audit' USING ERRCODE='23514'; END IF;
 proof:=convert_from(game_item_action_wire_bytes(game_item_action_wire_bytes(payload,15),1),'UTF8')::jsonb;
 IF proof IS DISTINCT FROM jsonb_build_object('schema','OTERYN_CARRIED_COST_RECEIPT_COMMITMENT/v1',
   'encoding','postgresql-jsonb-text-utf8/v1','transaction_id',NEW.transaction_id::text,
   'receipt_sha256',encode(NEW.proof_sha256,'hex')) THEN
  RAISE EXCEPTION 'closed cost native audit does not bind its full immutable receipt' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_srv7_cost_complete AFTER INSERT ON game_srv7_item_costs
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_srv7_cost_complete();

-- Prepend only this receipt-backed proof arm; every existing writer stays in the chain.
DO $migration$
DECLARE n TEXT; body TEXT; arm TEXT; begin_at INT; table_name TEXT; location_kind TEXT;
BEGIN
 FOREACH n IN ARRAY ARRAY['game_item_instance_guard','game_item_instance_change_proven',
  'game_item_container_entry_removal_proven','game_item_nested_entry_proven',
  'game_equipment_slot_proven','game_item_immutable'] LOOP
  body:=pg_get_functiondef((n||'()')::regprocedure);
  begin_at:=regexp_instr(body,E'\\mBEGIN\\M',1,1,0,'i');
  IF begin_at=0 THEN RAISE EXCEPTION 'unexpected closed cost guard body: %',n; END IF;
  IF n IN ('game_item_instance_guard','game_item_instance_change_proven','game_item_immutable') THEN
   arm:=$arm$
    IF TG_OP='UPDATE' AND TG_TABLE_NAME='game_item_instances' THEN
    IF EXISTS(
     SELECT 1 FROM game_srv7_item_costs r CROSS JOIN LATERAL jsonb_array_elements(r.inputs) e
      WHERE r.created_xact_id=pg_current_xact_id() AND e->>'item'=OLD.item_instance_id::text
       AND e->'before'=to_jsonb(OLD) AND game_srv7_cost_after(r,e,NEW)) THEN
      IF TG_WHEN='BEFORE' THEN RETURN NEW; END IF;
      RETURN NULL;
    END IF;
    END IF;
$arm$;
  ELSE arm:=''; END IF;
  IF n IN ('game_item_container_entry_removal_proven','game_item_nested_entry_proven','game_equipment_slot_proven','game_item_immutable') THEN
   arm:=arm||$arm$
    IF TG_OP='DELETE' AND TG_TABLE_NAME IN ('game_item_container_entries','game_item_nested_entries','game_character_equipment_slots') THEN
    IF EXISTS(
     SELECT 1 FROM game_srv7_item_costs r CROSS JOIN LATERAL jsonb_array_elements(r.inputs) e
      JOIN game_item_instances i ON i.item_instance_id=(e->>'item')::uuid
      WHERE r.created_xact_id=pg_current_xact_id() AND e->>'item'=OLD.item_instance_id::text
       AND e->'location'=to_jsonb(OLD) AND e->>'kind'=CASE TG_TABLE_NAME
        WHEN 'game_item_container_entries' THEN 'container' WHEN 'game_item_nested_entries' THEN 'nested' ELSE 'equipment' END
       AND i.quantity=0 AND i.lifecycle=2 AND game_srv7_cost_after(r,e,i)) THEN
      IF TG_WHEN='BEFORE' THEN RETURN OLD; END IF;
      RETURN NULL;
    END IF;
    END IF;
$arm$;
  END IF;
  EXECUTE substr(body,1,begin_at+4)||E'\n'||arm||substr(body,begin_at+5);
 END LOOP;
END $migration$;
DO $migration$
DECLARE signature TEXT;
BEGIN
 FOREACH signature IN ARRAY ARRAY['game_srv7_cost_basis(game_srv7_item_costs)',
  'game_srv7_cost_after(game_srv7_item_costs,jsonb,game_item_instances)',
  'game_srv7_cost_admit()','game_srv7_cost_complete()'] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',signature,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',signature);
  EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO oteryn_game_runtime',signature);
 END LOOP;
END $migration$;
-- END SRV7 closed carried cost guards.

-- BEGIN SRV7 Cake per-recipient XP receipt evidence.
ALTER TABLE game_party_kill_xp_members ADD COLUMN cake_xp_percent SMALLINT NOT NULL DEFAULT 0 CHECK(cake_xp_percent IN(0,50));
-- END SRV7 Cake per-recipient XP receipt evidence.

-- BEGIN SRV7 Cake character secret-backed source transitions.
ALTER TABLE game_seasonal_cake_character_receipts
 ADD COLUMN created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),
 ADD COLUMN world_id UUID NOT NULL, ADD COLUMN event_start BIGINT NOT NULL,
 ADD COLUMN game_session_id UUID NOT NULL, ADD COLUMN connection_generation NUMERIC(20,0) NOT NULL,
 ADD COLUMN lease_generation NUMERIC(20,0) NOT NULL, ADD COLUMN scope_generation NUMERIC(20,0) NOT NULL,
 ADD COLUMN channel_id UUID NOT NULL, ADD COLUMN node_id UUID NOT NULL,
 ADD COLUMN node_registration NUMERIC(20,0) NOT NULL,
 ADD COLUMN event_kind SMALLINT NOT NULL CHECK(event_kind BETWEEN 0 AND 3),
 ADD COLUMN city SMALLINT CHECK(city BETWEEN 0 AND 4),
 ADD FOREIGN KEY(character_id,world_id,event_start) REFERENCES game_seasonal_cake_characters(character_id,world_id,event_start);
CREATE TRIGGER game_cake_character_receipt_stamp BEFORE INSERT ON game_seasonal_cake_character_receipts
 FOR EACH ROW EXECUTE FUNCTION game_item_stamp_created_xact_id();
CREATE TRIGGER game_cake_character_receipt_immutable BEFORE UPDATE OR DELETE ON game_seasonal_cake_character_receipts
 FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_cake_character_receipt_no_truncate BEFORE TRUNCATE ON game_seasonal_cake_character_receipts
 FOR EACH STATEMENT EXECUTE FUNCTION game_world_reset_history_immutable();
CREATE TABLE game_cake_character_context (
 backend_pid INTEGER PRIMARY KEY, transaction_xid XID8 NOT NULL,
 character_id UUID NOT NULL, world_id UUID NOT NULL, event_start BIGINT NOT NULL,
 game_session_id UUID NOT NULL, connection_generation NUMERIC(20,0) NOT NULL,
 lease_generation NUMERIC(20,0) NOT NULL, scope_generation NUMERIC(20,0) NOT NULL,
 channel_id UUID NOT NULL, event_kind SMALLINT NOT NULL CHECK(event_kind BETWEEN 0 AND 5),
 city SMALLINT CHECK(city BETWEEN 0 AND 4), occurrence BYTEA CHECK(octet_length(occurrence)=32),
 command_id NUMERIC(20,0), before_state JSONB NOT NULL, stage SMALLINT NOT NULL
);
REVOKE ALL ON game_cake_character_context FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
CREATE FUNCTION game_cake_character_context_is_current() RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT EXISTS(SELECT 1 FROM game_cake_character_context c
 JOIN game_durability_reconnect_sessions s ON s.game_session_id=c.game_session_id
 JOIN game_character_roots r ON r.character_id=c.character_id
 JOIN game_durability_admission_character_guards cg ON cg.character_id=c.character_id
 JOIN game_durability_admission_account_guards ag ON ag.account_id=cg.account_id
 JOIN game_durability_admission_runtime_guards rg ON rg.scope_key='\x01'::bytea||uuid_send(c.world_id)||uuid_send(c.channel_id)
 WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id()
 AND game_cake_world_context_is_current(c.world_id,c.event_start)
 AND s.character_id=c.character_id AND s.world_id=c.world_id AND s.runtime_scope_kind=1
 AND s.runtime_scope_world_id=c.world_id AND s.runtime_scope_channel_id=c.channel_id
 AND s.runtime_scope_instance_id IS NULL AND s.runtime_scope_house_key IS NULL
 AND s.current_generation=c.connection_generation AND s.character_lease_generation=c.lease_generation
 AND s.scope_ownership_generation=c.scope_generation AND s.session_state IN(1,2)
 AND r.world_id=c.world_id AND r.account_id=s.account_id AND r.lifecycle=1
 AND cg.account_id=s.account_id AND cg.world_id=c.world_id AND cg.eligible
 AND cg.lease_generation=c.lease_generation AND cg.holder_game_session_id=c.game_session_id
 AND ag.presence_character_id=c.character_id AND ag.holder_game_session_id=c.game_session_id
 AND rg.ready AND rg.ownership_generation=c.scope_generation)
$$;
CREATE FUNCTION game_cake_arm_character(p_world UUID,p_channel UUID,p_generation NUMERIC,
 p_node UUID,p_registration NUMERIC,p_secret BYTEA,p_event BIGINT,p_now BIGINT,
 p_character UUID,p_session UUID,p_connection NUMERIC,p_lease NUMERIC,
 p_kind SMALLINT,p_city SMALLINT,p_occurrence BYTEA,p_command NUMERIC)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE predecessor JSONB; world_state JSONB;
BEGIN
 IF p_secret IS NULL OR octet_length(p_secret)<>32 OR p_kind IS NULL OR p_kind NOT BETWEEN 0 AND 5
 OR (p_kind=2 AND (p_city IS NULL OR p_city NOT BETWEEN 0 AND 4))
 OR (p_kind<4 AND (p_occurrence IS NULL OR octet_length(p_occurrence)<>32))
 OR (p_kind>=4 AND (p_command IS NULL OR p_command<=0)) THEN
  RAISE EXCEPTION 'Cake character arm requires complete source authority' USING ERRCODE='23514'; END IF;
 PERFORM game_cake_arm_world_node(p_world,p_channel,p_generation,p_node,p_registration,p_secret,p_event,p_now);
 IF EXISTS(SELECT 1 FROM game_cake_character_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id()) THEN
  RAISE EXCEPTION 'Cake character transaction already armed' USING ERRCODE='23514'; END IF;
 SELECT jsonb_build_object('started',started,'isle_armed',isle_armed,'visited_cities',visited_cities,
  'item_reward_given',item_reward_given,'cupcake_reward_given',cupcake_reward_given) INTO predecessor
 FROM game_seasonal_cake_characters WHERE character_id=p_character AND world_id=p_world AND event_start=p_event FOR UPDATE;
 IF predecessor IS NULL THEN predecessor:='{"started":false,"isle_armed":false,"visited_cities":0,"item_reward_given":false,"cupcake_reward_given":false}'::jsonb; END IF;
 SELECT state INTO world_state FROM game_seasonal_cake_worlds WHERE world_id=p_world AND event_start=p_event
 AND p_now>=event_start AND p_now<event_end FOR SHARE;
 IF world_state IS NULL OR (world_state->>'stage')::integer NOT BETWEEN 1 AND 3
 OR (p_kind<>1 AND (world_state->>'stage')::integer<>3)
 OR (p_kind>=4 AND (world_state->>'bonus_from' IS NULL OR (world_state->>'bonus_from')::bigint>p_now)) THEN
  RAISE EXCEPTION 'Cake character source stage is inactive' USING ERRCODE='23514'; END IF;
 DELETE FROM game_cake_character_context c WHERE c.backend_pid<>pg_backend_pid()
  AND NOT EXISTS(SELECT 1 FROM pg_stat_activity a WHERE a.pid=c.backend_pid);
 INSERT INTO game_cake_character_context(backend_pid,transaction_xid,character_id,world_id,event_start,
 game_session_id,connection_generation,lease_generation,scope_generation,channel_id,event_kind,city,occurrence,command_id,before_state,stage)
 VALUES(pg_backend_pid(),pg_current_xact_id(),p_character,p_world,p_event,p_session,p_connection,p_lease,p_generation,
 p_channel,p_kind,p_city,p_occurrence,p_command,predecessor,(world_state->>'stage')::smallint)
 ON CONFLICT(backend_pid) DO UPDATE SET transaction_xid=EXCLUDED.transaction_xid,character_id=EXCLUDED.character_id,
 world_id=EXCLUDED.world_id,event_start=EXCLUDED.event_start,game_session_id=EXCLUDED.game_session_id,
 connection_generation=EXCLUDED.connection_generation,lease_generation=EXCLUDED.lease_generation,
 scope_generation=EXCLUDED.scope_generation,channel_id=EXCLUDED.channel_id,event_kind=EXCLUDED.event_kind,
 city=EXCLUDED.city,occurrence=EXCLUDED.occurrence,command_id=EXCLUDED.command_id,before_state=EXCLUDED.before_state,stage=EXCLUDED.stage;
 -- Lock each independent fence row until this source transaction commits;
 -- a reconnect, lease successor or readiness retirement cannot slip after proof.
 PERFORM 1 FROM game_durability_reconnect_sessions s
 JOIN game_durability_admission_character_guards cg ON cg.character_id=p_character
 JOIN game_durability_admission_account_guards ag ON ag.account_id=cg.account_id
 JOIN game_durability_admission_runtime_guards rg ON rg.scope_key='\x01'::bytea||uuid_send(p_world)||uuid_send(p_channel)
 WHERE s.game_session_id=p_session AND s.character_id=p_character
 FOR SHARE OF s,cg,ag,rg;
 IF NOT FOUND OR NOT game_cake_character_context_is_current() THEN
  RAISE EXCEPTION 'Cake character arm has stale session/lease/Channel' USING ERRCODE='23514'; END IF;
END $$;
CREATE FUNCTION game_cake_character_receipt_guard() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_cake_character_context%ROWTYPE; n game_cake_world_node_context%ROWTYPE;
 expected_effect JSONB; mask INTEGER; armed BOOLEAN;
BEGIN
 SELECT * INTO c FROM game_cake_character_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF NOT game_cake_character_context_is_current() OR c.event_kind>=4 OR NEW.character_id IS DISTINCT FROM c.character_id
 OR NEW.occurrence IS DISTINCT FROM c.occurrence OR (NEW.result->>'event_start')::bigint IS DISTINCT FROM c.event_start THEN
  RAISE EXCEPTION 'Cake source receipt lacks current character authority' USING ERRCODE='23514'; END IF;
 mask:=(c.before_state->>'visited_cities')::integer; armed:=(c.before_state->>'isle_armed')::boolean;
 expected_effect:='"Status"'::jsonb;
 CASE c.event_kind
 WHEN 0 THEN expected_effect:=to_jsonb(CASE WHEN mask=31 THEN 'Complete' ELSE 'Started' END::text);
 WHEN 1 THEN IF c.stage=3 AND mask<31 AND NOT armed THEN expected_effect:='"Armed"'::jsonb; END IF;
 WHEN 2 THEN
  IF mask=31 THEN expected_effect:='"Complete"'::jsonb;
  ELSIF NOT armed THEN expected_effect:='"NoMark"'::jsonb;
  ELSIF (mask & (1<<c.city))<>0 THEN expected_effect:='"AlreadyVisited"'::jsonb;
  ELSE expected_effect:=jsonb_build_object('Extracted',(ARRAY['Carlin','Thais','Edron','Darashia','LibertyBay'])[c.city+1]); END IF;
 ELSE NULL;
 END CASE;
 IF NEW.result->'effect' IS DISTINCT FROM expected_effect THEN
  RAISE EXCEPTION 'Cake source receipt has another event effect' USING ERRCODE='23514'; END IF;
 SELECT * INTO n FROM game_cake_world_node_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 NEW.world_id:=c.world_id; NEW.event_start:=c.event_start; NEW.game_session_id:=c.game_session_id;
 NEW.connection_generation:=c.connection_generation; NEW.lease_generation:=c.lease_generation;
 NEW.scope_generation:=c.scope_generation; NEW.channel_id:=c.channel_id;
 NEW.node_id:=n.node_id; NEW.node_registration:=n.registration; NEW.event_kind:=c.event_kind; NEW.city:=c.city;
 RETURN NEW;
END $$;
CREATE TRIGGER game_cake_character_receipt_guard BEFORE INSERT ON game_seasonal_cake_character_receipts
 FOR EACH ROW EXECUTE FUNCTION game_cake_character_receipt_guard();
CREATE FUNCTION game_cake_character_state_guard() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_cake_character_context%ROWTYPE; expected JSONB; actual JSONB; mask INTEGER; armed BOOLEAN;
BEGIN
 SELECT * INTO c FROM game_cake_character_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF NOT game_cake_character_context_is_current() OR NEW.character_id IS DISTINCT FROM c.character_id
 OR NEW.world_id IS DISTINCT FROM c.world_id OR NEW.event_start IS DISTINCT FROM c.event_start
 OR (TG_OP='UPDATE' AND (OLD.character_id,OLD.world_id,OLD.event_start) IS DISTINCT FROM (NEW.character_id,NEW.world_id,NEW.event_start)) THEN
  RAISE EXCEPTION 'Cake character state lacks current source authority' USING ERRCODE='23514'; END IF;
 expected:=c.before_state; mask:=(expected->>'visited_cities')::integer; armed:=(expected->>'isle_armed')::boolean;
 CASE c.event_kind
 WHEN 0 THEN IF mask<31 THEN expected:=jsonb_set(expected,'{started}','true'); END IF;
 WHEN 1 THEN IF c.stage=3 AND mask<31 THEN expected:=jsonb_set(expected,'{isle_armed}','true'); END IF;
 WHEN 2 THEN IF armed AND mask<31 AND (mask & (1<<c.city))=0 THEN
  expected:=jsonb_set(jsonb_set(expected,'{visited_cities}',to_jsonb(mask | (1<<c.city))),'{isle_armed}','false'); END IF;
 WHEN 3 THEN NULL;
 WHEN 4,5 THEN
  IF mask<>31 OR (expected->>CASE WHEN c.event_kind=4 THEN 'item_reward_given' ELSE 'cupcake_reward_given' END)::boolean THEN
   RAISE EXCEPTION 'Cake character reward has no eligible predecessor' USING ERRCODE='23514'; END IF;
  expected:=jsonb_set(expected,ARRAY[CASE WHEN c.event_kind=4 THEN 'item_reward_given' ELSE 'cupcake_reward_given' END],'true');
  IF NOT EXISTS(SELECT 1 FROM game_reward_claim_mint_receipts r
   JOIN game_item_instances i ON i.item_instance_id=r.item_instance_id
   WHERE r.created_xact_id=pg_current_xact_id() AND r.quantity=1
   AND r.character_id=c.character_id AND r.game_session_id=c.game_session_id AND r.command_id=c.command_id
   AND i.definition_family='Item' AND
    ((c.event_kind=4 AND i.definition_production_key IN('oteryn:item.tibia.i14756','oteryn:item.tibia.i20347','oteryn:item.tibia.i20350'))
     OR(c.event_kind=5 AND i.definition_production_key IN('oteryn:item.tibia.i28484','oteryn:item.tibia.i28485','oteryn:item.tibia.i28486')))
   AND r.claim_family='RewardClaim' AND r.claim_production_key='oteryn:seasonal.cake.run'||c.event_start::text||CASE WHEN c.event_kind=4 THEN '.item' ELSE '.cupcake' END) THEN
   RAISE EXCEPTION 'Cake reward flag lacks same-transaction native mint receipt' USING ERRCODE='23514'; END IF;
 END CASE;
 actual:=jsonb_build_object('started',NEW.started,'isle_armed',NEW.isle_armed,'visited_cities',NEW.visited_cities,
 'item_reward_given',NEW.item_reward_given,'cupcake_reward_given',NEW.cupcake_reward_given);
 IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Cake character source transition mismatch' USING ERRCODE='23514'; END IF;
 IF c.event_kind<4 AND NOT EXISTS(SELECT 1 FROM game_seasonal_cake_character_receipts r
  WHERE r.character_id=c.character_id AND r.occurrence=c.occurrence AND r.created_xact_id=pg_current_xact_id()
  AND r.result-'event_start'-'effect'=actual) THEN
  RAISE EXCEPTION 'Cake mark lacks same-transaction source receipt' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE CONSTRAINT TRIGGER game_cake_character_state_guard AFTER INSERT OR UPDATE ON game_seasonal_cake_characters
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_character_state_guard();
CREATE TRIGGER game_cake_character_no_delete BEFORE DELETE ON game_seasonal_cake_characters
 FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_cake_character_no_truncate BEFORE TRUNCATE ON game_seasonal_cake_characters
 FOR EACH STATEMENT EXECUTE FUNCTION game_world_reset_history_immutable();
DO $migration$
DECLARE signature TEXT;
BEGIN
 FOREACH signature IN ARRAY ARRAY['game_cake_character_context_is_current()',
 'game_cake_arm_character(uuid,uuid,numeric,uuid,numeric,bytea,bigint,bigint,uuid,uuid,numeric,numeric,smallint,smallint,bytea,numeric)',
 'game_cake_character_receipt_guard()','game_cake_character_state_guard()'] LOOP
 EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',signature,current_schema());
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',signature);
 END LOOP;
 GRANT EXECUTE ON FUNCTION game_cake_arm_character(uuid,uuid,numeric,uuid,numeric,bytea,bigint,bigint,uuid,uuid,numeric,numeric,smallint,smallint,bytea,numeric) TO oteryn_game_runtime;
END $migration$;
-- END SRV7 Cake character secret-backed source transitions.

-- BEGIN SRV7 World source conservation.
-- SRV7 Cake World: private live-Node authority, one predecessor and conserved progress.
-- This block extends, and does not replace, the root-owned Node arm.
CREATE FUNCTION game_cake_world_state_valid(s JSONB) RETURNS BOOLEAN
LANGUAGE sql IMMUTABLE STRICT AS $$
 SELECT jsonb_typeof(s)='object' AND (SELECT count(*) FROM jsonb_object_keys(s))=10
  AND s ?& ARRAY['stage','substances','golems','layer','layer_progress','window_start','window_end','bonus_from','bonus_until','revision']
  AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY['stage','substances','golems','layer','layer_progress','revision']) k
   WHERE jsonb_typeof(s->k)<>'number' OR s->>k !~ '^[0-9]{1,20}$')
  AND (s->>'stage')::numeric BETWEEN 0 AND 3 AND (s->>'substances')::numeric BETWEEN 0 AND 200
  AND (s->>'golems')::numeric BETWEEN 0 AND 200 AND (s->>'layer')::numeric BETWEEN 1 AND 4
  AND (s->>'layer_progress')::numeric BETWEEN 0 AND 1116 AND (s->>'revision')::numeric BETWEEN 1 AND 18446744073709551615
  AND NOT EXISTS(SELECT 1 FROM unnest(ARRAY['window_start','window_end','bonus_from','bonus_until']) k
   WHERE s->k<>'null'::jsonb AND (jsonb_typeof(s->k)<>'number' OR s->>k !~ '^[0-9]{1,12}$'))
  AND ((s->'window_start'='null'::jsonb AND s->'window_end'='null'::jsonb)
   OR ((s->>'window_start')::bigint>=0 AND (s->>'window_end')::bigint-(s->>'window_start')::bigint=1800))
  AND ((s->'bonus_from'='null'::jsonb AND s->'bonus_until'='null'::jsonb)
   OR ((s->>'bonus_from')::bigint>=0 AND (s->>'bonus_until')::bigint-(s->>'bonus_from')::bigint=604800))
$$;
CREATE FUNCTION game_cake_world_capture() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_cake_world_node_context%ROWTYPE; initial JSONB;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'Cake World history is retained' USING ERRCODE='23514'; END IF;
 IF TG_OP='UPDATE' AND (NEW.world_id,NEW.event_start,NEW.event_end) IS DISTINCT FROM (OLD.world_id,OLD.event_start,OLD.event_end) THEN
  RAISE EXCEPTION 'Cake occurrence identity and source dates are immutable' USING ERRCODE='23514'; END IF;
 IF NEW.event_end<>NEW.event_start+518400 OR game_cake_world_state_valid(NEW.state) IS DISTINCT FROM TRUE
  OR game_cake_world_context_is_current(NEW.world_id,NEW.event_start) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'Cake World write lacks source calendar/current Node authority' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT c FROM game_cake_world_node_context WHERE backend_pid=pg_backend_pid() FOR UPDATE;
 initial:=jsonb_build_object('stage',1,'substances',0,'golems',0,'layer',1,'layer_progress',0,
  'window_start',NULL,'window_end',NULL,'bonus_from',NULL,'bonus_until',NULL,'revision',1);
 IF TG_OP='INSERT' AND (NEW.state<>initial OR c.now_seconds>=NEW.event_end) THEN
  RAISE EXCEPTION 'Cake World can begin only with the exact source initial state' USING ERRCODE='23514'; END IF;
 -- BEFORE INSERT also runs for ON CONFLICT DO NOTHING; capture only an actual insertion.
 IF TG_OP='INSERT' AND TG_WHEN='BEFORE' THEN RETURN NEW; END IF;
 IF c.captured THEN RAISE EXCEPTION 'Cake World permits one physical write per transaction' USING ERRCODE='23514'; END IF;
 UPDATE game_cake_world_node_context SET captured=TRUE,inserted=(TG_OP='INSERT'),
  initial_state=CASE WHEN TG_OP='INSERT' THEN initial ELSE OLD.state END WHERE backend_pid=pg_backend_pid();
 RETURN NEW;
END $$;
CREATE TRIGGER game_cake_world_capture BEFORE INSERT OR UPDATE OR DELETE ON game_seasonal_cake_worlds
 FOR EACH ROW EXECUTE FUNCTION game_cake_world_capture();
CREATE TRIGGER game_cake_world_insert_capture AFTER INSERT ON game_seasonal_cake_worlds
 FOR EACH ROW EXECUTE FUNCTION game_cake_world_capture();

-- BEFORE triggers capture actual mutable predecessors; runtime cannot invent them.
-- Old-XID rows of this backend and dead backend rows are reclaimed before every capture.
CREATE TABLE game_cake_world_side_context (
 backend_pid INTEGER NOT NULL,transaction_xid XID8 NOT NULL,kind SMALLINT NOT NULL CHECK(kind IN(1,2)),
 identity TEXT NOT NULL CHECK(octet_length(identity) BETWEEN 1 AND 256),
 before_state JSONB,after_state JSONB NOT NULL,
 PRIMARY KEY(backend_pid,kind,identity)
);
REVOKE ALL ON game_cake_world_side_context FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
ALTER TABLE game_seasonal_cake_bites ADD COLUMN last_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id();
ALTER TABLE game_seasonal_cake_tiles ADD COLUMN last_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id();
CREATE FUNCTION game_cake_world_side_capture() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE k SMALLINT; key TEXT; prior JSONB;
BEGIN
 IF TG_OP='DELETE' OR game_cake_world_context_is_current(NEW.world_id,NEW.event_start) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'Cake mutable marks require current source Node context' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='game_seasonal_cake_bites' THEN
  k:=1; key:=NEW.character_id::text;
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['window_start','bites','last_bite','last_xact_id']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['window_start','bites','last_bite','last_xact_id']) THEN
   RAISE EXCEPTION 'Cake personal bite identity is immutable' USING ERRCODE='23514'; END IF;
 ELSE
  k:=2; key:=NEW.layer::text||':'||NEW.x::text||':'||NEW.y::text||':'||NEW.floor::text;
  IF TG_OP='UPDATE' AND (to_jsonb(NEW)-ARRAY['removed','window_start','last_xact_id']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['removed','window_start','last_xact_id']) THEN
   RAISE EXCEPTION 'Cake physical tile identity is immutable' USING ERRCODE='23514'; END IF;
 END IF;
 NEW.last_xact_id:=pg_current_xact_id();
 -- BEFORE INSERT also runs on both UPSERT conflict paths; retain only actual writes.
 IF TG_OP='INSERT' AND TG_WHEN='BEFORE' THEN RETURN NEW; END IF;
 DELETE FROM game_cake_world_side_context s WHERE (s.backend_pid=pg_backend_pid() AND s.transaction_xid<>pg_current_xact_id())
  OR NOT EXISTS(SELECT 1 FROM pg_stat_activity a WHERE a.pid=s.backend_pid);
 IF (SELECT count(*) FROM game_cake_world_side_context WHERE backend_pid=pg_backend_pid())>=1718 THEN
  RAISE EXCEPTION 'Cake source tile capture bound exceeded' USING ERRCODE='23514'; END IF;
 prior:=CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END;
 INSERT INTO game_cake_world_side_context VALUES(pg_backend_pid(),pg_current_xact_id(),k,key,prior,to_jsonb(NEW))
  ON CONFLICT DO NOTHING;
 IF NOT FOUND THEN RAISE EXCEPTION 'Cake marks change once per physical transaction' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER game_cake_bites_capture BEFORE INSERT OR UPDATE OR DELETE ON game_seasonal_cake_bites
 FOR EACH ROW EXECUTE FUNCTION game_cake_world_side_capture();
CREATE TRIGGER game_cake_tiles_capture BEFORE INSERT OR UPDATE OR DELETE ON game_seasonal_cake_tiles
 FOR EACH ROW EXECUTE FUNCTION game_cake_world_side_capture();
CREATE TRIGGER game_cake_bites_insert_capture AFTER INSERT ON game_seasonal_cake_bites
 FOR EACH ROW EXECUTE FUNCTION game_cake_world_side_capture();
CREATE TRIGGER game_cake_tiles_insert_capture AFTER INSERT ON game_seasonal_cake_tiles
 FOR EACH ROW EXECUTE FUNCTION game_cake_world_side_capture();

CREATE FUNCTION game_cake_world_receipt_admit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_cake_world_node_context%ROWTYPE;
BEGIN
 IF game_cake_world_context_is_current(NEW.world_id,NEW.event_start) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'Cake progress receipt lacks current source Node context' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT c FROM game_cake_world_node_context WHERE backend_pid=pg_backend_pid();
 NEW.created_xact_id:=pg_current_xact_id();
 IF c.now_seconds>=c.event_start+518400 THEN
  RAISE EXCEPTION 'Cake source occurrence has ended' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='game_seasonal_cake_extractions' THEN
  IF NEW.extracted_at<>c.now_seconds OR NEW.source_occurrence=decode(repeat('00',32),'hex') THEN
   RAISE EXCEPTION 'Cake extraction requires current native source observation' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='game_seasonal_cake_deliveries' THEN
  IF (NEW.result ?& ARRAY['accepted','substances','golems','stage']) IS DISTINCT FROM TRUE
   OR (SELECT count(*) FROM jsonb_object_keys(NEW.result))<>4
   OR EXISTS(SELECT 1 FROM unnest(ARRAY['accepted','substances','golems','stage']) k
    WHERE jsonb_typeof(NEW.result->k)<>'number' OR NEW.result->>k !~ '^[0-9]{1,3}$')
   OR NEW.result->>'accepted' !~ '^[0-9]{1,3}$' OR (NEW.result->>'accepted')::integer NOT BETWEEN 1 AND 200
   OR NOT EXISTS(SELECT 1 FROM game_srv7_item_costs cost WHERE cost.transaction_id=NEW.cost_transaction_id
    AND cost.created_xact_id=pg_current_xact_id() AND cost.cause_kind='cake_substance'
    AND cost.game_session_id=NEW.game_session_id AND cost.command_id=NEW.command_id
    AND cost.character_id=NEW.character_id AND cost.world_id=NEW.world_id AND cost.channel_id=c.channel_id
    AND cost.source_key IN ('cake:'||NEW.event_start||':oteryn:npc.balduin_the_baker',
     'cake:'||NEW.event_start||':oteryn:npc.benny_the_baker','cake:'||NEW.event_start||':oteryn:npc.biff_the_baker',
     'cake:'||NEW.event_start||':oteryn:npc.billy_the_baker','cake:'||NEW.event_start||':oteryn:npc.brian_the_baker')
    AND jsonb_array_length(cost.requirements)=1 AND cost.requirements->0->>'family'='Item'
    AND cost.requirements->0->>'key'='oteryn:item.tibia.i12143'
    AND (cost.requirements->0->>'count')::integer=(NEW.result->>'accepted')::integer) THEN
   RAISE EXCEPTION 'Cake delivery requires exact same-transaction substance cost' USING ERRCODE='23514'; END IF;
 ELSE
  IF NEW.channel_id<>c.channel_id OR get_byte(NEW.placement,32)<>0 OR get_byte(NEW.placement,33)<>0
   OR NEW.x<>get_byte(NEW.placement,34)*256+get_byte(NEW.placement,35)
   OR NEW.y<>get_byte(NEW.placement,36)*256+get_byte(NEW.placement,37)
   OR get_byte(NEW.placement,38)<>7 OR get_byte(NEW.placement,39)>=64
   OR NOT EXISTS(SELECT 1 FROM game_cake_terrain_cas_context proof WHERE proof.backend_pid=pg_backend_pid()
    AND proof.transaction_xid=pg_current_xact_id() AND proof.world_id=NEW.world_id AND proof.event_start=NEW.event_start
    AND proof.channel_id=NEW.channel_id AND proof.game_session_id=NEW.game_session_id AND proof.command_id=NEW.command_id
    AND proof.character_id=NEW.character_id AND proof.placement=NEW.placement AND proof.appearance=NEW.appearance)
   OR NOT EXISTS(SELECT 1 FROM game_terrain_tool_receipts r JOIN game_terrain_tool_transforms t
    ON t.world_id=r.world_id AND t.channel_id=r.channel_id AND t.placement=r.placement AND t.reset_epoch=r.reset_epoch
    WHERE r.game_session_id=NEW.game_session_id AND r.command_id=NEW.command_id AND r.character_id=NEW.character_id
     AND r.world_id=NEW.world_id AND r.channel_id=NEW.channel_id AND r.placement=NEW.placement
     AND r.tool_item_instance_id IS NULL AND r.transformed_item_id=0 AND r.created_xact_id=pg_current_xact_id()
     AND t.state_item_id=0 AND t.decay_states='{}'::bigint[] AND t.decay_delays='{}'::bigint[])
   OR NOT EXISTS(SELECT 1 FROM game_durability_reconnect_sessions s WHERE s.game_session_id=NEW.game_session_id
    AND s.character_id=NEW.character_id AND s.world_id=NEW.world_id AND s.session_state IN(1,2)
    AND s.runtime_scope_kind=1 AND s.runtime_scope_channel_id=c.channel_id AND s.scope_ownership_generation=c.generation) THEN
   RAISE EXCEPTION 'Cake bite requires actual current native terrain CAS receipt' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER game_cake_extraction_admit BEFORE INSERT ON game_seasonal_cake_extractions
 FOR EACH ROW EXECUTE FUNCTION game_cake_world_receipt_admit();
CREATE TRIGGER game_cake_delivery_admit BEFORE INSERT ON game_seasonal_cake_deliveries
 FOR EACH ROW EXECUTE FUNCTION game_cake_world_receipt_admit();
CREATE TRIGGER game_cake_bite_admit BEFORE INSERT ON game_seasonal_cake_bite_receipts
 FOR EACH ROW EXECUTE FUNCTION game_cake_world_receipt_admit();

ALTER TABLE game_cake_world_node_context ADD COLUMN validated BOOLEAN NOT NULL DEFAULT FALSE;
CREATE FUNCTION game_cake_world_complete(p_world UUID,p_event BIGINT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_cake_world_node_context%ROWTYPE; w game_seasonal_cake_worlds%ROWTYPE;
 old JSONB; expected JSONB; subst BIGINT; extracted BIGINT; bitten BIGINT; receipts BIGINT;
 stg INTEGER; current_layer INTEGER; progress INTEGER; start_at BIGINT; end_at BIGINT; bonus BIGINT;
 restore BOOLEAN:=FALSE; side game_cake_world_side_context%ROWTYPE; r game_seasonal_cake_bite_receipts%ROWTYPE;
 prior JSONB; after JSONB; expected_bites INTEGER;
BEGIN
 IF game_cake_world_context_is_current(p_world,p_event) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'Cake completion lacks its exact current Node context' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT c FROM game_cake_world_node_context WHERE backend_pid=pg_backend_pid();
 IF c.validated THEN RETURN; END IF;
 SELECT * INTO STRICT w FROM game_seasonal_cake_worlds WHERE world_id=p_world AND event_start=p_event;
 old:=CASE WHEN c.captured THEN c.initial_state ELSE w.state END;
 SELECT coalesce(sum((result->>'accepted')::bigint),0),count(*) INTO subst,receipts
  FROM game_seasonal_cake_deliveries WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id();
 SELECT count(*) FILTER(WHERE counted) INTO extracted FROM game_seasonal_cake_extractions
  WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id();
 SELECT count(*) INTO bitten FROM game_seasonal_cake_bite_receipts
  WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id();
 IF receipts>1 OR extracted>1 OR bitten>1
  OR (SELECT count(*) FROM game_seasonal_cake_extractions WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id())>1
  OR ((subst>0 OR extracted>0 OR bitten>0) AND NOT c.captured)
  OR (c.inserted AND (subst<>0 OR extracted<>0 OR bitten<>0)) THEN
  RAISE EXCEPTION 'Cake progress requires one physical source action and its World write' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM game_seasonal_cake_extractions e WHERE e.world_id=p_world AND e.event_start=p_event
  AND e.created_xact_id=pg_current_xact_id() AND e.counted IS DISTINCT FROM
   ((old->>'stage')::integer=1 AND (old->>'golems')::integer<200 AND c.now_seconds<w.event_end)) THEN
  RAISE EXCEPTION 'Cake extraction count disagrees with exact source stage' USING ERRCODE='23514'; END IF;
 IF NOT c.captured THEN
  IF EXISTS(SELECT 1 FROM game_cake_world_side_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id()) THEN
   RAISE EXCEPTION 'Cake marks require their same-transaction World transition' USING ERRCODE='23514'; END IF;
  UPDATE game_cake_world_node_context SET validated=TRUE WHERE backend_pid=pg_backend_pid(); RETURN;
 END IF;
 expected:=old;
 stg:=(old->>'stage')::integer; current_layer:=(old->>'layer')::integer; progress:=(old->>'layer_progress')::integer;
 start_at:=(old->>'window_start')::bigint; end_at:=(old->>'window_end')::bigint;
 IF c.inserted THEN
  IF w.state<>old THEN RAISE EXCEPTION 'Cake insertion cannot carry progress' USING ERRCODE='23514'; END IF;
 ELSIF c.now_seconds>=w.event_end THEN
  IF subst<>0 OR extracted<>0 OR bitten<>0 THEN RAISE EXCEPTION 'ended Cake occurrence cannot earn progress' USING ERRCODE='23514'; END IF;
  expected:=expected||jsonb_build_object('stage',0,'window_start',NULL,'window_end',NULL);
 ELSIF stg=1 THEN
  IF bitten<>0 OR (old->>'substances')::bigint+subst>200 OR (old->>'golems')::bigint+extracted>200 THEN
   RAISE EXCEPTION 'Cake source counters exceed their stage or goals' USING ERRCODE='23514'; END IF;
  expected:=expected||jsonb_build_object('substances',(old->>'substances')::bigint+subst,'golems',(old->>'golems')::bigint+extracted);
  IF (expected->>'substances')::integer=200 AND (expected->>'golems')::integer=200 THEN expected:=expected||jsonb_build_object('stage',2); END IF;
 ELSIF stg=2 THEN
  IF subst<>0 OR extracted<>0 THEN RAISE EXCEPTION 'Cake harvesting counters are closed' USING ERRCODE='23514'; END IF;
  IF bitten=1 THEN
   IF progress>=1116 OR (end_at IS NOT NULL AND c.now_seconds>=end_at) THEN
    RAISE EXCEPTION 'Cake bite cannot bypass completed or expired round' USING ERRCODE='23514'; END IF;
   start_at:=coalesce(start_at,c.now_seconds);
   expected:=expected||jsonb_build_object('window_start',start_at,'window_end',start_at+1800,'layer_progress',progress+1);
  ELSIF end_at IS NOT NULL AND (c.now_seconds>=end_at OR progress>=1116) THEN
   restore:=progress<1116 OR current_layer<4;
   expected:=expected||jsonb_build_object('window_start',NULL,'window_end',NULL);
   IF progress>=1116 THEN
    IF current_layer=4 THEN
     bonus:=floor(extract(epoch FROM ((date_trunc('day',to_timestamp(c.now_seconds::double precision) AT TIME ZONE 'Europe/Berlin'-interval '6 hours')+interval '1 day 6 hours') AT TIME ZONE 'Europe/Berlin')))::bigint;
     expected:=expected||jsonb_build_object('stage',3,'bonus_from',bonus,'bonus_until',bonus+604800);
    ELSE expected:=expected||jsonb_build_object('layer',current_layer+1,'layer_progress',0); END IF;
   ELSE expected:=expected||jsonb_build_object('layer_progress',0); END IF;
  END IF;
 ELSE
  IF subst<>0 OR extracted<>0 OR bitten<>0 THEN RAISE EXCEPTION 'Cake progress is closed' USING ERRCODE='23514'; END IF;
 END IF;
 IF NOT c.inserted THEN
  IF expected-ARRAY['revision']=old-ARRAY['revision'] THEN
   RAISE EXCEPTION 'Cake World revision requires a real source transition' USING ERRCODE='23514'; END IF;
  expected:=expected||jsonb_build_object('revision',(old->>'revision')::numeric+1);
 END IF;
 IF w.state IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'Cake World final state does not conserve exact source receipts and deadlines' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM game_seasonal_cake_deliveries d WHERE d.world_id=p_world AND d.event_start=p_event
  AND d.created_xact_id=pg_current_xact_id() AND (d.result->'substances' IS DISTINCT FROM expected->'substances'
   OR d.result->'golems' IS DISTINCT FROM expected->'golems' OR d.result->'stage' IS DISTINCT FROM expected->'stage')) THEN
  RAISE EXCEPTION 'Cake delivery result differs from committed World counters' USING ERRCODE='23514'; END IF;
 FOR r IN SELECT * FROM game_seasonal_cake_bite_receipts WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id() LOOP
  IF stg<>2 OR r.layer<>current_layer OR r.window_start<>coalesce((old->>'window_start')::bigint,c.now_seconds)
   OR r.world_revision_before<>(old->>'revision')::numeric OR r.world_revision_after<>(expected->>'revision')::numeric
   OR NOT EXISTS(SELECT 1 FROM game_cake_world_side_context s WHERE s.backend_pid=pg_backend_pid()
    AND s.transaction_xid=pg_current_xact_id() AND s.kind=1 AND s.identity=r.character_id::text)
   OR NOT EXISTS(SELECT 1 FROM game_cake_world_side_context s WHERE s.backend_pid=pg_backend_pid()
    AND s.transaction_xid=pg_current_xact_id() AND s.kind=2 AND s.identity=r.layer||':'||r.x||':'||r.y||':'||r.floor) THEN
   RAISE EXCEPTION 'Cake bite lacks its exact World/personal/physical marks' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR side IN SELECT * FROM game_cake_world_side_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id() LOOP
  prior:=side.before_state; after:=side.after_state;
  IF (after->>'world_id')::uuid<>p_world OR (after->>'event_start')::bigint<>p_event THEN
   RAISE EXCEPTION 'Cake side mark names another occurrence' USING ERRCODE='23514'; END IF;
  IF side.kind=1 THEN
   SELECT * INTO r FROM game_seasonal_cake_bite_receipts b WHERE b.world_id=p_world AND b.event_start=p_event
    AND b.created_xact_id=pg_current_xact_id() AND b.character_id=(after->>'character_id')::uuid;
   expected_bites:=CASE WHEN prior IS NOT NULL AND (prior->>'window_start')::bigint=r.window_start THEN (prior->>'bites')::integer+1 ELSE 1 END;
   IF r.game_session_id IS NULL OR (after->>'window_start')::bigint<>r.window_start
    OR (after->>'last_bite')::bigint<>c.now_seconds OR (after->>'bites')::integer<>expected_bites OR expected_bites>12
    OR (prior IS NOT NULL AND c.now_seconds<(prior->>'last_bite')::bigint+90)
    OR NOT EXISTS(SELECT 1 FROM game_seasonal_cake_bites b WHERE b.character_id=r.character_id
     AND b.world_id=p_world AND b.event_start=p_event AND to_jsonb(b)=after) THEN
    RAISE EXCEPTION 'Cake personal count/cooldown lacks its actual predecessor and bite' USING ERRCODE='23514'; END IF;
  ELSIF (after->>'removed')::boolean THEN
   SELECT * INTO r FROM game_seasonal_cake_bite_receipts b WHERE b.world_id=p_world AND b.event_start=p_event
    AND b.created_xact_id=pg_current_xact_id() AND b.layer=(after->>'layer')::smallint
    AND b.x=(after->>'x')::integer AND b.y=(after->>'y')::integer AND b.floor=(after->>'floor')::smallint;
   IF r.game_session_id IS NULL OR coalesce((prior->>'removed')::boolean,FALSE)
    OR (after->>'window_start')::bigint<>r.window_start OR (after->>'appearance')::integer<>r.appearance THEN
    RAISE EXCEPTION 'Cake removed square lacks its unique physical bite' USING ERRCODE='23514'; END IF;
  ELSE
   IF NOT restore OR prior IS NULL OR (prior->>'removed')::boolean IS DISTINCT FROM TRUE
    OR (after->>'layer')::integer<>current_layer
    OR (after-ARRAY['removed','last_xact_id']) IS DISTINCT FROM (prior-ARRAY['removed','last_xact_id']) THEN
    RAISE EXCEPTION 'Cake restore may touch only current failed/nonfinal completed layer' USING ERRCODE='23514'; END IF;
  END IF;
  IF side.kind=2 AND NOT EXISTS(SELECT 1 FROM game_seasonal_cake_tiles t WHERE t.world_id=p_world AND t.event_start=p_event
   AND t.layer=(after->>'layer')::smallint AND t.x=(after->>'x')::integer AND t.y=(after->>'y')::integer
   AND t.floor=(after->>'floor')::smallint AND to_jsonb(t)=after) THEN
   RAISE EXCEPTION 'Cake physical mark differs from its captured write' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF restore AND EXISTS(SELECT 1 FROM game_seasonal_cake_tiles WHERE world_id=p_world AND event_start=p_event AND game_seasonal_cake_tiles.layer=current_layer AND removed) THEN
  RAISE EXCEPTION 'Cake round restore must restore its entire current layer' USING ERRCODE='23514'; END IF;
 UPDATE game_cake_world_node_context SET validated=TRUE WHERE backend_pid=pg_backend_pid();
END $$;
CREATE FUNCTION game_cake_world_deferred() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN PERFORM game_cake_world_complete(NEW.world_id,NEW.event_start); RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER game_cake_world_complete AFTER INSERT OR UPDATE ON game_seasonal_cake_worlds
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_world_deferred();
CREATE CONSTRAINT TRIGGER game_cake_extraction_complete AFTER INSERT ON game_seasonal_cake_extractions
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_world_deferred();
CREATE CONSTRAINT TRIGGER game_cake_delivery_complete AFTER INSERT ON game_seasonal_cake_deliveries
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_world_deferred();
CREATE CONSTRAINT TRIGGER game_cake_bite_complete AFTER INSERT ON game_seasonal_cake_bite_receipts
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_world_deferred();
CREATE CONSTRAINT TRIGGER game_cake_personal_complete AFTER INSERT OR UPDATE ON game_seasonal_cake_bites
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_world_deferred();
CREATE CONSTRAINT TRIGGER game_cake_tile_complete AFTER INSERT OR UPDATE ON game_seasonal_cake_tiles
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_world_deferred();

-- Every new actual write invalidates a previously forced-immediate check.
CREATE FUNCTION game_cake_world_invalidate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN UPDATE game_cake_world_node_context SET validated=FALSE WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id(); RETURN NEW; END $$;
DO $$ DECLARE t TEXT; f regprocedure; BEGIN
 FOREACH t IN ARRAY ARRAY['game_seasonal_cake_worlds','game_seasonal_cake_extractions','game_seasonal_cake_deliveries',
  'game_seasonal_cake_bite_receipts','game_seasonal_cake_bites','game_seasonal_cake_tiles'] LOOP
  EXECUTE format('CREATE TRIGGER game_cake_z_invalidate BEFORE INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION game_cake_world_invalidate()',t);
 END LOOP;
 FOREACH f IN ARRAY ARRAY['game_cake_world_state_valid(jsonb)'::regprocedure,'game_cake_world_capture()'::regprocedure,
  'game_cake_world_side_capture()'::regprocedure,'game_cake_world_receipt_admit()'::regprocedure,
  'game_cake_world_complete(uuid,bigint)'::regprocedure,'game_cake_world_deferred()'::regprocedure,
  'game_cake_world_invalidate()'::regprocedure] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',f,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_runtime,oteryn_game_control',f);
 END LOOP;
END $$;

-- Only this closed gateway can retain proof that the actual generic CAS ran for Cake.
-- Generic terrain/tool callers and their existing function remain unchanged.
CREATE TABLE game_cake_terrain_cas_context (
 backend_pid INTEGER PRIMARY KEY,transaction_xid XID8 NOT NULL,
 world_id UUID NOT NULL,channel_id UUID NOT NULL,event_start BIGINT NOT NULL,
 game_session_id UUID NOT NULL,command_id NUMERIC(20,0) NOT NULL,character_id UUID NOT NULL,
 placement BYTEA NOT NULL CHECK(octet_length(placement)=40),appearance INTEGER NOT NULL CHECK(appearance IN(12085,12086))
);
REVOKE ALL ON game_cake_terrain_cas_context FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
CREATE FUNCTION game_cake_apply_terrain_tool_transform(
 p_game_session_id UUID,p_command_id NUMERIC,p_character_id UUID,p_tool_item_instance_id UUID,p_intent BYTEA,
 p_world_id UUID,p_channel_id UUID,p_placement BYTEA,p_map_revision TEXT,p_content_generation BYTEA,
 p_reset_epoch BIGINT,p_expected_revision BIGINT,p_before_item_id BIGINT,p_after_item_id BIGINT,
 p_decay_states BIGINT[],p_decay_delays BIGINT[]
) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_cake_world_node_context%ROWTYPE; w game_seasonal_cake_worlds%ROWTYPE; applied BOOLEAN;
BEGIN
 SELECT * INTO c FROM game_cake_world_node_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF c.world_id IS DISTINCT FROM p_world_id OR c.channel_id IS DISTINCT FROM p_channel_id
  OR game_cake_world_context_is_current(p_world_id,c.event_start) IS DISTINCT FROM TRUE
  OR p_tool_item_instance_id IS NOT NULL OR p_before_item_id IS NULL OR p_before_item_id NOT IN(12085,12086)
  OR p_after_item_id IS DISTINCT FROM 0 OR p_decay_states IS NULL OR p_decay_delays IS NULL OR p_placement IS NULL
  OR cardinality(p_decay_states)<>0 OR cardinality(p_decay_delays)<>0 OR octet_length(p_placement)<>40
  OR get_byte(p_placement,32)<>0 OR get_byte(p_placement,33)<>0 OR get_byte(p_placement,38)<>7 OR get_byte(p_placement,39)>=64
  OR get_byte(p_placement,34)*256+get_byte(p_placement,35) NOT BETWEEN 33287 AND 33330
  OR get_byte(p_placement,36)*256+get_byte(p_placement,37) NOT BETWEEN 32065 AND 32103
 THEN RAISE EXCEPTION 'Cake terrain gateway requires exact native tower/Cake/Node source' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT w FROM game_seasonal_cake_worlds WHERE world_id=p_world_id AND event_start=c.event_start FOR UPDATE;
 IF (w.state->>'stage')::integer<>2 OR (w.state->>'layer_progress')::integer>=1116 OR c.now_seconds>=w.event_end
  OR ((w.state->>'window_end') IS NOT NULL AND c.now_seconds>=(w.state->>'window_end')::bigint)
  OR NOT EXISTS(SELECT 1 FROM game_content_activations a WHERE a.world_id=p_world_id AND a.channel_id=p_channel_id
   AND a.server_artifact_digest=p_content_generation AND NOT EXISTS(SELECT 1 FROM game_content_activations later
    WHERE later.world_id=a.world_id AND later.channel_id=a.channel_id AND later.activation_sequence>a.activation_sequence))
  OR NOT EXISTS(SELECT 1 FROM game_durability_reconnect_sessions s
   JOIN game_durability_admission_character_guards g ON g.character_id=s.character_id AND g.account_id=s.account_id
   JOIN game_durability_admission_account_guards account ON account.account_id=g.account_id
   WHERE s.game_session_id=p_game_session_id AND s.character_id=p_character_id AND s.world_id=p_world_id
    AND s.session_state IN(1,2) AND s.runtime_scope_kind=1 AND s.runtime_scope_world_id=p_world_id
    AND s.runtime_scope_channel_id=p_channel_id AND s.scope_ownership_generation=c.generation
    AND g.eligible AND g.lease_generation=s.character_lease_generation AND g.holder_game_session_id=s.game_session_id
    AND account.presence_character_id=g.character_id AND account.holder_game_session_id=s.game_session_id) THEN
  RAISE EXCEPTION 'Cake terrain gateway requires live stage, content and Character' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('oteryn:terrain-scope:'||p_world_id::text||':'||p_channel_id::text,0));
 -- A previous/raw receipt is never upgraded into private Cake source authority.
 IF EXISTS(SELECT 1 FROM game_terrain_tool_receipts WHERE game_session_id=p_game_session_id AND command_id=p_command_id) THEN RETURN FALSE; END IF;
 IF EXISTS(SELECT 1 FROM game_cake_terrain_cas_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id()) THEN
  RAISE EXCEPTION 'Cake terrain gateway accepts one physical bite per transaction' USING ERRCODE='23514'; END IF;
 applied:=game_apply_terrain_tool_transform(p_game_session_id,p_command_id,p_character_id,NULL,p_intent,
  p_world_id,p_channel_id,p_placement,p_map_revision,p_content_generation,p_reset_epoch,p_expected_revision,
  p_before_item_id,p_after_item_id,p_decay_states,p_decay_delays);
 IF NOT applied THEN RETURN FALSE; END IF;
 DELETE FROM game_cake_terrain_cas_context p WHERE p.backend_pid<>pg_backend_pid()
  AND NOT EXISTS(SELECT 1 FROM pg_stat_activity a WHERE a.pid=p.backend_pid);
 INSERT INTO game_cake_terrain_cas_context VALUES(pg_backend_pid(),pg_current_xact_id(),p_world_id,p_channel_id,c.event_start,
  p_game_session_id,p_command_id,p_character_id,p_placement,p_before_item_id)
 ON CONFLICT(backend_pid) DO UPDATE SET transaction_xid=EXCLUDED.transaction_xid,world_id=EXCLUDED.world_id,
  channel_id=EXCLUDED.channel_id,event_start=EXCLUDED.event_start,game_session_id=EXCLUDED.game_session_id,
  command_id=EXCLUDED.command_id,character_id=EXCLUDED.character_id,placement=EXCLUDED.placement,appearance=EXCLUDED.appearance;
 RETURN TRUE;
END $$;
DO $$ BEGIN
 EXECUTE format('ALTER FUNCTION game_cake_apply_terrain_tool_transform(uuid,numeric,uuid,uuid,bytea,uuid,uuid,bytea,text,bytea,bigint,bigint,bigint,bigint,bigint[],bigint[]) SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $$;
REVOKE ALL ON FUNCTION game_cake_apply_terrain_tool_transform(uuid,numeric,uuid,uuid,bytea,uuid,uuid,bytea,text,bytea,bigint,bigint,bigint,bigint,bigint[],bigint[]) FROM PUBLIC,oteryn_game_control;
GRANT EXECUTE ON FUNCTION game_cake_apply_terrain_tool_transform(uuid,numeric,uuid,uuid,bytea,uuid,uuid,bytea,text,bytea,bigint,bigint,bigint,bigint,bigint[],bigint[]) TO oteryn_game_runtime;
CREATE FUNCTION game_cake_terrain_cas_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF NEW.transaction_xid<>pg_current_xact_id() OR NOT EXISTS(SELECT 1 FROM game_seasonal_cake_bite_receipts r
  WHERE r.world_id=NEW.world_id AND r.channel_id=NEW.channel_id AND r.event_start=NEW.event_start
   AND r.game_session_id=NEW.game_session_id AND r.command_id=NEW.command_id AND r.character_id=NEW.character_id
   AND r.placement=NEW.placement AND r.appearance=NEW.appearance AND r.created_xact_id=pg_current_xact_id()) THEN
  RAISE EXCEPTION 'Cake terrain CAS requires its atomic World/personal/physical bite receipt' USING ERRCODE='23514'; END IF;
 PERFORM game_cake_world_complete(NEW.world_id,NEW.event_start); RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_cake_terrain_cas_complete AFTER INSERT OR UPDATE ON game_cake_terrain_cas_context
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_terrain_cas_complete();
DO $$ BEGIN
 EXECUTE format('ALTER FUNCTION game_cake_terrain_cas_complete() SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $$;
REVOKE ALL ON FUNCTION game_cake_terrain_cas_complete() FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;

-- END SRV7 World source conservation.

-- BEGIN SRV7 exact native terrain CAS provenance.
-- Bind the durable bite to the exact native CAS revision/map/content/reset, so a
-- later zero transform cannot be mistaken for this older Cake removal on restart.
ALTER TABLE game_seasonal_cake_bite_receipts
 ADD COLUMN terrain_reset_epoch BIGINT NOT NULL CHECK(terrain_reset_epoch>=0),
 ADD COLUMN terrain_revision_after BIGINT NOT NULL CHECK(terrain_revision_after>0),
 ADD COLUMN terrain_map_revision TEXT NOT NULL CHECK(octet_length(terrain_map_revision) BETWEEN 1 AND 512),
 ADD COLUMN terrain_content_generation BYTEA NOT NULL CHECK(octet_length(terrain_content_generation)=32);
CREATE INDEX game_seasonal_cake_bite_receipts_source ON game_seasonal_cake_bite_receipts
 (world_id,channel_id,event_start,placement,terrain_reset_epoch,world_revision_after DESC);
ALTER TABLE game_cake_terrain_cas_context
 ADD COLUMN terrain_reset_epoch BIGINT NOT NULL,
 ADD COLUMN terrain_revision_after BIGINT NOT NULL,
 ADD COLUMN terrain_map_revision TEXT NOT NULL,
 ADD COLUMN terrain_content_generation BYTEA NOT NULL;
DO $migration$ DECLARE body TEXT; needle TEXT; replacement TEXT; BEGIN
 body:=pg_get_functiondef('game_cake_apply_terrain_tool_transform(uuid,numeric,uuid,uuid,bytea,uuid,uuid,bytea,text,bytea,bigint,bigint,bigint,bigint,bigint[],bigint[])'::regprocedure);
 needle:=$old$ INSERT INTO game_cake_terrain_cas_context VALUES(pg_backend_pid(),pg_current_xact_id(),p_world_id,p_channel_id,c.event_start,
  p_game_session_id,p_command_id,p_character_id,p_placement,p_before_item_id)
 ON CONFLICT(backend_pid) DO UPDATE SET transaction_xid=EXCLUDED.transaction_xid,world_id=EXCLUDED.world_id,
  channel_id=EXCLUDED.channel_id,event_start=EXCLUDED.event_start,game_session_id=EXCLUDED.game_session_id,
  command_id=EXCLUDED.command_id,character_id=EXCLUDED.character_id,placement=EXCLUDED.placement,appearance=EXCLUDED.appearance;$old$;
 replacement:=$new$ INSERT INTO game_cake_terrain_cas_context(backend_pid,transaction_xid,world_id,channel_id,event_start,
  game_session_id,command_id,character_id,placement,appearance,terrain_reset_epoch,terrain_revision_after,terrain_map_revision,terrain_content_generation)
 SELECT pg_backend_pid(),pg_current_xact_id(),p_world_id,p_channel_id,c.event_start,p_game_session_id,p_command_id,p_character_id,
  p_placement,p_before_item_id,t.reset_epoch,t.object_revision,t.map_revision,t.content_generation
 FROM game_terrain_tool_transforms t WHERE t.world_id=p_world_id AND t.channel_id=p_channel_id AND t.placement=p_placement
  AND t.reset_epoch=p_reset_epoch AND t.state_item_id=0
 ON CONFLICT(backend_pid) DO UPDATE SET transaction_xid=EXCLUDED.transaction_xid,world_id=EXCLUDED.world_id,
  channel_id=EXCLUDED.channel_id,event_start=EXCLUDED.event_start,game_session_id=EXCLUDED.game_session_id,
  command_id=EXCLUDED.command_id,character_id=EXCLUDED.character_id,placement=EXCLUDED.placement,appearance=EXCLUDED.appearance,
  terrain_reset_epoch=EXCLUDED.terrain_reset_epoch,terrain_revision_after=EXCLUDED.terrain_revision_after,
  terrain_map_revision=EXCLUDED.terrain_map_revision,terrain_content_generation=EXCLUDED.terrain_content_generation;
 IF NOT FOUND THEN RAISE EXCEPTION 'Cake native CAS result disappeared' USING ERRCODE='23514'; END IF;$new$;
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'missing exact Cake private CAS insert'; END IF;
 EXECUTE replace(body,needle,replacement);
 body:=pg_get_functiondef('game_cake_world_receipt_admit()'::regprocedure);
 needle:=$old$ ELSE
  IF NEW.channel_id<>c.channel_id$old$;
 replacement:=$new$ ELSE
  SELECT proof.terrain_reset_epoch,proof.terrain_revision_after,proof.terrain_map_revision,proof.terrain_content_generation
   INTO NEW.terrain_reset_epoch,NEW.terrain_revision_after,NEW.terrain_map_revision,NEW.terrain_content_generation
   FROM game_cake_terrain_cas_context proof WHERE proof.backend_pid=pg_backend_pid() AND proof.transaction_xid=pg_current_xact_id()
    AND proof.world_id=NEW.world_id AND proof.channel_id=NEW.channel_id AND proof.event_start=NEW.event_start
    AND proof.game_session_id=NEW.game_session_id AND proof.command_id=NEW.command_id AND proof.placement=NEW.placement;
  IF NEW.channel_id<>c.channel_id$new$;
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'missing exact Cake bite source admission'; END IF;
 body:=replace(body,needle,replacement);
 needle:=$old$     AND t.state_item_id=0 AND t.decay_states='{}'::bigint[] AND t.decay_delays='{}'::bigint[])$old$;
 replacement:=$new$     AND t.state_item_id=0 AND t.decay_states='{}'::bigint[] AND t.decay_delays='{}'::bigint[]
     AND t.reset_epoch=NEW.terrain_reset_epoch AND t.object_revision=NEW.terrain_revision_after
     AND t.map_revision=NEW.terrain_map_revision AND t.content_generation=NEW.terrain_content_generation)$new$;
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'missing exact Cake terrain receipt predicate'; END IF;
 EXECUTE replace(body,needle,replacement);
 body:=pg_get_functiondef('game_cake_terrain_cas_complete()'::regprocedure);
 needle:=$old$ IF NEW.transaction_xid<>pg_current_xact_id() OR NOT EXISTS$old$;
 replacement:=$new$ IF NEW.transaction_xid<>pg_current_xact_id() OR NOT EXISTS(SELECT 1 FROM game_terrain_tool_transforms t
  WHERE t.world_id=NEW.world_id AND t.channel_id=NEW.channel_id AND t.placement=NEW.placement
   AND t.reset_epoch=NEW.terrain_reset_epoch AND t.object_revision=NEW.terrain_revision_after
   AND t.map_revision=NEW.terrain_map_revision AND t.content_generation=NEW.terrain_content_generation
   AND t.state_item_id=0 AND t.decay_states='{}'::bigint[] AND t.decay_delays='{}'::bigint[])
  OR NOT EXISTS$new$;
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'missing exact Cake deferred native CAS predicate'; END IF;
 EXECUTE replace(body,needle,replacement);
END $migration$;

-- A forced-immediate check cannot authorize a later raw edit to the same source.
-- All non-Cake terrain writes continue through their existing owners unchanged.
CREATE FUNCTION game_cake_terrain_current_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE p game_cake_terrain_cas_context%ROWTYPE; key JSONB;
BEGIN
 key:=CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 SELECT * INTO p FROM game_cake_terrain_cas_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id()
  AND world_id=(key->>'world_id')::uuid AND channel_id=(key->>'channel_id')::uuid
  AND placement=(key->>'placement')::bytea AND terrain_reset_epoch=(key->>'reset_epoch')::bigint;
 IF FOUND AND NOT EXISTS(SELECT 1 FROM game_terrain_tool_transforms t WHERE t.world_id=p.world_id AND t.channel_id=p.channel_id
  AND t.placement=p.placement AND t.reset_epoch=p.terrain_reset_epoch AND t.object_revision=p.terrain_revision_after
  AND t.map_revision=p.terrain_map_revision AND t.content_generation=p.terrain_content_generation
  AND t.state_item_id=0 AND t.decay_states='{}'::bigint[] AND t.decay_delays='{}'::bigint[]) THEN
  RAISE EXCEPTION 'Cake bite cannot retain progress after a later raw terrain edit' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_cake_terrain_current_complete AFTER INSERT OR UPDATE ON game_terrain_tool_transforms
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_terrain_current_complete();
DO $$ BEGIN
 EXECUTE format('ALTER FUNCTION game_cake_terrain_current_complete() SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $$;
REVOKE ALL ON FUNCTION game_cake_terrain_current_complete() FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;

-- END SRV7 exact native terrain CAS provenance.

-- BEGIN SRV7 Channel-local native terrain repair.
-- Repair this Channel's own zero CAS after the specific global failed/nonfinal
-- round restored its marks. Event cleanup itself never restores eaten Cake.
CREATE TABLE game_seasonal_cake_terrain_restores (
 world_id UUID NOT NULL,channel_id UUID NOT NULL,event_start BIGINT NOT NULL,
 placement BYTEA NOT NULL CHECK(octet_length(placement)=40),reset_epoch BIGINT NOT NULL CHECK(reset_epoch>=0),
 source_game_session_id UUID NOT NULL,source_command_id NUMERIC(20,0) NOT NULL,
 window_start BIGINT NOT NULL,appearance INTEGER NOT NULL CHECK(appearance IN(12085,12086)),
 object_revision_before BIGINT NOT NULL CHECK(object_revision_before>0),
 object_revision_after BIGINT NOT NULL CHECK(object_revision_after=object_revision_before+1),
 map_revision TEXT NOT NULL CHECK(octet_length(map_revision) BETWEEN 1 AND 512),
 content_generation BYTEA NOT NULL CHECK(octet_length(content_generation)=32),
 restored_at BIGINT NOT NULL,created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),
 PRIMARY KEY(world_id,channel_id,event_start,placement,reset_epoch,object_revision_before),
 FOREIGN KEY(source_game_session_id,source_command_id) REFERENCES game_seasonal_cake_bite_receipts,
 FOREIGN KEY(world_id,event_start) REFERENCES game_seasonal_cake_worlds
);
CREATE INDEX game_seasonal_cake_terrain_restores_transaction ON game_seasonal_cake_terrain_restores
 (created_xact_id,world_id,channel_id,placement,reset_epoch);
CREATE TRIGGER game_seasonal_cake_terrain_restores_immutable BEFORE UPDATE OR DELETE ON game_seasonal_cake_terrain_restores
 FOR EACH ROW EXECUTE FUNCTION game_world_reset_history_immutable();
REVOKE ALL ON game_seasonal_cake_terrain_restores FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
GRANT SELECT ON game_seasonal_cake_terrain_restores TO oteryn_game_runtime,oteryn_game_control;
CREATE FUNCTION game_cake_restore_terrain(p_world UUID,p_channel UUID,p_event BIGINT,p_map TEXT,p_content BYTEA,p_reset BIGINT)
RETURNS TABLE(placement BYTEA,object_revision BIGINT,state_item_id BIGINT)
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_cake_world_node_context%ROWTYPE; source RECORD; revision BIGINT;
BEGIN
 SELECT * INTO c FROM game_cake_world_node_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF c.world_id IS DISTINCT FROM p_world OR c.channel_id IS DISTINCT FROM p_channel OR c.event_start IS DISTINCT FROM p_event
  OR game_cake_world_context_is_current(p_world,p_event) IS DISTINCT FROM TRUE
  OR p_reset IS NULL OR p_reset<0 OR p_map IS NULL OR octet_length(p_map) NOT BETWEEN 1 AND 512
  OR p_content IS NULL OR octet_length(p_content)<>32
  OR NOT EXISTS(SELECT 1 FROM game_content_activations a WHERE a.world_id=p_world AND a.channel_id=p_channel
   AND a.server_artifact_digest=p_content AND NOT EXISTS(SELECT 1 FROM game_content_activations later
    WHERE later.world_id=a.world_id AND later.channel_id=a.channel_id AND later.activation_sequence>a.activation_sequence)) THEN
  RAISE EXCEPTION 'Cake terrain restore requires current Node/Channel/Content context' USING ERRCODE='23514'; END IF;
 -- The World lock serializes marks/window successors with both the bite and repair.
 PERFORM 1 FROM game_seasonal_cake_worlds w WHERE w.world_id=p_world AND w.event_start=p_event FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Cake terrain restore lacks its occurrence' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('oteryn:terrain-scope:'||p_world::text||':'||p_channel::text,0));
 FOR source IN
  SELECT t.placement,t.object_revision,b.game_session_id,b.command_id,b.window_start,b.appearance
  FROM game_terrain_tool_transforms t
  JOIN LATERAL(SELECT b.* FROM game_seasonal_cake_bite_receipts b
   WHERE b.world_id=t.world_id AND b.channel_id=t.channel_id AND b.event_start=p_event AND b.placement=t.placement
    AND b.terrain_reset_epoch=t.reset_epoch AND b.terrain_revision_after=t.object_revision
    AND b.terrain_map_revision=t.map_revision AND b.terrain_content_generation=t.content_generation
    AND NOT EXISTS(SELECT 1 FROM game_seasonal_cake_bite_receipts newer WHERE newer.world_id=b.world_id
     AND newer.channel_id=b.channel_id AND newer.event_start=b.event_start AND newer.placement=b.placement
     AND newer.terrain_reset_epoch=b.terrain_reset_epoch AND newer.world_revision_after>b.world_revision_after)
   ORDER BY b.world_revision_after DESC LIMIT 1) b ON TRUE
  JOIN game_terrain_tool_receipts actual ON actual.game_session_id=b.game_session_id AND actual.command_id=b.command_id
   AND actual.character_id=b.character_id AND actual.world_id=b.world_id AND actual.channel_id=b.channel_id
   AND actual.placement=b.placement AND actual.reset_epoch=b.terrain_reset_epoch
   AND actual.tool_item_instance_id IS NULL AND actual.transformed_item_id=0 AND actual.created_xact_id=b.created_xact_id
  JOIN game_seasonal_cake_tiles global ON global.world_id=b.world_id AND global.event_start=b.event_start
   AND global.layer=b.layer AND global.x=b.x AND global.y=b.y AND global.floor=b.floor AND global.appearance=b.appearance
   AND global.window_start>=b.window_start AND NOT global.removed
  WHERE t.world_id=p_world AND t.channel_id=p_channel AND t.map_revision=p_map AND t.content_generation=p_content
   AND t.reset_epoch=p_reset AND t.state_item_id=0 AND t.decay_states='{}'::bigint[] AND t.decay_delays='{}'::bigint[]
   AND t.object_revision<9223372036854775807
  ORDER BY t.placement LIMIT 1716 FOR UPDATE OF t
 LOOP
  UPDATE game_terrain_tool_transforms t SET state_item_id=source.appearance,object_revision=t.object_revision+1
   WHERE t.world_id=p_world AND t.channel_id=p_channel AND t.placement=source.placement AND t.reset_epoch=p_reset
    AND t.object_revision=source.object_revision AND t.state_item_id=0
   RETURNING t.object_revision INTO revision;
  IF NOT FOUND THEN RAISE EXCEPTION 'Cake restore lost its exact native CAS predecessor' USING ERRCODE='23514'; END IF;
  INSERT INTO game_seasonal_cake_terrain_restores(world_id,channel_id,event_start,placement,reset_epoch,
   source_game_session_id,source_command_id,window_start,appearance,object_revision_before,object_revision_after,
   map_revision,content_generation,restored_at)
  VALUES(p_world,p_channel,p_event,source.placement,p_reset,source.game_session_id,source.command_id,source.window_start,
   source.appearance,source.object_revision,revision,p_map,p_content,c.now_seconds);
  placement:=source.placement; object_revision:=revision; state_item_id:=source.appearance; RETURN NEXT;
 END LOOP;
END $$;
CREATE FUNCTION game_cake_terrain_restore_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF NEW.created_xact_id<>pg_current_xact_id() OR game_cake_world_context_is_current(NEW.world_id,NEW.event_start) IS DISTINCT FROM TRUE
  OR NOT EXISTS(SELECT 1 FROM game_cake_world_node_context c WHERE c.backend_pid=pg_backend_pid()
   AND c.transaction_xid=pg_current_xact_id() AND c.channel_id=NEW.channel_id AND c.now_seconds=NEW.restored_at)
  OR NOT EXISTS(SELECT 1 FROM game_terrain_tool_transforms t WHERE t.world_id=NEW.world_id AND t.channel_id=NEW.channel_id
   AND t.placement=NEW.placement AND t.reset_epoch=NEW.reset_epoch AND t.map_revision=NEW.map_revision
   AND t.content_generation=NEW.content_generation AND t.object_revision=NEW.object_revision_after
   AND t.state_item_id=NEW.appearance AND t.decay_states='{}'::bigint[] AND t.decay_delays='{}'::bigint[]) THEN
  RAISE EXCEPTION 'Cake physical restore lacks its exact source CAS/current Node receipt' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_cake_terrain_restore_complete AFTER INSERT ON game_seasonal_cake_terrain_restores
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_terrain_restore_complete();
DO $$ DECLARE f regprocedure; BEGIN
 FOREACH f IN ARRAY ARRAY['game_cake_restore_terrain(uuid,uuid,bigint,text,bytea,bigint)'::regprocedure,
  'game_cake_terrain_restore_complete()'::regprocedure] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',f,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_runtime,oteryn_game_control',f);
 END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION game_cake_restore_terrain(uuid,uuid,bigint,text,bytea,bigint) TO oteryn_game_runtime;
CREATE FUNCTION game_cake_terrain_restore_current_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE key JSONB;
BEGIN
 key:=CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
 IF EXISTS(SELECT 1 FROM game_seasonal_cake_terrain_restores r WHERE r.created_xact_id=pg_current_xact_id()
  AND r.world_id=(key->>'world_id')::uuid AND r.channel_id=(key->>'channel_id')::uuid
  AND r.placement=(key->>'placement')::bytea AND r.reset_epoch=(key->>'reset_epoch')::bigint
  AND NOT EXISTS(SELECT 1 FROM game_terrain_tool_transforms t WHERE t.world_id=r.world_id AND t.channel_id=r.channel_id
   AND t.placement=r.placement AND t.reset_epoch=r.reset_epoch AND t.map_revision=r.map_revision
   AND t.content_generation=r.content_generation AND t.object_revision=r.object_revision_after
   AND t.state_item_id=r.appearance AND t.decay_states='{}'::bigint[] AND t.decay_delays='{}'::bigint[])) THEN
  RAISE EXCEPTION 'Cake restore cannot authorize a later raw terrain edit' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_cake_terrain_restore_current_complete AFTER INSERT OR UPDATE ON game_terrain_tool_transforms
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_terrain_restore_current_complete();
DO $$ BEGIN
 EXECUTE format('ALTER FUNCTION game_cake_terrain_restore_current_complete() SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $$;
REVOKE ALL ON FUNCTION game_cake_terrain_restore_current_complete() FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;

-- END SRV7 Channel-local native terrain repair.

-- BEGIN SRV7 source first-use window before cooldown.
-- Crystal actions_cake_bite.lua:9-11 opens a round before personal cooldown/limit
-- refusal. A window-only source action changes no terrain, personal count or progress.
CREATE TABLE game_seasonal_cake_window_starts (
 game_session_id UUID NOT NULL REFERENCES game_durability_reconnect_sessions,
 command_id NUMERIC(20,0) NOT NULL CHECK(command_id BETWEEN 1 AND 18446744073709551615),
 character_id UUID NOT NULL REFERENCES game_character_roots,
 intent BYTEA NOT NULL CHECK(octet_length(intent) BETWEEN 1 AND 4096),
 world_id UUID NOT NULL,channel_id UUID NOT NULL,event_start BIGINT NOT NULL,
 placement BYTEA NOT NULL CHECK(octet_length(placement)=40),appearance INTEGER NOT NULL CHECK(appearance IN(12085,12086)),
 window_start BIGINT NOT NULL CHECK(window_start>=event_start),
 world_revision_before NUMERIC(20,0) NOT NULL CHECK(world_revision_before>0),
 world_revision_after NUMERIC(20,0) NOT NULL CHECK(world_revision_after=world_revision_before+1),
 created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),PRIMARY KEY(game_session_id,command_id),
 FOREIGN KEY(world_id,event_start) REFERENCES game_seasonal_cake_worlds
);
CREATE INDEX game_seasonal_cake_window_starts_world ON game_seasonal_cake_window_starts(world_id,event_start,created_xact_id);
CREATE TRIGGER game_seasonal_cake_window_starts_immutable BEFORE UPDATE OR DELETE ON game_seasonal_cake_window_starts
 FOR EACH ROW EXECUTE FUNCTION game_world_reset_history_immutable();
REVOKE ALL ON game_seasonal_cake_window_starts FROM PUBLIC;
GRANT SELECT,INSERT ON game_seasonal_cake_window_starts TO oteryn_game_runtime;
GRANT SELECT ON game_seasonal_cake_window_starts TO oteryn_game_control;
CREATE FUNCTION game_cake_window_start_admit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_cake_world_node_context%ROWTYPE; previous JSONB; ending BIGINT;
BEGIN
 IF game_cake_world_context_is_current(NEW.world_id,NEW.event_start) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'Cake window start requires current source Node context' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT c FROM game_cake_world_node_context WHERE backend_pid=pg_backend_pid();
 SELECT CASE WHEN c.captured THEN c.initial_state ELSE w.state END,w.event_end INTO previous,ending
  FROM game_seasonal_cake_worlds w WHERE w.world_id=NEW.world_id AND w.event_start=NEW.event_start;
 IF NEW.channel_id<>c.channel_id OR NEW.window_start<>c.now_seconds OR c.now_seconds>=ending
  OR (previous->>'stage')::integer<>2 OR previous->'window_start'<>'null'::jsonb OR (previous->>'layer_progress')::integer<>0
  OR NEW.world_revision_before<>(previous->>'revision')::numeric
  OR get_byte(NEW.placement,32)<>0 OR get_byte(NEW.placement,33)<>0 OR get_byte(NEW.placement,38)<>7 OR get_byte(NEW.placement,39)>=64
  OR get_byte(NEW.placement,34)*256+get_byte(NEW.placement,35) NOT BETWEEN 33287 AND 33330
  OR get_byte(NEW.placement,36)*256+get_byte(NEW.placement,37) NOT BETWEEN 32065 AND 32103
  OR NOT EXISTS(SELECT 1 FROM game_seasonal_cake_bites b WHERE b.character_id=NEW.character_id
   AND b.world_id=NEW.world_id AND b.event_start=NEW.event_start AND b.last_bite+90>c.now_seconds)
  OR NOT EXISTS(SELECT 1 FROM game_durability_reconnect_sessions s
   JOIN game_durability_admission_character_guards g ON g.character_id=s.character_id AND g.account_id=s.account_id
   JOIN game_durability_admission_account_guards account ON account.account_id=g.account_id
   WHERE s.game_session_id=NEW.game_session_id AND s.character_id=NEW.character_id AND s.world_id=NEW.world_id
    AND s.session_state IN(1,2) AND s.runtime_scope_kind=1 AND s.runtime_scope_world_id=NEW.world_id
    AND s.runtime_scope_channel_id=c.channel_id AND s.scope_ownership_generation=c.generation
    AND g.eligible AND g.lease_generation=s.character_lease_generation AND g.holder_game_session_id=s.game_session_id
    AND account.presence_character_id=g.character_id AND account.holder_game_session_id=s.game_session_id) THEN
  RAISE EXCEPTION 'Cake window start requires exact current stage/native tower/session source' USING ERRCODE='23514'; END IF;
 NEW.created_xact_id:=pg_current_xact_id(); RETURN NEW;
END $$;
CREATE TRIGGER game_cake_window_start_admit BEFORE INSERT ON game_seasonal_cake_window_starts
 FOR EACH ROW EXECUTE FUNCTION game_cake_window_start_admit();
CREATE TRIGGER game_cake_z_invalidate BEFORE INSERT ON game_seasonal_cake_window_starts
 FOR EACH ROW EXECUTE FUNCTION game_cake_world_invalidate();
CREATE CONSTRAINT TRIGGER game_cake_window_start_complete AFTER INSERT ON game_seasonal_cake_window_starts
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_world_deferred();
DO $migration$ DECLARE body TEXT; needle TEXT; replacement TEXT; BEGIN
 body:=pg_get_functiondef('game_cake_world_complete(uuid,bigint)'::regprocedure);
 needle:=' stg INTEGER; current_layer INTEGER;'; replacement:=' opened BIGINT; stg INTEGER; current_layer INTEGER;';
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'missing exact Cake World transition variables'; END IF;
 body:=replace(body,needle,replacement);
 needle:=$old$ IF receipts>1 OR extracted>1 OR bitten>1$old$;
 replacement:=$new$ SELECT count(*) INTO opened FROM game_seasonal_cake_window_starts
  WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id();
 IF opened>1 OR (opened>0 AND (receipts>0 OR extracted>0 OR bitten>0))
  OR receipts>1 OR extracted>1 OR bitten>1$new$;
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'missing exact Cake physical source action bound'; END IF;
 body:=replace(body,needle,replacement);
 body:=replace(body,'((subst>0 OR extracted>0 OR bitten>0) AND NOT c.captured)',
  '((subst>0 OR extracted>0 OR bitten>0 OR opened>0) AND NOT c.captured)');
 body:=replace(body,'(c.inserted AND (subst<>0 OR extracted<>0 OR bitten<>0))',
  '(c.inserted AND (subst<>0 OR extracted<>0 OR bitten<>0 OR opened<>0))');
 body:=replace(body,'IF subst<>0 OR extracted<>0 OR bitten<>0 THEN',
  'IF subst<>0 OR extracted<>0 OR bitten<>0 OR opened<>0 THEN');
 body:=replace(body,'IF bitten<>0 OR (old->>''substances'')::bigint+subst>200',
  'IF bitten<>0 OR opened<>0 OR (old->>''substances'')::bigint+subst>200');
 needle:=$old$  IF bitten=1 THEN$old$;
 replacement:=$new$  IF opened=1 THEN
   IF start_at IS NOT NULL OR progress<>0 THEN
    RAISE EXCEPTION 'Cake window cannot restart or erase an active round' USING ERRCODE='23514'; END IF;
   expected:=expected||jsonb_build_object('window_start',c.now_seconds,'window_end',c.now_seconds+1800);
  ELSIF bitten=1 THEN$new$;
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'missing exact Cake bite/window transition'; END IF;
 body:=replace(body,needle,replacement);
 needle:=$old$ FOR r IN SELECT * FROM game_seasonal_cake_bite_receipts$old$;
 replacement:=$new$ IF EXISTS(SELECT 1 FROM game_seasonal_cake_window_starts opening WHERE opening.world_id=p_world AND opening.event_start=p_event
  AND opening.created_xact_id=pg_current_xact_id() AND (opening.world_revision_before<>(old->>'revision')::numeric
   OR opening.world_revision_after<>(expected->>'revision')::numeric OR opening.window_start<>c.now_seconds)) THEN
  RAISE EXCEPTION 'Cake window receipt differs from its exact World transition' USING ERRCODE='23514'; END IF;
 FOR r IN SELECT * FROM game_seasonal_cake_bite_receipts$new$;
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'missing exact Cake receipt conservation tail'; END IF;
 EXECUTE replace(body,needle,replacement);
END $migration$;
DO $$ BEGIN
 EXECUTE format('ALTER FUNCTION game_cake_window_start_admit() SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $$;
REVOKE ALL ON FUNCTION game_cake_window_start_admit() FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;

-- END SRV7 source first-use window before cooldown.

-- SRV7 W05d native Cake raid source cadence survives a Channel owner restart.
CREATE TABLE game_seasonal_cake_raid_slots (
    world_id UUID NOT NULL,
    channel_id UUID NOT NULL,
    event_start BIGINT NOT NULL,
    slot SMALLINT NOT NULL CHECK(slot BETWEEN 0 AND 143),
    claimed_at BIGINT NOT NULL,
    created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),
    PRIMARY KEY(world_id,channel_id,event_start,slot),
    FOREIGN KEY(world_id,event_start) REFERENCES game_seasonal_cake_worlds,
    CHECK(claimed_at >= event_start+3600+slot*3600 AND claimed_at < event_start+3600+(slot+1)*3600)
);
CREATE TRIGGER game_seasonal_cake_raid_slots_immutable BEFORE UPDATE OR DELETE ON game_seasonal_cake_raid_slots
FOR EACH ROW EXECUTE FUNCTION game_world_reset_history_immutable();
REVOKE ALL ON game_seasonal_cake_raid_slots FROM PUBLIC;
GRANT SELECT,INSERT ON game_seasonal_cake_raid_slots TO oteryn_game_runtime;
GRANT SELECT ON game_seasonal_cake_raid_slots TO oteryn_game_control;
CREATE FUNCTION game_cake_raid_slot_admit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_cake_world_node_context%ROWTYPE; w game_seasonal_cake_worlds%ROWTYPE;
BEGIN
 IF game_cake_world_context_is_current(NEW.world_id,NEW.event_start) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'Cake raid slot requires current Node authority' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT c FROM game_cake_world_node_context WHERE backend_pid=pg_backend_pid();
 SELECT * INTO STRICT w FROM game_seasonal_cake_worlds WHERE world_id=NEW.world_id AND event_start=NEW.event_start;
 IF NEW.channel_id<>c.channel_id OR NEW.claimed_at<>c.now_seconds OR c.now_seconds>=w.event_end
  OR (w.state->>'stage')::integer<>1 THEN
  RAISE EXCEPTION 'Cake raid slot is outside current source stage/clock' USING ERRCODE='23514'; END IF;
 NEW.created_xact_id:=pg_current_xact_id(); RETURN NEW;
END $$;
CREATE TRIGGER game_cake_raid_slot_admit BEFORE INSERT ON game_seasonal_cake_raid_slots
FOR EACH ROW EXECUTE FUNCTION game_cake_raid_slot_admit();
REVOKE ALL ON FUNCTION game_cake_raid_slot_admit() FROM PUBLIC;

-- Carried costs include worn items; invalidate their durable equipment snapshot.
ALTER TABLE game_srv7_item_costs ADD COLUMN equipment_revision_before NUMERIC(20,0)
 CHECK(equipment_revision_before BETWEEN 1 AND 18446744073709551614);
DO $migration$ DECLARE body TEXT; needle TEXT; BEGIN
 body:=pg_get_functiondef('game_srv7_cost_admit()'::regprocedure);
 needle:=' NEW.created_xact_id:=pg_current_xact_id();';
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'missing closed cost admission stamp'; END IF;
 EXECUTE replace(body,needle,$new$ IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.inputs) AS cost_input(value) WHERE cost_input.value->>'kind'='equipment') THEN
  SELECT revision INTO STRICT NEW.equipment_revision_before FROM game_character_equipment_state
   WHERE character_id=NEW.character_id FOR UPDATE;
 ELSE NEW.equipment_revision_before:=NULL; END IF;
 NEW.created_xact_id:=pg_current_xact_id();$new$);
 body:=pg_get_functiondef('game_srv7_cost_complete()'::regprocedure);
 needle:=' IF NEW.cause_kind=''npc_cosmetic'' THEN';
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'missing closed cost domain receipt check'; END IF;
 EXECUTE replace(body,needle,$new$ IF NEW.equipment_revision_before IS NOT NULL AND NOT EXISTS(
  SELECT 1 FROM game_character_equipment_state s WHERE s.character_id=NEW.character_id
   AND s.revision=NEW.equipment_revision_before+1 AND s.last_transaction_id=NEW.transaction_id) THEN
  RAISE EXCEPTION 'worn item cost lacks exact equipment successor' USING ERRCODE='23514'; END IF;
 IF NEW.cause_kind='npc_cosmetic' THEN$new$);
 body:=pg_get_functiondef('game_equipment_state_proven()'::regprocedure);
 needle:=E'BEGIN\n';
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'unexpected equipment proof body'; END IF;
 EXECUTE replace(body,needle,$new$BEGIN
 IF EXISTS(SELECT 1 FROM game_srv7_item_costs r WHERE r.transaction_id=NEW.last_transaction_id
  AND r.character_id=NEW.character_id AND r.created_xact_id=pg_current_xact_id()
  AND r.equipment_revision_before=OLD.revision AND NEW.revision=OLD.revision+1
  AND (to_jsonb(NEW)-ARRAY['revision','last_transaction_id'])=(to_jsonb(OLD)-ARRAY['revision','last_transaction_id'])) THEN RETURN NULL; END IF;
$new$);
END $migration$;

-- SRV7 closed Santa gift actions.
-- Closed Santa gift leaves; all other consume/transform contracts remain unchanged.
CREATE FUNCTION game_santa_gift_record(r game_item_consume_transform_records) RETURNS BOOLEAN
LANGUAGE sql IMMUTABLE AS $$
 SELECT r.recipe IN('oteryn:novelty-item.i2995.v1','oteryn:novelty-item.i5080.v1','oteryn:novelty-item.i6511.v1','oteryn:novelty-item.i5791.v1','oteryn:novelty-item.i6566.v1')
  AND r.before_item->>'definition_production_key'='oteryn:item.tibia.i'||(r.effects->>'source_item_id')
  AND r.recipe='oteryn:novelty-item.i'||(r.effects->>'source_item_id')||'.v1'
$$;
CREATE FUNCTION game_santa_gift_custody(r game_item_consume_transform_records) RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT CASE WHEN r.source_kind=5 THEN game_item_action_house_custody(r)
 WHEN r.source_kind IN(1,4) THEN game_item_action_furniture_custody(r)
 WHEN r.source_kind=3 THEN game_item_action_custody_current(r) ELSE FALSE END
$$;
-- Actual House actor/source positions are sealed by its current Node, not supplied
-- by a later runtime receipt which could choose a convenient actor_position.
CREATE TABLE game_santa_house_source_context(
 backend_pid INTEGER PRIMARY KEY,transaction_xid XID8 NOT NULL,node_id UUID NOT NULL,registration NUMERIC NOT NULL,
 character_id UUID NOT NULL,game_session_id UUID NOT NULL,command_id NUMERIC NOT NULL,connection NUMERIC NOT NULL,lease NUMERIC NOT NULL,generation NUMERIC NOT NULL,
 world_id UUID NOT NULL,house_key TEXT NOT NULL,source_item UUID NOT NULL,actor_position JSONB NOT NULL,source_position JSONB NOT NULL);
REVOKE ALL ON game_santa_house_source_context FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
CREATE FUNCTION game_santa_arm_house_source(p_node UUID,p_registration NUMERIC,p_secret BYTEA,p_character UUID,p_session UUID,p_command NUMERIC,
 p_connection NUMERIC,p_lease NUMERIC,p_generation NUMERIC,p_world UUID,p_house TEXT,p_source UUID,p_actor JSONB,p_at JSONB)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF game_node_prove_current_incarnation(p_node,p_registration,p_secret) IS DISTINCT FROM TRUE
  OR p_command IS NULL OR p_command<>trunc(p_command) OR p_command NOT BETWEEN 1 AND 18446744073709551615
  OR p_source IS NULL OR p_house IS NULL OR octet_length(p_house) NOT BETWEEN 1 AND 256
  OR (jsonb_typeof(p_actor)='array' AND jsonb_array_length(p_actor)=3 AND jsonb_typeof(p_at)='array' AND jsonb_array_length(p_at)=3) IS DISTINCT FROM TRUE
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_actor||p_at) value WHERE jsonb_typeof(value)<>'number' OR value::text !~ '^-?[0-9]{1,10}$'
   OR value::text::bigint NOT BETWEEN -2147483648 AND 2147483647)
  OR (p_actor->>2)::integer IS DISTINCT FROM (p_at->>2)::integer
  OR abs((p_actor->>0)::bigint-(p_at->>0)::bigint)>1 OR abs((p_actor->>1)::bigint-(p_at->>1)::bigint)>1 THEN
  RAISE EXCEPTION 'Santa House source lacks current private Node and actual actor adjacency' USING ERRCODE='23514'; END IF;
 PERFORM game_house_podium_fence(p_session,p_character,p_connection,p_lease,p_generation,p_node,p_registration,p_world,p_house);
 IF EXISTS(SELECT 1 FROM game_santa_house_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id()) THEN
  RAISE EXCEPTION 'Santa House source accepts one immutable native observation' USING ERRCODE='23514'; END IF;
 DELETE FROM game_santa_house_source_context c WHERE c.backend_pid=pg_backend_pid() OR NOT EXISTS(SELECT 1 FROM pg_stat_activity a WHERE a.pid=c.backend_pid);
 INSERT INTO game_santa_house_source_context VALUES(pg_backend_pid(),pg_current_xact_id(),p_node,p_registration,p_character,p_session,p_command,
  p_connection,p_lease,p_generation,p_world,p_house,p_source,p_actor,p_at);
END $$;
DO $$ BEGIN EXECUTE format('ALTER FUNCTION game_santa_arm_house_source(uuid,numeric,bytea,uuid,uuid,numeric,numeric,numeric,numeric,uuid,text,uuid,jsonb,jsonb) SET search_path=pg_catalog,%I,pg_temp',current_schema()); END $$;
REVOKE ALL ON FUNCTION game_santa_arm_house_source(uuid,numeric,bytea,uuid,uuid,numeric,numeric,numeric,numeric,uuid,text,uuid,jsonb,jsonb) FROM PUBLIC,oteryn_game_control;
GRANT EXECUTE ON FUNCTION game_santa_arm_house_source(uuid,numeric,bytea,uuid,uuid,numeric,numeric,numeric,numeric,uuid,text,uuid,jsonb,jsonb) TO oteryn_game_runtime;

-- Same closed one-tile action distance as the native House actor/placed source.
-- Custody independently compares this location with the real locked item row.
CREATE FUNCTION game_santa_gift_adjacent(r game_item_consume_transform_records) RETURNS BOOLEAN
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE at JSONB:=r.effects->'ground'; actor JSONB:=r.source_location->'actor_position';
BEGIN
 IF r.source_kind<>5 OR coalesce(r.source_location->>'custody_kind','house')<>'house' THEN RETURN TRUE; END IF;
 IF jsonb_typeof(at) IS DISTINCT FROM 'object' OR jsonb_typeof(actor) IS DISTINCT FROM 'array'
  OR jsonb_array_length(actor)<>3 THEN RETURN FALSE; END IF;
 RETURN ((r.source_location->'house'->>'spatial_position')::bytea =
   int4send((at->>'x')::integer)||int4send((at->>'y')::integer)||int4send((at->>'floor')::integer))
  AND (at->>'floor')::integer=(actor->>2)::integer
  AND abs((at->>'x')::bigint-(actor->>0)::bigint)<=1
  AND abs((at->>'y')::bigint-(actor->>1)::bigint)<=1;
END $$;
CREATE FUNCTION game_santa_gift_effects_valid(r game_item_consume_transform_records) RETURNS BOOLEAN
LANGUAGE sql IMMUTABLE AS $$
 SELECT r.effects->>'kind'='consume_effect'
  AND r.effects->>'donor'='crystal-201189f871d23597b82caf88fd611454a2ddefb8:data/scripts/actions/items/'||CASE WHEN r.effects->>'source_item_id'='2995' THEN 'piggy_bank.lua:3-13' WHEN r.effects->>'source_item_id'='6511' THEN 'dolls.lua:23-30,111-149' ELSE 'dolls.lua:2,15-21,111-149' END
  AND r.effects->'private_speech'='false'::jsonb AND r.effects->'require_head'='false'::jsonb
  AND r.effects->'require_player_target'='false'::jsonb
  AND NOT (r.effects ?| ARRAY['dice_value','costume','achievement','timed_output'])
  AND CASE (CASE WHEN r.effects->>'source_item_id'='5791' THEN '6566' ELSE r.effects->>'source_item_id' END)
  WHEN '2995' THEN NOT(r.effects ? 'speech') AND NOT(r.effects ? 'damage')
   AND r.effects->'cues'=CASE r.effects->>'gift_currency'
    WHEN '3031' THEN '[{"binding":"appearance:effect/poff","effect_id":3}]'::jsonb
    WHEN '3035' THEN '[{"binding":"appearance:effect/sound_yellow","effect_id":22}]'::jsonb END
  WHEN '5080' THEN r.effects->>'speech'='Hug me!' AND NOT(r.effects ? 'damage') AND r.effects->'cues'='[]'::jsonb
  WHEN '6511' THEN r.effects->>'speech'=ANY(ARRAY['Ho ho ho','Jingle bells, jingle bells...','Have you been naughty?','Have you been nice?','Merry Christmas!','Can you stop squeezing me now... I''m starting to feel a little sick.']) AND NOT(r.effects ? 'damage') AND r.effects->'cues'='[]'::jsonb
  WHEN '6566' THEN CASE r.effects->>'speech'
   WHEN 'Fchhhhhh!' THEN NOT(r.effects ? 'damage') AND r.effects->'cues'='[]'::jsonb
   WHEN 'Zchhhhhh!' THEN NOT(r.effects ? 'damage') AND r.effects->'cues'='[]'::jsonb
   WHEN 'Groaaarrr.... *cough*' THEN NOT(r.effects ? 'damage') AND r.effects->'cues'='[{"binding":"appearance:effect/poff","effect_id":3}]'::jsonb
   WHEN 'Aaa... CHOO!' THEN NOT(r.effects ? 'damage') AND r.effects->'cues'='[{"binding":"appearance:effect/firearea","effect_id":7}]'::jsonb
   WHEN 'You... will.... burn!!' THEN r.effects->'damage'='1'::jsonb AND r.effects->'cues'='[{"binding":"appearance:effect/explosionhit","effect_id":6}]'::jsonb
   ELSE FALSE END
  ELSE FALSE END
$$;
-- Same native SHA256 domain and unsigned network-order fields. Resource bound
-- fails closed instead of accepting a different draw if sixteen rejections occur.
CREATE FUNCTION game_santa_gift_draw(p_session UUID,p_command NUMERIC,p_source UUID,p_domain INTEGER,p_upper INTEGER)
RETURNS INTEGER LANGUAGE plpgsql IMMUTABLE STRICT AS $$
DECLARE command_bytes BYTEA; digest BYTEA; value NUMERIC; zone NUMERIC; counter INTEGER; n INTEGER;
BEGIN
 IF p_command<>trunc(p_command) OR p_command NOT BETWEEN 1 AND 18446744073709551615 OR (p_domain,p_upper) NOT IN((210,6),(211,5),(212,6)) THEN
  RAISE EXCEPTION 'invalid closed Santa RNG domain' USING ERRCODE='23514'; END IF;
 command_bytes:=int8send((CASE WHEN p_command>9223372036854775807 THEN p_command-18446744073709551616 ELSE p_command END)::bigint);
 zone:=18446744073709551615-mod(18446744073709551615,p_upper);
 FOR counter IN 0..15 LOOP
  digest:=sha256(convert_to('oteryn:reward-bag-draw:v1','UTF8')||uuid_send(p_session)||command_bytes
   ||uuid_send(p_source)||set_byte(decode('00','hex'),0,p_domain)||int4send(counter));
  value:=0;
  FOR n IN 0..7 LOOP value:=value*256+get_byte(digest,n); END LOOP;
  IF value<zone THEN RETURN mod(value,p_upper)::integer; END IF;
 END LOOP;
 RAISE EXCEPTION 'Santa RNG rejection resource bound' USING ERRCODE='23514';
END $$;
CREATE FUNCTION game_santa_gift_admit(r game_item_consume_transform_records) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE i game_item_instances%ROWTYPE; o JSONB; parent UUID; node UUID; node_revision NUMERIC;
BEGIN
 SELECT * INTO i FROM game_item_instances WHERE item_instance_id=r.source_item_instance_id FOR UPDATE;
 IF game_santa_gift_record(r) IS DISTINCT FROM TRUE OR i.item_instance_id IS NULL
  OR to_jsonb(i) IS DISTINCT FROM r.before_item OR r.before_secondary IS DISTINCT FROM r.before_item
  OR r.secondary_item_instance_id IS DISTINCT FROM r.source_item_instance_id OR r.source_kind NOT IN(1,3,4,5)
  OR r.consume_source OR r.source_count<>0 OR r.extra_inputs<>'[]'::jsonb
  OR i.lifecycle<>1 OR i.quantity<>1 OR i.world_id<>r.world_id OR i.definition_family<>'Item'
  OR game_santa_gift_adjacent(r) IS DISTINCT FROM TRUE
  OR game_santa_gift_effects_valid(r) IS DISTINCT FROM TRUE OR r.content_digest IS NULL
  OR game_santa_gift_custody(r) IS DISTINCT FROM TRUE
  OR EXISTS(SELECT 1 FROM game_item_keys WHERE item_instance_id=i.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=i.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_texts WHERE item_instance_id=i.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_imbuements WHERE item_instance_id=i.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_container_entries WHERE parent_item_instance_id=i.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_nested_entries WHERE parent_item_instance_id=i.item_instance_id)
 THEN RAISE EXCEPTION 'Santa gift requires exact unchanged plain source and custody' USING ERRCODE='23514'; END IF;
 node:=(r.effects->'gift_node'->>'id')::uuid;
 node_revision:=(r.effects->'gift_node'->>'revision')::numeric;
 IF node IS NULL OR node_revision IS NULL OR game_runtime_scope_assignment_history_valid() IS DISTINCT FROM TRUE
  OR game_node_lock_current_registration(node,node_revision) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'Santa gift requires current Node registration' USING ERRCODE='23514'; END IF;
 IF r.source_kind=5 THEN
  IF node IS DISTINCT FROM (r.source_location->>'node')::uuid
   OR node_revision IS DISTINCT FROM (r.source_location->>'node_revision')::numeric THEN
   RAISE EXCEPTION 'Santa gift House Node mismatch' USING ERRCODE='23514'; END IF;
  IF NOT EXISTS(SELECT 1 FROM game_santa_house_source_context c WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id()
   AND (c.node_id,c.registration,c.character_id,c.game_session_id,c.world_id,c.house_key,c.source_item,c.actor_position,c.source_position)
   IS NOT DISTINCT FROM(node,node_revision,r.character_id,r.game_session_id,r.world_id,r.source_location->'house'->>'house_key',r.source_item_instance_id,
    r.source_location->'actor_position',jsonb_build_array((r.effects->'ground'->>'x')::integer,(r.effects->'ground'->>'y')::integer,(r.effects->'ground'->>'floor')::integer))
   AND c.command_id=r.command_id AND c.connection=(r.audit_context->>'connection_generation')::numeric AND c.lease=(r.audit_context->>'lease_generation')::numeric
   AND c.generation=(r.audit_context->>'scope_generation')::numeric) THEN
   RAISE EXCEPTION 'Santa House receipt differs from private native source observation' USING ERRCODE='23514'; END IF;
  PERFORM game_house_podium_fence(r.game_session_id,r.character_id,
   (r.audit_context->>'connection_generation')::numeric,(r.audit_context->>'lease_generation')::numeric,
   (r.audit_context->>'scope_generation')::numeric,node,node_revision,r.world_id,r.source_location->'house'->>'house_key');
 ELSE
  IF node IS NULL OR node_revision IS NULL
   OR game_runtime_scope_assignment_history_valid() IS DISTINCT FROM TRUE
   OR game_node_lock_current_registration(node,node_revision) IS DISTINCT FROM TRUE
   OR NOT EXISTS(SELECT 1 FROM game_durability_reconnect_sessions s
    JOIN game_durability_admission_character_guards c ON c.character_id=s.character_id AND c.account_id=s.account_id
    JOIN game_durability_admission_account_guards a ON a.account_id=c.account_id
    JOIN game_runtime_scope_assignments runtime ON runtime.scope_kind=1 AND runtime.world_id=r.world_id
     AND runtime.channel_id=s.runtime_scope_channel_id
    JOIN game_durability_admission_runtime_guards g ON g.scope_key=runtime.scope_key
    WHERE s.game_session_id=r.game_session_id AND s.character_id=r.character_id AND s.world_id=r.world_id
     AND s.session_state IN(1,2) AND s.runtime_scope_kind=1 AND s.runtime_scope_world_id=r.world_id
     AND s.current_generation=(r.audit_context->>'connection_generation')::numeric
     AND s.character_lease_generation=(r.audit_context->>'lease_generation')::numeric
     AND s.scope_ownership_generation=(r.audit_context->>'scope_generation')::numeric
     AND c.eligible AND c.lease_generation=s.character_lease_generation AND c.holder_game_session_id=s.game_session_id
     AND a.presence_character_id=c.character_id AND a.holder_game_session_id=s.game_session_id
     AND runtime.state=1 AND runtime.ownership_generation=s.scope_ownership_generation
     AND runtime.holder_node_id=node AND runtime.holder_registration_revision=node_revision
     AND (r.source_kind<>3 OR EXISTS(SELECT 1 FROM game_item_ground_locations ground
      WHERE ground.item_instance_id=r.source_item_instance_id AND ground.channel_id=s.runtime_scope_channel_id
       AND ground.world_id=r.world_id AND ground.runtime_scope_ownership_generation=s.scope_ownership_generation))
     AND g.ready AND g.ownership_generation=runtime.ownership_generation)
  THEN RAISE EXCEPTION 'Santa gift requires current Character and Node' USING ERRCODE='23514'; END IF;
 END IF;
 IF r.effects->>'source_item_id'='2995' THEN
  o:=r.outputs->0; parent:=(o->>'gift_parent')::uuid;
  IF r.effects->>'gift_currency' IS DISTINCT FROM (CASE WHEN game_santa_gift_draw(r.game_session_id,r.command_id,r.source_item_instance_id,210,6)=0 THEN '3031' ELSE '3035' END)
   OR (r.effects ? 'gift_after' AND i.state_revision>=18446744073709551615) THEN
   RAISE EXCEPTION 'Santa bank requires exact native random branch and transform revision' USING ERRCODE='23514'; END IF;
  IF jsonb_array_length(r.outputs)<>1 OR (o->>'count')::integer<>1
   OR o->>'key' IS DISTINCT FROM ('oteryn:item.tibia.i'||(r.effects->>'gift_currency'))
   OR o->>'revision' IS DISTINCT FROM i.definition_revision_ref
   OR o->'decay' IS DISTINCT FROM 'null'::jsonb OR NOT game_character_is_uuid_v7((o->>'item')::uuid)
   OR EXISTS(SELECT 1 FROM game_item_instances WHERE item_instance_id=(o->>'item')::uuid)
   OR NOT EXISTS(SELECT 1 FROM game_item_container_slots s JOIN game_item_instances b
     ON b.item_instance_id=s.item_instance_id AND b.world_id=s.world_id
     WHERE s.character_id=r.character_id AND s.world_id=r.world_id AND s.item_instance_id=parent AND b.lifecycle=1)
   OR r.parent_capacity NOT BETWEEN 1 AND 500
   OR (SELECT count(*) FROM (SELECT item_instance_id FROM game_item_container_entries WHERE parent_item_instance_id=parent UNION ALL SELECT item_instance_id FROM game_item_nested_entries WHERE parent_item_instance_id=parent) entries)>=r.parent_capacity
   OR (o->>'ordinal')::numeric<=(SELECT coalesce(max(placement_ordinal),0) FROM (
     SELECT placement_ordinal FROM game_item_container_entries WHERE parent_item_instance_id=parent UNION ALL
     SELECT placement_ordinal FROM game_item_nested_entries WHERE parent_item_instance_id=parent) entries)
   OR (r.effects->>'gift_currency'='3031' AND
      (r.effects->'gift_after' IS DISTINCT FROM jsonb_build_object('key','oteryn:item.tibia.i2996','revision',i.definition_revision_ref)
       OR r.effects->'achievement_progress' IS DISTINCT FROM '[{"key":"oteryn:achievement/allowance_collector","target":50}]'::jsonb))
   OR (r.effects->>'gift_currency'='3035' AND (r.effects ? 'gift_after' OR r.effects->'achievement_progress' IS DISTINCT FROM '[]'::jsonb))
   OR r.effects->>'gift_currency' IS NULL OR r.effects->>'gift_currency' NOT IN('3031','3035')
  THEN RAISE EXCEPTION 'Santa bank delivers exactly one native coin into current backpack' USING ERRCODE='23514'; END IF;
 ELSE
  IF r.effects->>'source_item_id'='6511' AND r.effects->>'speech' IS DISTINCT FROM
   (ARRAY['Ho ho ho','Jingle bells, jingle bells...','Have you been naughty?','Have you been nice?','Merry Christmas!','Can you stop squeezing me now... I''m starting to feel a little sick.'])[1+game_santa_gift_draw(r.game_session_id,r.command_id,r.source_item_instance_id,212,6)] THEN
   RAISE EXCEPTION 'Santa doll requires exact native random speech branch' USING ERRCODE='23514'; END IF;
  IF r.effects->>'source_item_id' IN('5791','6566') AND r.effects->>'speech' IS DISTINCT FROM
   (ARRAY['Fchhhhhh!','Zchhhhhh!','Groaaarrr.... *cough*','Aaa... CHOO!','You... will.... burn!!'])[1+game_santa_gift_draw(r.game_session_id,r.command_id,r.source_item_instance_id,211,5)] THEN
   RAISE EXCEPTION 'Santa dragon requires exact native random speech branch' USING ERRCODE='23514'; END IF;
  IF r.outputs<>'[]'::jsonb OR r.effects ? 'gift_after' OR r.effects ? 'gift_currency'
   OR r.effects->'achievement_progress' IS DISTINCT FROM '[]'::jsonb THEN
   RAISE EXCEPTION 'Santa doll cannot mint or transform' USING ERRCODE='23514'; END IF;
 END IF;
END $$;
CREATE FUNCTION game_santa_gift_complete(p_transaction UUID) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE; i game_item_instances%ROWTYPE; o JSONB; after_key TEXT;
BEGIN
 SELECT * INTO r FROM game_item_consume_transform_records WHERE transaction_id=p_transaction;
 SELECT * INTO i FROM game_item_instances WHERE item_instance_id=r.source_item_instance_id;
 after_key:=r.effects->'gift_after'->>'key';
 IF r.transaction_id IS NULL OR game_santa_gift_record(r) IS DISTINCT FROM TRUE
  OR r.created_xact_id<>pg_current_xact_id() OR game_santa_gift_custody(r) IS DISTINCT FROM TRUE
  OR (after_key IS NULL AND to_jsonb(i) IS DISTINCT FROM r.before_item)
  OR (after_key IS NOT NULL AND (i.last_transaction_id IS DISTINCT FROM r.transaction_id
    OR i.state_revision IS DISTINCT FROM (r.before_item->>'state_revision')::numeric+1
    OR i.definition_production_key IS DISTINCT FROM 'oteryn:item.tibia.i2996'
    OR (to_jsonb(i)-ARRAY['definition_production_key','last_transaction_id','state_revision'])
      IS DISTINCT FROM (r.before_item-ARRAY['definition_production_key','last_transaction_id','state_revision'])))
  OR (SELECT count(*) FROM game_item_instances WHERE minted_transaction_id=r.transaction_id)<>jsonb_array_length(r.outputs)
  OR (SELECT count(*) FROM game_item_instances WHERE last_transaction_id=r.transaction_id)<>(CASE WHEN after_key IS NULL THEN 0 ELSE 1 END)
  OR (SELECT count(*) FROM game_item_audit_outbox WHERE transaction_id=r.transaction_id)<>1
  OR NOT EXISTS(SELECT 1 FROM game_item_audit_outbox WHERE event_id=r.event_id AND transaction_id=r.transaction_id
   AND item_instance_id=r.source_item_instance_id AND occurred_at=r.occurred_at AND envelope_sha256=r.envelope_sha256
   AND created_xact_id=pg_current_xact_id() AND transaction_ordinal=1 AND transaction_count=1
   AND publication_state=1 AND published_at IS NULL)
 THEN RAISE EXCEPTION 'Santa gift changed source, custody or exact audit' USING ERRCODE='23514'; END IF;
 FOR o IN SELECT value FROM jsonb_array_elements(r.outputs) LOOP
  IF (SELECT count(*) FROM (SELECT item_instance_id FROM game_item_container_entries WHERE parent_item_instance_id=(o->>'gift_parent')::uuid UNION ALL SELECT item_instance_id FROM game_item_nested_entries WHERE parent_item_instance_id=(o->>'gift_parent')::uuid) entries)>r.parent_capacity
   OR NOT EXISTS(SELECT 1 FROM game_item_instances coin JOIN game_item_container_entries e USING(item_instance_id)
    JOIN game_item_container_slots s ON s.item_instance_id=e.parent_item_instance_id AND s.character_id=e.character_id AND s.world_id=e.world_id
    WHERE coin.item_instance_id=(o->>'item')::uuid AND coin.minted_transaction_id=r.transaction_id
     AND coin.world_id=r.world_id AND coin.definition_family='Item' AND coin.definition_production_key=o->>'key'
     AND coin.definition_revision_ref=o->>'revision' AND coin.quantity=1 AND coin.lifecycle=1
     AND coin.last_transaction_id IS NULL AND coin.state_revision=1
     AND e.world_id=r.world_id AND e.character_id=r.character_id AND e.parent_item_instance_id=(o->>'gift_parent')::uuid
     AND e.placement_ordinal=(o->>'ordinal')::numeric AND e.placed_transaction_id=r.transaction_id)
   OR EXISTS(SELECT 1 FROM game_item_ground_locations WHERE item_instance_id=(o->>'item')::uuid)
   OR EXISTS(SELECT 1 FROM game_item_nested_entries WHERE item_instance_id=(o->>'item')::uuid)
   OR EXISTS(SELECT 1 FROM game_item_house_interior_locations WHERE item_instance_id=(o->>'item')::uuid)
  THEN RAISE EXCEPTION 'Santa currency requires exact fresh actor backpack custody' USING ERRCODE='23514'; END IF;
 END LOOP;
END $$;
CREATE FUNCTION game_santa_gift_apply(p_transaction UUID) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE;
BEGIN
 SELECT * INTO r FROM game_item_consume_transform_records WHERE transaction_id=p_transaction;
 IF r.transaction_id IS NULL OR r.created_xact_id<>pg_current_xact_id() THEN
  RAISE EXCEPTION 'Santa gift requires original receipt transaction' USING ERRCODE='23514'; END IF;
 PERFORM game_santa_gift_admit(r);
 IF r.effects ? 'gift_after' THEN
  UPDATE game_item_instances SET definition_production_key='oteryn:item.tibia.i2996',state_revision=state_revision+1,
   last_transaction_id=r.transaction_id WHERE item_instance_id=r.source_item_instance_id;
 END IF;
END $$;
