CREATE FUNCTION game_seasonal_cupcake_effects(p_item BIGINT) RETURNS JSONB LANGUAGE SQL IMMUTABLE AS $$
 SELECT CASE WHEN p_item IN(28484,28485,28486) THEN jsonb_build_object(
 'kind','consume_effect','source_item_id',p_item,'donor',CASE p_item
 WHEN 28484 THEN 'data/scripts/actions/items/blueberry_cupcake.lua:3-14'
 WHEN 28485 THEN 'data/scripts/actions/items/strawberry_cupcake.lua:3-14'
 ELSE 'data/scripts/actions/items/lemon_cupcake.lua:1-20' END,
 'cues','[]'::jsonb,'speech','Mmmm.','private_speech',false,'require_head',false,
 'require_player_target',false,'achievement_progress','[]'::jsonb) END
$$;
CREATE FUNCTION game_seasonal_cupcake_house_position(p BYTEA) RETURNS INTEGER[] LANGUAGE SQL IMMUTABLE STRICT AS $$
 SELECT CASE WHEN octet_length(p)=12 THEN ARRAY[
 (('x'||encode(substring(p FROM 1 FOR 4),'hex'))::bit(32)::integer),
 (('x'||encode(substring(p FROM 5 FOR 4),'hex'))::bit(32)::integer),
 (('x'||encode(substring(p FROM 9 FOR 4),'hex'))::bit(32)::integer)] END
$$;
