 ALTER TABLE game_item_consume_transform_records DROP CONSTRAINT game_item_action_source_custody;
 EXECUTE 'ALTER TABLE game_item_consume_transform_records ADD CONSTRAINT game_item_action_source_custody CHECK(('||prior||') OR coalesce(('
 ||'source_kind=5 AND consume_source AND source_count=1 AND outputs=''[]''::jsonb AND extra_inputs=''[]''::jsonb '
 ||'AND parent_item_instance_id IS NULL AND secondary_item_instance_id=source_item_instance_id '
