CREATE FUNCTION game_seasonal_cupcake_house_source(p_session UUID,p_character UUID,p_connection NUMERIC,p_lease NUMERIC,p_scope NUMERIC,p_node UUID,p_node_revision NUMERIC,p_world UUID,p_house TEXT,p_item UUID)
RETURNS TABLE(before_item JSONB,location JSONB,provenance JSONB,spatial_position BYTEA,stack_ordinal TEXT)
