 WHERE i.item_instance_id=p_item AND i.world_id=p_world AND h.house_key=p_house AND i.lifecycle=1 AND i.quantity BETWEEN 1 AND 100 AND i.definition_family='Item'
 AND i.definition_production_key IN('oteryn:item.tibia.i28484','oteryn:item.tibia.i28485','oteryn:item.tibia.i28486')
