END $$;
CREATE FUNCTION game_seasonal_cupcake_house_admit(r game_item_consume_transform_records) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE i game_item_instances%ROWTYPE; at INTEGER[]; actor_at BIGINT[];
BEGIN
 PERFORM game_house_podium_fence(r.game_session_id,r.character_id,(r.audit_context->>'connection_generation')::numeric,
 (r.audit_context->>'lease_generation')::numeric,(r.audit_context->>'scope_generation')::numeric,
 (r.source_location->>'node')::uuid,(r.source_location->>'node_revision')::numeric,r.world_id,r.source_location->'house'->>'house_key');
 SELECT * INTO i FROM game_item_instances WHERE item_instance_id=r.source_item_instance_id FOR UPDATE;
 at:=game_seasonal_cupcake_house_position((r.source_location->'house'->>'spatial_position')::bytea);
 SELECT array_agg(value::text::bigint ORDER BY ordinal) INTO actor_at FROM jsonb_array_elements(r.source_location->'actor_position') WITH ORDINALITY a(value,ordinal);
 IF r.source_kind<>5 OR NOT r.consume_source OR r.source_count<>1 OR r.outputs<>'[]'::jsonb OR r.extra_inputs<>'[]'::jsonb
 OR r.parent_item_instance_id IS NOT NULL OR r.secondary_item_instance_id<>r.source_item_instance_id
 OR i.item_instance_id IS NULL OR to_jsonb(i) IS DISTINCT FROM r.before_item OR r.before_secondary IS DISTINCT FROM r.before_item
 OR i.world_id<>r.world_id OR i.lifecycle<>1 OR i.quantity NOT BETWEEN 1 AND 100 OR i.definition_family<>'Item'
 OR i.definition_production_key NOT IN('oteryn:item.tibia.i28484','oteryn:item.tibia.i28485','oteryn:item.tibia.i28486')
 OR i.definition_production_key IS DISTINCT FROM 'oteryn:item.tibia.i'||(r.effects->>'source_item_id')
 OR r.recipe IS DISTINCT FROM 'oteryn:seasonal.cupcake.'||(r.effects->>'source_item_id')
 OR r.effects IS DISTINCT FROM game_seasonal_cupcake_effects((r.effects->>'source_item_id')::bigint)
 OR coalesce(r.source_location->>'custody_kind','house')<>'house' OR r.content_digest IS NULL
 OR game_item_action_house_custody(r) IS DISTINCT FROM TRUE OR cardinality(at) IS DISTINCT FROM 3 OR cardinality(actor_at) IS DISTINCT FROM 3
 OR at[3]<>actor_at[3] OR abs(at[1]::bigint-actor_at[1])>1 OR abs(at[2]::bigint-actor_at[2])>1
 OR EXISTS(SELECT 1 FROM game_item_keys WHERE item_instance_id=i.item_instance_id)
 OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=i.item_instance_id)
 OR EXISTS(SELECT 1 FROM game_item_texts WHERE item_instance_id=i.item_instance_id)
 OR EXISTS(SELECT 1 FROM game_item_imbuements WHERE item_instance_id=i.item_instance_id)
 OR EXISTS(SELECT 1 FROM game_item_container_entries WHERE parent_item_instance_id=i.item_instance_id)
 OR EXISTS(SELECT 1 FROM game_item_nested_entries WHERE parent_item_instance_id=i.item_instance_id)
 THEN RAISE EXCEPTION 'House Cupcake requires exact source food, current adjacent House actor and one-unit burn' USING ERRCODE='23514'; END IF;
END $$;
ALTER FUNCTION game_item_action_house_admit(game_item_consume_transform_records) RENAME TO game_item_action_house_admit_before_cupcake;
CREATE FUNCTION game_item_action_house_admit(r game_item_consume_transform_records) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF r.recipe IN('oteryn:seasonal.cupcake.28484','oteryn:seasonal.cupcake.28485','oteryn:seasonal.cupcake.28486') THEN PERFORM game_seasonal_cupcake_house_admit(r);
 ELSE PERFORM game_item_action_house_admit_before_cupcake(r); END IF;
END $$;
ALTER FUNCTION game_item_action_house_apply(UUID) RENAME TO game_item_action_house_apply_before_cupcake;
CREATE FUNCTION game_item_action_house_apply(p_transaction UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE;
BEGIN
 SELECT * INTO r FROM game_item_consume_transform_records WHERE transaction_id=p_transaction;
 IF r.recipe IN('oteryn:seasonal.cupcake.28484','oteryn:seasonal.cupcake.28485','oteryn:seasonal.cupcake.28486') THEN
  IF r.created_xact_id<>pg_current_xact_id() THEN RAISE EXCEPTION 'fresh House Cupcake receipt required' USING ERRCODE='23514'; END IF;
  PERFORM game_seasonal_cupcake_house_admit(r); RETURN;
 END IF;
 PERFORM game_item_action_house_apply_before_cupcake(p_transaction);
END $$;
CREATE FUNCTION game_seasonal_cupcake_house_burn(p_transaction UUID,p_item UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE;
BEGIN
 SELECT * INTO r FROM game_item_consume_transform_records WHERE transaction_id=p_transaction AND source_item_instance_id=p_item AND source_kind=5;
 IF r.transaction_id IS NULL OR r.created_xact_id<>pg_current_xact_id() THEN RAISE EXCEPTION 'fresh original House Cupcake receipt required' USING ERRCODE='23514'; END IF;
 PERFORM game_seasonal_cupcake_house_admit(r);
 UPDATE game_item_instances SET quantity=quantity-1,lifecycle=CASE WHEN quantity=1 THEN 2 ELSE 1 END,last_transaction_id=p_transaction
 WHERE item_instance_id=p_item AND to_jsonb(game_item_instances)=r.before_item;
 IF NOT FOUND THEN RAISE EXCEPTION 'House Cupcake source changed' USING ERRCODE='23514'; END IF;
 IF (r.before_item->>'quantity')::bigint=1 THEN
  DELETE FROM game_item_house_interior_locations h WHERE item_instance_id=p_item AND to_jsonb(h)=r.source_location->'house';
  IF NOT FOUND THEN RAISE EXCEPTION 'House Cupcake terminal custody changed' USING ERRCODE='23514'; END IF;
  DELETE FROM game_item_house_reclaim_provenance p WHERE item_instance_id=p_item AND to_jsonb(p)=r.source_location->'provenance';
  IF NOT FOUND THEN RAISE EXCEPTION 'House Cupcake terminal provenance changed' USING ERRCODE='23514'; END IF;
 END IF;
END $$;
CREATE FUNCTION game_seasonal_cupcake_house_update(o game_item_instances,n game_item_instances,r game_item_consume_transform_records) RETURNS BOOLEAN LANGUAGE SQL STABLE AS $$
 SELECT r.source_kind=5 AND r.created_xact_id=pg_current_xact_id() AND r.before_item=to_jsonb(o)
 AND r.source_item_instance_id=o.item_instance_id AND r.transaction_id=n.last_transaction_id
 AND r.recipe IN('oteryn:seasonal.cupcake.28484','oteryn:seasonal.cupcake.28485','oteryn:seasonal.cupcake.28486')
 AND r.consume_source AND r.source_count=1 AND r.outputs='[]'::jsonb AND r.extra_inputs='[]'::jsonb
 AND r.effects=game_seasonal_cupcake_effects((r.effects->>'source_item_id')::bigint)
 AND n.quantity=o.quantity-1 AND n.lifecycle=CASE WHEN o.quantity=1 THEN 2 ELSE 1 END
 AND (to_jsonb(n)-ARRAY['quantity','lifecycle','last_transaction_id'])=(to_jsonb(o)-ARRAY['quantity','lifecycle','last_transaction_id'])
$$;
