 IF at=0 THEN RAISE EXCEPTION 'missing native item guard'; END IF;
 EXECUTE overlay(body placing E'BEGIN\n'||$arm$
 IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM game_item_consume_transform_records r WHERE r.source_kind=5 AND r.source_item_instance_id=OLD.item_instance_id AND r.transaction_id=NEW.last_transaction_id AND r.created_xact_id=pg_current_xact_id() AND r.recipe IN('oteryn:seasonal.cupcake.28484','oteryn:seasonal.cupcake.28485','oteryn:seasonal.cupcake.28486')) THEN
  IF NOT EXISTS(SELECT 1 FROM game_item_consume_transform_records r WHERE r.transaction_id=NEW.last_transaction_id AND game_seasonal_cupcake_house_update(OLD,NEW,r) IS TRUE) THEN RAISE EXCEPTION 'House Cupcake changes only one source unit' USING ERRCODE='23514'; END IF;
