ALTER FUNCTION game_item_action_house_complete(UUID) RENAME TO game_item_action_house_complete_before_cupcake;
CREATE FUNCTION game_item_action_house_complete(p_transaction UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_consume_transform_records%ROWTYPE; i game_item_instances%ROWTYPE; remaining BIGINT;
BEGIN
 SELECT * INTO r FROM game_item_consume_transform_records WHERE transaction_id=p_transaction;
 IF r.recipe NOT IN('oteryn:seasonal.cupcake.28484','oteryn:seasonal.cupcake.28485','oteryn:seasonal.cupcake.28486') OR r.transaction_id IS NULL THEN PERFORM game_item_action_house_complete_before_cupcake(p_transaction); RETURN; END IF;
 SELECT * INTO i FROM game_item_instances WHERE item_instance_id=r.source_item_instance_id;
 remaining:=(r.before_item->>'quantity')::bigint-1;
 IF r.created_xact_id<>pg_current_xact_id() OR game_seasonal_cupcake_house_update(jsonb_populate_record(NULL::game_item_instances,r.before_item),i,r) IS DISTINCT FROM TRUE
 OR NOT EXISTS(SELECT 1 FROM game_seasonal_cupcake_uses c WHERE c.transaction_id=r.transaction_id AND c.source_kind=2 AND c.transform_transaction_id=r.transaction_id AND c.character_id=r.character_id AND c.game_session_id=r.game_session_id AND c.command_id=r.command_id AND c.created_xact_id=pg_current_xact_id())
 OR (remaining>0 AND game_item_action_house_custody(r) IS DISTINCT FROM TRUE)
 OR (remaining=0 AND(EXISTS(SELECT 1 FROM game_item_house_interior_locations WHERE item_instance_id=i.item_instance_id) OR EXISTS(SELECT 1 FROM game_item_house_reclaim_provenance WHERE item_instance_id=i.item_instance_id)))
 OR EXISTS(SELECT 1 FROM game_item_instances WHERE minted_transaction_id=r.transaction_id)
 OR (SELECT count(*) FROM game_item_instances WHERE last_transaction_id=r.transaction_id)<>1
 OR (SELECT count(*) FROM game_item_audit_outbox WHERE transaction_id=r.transaction_id)<>1
 OR NOT EXISTS(SELECT 1 FROM game_item_audit_outbox WHERE event_id=r.event_id AND transaction_id=r.transaction_id AND item_instance_id=r.source_item_instance_id AND occurred_at=r.occurred_at AND envelope_sha256=r.envelope_sha256 AND created_xact_id=pg_current_xact_id() AND transaction_ordinal=1 AND transaction_count=1 AND publication_state=1 AND published_at IS NULL)
