-- BEGIN SRV7 current-source seasonal-cake-source-goal-guards.sql
DO $migration$ DECLARE body TEXT; needle TEXT; BEGIN
 body:=pg_get_functiondef('game_cake_world_state_valid(jsonb)'::regprocedure);
 needle:='BETWEEN 0 AND 1116'; IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'Cake goal state anchor changed'; END IF;
 EXECUTE replace(body,needle,'BETWEEN 0 AND 1066');
 body:=pg_get_functiondef('game_cake_apply_terrain_tool_transform(uuid,numeric,uuid,uuid,bytea,uuid,uuid,bytea,text,bytea,bigint,bigint,bigint,bigint,bigint[],bigint[])'::regprocedure);
 needle:=$text$(w.state->>'layer_progress')::integer>=1116$text$;
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'Cake CAS goal anchor changed'; END IF;
 body:=replace(body,needle,$text$(w.state->>'layer_progress')::integer>=game_cake_edible_goal()$text$);
 needle:=$text$ OR ((w.state->>'window_end') IS NOT NULL AND c.now_seconds>=(w.state->>'window_end')::bigint)$text$;
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'Cake CAS fixed-window anchor changed'; END IF;
 body:=replace(body,needle,$text$ OR (w.state->>'window_start') IS NULL OR (w.state->>'window_end') IS NULL OR c.now_seconds<(w.state->>'window_start')::bigint OR c.now_seconds>=(w.state->>'window_end')::bigint$text$);
 needle:=' SELECT * INTO STRICT w FROM game_seasonal_cake_worlds';
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'Cake CAS footprint anchor changed'; END IF;
 body:=replace(body,needle,$guard$ IF NOT EXISTS(SELECT 1 FROM game_cake_edible_cells cell WHERE cell.x=get_byte(p_placement,34)*256+get_byte(p_placement,35)
  AND cell.y=get_byte(p_placement,36)*256+get_byte(p_placement,37) AND cell.appearance=p_before_item_id AND cell.stack=get_byte(p_placement,39)) THEN
 RAISE EXCEPTION 'Cake source is not an actual edible floor7 cell' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT w FROM game_seasonal_cake_worlds$guard$);
 EXECUTE body;
END $migration$;

-- END SRV7 current-source seasonal-cake-source-goal-guards.sql

-- BEGIN SRV7 current-source seasonal-cake-fixed-clock.sql
-- Current Wiki cadence: source stage checks every600s, fixed1800s eating rounds.
CREATE TABLE game_seasonal_cake_stage_polls (
 world_id UUID NOT NULL,event_start BIGINT NOT NULL,poll_slot BIGINT NOT NULL CHECK(poll_slot>=1),
 observed_at BIGINT NOT NULL,opened_bridge BOOLEAN NOT NULL,created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),
 PRIMARY KEY(world_id,event_start,poll_slot),FOREIGN KEY(world_id,event_start) REFERENCES game_seasonal_cake_worlds
);
CREATE TABLE game_seasonal_cake_windows (
 world_id UUID NOT NULL,event_start BIGINT NOT NULL,window_start BIGINT NOT NULL,
 layer SMALLINT NOT NULL CHECK(layer BETWEEN 1 AND 4),observed_at BIGINT NOT NULL,
 created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),
 PRIMARY KEY(world_id,event_start,window_start),FOREIGN KEY(world_id,event_start) REFERENCES game_seasonal_cake_worlds
);
CREATE UNIQUE INDEX game_cake_one_bridge_open ON game_seasonal_cake_stage_polls(world_id,event_start) WHERE opened_bridge;
CREATE TRIGGER game_cake_stage_polls_immutable BEFORE UPDATE OR DELETE ON game_seasonal_cake_stage_polls FOR EACH ROW EXECUTE FUNCTION game_world_reset_history_immutable();
CREATE TRIGGER game_cake_windows_immutable BEFORE UPDATE OR DELETE ON game_seasonal_cake_windows FOR EACH ROW EXECUTE FUNCTION game_world_reset_history_immutable();
REVOKE ALL ON game_seasonal_cake_stage_polls,game_seasonal_cake_windows FROM PUBLIC;
GRANT SELECT,INSERT ON game_seasonal_cake_stage_polls,game_seasonal_cake_windows TO oteryn_game_runtime;
GRANT SELECT ON game_seasonal_cake_stage_polls,game_seasonal_cake_windows TO oteryn_game_control;
CREATE FUNCTION game_cake_fixed_clock_admit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_cake_world_node_context%ROWTYPE; w game_seasonal_cake_worlds%ROWTYPE; previous JSONB; anchor BIGINT; slot BIGINT; prior_window BIGINT;
BEGIN
 SELECT * INTO c FROM game_cake_world_node_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF NOT FOUND OR game_cake_world_context_is_current(NEW.world_id,NEW.event_start) IS DISTINCT FROM TRUE
  OR NEW.observed_at<>c.now_seconds OR c.now_seconds>=c.event_start+518400 THEN
  RAISE EXCEPTION 'Cake clock claim lacks exact current Node occurrence' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT w FROM game_seasonal_cake_worlds WHERE world_id=NEW.world_id AND event_start=NEW.event_start FOR UPDATE;
 previous:=CASE WHEN c.captured THEN c.initial_state ELSE w.state END;
 NEW.created_xact_id:=pg_current_xact_id();
 IF TG_TABLE_NAME='game_seasonal_cake_stage_polls' THEN
  IF (previous->>'stage')::integer<>1 OR NEW.poll_slot<>(c.now_seconds-c.event_start)/600
   OR NEW.poll_slot<1 OR NEW.opened_bridge IS DISTINCT FROM ((previous->>'substances')::integer=200 AND (previous->>'golems')::integer=200) THEN
   RAISE EXCEPTION 'Cake stage poll is not its due source bucket or predecessor' USING ERRCODE='23514'; END IF;
 ELSE
  SELECT observed_at INTO anchor FROM game_seasonal_cake_stage_polls WHERE world_id=NEW.world_id AND event_start=NEW.event_start AND opened_bridge;
  slot:=CASE WHEN anchor IS NULL THEN NULL ELSE anchor+((c.now_seconds-anchor)/1800)*1800 END;
  SELECT max(window_start) INTO prior_window FROM game_seasonal_cake_tiles WHERE world_id=NEW.world_id AND event_start=NEW.event_start AND layer=NEW.layer-1;
  IF (previous->>'stage')::integer<>2 OR anchor IS NULL OR c.now_seconds<anchor+1800
   OR NEW.window_start IS DISTINCT FROM slot OR NEW.layer NOT IN ((previous->>'layer')::smallint,(previous->>'layer')::smallint+1)
   OR (prior_window IS NOT NULL AND NEW.window_start<=prior_window)
   OR ((previous->>'window_end') IS NOT NULL AND c.now_seconds<(previous->>'window_end')::bigint)
  THEN RAISE EXCEPTION 'Cake eating window is not the next fixed source interval' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER game_cake_fixed_clock_admit BEFORE INSERT ON game_seasonal_cake_stage_polls FOR EACH ROW EXECUTE FUNCTION game_cake_fixed_clock_admit();
CREATE TRIGGER game_cake_fixed_clock_admit BEFORE INSERT ON game_seasonal_cake_windows FOR EACH ROW EXECUTE FUNCTION game_cake_fixed_clock_admit();
CREATE TRIGGER game_cake_z_invalidate BEFORE INSERT ON game_seasonal_cake_stage_polls FOR EACH ROW EXECUTE FUNCTION game_cake_world_invalidate();
CREATE TRIGGER game_cake_z_invalidate BEFORE INSERT ON game_seasonal_cake_windows FOR EACH ROW EXECUTE FUNCTION game_cake_world_invalidate();
CREATE CONSTRAINT TRIGGER game_cake_fixed_clock_complete AFTER INSERT ON game_seasonal_cake_stage_polls DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_world_deferred();
CREATE CONSTRAINT TRIGGER game_cake_fixed_clock_complete AFTER INSERT ON game_seasonal_cake_windows DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_cake_world_deferred();
-- Old first-USE window receipts remain readable for immutable historical replay;
-- they cannot authorize new rounds under the current fixed source clock.
CREATE OR REPLACE FUNCTION game_cake_window_start_admit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN RAISE EXCEPTION 'Cake windows are opened by the fixed native clock' USING ERRCODE='23514'; END $$;
DO $$ DECLARE f REGPROCEDURE; BEGIN
 FOREACH f IN ARRAY ARRAY['game_cake_fixed_clock_admit()'::regprocedure,'game_cake_window_start_admit()'::regprocedure] LOOP
 EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',f,current_schema());
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_runtime,oteryn_game_control',f);
 END LOOP;
END $$;

-- END SRV7 current-source seasonal-cake-fixed-clock.sql

-- BEGIN SRV7 current-source seasonal-cake-fixed-world.sql
CREATE OR REPLACE FUNCTION game_cake_world_complete(p_world UUID,p_event BIGINT) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_cake_world_node_context%ROWTYPE; w game_seasonal_cake_worlds%ROWTYPE;
 old JSONB; expected JSONB; subst BIGINT; extracted BIGINT; bitten BIGINT; receipts BIGINT;
 stg INTEGER; current_layer INTEGER; progress INTEGER; start_at BIGINT; end_at BIGINT; bonus BIGINT;
 restore BOOLEAN:=FALSE; side game_cake_world_side_context%ROWTYPE; r game_seasonal_cake_bite_receipts%ROWTYPE;
 prior JSONB; after JSONB; expected_bites INTEGER;
 polls BIGINT; openings BIGINT; bridged BOOLEAN; new_window BIGINT; new_layer INTEGER;
BEGIN
 IF game_cake_world_context_is_current(p_world,p_event) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'Cake completion lacks its exact current Node context' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT c FROM game_cake_world_node_context WHERE backend_pid=pg_backend_pid();
 IF c.validated THEN RETURN; END IF;
 SELECT * INTO STRICT w FROM game_seasonal_cake_worlds WHERE world_id=p_world AND event_start=p_event;
 old:=CASE WHEN c.captured THEN c.initial_state ELSE w.state END;
 SELECT coalesce(sum((result->>'accepted')::bigint),0),count(*) INTO subst,receipts
  FROM game_seasonal_cake_deliveries WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id();
 SELECT count(*) FILTER(WHERE counted) INTO extracted FROM game_seasonal_cake_extractions
  WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id();
 SELECT count(*) INTO bitten FROM game_seasonal_cake_bite_receipts
  WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id();
 SELECT count(*),coalesce(bool_or(opened_bridge),FALSE) INTO polls,bridged FROM game_seasonal_cake_stage_polls
  WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id();
 SELECT count(*),max(window_start),max(layer) INTO openings,new_window,new_layer FROM game_seasonal_cake_windows
  WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id();
 IF polls>1 OR openings>1 OR (polls>0 AND (bitten>0 OR receipts>0 OR extracted>0))
  OR (openings>0 AND (polls>0 OR bitten>0 OR receipts>0 OR extracted>0))
  OR receipts>1 OR extracted>1 OR bitten>1
  OR (SELECT count(*) FROM game_seasonal_cake_extractions WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id())>1
  OR ((subst>0 OR extracted>0 OR bitten>0 OR openings>0 OR bridged) AND NOT c.captured)
  OR (c.inserted AND (subst<>0 OR extracted<>0 OR bitten<>0 OR openings<>0 OR polls<>0)) THEN
  RAISE EXCEPTION 'Cake progress requires one physical source action and its World write' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM game_seasonal_cake_extractions e WHERE e.world_id=p_world AND e.event_start=p_event
  AND e.created_xact_id=pg_current_xact_id() AND e.counted IS DISTINCT FROM
   ((old->>'stage')::integer=1 AND (old->>'golems')::integer<200 AND c.now_seconds<w.event_end)) THEN
  RAISE EXCEPTION 'Cake extraction count disagrees with exact source stage' USING ERRCODE='23514'; END IF;
 IF polls>0 AND (old->>'stage')::integer<>1 THEN
  RAISE EXCEPTION 'Cake stage poll requires its stage-one predecessor' USING ERRCODE='23514'; END IF;
 IF NOT c.captured THEN
  IF EXISTS(SELECT 1 FROM game_cake_world_side_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id()) THEN
   RAISE EXCEPTION 'Cake marks require their same-transaction World transition' USING ERRCODE='23514'; END IF;
  UPDATE game_cake_world_node_context SET validated=TRUE WHERE backend_pid=pg_backend_pid(); RETURN;
 END IF;
 expected:=old;
 stg:=(old->>'stage')::integer; current_layer:=(old->>'layer')::integer; progress:=(old->>'layer_progress')::integer;
 start_at:=(old->>'window_start')::bigint; end_at:=(old->>'window_end')::bigint;
 IF c.inserted THEN
  IF w.state<>old THEN RAISE EXCEPTION 'Cake insertion cannot carry progress' USING ERRCODE='23514'; END IF;
 ELSIF c.now_seconds>=w.event_end THEN
  IF subst<>0 OR extracted<>0 OR bitten<>0 OR openings<>0 OR polls<>0 THEN RAISE EXCEPTION 'ended Cake occurrence cannot earn progress' USING ERRCODE='23514'; END IF;
  expected:=expected||jsonb_build_object('stage',0,'window_start',NULL,'window_end',NULL);
 ELSIF stg=1 THEN
  IF bitten<>0 OR openings<>0 OR (old->>'substances')::bigint+subst>200 OR (old->>'golems')::bigint+extracted>200 THEN
   RAISE EXCEPTION 'Cake source counters exceed their stage or goals' USING ERRCODE='23514'; END IF;
  expected:=expected||jsonb_build_object('substances',(old->>'substances')::bigint+subst,'golems',(old->>'golems')::bigint+extracted);
  IF bridged THEN
   IF (old->>'substances')::integer<>200 OR (old->>'golems')::integer<>200 THEN
    RAISE EXCEPTION 'Cake bridge poll cannot anticipate a later delivery' USING ERRCODE='23514'; END IF;
   expected:=expected||jsonb_build_object('stage',2); END IF;
 ELSIF stg=2 THEN
  IF subst<>0 OR extracted<>0 THEN RAISE EXCEPTION 'Cake harvesting counters are closed' USING ERRCODE='23514'; END IF;
  IF bitten=1 THEN
   IF progress>=game_cake_edible_goal() OR start_at IS NULL OR end_at IS NULL OR c.now_seconds<start_at OR c.now_seconds>=end_at OR openings<>0 THEN
    RAISE EXCEPTION 'Cake bite requires its active fixed eating window' USING ERRCODE='23514'; END IF;
   expected:=expected||jsonb_build_object('layer_progress',progress+1);
  ELSE
   IF end_at IS NOT NULL AND (c.now_seconds>=end_at OR progress>=game_cake_edible_goal()) THEN
    restore:=progress<game_cake_edible_goal() OR current_layer<4;
    expected:=expected||jsonb_build_object('window_start',NULL,'window_end',NULL);
    IF progress>=game_cake_edible_goal() THEN
     IF current_layer=4 THEN
      bonus:=floor(extract(epoch FROM ((date_trunc('day',to_timestamp(c.now_seconds::double precision) AT TIME ZONE 'Europe/Berlin'-interval '6 hours')+interval '1 day 6 hours') AT TIME ZONE 'Europe/Berlin')))::bigint;
      expected:=expected||jsonb_build_object('stage',3,'bonus_from',bonus,'bonus_until',bonus+604800);
     ELSE expected:=expected||jsonb_build_object('layer',current_layer+1,'layer_progress',0); END IF;
    ELSE expected:=expected||jsonb_build_object('layer_progress',0); END IF;
   END IF;
   IF openings=1 THEN
    IF (expected->>'stage')::integer<>2 OR expected->>'window_start' IS NOT NULL
     OR new_layer<>(expected->>'layer')::integer THEN
     RAISE EXCEPTION 'Cake clock cannot replace a live or completed final round' USING ERRCODE='23514'; END IF;
    expected:=expected||jsonb_build_object('window_start',new_window,'window_end',new_window+1800);
   END IF;
  END IF;
 ELSE
  IF subst<>0 OR extracted<>0 OR bitten<>0 OR openings<>0 OR polls<>0 THEN RAISE EXCEPTION 'Cake progress is closed' USING ERRCODE='23514'; END IF;
 END IF;
 IF NOT c.inserted THEN
  IF expected-ARRAY['revision']=old-ARRAY['revision'] THEN
   RAISE EXCEPTION 'Cake World revision requires a real source transition' USING ERRCODE='23514'; END IF;
  expected:=expected||jsonb_build_object('revision',(old->>'revision')::numeric+1);
 END IF;
 IF w.state IS DISTINCT FROM expected THEN
  RAISE EXCEPTION 'Cake World final state does not conserve exact source receipts and deadlines' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM game_seasonal_cake_deliveries d WHERE d.world_id=p_world AND d.event_start=p_event
  AND d.created_xact_id=pg_current_xact_id() AND (d.result->'substances' IS DISTINCT FROM expected->'substances'
   OR d.result->'golems' IS DISTINCT FROM expected->'golems' OR d.result->'stage' IS DISTINCT FROM expected->'stage')) THEN
  RAISE EXCEPTION 'Cake delivery result differs from committed World counters' USING ERRCODE='23514'; END IF;
 FOR r IN SELECT * FROM game_seasonal_cake_bite_receipts WHERE world_id=p_world AND event_start=p_event AND created_xact_id=pg_current_xact_id() LOOP
  IF stg<>2 OR r.layer<>current_layer OR r.window_start IS DISTINCT FROM (old->>'window_start')::bigint
   OR r.world_revision_before<>(old->>'revision')::numeric OR r.world_revision_after<>(expected->>'revision')::numeric
   OR NOT EXISTS(SELECT 1 FROM game_cake_world_side_context s WHERE s.backend_pid=pg_backend_pid()
    AND s.transaction_xid=pg_current_xact_id() AND s.kind=1 AND s.identity=r.character_id::text)
   OR NOT EXISTS(SELECT 1 FROM game_cake_world_side_context s WHERE s.backend_pid=pg_backend_pid()
    AND s.transaction_xid=pg_current_xact_id() AND s.kind=2 AND s.identity=r.layer||':'||r.x||':'||r.y||':'||r.floor) THEN
   RAISE EXCEPTION 'Cake bite lacks its exact World/personal/physical marks' USING ERRCODE='23514'; END IF;
 END LOOP;
 FOR side IN SELECT * FROM game_cake_world_side_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id() LOOP
  prior:=side.before_state; after:=side.after_state;
  IF (after->>'world_id')::uuid<>p_world OR (after->>'event_start')::bigint<>p_event THEN
   RAISE EXCEPTION 'Cake side mark names another occurrence' USING ERRCODE='23514'; END IF;
  IF side.kind=1 THEN
   SELECT * INTO r FROM game_seasonal_cake_bite_receipts b WHERE b.world_id=p_world AND b.event_start=p_event
    AND b.created_xact_id=pg_current_xact_id() AND b.character_id=(after->>'character_id')::uuid;
   expected_bites:=CASE WHEN prior IS NOT NULL AND (prior->>'window_start')::bigint=r.window_start THEN (prior->>'bites')::integer+1 ELSE 1 END;
   IF r.game_session_id IS NULL OR (after->>'window_start')::bigint<>r.window_start
    OR (after->>'last_bite')::bigint<>c.now_seconds OR (after->>'bites')::integer<>expected_bites OR expected_bites>12
    OR NOT EXISTS(SELECT 1 FROM game_seasonal_cake_bites b WHERE b.character_id=r.character_id
     AND b.world_id=p_world AND b.event_start=p_event AND to_jsonb(b)=after) THEN
    RAISE EXCEPTION 'Cake personal mark lacks its actual predecessor and food-backed bite' USING ERRCODE='23514'; END IF;
  ELSIF (after->>'removed')::boolean THEN
   SELECT * INTO r FROM game_seasonal_cake_bite_receipts b WHERE b.world_id=p_world AND b.event_start=p_event
    AND b.created_xact_id=pg_current_xact_id() AND b.layer=(after->>'layer')::smallint
    AND b.x=(after->>'x')::integer AND b.y=(after->>'y')::integer AND b.floor=(after->>'floor')::smallint;
   IF r.game_session_id IS NULL OR coalesce((prior->>'removed')::boolean,FALSE)
    OR (after->>'window_start')::bigint<>r.window_start OR (after->>'appearance')::integer<>r.appearance THEN
    RAISE EXCEPTION 'Cake removed square lacks its unique physical bite' USING ERRCODE='23514'; END IF;
  ELSE
   IF NOT restore OR prior IS NULL OR (prior->>'removed')::boolean IS DISTINCT FROM TRUE
    OR (after->>'layer')::integer<>current_layer
    OR (after-ARRAY['removed','last_xact_id']) IS DISTINCT FROM (prior-ARRAY['removed','last_xact_id']) THEN
    RAISE EXCEPTION 'Cake restore may touch only current failed/nonfinal completed layer' USING ERRCODE='23514'; END IF;
  END IF;
  IF side.kind=2 AND NOT EXISTS(SELECT 1 FROM game_seasonal_cake_tiles t WHERE t.world_id=p_world AND t.event_start=p_event
   AND t.layer=(after->>'layer')::smallint AND t.x=(after->>'x')::integer AND t.y=(after->>'y')::integer
   AND t.floor=(after->>'floor')::smallint AND to_jsonb(t)=after) THEN
   RAISE EXCEPTION 'Cake physical mark differs from its captured write' USING ERRCODE='23514'; END IF;
 END LOOP;
 IF restore AND EXISTS(SELECT 1 FROM game_seasonal_cake_tiles WHERE world_id=p_world AND event_start=p_event AND game_seasonal_cake_tiles.layer=current_layer AND removed) THEN
  RAISE EXCEPTION 'Cake round restore must restore its entire current layer' USING ERRCODE='23514'; END IF;
 UPDATE game_cake_world_node_context SET validated=TRUE WHERE backend_pid=pg_backend_pid();
END $$;

-- END SRV7 current-source seasonal-cake-fixed-world.sql

-- BEGIN SRV7 current-source srv7-0993-foreign-key-indexes.sql
-- SRV7 child-side foreign keys use complete leading B-tree keys.
CREATE INDEX game_seasonal_cake_receipts_character_world_event ON game_seasonal_cake_character_receipts(character_id,world_id,event_start);
CREATE INDEX game_seasonal_cake_restores_bite ON game_seasonal_cake_terrain_restores(source_game_session_id,source_command_id);
CREATE INDEX game_seasonal_cake_restores_world_event ON game_seasonal_cake_terrain_restores(world_id,event_start);
CREATE INDEX game_seasonal_cake_window_starts_character ON game_seasonal_cake_window_starts(character_id);
CREATE INDEX game_seasonal_cake_raid_slots_world_event ON game_seasonal_cake_raid_slots(world_id,event_start);
CREATE INDEX game_seasonal_cupcake_uses_use_receipt ON game_seasonal_cupcake_uses(use_transaction_id);
CREATE INDEX game_seasonal_cupcake_uses_transform_receipt ON game_seasonal_cupcake_uses(transform_transaction_id);

-- END SRV7 current-source srv7-0993-foreign-key-indexes.sql

-- BEGIN SRV7 indexed current-transaction Cake proof
-- Ordinary condition snapshots and each native Cake action must find only their
-- own transaction's receipts rather than scan accumulated event history.
CREATE INDEX game_seasonal_cake_food_character_xact ON game_seasonal_cake_food_uses(character_id,created_xact_id);
CREATE INDEX game_seasonal_cake_bite_world_event_xact ON game_seasonal_cake_bite_receipts(world_id,event_start,created_xact_id);
CREATE INDEX game_seasonal_cake_extraction_world_event_xact ON game_seasonal_cake_extractions(world_id,event_start,created_xact_id);
CREATE INDEX game_seasonal_cake_delivery_world_event_xact ON game_seasonal_cake_deliveries(world_id,event_start,created_xact_id);
CREATE INDEX game_seasonal_cake_poll_world_event_xact ON game_seasonal_cake_stage_polls(world_id,event_start,created_xact_id);
CREATE INDEX game_seasonal_cake_windows_world_event_xact ON game_seasonal_cake_windows(world_id,event_start,created_xact_id);

-- END SRV7 indexed current-transaction Cake proof

-- BEGIN SRV7 individually moved Santa toy source clocks.
-- Closed Santa toy aliases: XML default duration starts only when that Item
-- actually moves (Crystal game.cpp2418/2426), never when its containing giftbag moves.
CREATE TABLE game_santa_toy_lifetimes(item_key TEXT PRIMARY KEY,target_key TEXT NOT NULL,duration_ms BIGINT NOT NULL CHECK(duration_ms=3000));
INSERT INTO game_santa_toy_lifetimes VALUES('oteryn:item.tibia.i6566','oteryn:item.tibia.i5791',3000),('oteryn:item.tibia.i6567','oteryn:item.tibia.i6511',3000),('oteryn:item.tibia.i6568','oteryn:item.tibia.i5080',3000);
REVOKE ALL ON game_santa_toy_lifetimes FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
GRANT SELECT ON game_santa_toy_lifetimes TO oteryn_game_runtime,oteryn_game_control;
CREATE FUNCTION game_santa_toy_movement_start(p_tx UUID) RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE r game_item_loop_move_receipts%ROWTYPE; l game_item_loop_move_lines%ROWTYPE;
 life game_santa_toy_lifetimes%ROWTYPE; started BIGINT;
BEGIN
 SELECT * INTO r FROM game_item_loop_move_receipts WHERE transaction_id=p_tx;
 IF r.transaction_id IS NULL OR r.created_xact_id<>pg_current_xact_id() THEN
  RAISE EXCEPTION 'Santa toy duration starts only with original movement' USING ERRCODE='23514'; END IF;
 started:=floor(extract(epoch FROM r.created_at)*1000)::bigint;
 FOR l IN SELECT * FROM game_item_loop_move_lines WHERE transaction_id=p_tx
  AND definition_production_key IN('oteryn:item.tibia.i6566','oteryn:item.tibia.i6567','oteryn:item.tibia.i6568')
  AND quantity_before=1 AND quantity_after=1 AND from_kind IN(1,2,3) AND to_kind IN(1,2,3) LOOP
  IF EXISTS(SELECT 1 FROM game_spell_item_temporal_schedules WHERE item_instance_id=l.item_instance_id)
   OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=l.item_instance_id) THEN CONTINUE; END IF;
  SELECT * INTO life FROM game_santa_toy_lifetimes
   WHERE item_key=l.definition_production_key;
  IF life.duration_ms IS NULL OR life.target_key IS NULL THEN
   RAISE EXCEPTION 'qualified Santa toy lost duration source' USING ERRCODE='23514'; END IF;
  INSERT INTO game_spell_item_temporal_schedules(item_instance_id,source_transaction_id,source_ordinal,
   duration_millis,expires_at_unix_ms,definition_family,definition_production_key,definition_revision,
   target_family,target_production_key,target_revision,content_digest)
  VALUES(l.item_instance_id,r.transaction_id,l.line_ordinal,life.duration_ms,started+life.duration_ms,
   l.definition_family,l.definition_production_key,l.definition_revision_ref,'Item',
   life.target_key,l.definition_revision_ref,r.content_digest);
 END LOOP;
END $$;
DO $migration$ DECLARE body TEXT; arm TEXT; begin_at INTEGER; BEGIN
 body:=pg_get_functiondef('game_spell_item_temporal_schedule_proven()'::regprocedure);
 begin_at:=regexp_instr(body,E'\\mBEGIN\\M',1,1,0,'i');
 IF begin_at=0 THEN RAISE EXCEPTION 'missing Item temporal source proof'; END IF;
 arm:=$arm$
 IF EXISTS(SELECT 1 FROM game_item_loop_move_receipts r JOIN game_item_loop_move_lines l USING(transaction_id)
  JOIN game_item_instances i USING(item_instance_id) JOIN game_santa_toy_lifetimes life
   ON life.item_key=l.definition_production_key
  WHERE r.transaction_id=NEW.source_transaction_id AND l.line_ordinal=NEW.source_ordinal
   AND l.item_instance_id=NEW.item_instance_id AND l.created_xact_id=pg_current_xact_id()
   AND r.created_xact_id=pg_current_xact_id() AND NEW.created_xact_id=pg_current_xact_id()
   AND i.lifecycle=1 AND i.quantity=1 AND l.quantity_before=1 AND l.quantity_after=1
   AND l.from_kind IN(1,2,3) AND l.to_kind IN(1,2,3)
   AND life.item_key IN('oteryn:item.tibia.i6566','oteryn:item.tibia.i6567','oteryn:item.tibia.i6568')
   AND (i.definition_family,i.definition_production_key,i.definition_revision_ref)=
    (NEW.definition_family,NEW.definition_production_key,NEW.definition_revision)
   AND (l.definition_family,l.definition_production_key,l.definition_revision_ref)=
    (NEW.definition_family,NEW.definition_production_key,NEW.definition_revision)
   AND NEW.duration_millis=life.duration_ms
   AND NEW.expires_at_unix_ms=floor(extract(epoch FROM r.created_at)*1000)::bigint+life.duration_ms
   AND NEW.target_family='Item' AND NEW.target_production_key=life.target_key
   AND NEW.target_revision=NEW.definition_revision AND NEW.content_digest=r.content_digest
   AND NOT EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=i.item_instance_id))
 THEN RETURN NULL; END IF;
 $arm$;
 EXECUTE substring(body FROM 1 FOR begin_at+4)||E'\n'||arm||substring(body FROM begin_at+5);
END $migration$;
DO $$ BEGIN
 EXECUTE format('ALTER FUNCTION game_santa_toy_movement_start(uuid) SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $$;
REVOKE ALL ON FUNCTION game_santa_toy_movement_start(uuid) FROM PUBLIC,oteryn_game_control;
GRANT EXECUTE ON FUNCTION game_santa_toy_movement_start(uuid) TO oteryn_game_runtime;

-- END SRV7 individually moved Santa toy source clocks.

-- BEGIN SRV7 santa-toy-transfer-start.sql
-- Separate source proof for individually moved Santa toys in the mature House
-- transfer owner. The existing immutable transfer audit timestamp is unchanged.
ALTER TABLE game_item_transfer_receipts
 ADD COLUMN santa_toy_content_digest BYTEA CHECK(santa_toy_content_digest IS NULL OR octet_length(santa_toy_content_digest)=32);
CREATE FUNCTION game_santa_toy_transfer_current(santa_transfer game_item_transfer_receipts,santa_item game_item_instances)
RETURNS BOOLEAN LANGUAGE sql STABLE AS $$
 SELECT santa_transfer.created_xact_id=pg_current_xact_id() AND santa_transfer.shape IN(5,6,7)
  AND santa_transfer.source_item_instance_id=santa_item.item_instance_id
  AND santa_transfer.source_quantity_before=1 AND santa_transfer.source_quantity_after=1
  AND santa_item.lifecycle=1 AND santa_item.quantity=1
  AND CASE WHEN santa_transfer.shape IN(5,7) THEN EXISTS(
   SELECT 1 FROM game_item_house_interior_locations santa_house WHERE santa_house.item_instance_id=santa_item.item_instance_id
    AND santa_house.world_id=santa_item.world_id AND santa_house.placed_transaction_id=santa_transfer.transaction_id)
  ELSE EXISTS(SELECT 1 FROM game_item_container_entries santa_entry
   WHERE santa_entry.item_instance_id=santa_item.item_instance_id AND santa_entry.world_id=santa_item.world_id
    AND santa_entry.character_id=santa_transfer.character_id
    AND santa_entry.parent_item_instance_id=santa_transfer.destination_parent_item_instance_id
    AND santa_entry.placement_ordinal=santa_transfer.destination_ordinal
    AND santa_entry.placed_transaction_id=santa_transfer.transaction_id) END
$$;
CREATE FUNCTION game_santa_toy_transfer_start(p_transaction UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE santa_transfer game_item_transfer_receipts%ROWTYPE; santa_item game_item_instances%ROWTYPE; santa_life game_santa_toy_lifetimes%ROWTYPE;
BEGIN
 SELECT * INTO santa_transfer FROM game_item_transfer_receipts WHERE transaction_id=p_transaction;
 IF santa_transfer.transaction_id IS NULL OR santa_transfer.created_xact_id<>pg_current_xact_id() THEN
  RAISE EXCEPTION 'Santa toy requires current individual House movement' USING ERRCODE='23514'; END IF;
 IF santa_transfer.santa_toy_content_digest IS NULL THEN RETURN; END IF;
 SELECT * INTO santa_item FROM game_item_instances WHERE item_instance_id=santa_transfer.source_item_instance_id;
 SELECT * INTO santa_life FROM game_santa_toy_lifetimes WHERE item_key=santa_item.definition_production_key;
 IF santa_life.item_key IS NULL OR santa_transfer.physical_started_at_unix_ms IS NULL
  OR game_santa_toy_transfer_current(santa_transfer,santa_item) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'Santa toy clock lacks exact current House movement' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM game_spell_item_temporal_schedules WHERE item_instance_id=santa_item.item_instance_id)
  OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=santa_item.item_instance_id) THEN RETURN; END IF;
 INSERT INTO game_spell_item_temporal_schedules(item_instance_id,source_transaction_id,source_ordinal,
 duration_millis,expires_at_unix_ms,definition_family,definition_production_key,definition_revision,
 target_family,target_production_key,target_revision,content_digest)
 VALUES(santa_item.item_instance_id,santa_transfer.transaction_id,1,santa_life.duration_ms,
 santa_transfer.physical_started_at_unix_ms+santa_life.duration_ms,santa_item.definition_family,
 santa_item.definition_production_key,santa_item.definition_revision_ref,'Item',santa_life.target_key,
 santa_item.definition_revision_ref,santa_transfer.santa_toy_content_digest);
END $$;
DO $migration$ DECLARE body TEXT; arm TEXT; at INTEGER; BEGIN
 body:=pg_get_functiondef('game_spell_item_temporal_schedule_proven()'::regprocedure);at:=regexp_instr(body,E'\\mBEGIN\\M',1,1,0,'i');
 IF at=0 THEN RAISE EXCEPTION 'missing original absolute timer guard'; END IF;
 arm:=$arm$
 IF EXISTS(SELECT 1 FROM game_item_transfer_receipts santa_transfer
 JOIN game_item_instances santa_item ON santa_item.item_instance_id=santa_transfer.source_item_instance_id
 JOIN game_santa_toy_lifetimes santa_life ON santa_life.item_key=santa_item.definition_production_key
 WHERE santa_transfer.transaction_id=NEW.source_transaction_id AND NEW.source_ordinal=1
  AND santa_item.item_instance_id=NEW.item_instance_id AND NEW.created_xact_id=pg_current_xact_id()
  AND game_santa_toy_transfer_current(santa_transfer,santa_item) IS TRUE
  AND (NEW.definition_family,NEW.definition_production_key,NEW.definition_revision)=(santa_item.definition_family,santa_item.definition_production_key,santa_item.definition_revision_ref)
  AND (NEW.target_family,NEW.target_production_key,NEW.target_revision)=('Item',santa_life.target_key,santa_item.definition_revision_ref)
  AND NEW.duration_millis=santa_life.duration_ms
  AND NEW.expires_at_unix_ms=santa_transfer.physical_started_at_unix_ms+santa_life.duration_ms
  AND NEW.content_digest=santa_transfer.santa_toy_content_digest
  AND NOT EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=NEW.item_instance_id)) THEN RETURN NULL; END IF;
 $arm$;
 EXECUTE overlay(body placing E'BEGIN\n'||arm from at for 5);
END $migration$;
DO $$ DECLARE f REGPROCEDURE; BEGIN
 FOREACH f IN ARRAY ARRAY['game_santa_toy_transfer_start(uuid)'::regprocedure,'game_santa_toy_transfer_current(game_item_transfer_receipts,game_item_instances)'::regprocedure] LOOP
 EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',f,current_schema());
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_control',f);
 EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO oteryn_game_runtime',f);
 END LOOP;
END $$;
CREATE FUNCTION game_santa_toy_transfer_clock_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF NEW.shape IN(5,6,7) AND EXISTS(SELECT 1 FROM game_item_instances santa_item
  JOIN game_santa_toy_lifetimes santa_life ON santa_life.item_key=santa_item.definition_production_key
  WHERE santa_item.item_instance_id=NEW.source_item_instance_id)
  AND NOT EXISTS(SELECT 1 FROM game_spell_item_temporal_schedules WHERE item_instance_id=NEW.source_item_instance_id)
  AND NOT EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=NEW.source_item_instance_id) THEN
  RAISE EXCEPTION 'individual House toy movement requires its original source clock' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_santa_toy_transfer_clock_complete AFTER INSERT ON game_item_transfer_receipts
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_santa_toy_transfer_clock_complete();
DO $$ BEGIN EXECUTE format('ALTER FUNCTION game_santa_toy_transfer_clock_complete() SET search_path=pg_catalog,%I,pg_temp',current_schema()); END $$;
REVOKE ALL ON FUNCTION game_santa_toy_transfer_clock_complete() FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;

-- END SRV7 santa-toy-transfer-start.sql

-- BEGIN SRV7 santa-toy-loop-complete.sql
-- A valid individual movement cannot omit its required source clock.
CREATE FUNCTION game_santa_toy_loop_clock_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF NEW.from_kind IN(1,2,3) AND NEW.to_kind IN(1,2,3)
  AND NEW.quantity_before=1 AND NEW.quantity_after=1
  AND EXISTS(SELECT 1 FROM game_santa_toy_lifetimes WHERE item_key=NEW.definition_production_key)
  AND NOT EXISTS(SELECT 1 FROM game_spell_item_temporal_schedules WHERE item_instance_id=NEW.item_instance_id)
  AND NOT EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=NEW.item_instance_id) THEN
  RAISE EXCEPTION 'individual toy movement requires its original source clock' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_santa_toy_loop_clock_complete AFTER INSERT ON game_item_loop_move_lines
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_santa_toy_loop_clock_complete();
DO $$ BEGIN EXECUTE format('ALTER FUNCTION game_santa_toy_loop_clock_complete() SET search_path=pg_catalog,%I,pg_temp',current_schema()); END $$;
REVOKE ALL ON FUNCTION game_santa_toy_loop_clock_complete() FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;

-- END SRV7 santa-toy-loop-complete.sql

-- BEGIN SRV7 santa-toy-house-expiry.sql
-- Admit only the three already-sealed toy schedules to the existing named-House
-- absolute deadline owner. Its current Node/House/custody/CAS/audit chain is retained.
CREATE FUNCTION game_santa_toy_schedule_matches(toy_schedule game_spell_item_temporal_schedules)
RETURNS BOOLEAN LANGUAGE sql STABLE AS $$
 SELECT toy_schedule.definition_family='Item' AND toy_schedule.target_family='Item'
  AND toy_schedule.target_revision=toy_schedule.definition_revision
  AND EXISTS(SELECT 1 FROM game_santa_toy_lifetimes toy_schedule_life
   WHERE toy_schedule_life.item_key=toy_schedule.definition_production_key
    AND toy_schedule_life.target_key=toy_schedule.target_production_key
    AND toy_schedule_life.duration_ms=toy_schedule.duration_millis)
$$;
