 needle:=$old$p.definition_production_key NOT IN('oteryn:item.tibia.i9034','oteryn:item.tibia.i9039',
   'oteryn:item.tibia.i35949','oteryn:item.tibia.i35951','oteryn:item.tibia.i35969','oteryn:item.tibia.i35971')$old$;
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'missing original House expiry completion source predicate'; END IF;
 EXECUTE replace(body,needle,'('||needle||' AND game_santa_toy_schedule_matches(p) IS DISTINCT FROM TRUE)');
 body:=pg_get_functiondef('game_house_furniture_absolute_expire(uuid,uuid,numeric,numeric,numeric,uuid,numeric,uuid,text)'::regprocedure);
 needle:=$old$i.definition_production_key IN('oteryn:item.tibia.i9034','oteryn:item.tibia.i9039',
    'oteryn:item.tibia.i35949','oteryn:item.tibia.i35951','oteryn:item.tibia.i35969','oteryn:item.tibia.i35971')$old$;
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'missing original House expiry candidate source predicate'; END IF;
 EXECUTE replace(body,needle,'('||needle||' OR game_santa_toy_schedule_matches(schedule) IS TRUE)');
END $migration$;
DO $$ BEGIN EXECUTE format('ALTER FUNCTION game_santa_toy_schedule_matches(game_spell_item_temporal_schedules) SET search_path=pg_catalog,%I,pg_temp',current_schema()); END $$;
REVOKE ALL ON FUNCTION game_santa_toy_schedule_matches(game_spell_item_temporal_schedules) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION game_santa_toy_schedule_matches(game_spell_item_temporal_schedules) TO oteryn_game_runtime,oteryn_game_control;

-- END SRV7 santa-toy-house-expiry.sql

-- BEGIN SRV7 pumpkin-reward-visits.sql
-- Halloween current rewardroom:8133death is distinct from static12816 rewardobject.
CREATE TABLE game_pumpkin_reward_visits(
 world_id UUID NOT NULL,death_id UUID NOT NULL,character_id UUID NOT NULL REFERENCES game_character_roots(character_id),
 first_entry_ms BIGINT NOT NULL CHECK(first_entry_ms>0),deadline_ms BIGINT NOT NULL CHECK(deadline_ms=first_entry_ms+300000),
 source_game_session_id UUID NOT NULL REFERENCES game_durability_reconnect_sessions(game_session_id),source_occurrence BYTEA NOT NULL CHECK(octet_length(source_occurrence)=32),created_xact_id XID8 NOT NULL,
 PRIMARY KEY(character_id,world_id,death_id),UNIQUE(character_id,world_id,source_occurrence),FOREIGN KEY(world_id,death_id) REFERENCES game_boss_reward_deaths(world_id,death_id));
CREATE INDEX game_pumpkin_visits_source_session ON game_pumpkin_reward_visits(source_game_session_id);
CREATE INDEX game_pumpkin_visits_death ON game_pumpkin_reward_visits(world_id,death_id);
CREATE TABLE game_pumpkin_source_context(
 backend_pid INTEGER PRIMARY KEY,transaction_xid XID8 NOT NULL,world_id UUID NOT NULL,channel_id UUID NOT NULL,
 generation NUMERIC NOT NULL,character_id UUID NOT NULL,game_session_id UUID NOT NULL,connection NUMERIC NOT NULL,
 lease NUMERIC NOT NULL,phase TEXT NOT NULL CHECK(phase IN('visit','replay_visit','claim')),death_id UUID NOT NULL,
 occurrence BYTEA,command_id NUMERIC,knife_id UUID,body_placement BYTEA,body_revision NUMERIC,map_digest BYTEA,wire_binding BYTEA,
 knife_before JSONB);
REVOKE ALL ON game_pumpkin_source_context FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
CREATE FUNCTION game_pumpkin_skinning_current() RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT EXISTS(SELECT 1 FROM game_pumpkin_source_context c
 JOIN game_durability_reconnect_sessions s ON s.game_session_id=c.game_session_id
 JOIN game_character_roots r ON r.character_id=c.character_id
 JOIN game_durability_admission_character_guards cg ON cg.character_id=c.character_id
 JOIN game_durability_admission_account_guards ag ON ag.account_id=cg.account_id
 JOIN game_durability_admission_runtime_guards rg ON rg.scope_key='\x01'::bytea||uuid_send(c.world_id)||uuid_send(c.channel_id)
 WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id()
 AND s.character_id=c.character_id AND s.world_id=c.world_id AND s.runtime_scope_kind=1
 AND s.runtime_scope_world_id=c.world_id AND s.runtime_scope_channel_id=c.channel_id
 AND s.runtime_scope_instance_id IS NULL AND s.runtime_scope_house_key IS NULL
 AND s.current_generation=c.connection AND s.character_lease_generation=c.lease
 AND s.scope_ownership_generation=c.generation AND s.session_state IN(1,2)
 AND r.world_id=c.world_id AND r.account_id=s.account_id AND r.lifecycle=1
 AND cg.account_id=s.account_id AND cg.world_id=c.world_id AND cg.eligible
 AND cg.lease_generation=c.lease AND cg.holder_game_session_id=c.game_session_id
 AND ag.presence_character_id=c.character_id AND ag.holder_game_session_id=c.game_session_id
 AND rg.ready AND rg.ownership_generation=c.generation)
$$;
CREATE FUNCTION game_pumpkin_source_arm(p_world UUID,p_channel UUID,p_generation NUMERIC,p_node UUID,p_registration NUMERIC,p_secret BYTEA,
 p_character UUID,p_session UUID,p_connection NUMERIC,p_lease NUMERIC,p_phase TEXT,p_death UUID,p_occurrence BYTEA,p_command NUMERIC,
 p_knife UUID,p_placement BYTEA,p_revision NUMERIC,p_map BYTEA,p_wire BYTEA)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE knife JSONB; now_ms BIGINT;
BEGIN
 IF p_secret IS NULL OR octet_length(p_secret)<>32 OR p_phase IS NULL OR p_phase NOT IN('visit','replay_visit')
 OR NOT game_node_prove_current_incarnation(p_node,p_registration,p_secret) OR NOT game_runtime_scope_assignment_history_valid() THEN
 RAISE EXCEPTION 'Halloween source requires current Node possession' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM game_runtime_scope_assignments a WHERE a.scope_key='\x01'::bytea||uuid_send(p_world)||uuid_send(p_channel)
 AND a.scope_kind=1 AND a.world_id=p_world AND a.channel_id=p_channel AND a.state=1 AND a.ownership_generation=p_generation
 AND a.holder_node_id=p_node AND a.holder_registration_revision=p_registration FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'stale Halloween Channel' USING ERRCODE='23514'; END IF;
 now_ms:=floor(extract(epoch FROM public.game_daily_effect_now())*1000)::bigint;
 PERFORM 1 FROM game_boss_reward_contributors bc JOIN game_boss_reward_deaths bd USING(world_id,death_id)
 WHERE bc.character_id=p_character AND bc.world_id=p_world AND bc.death_id=p_death
 AND bd.boss_key='oteryn:creature.the_mutated_pumpkin' AND bd.scope_kind=1 AND bd.settlement_outcome=1 AND bd.channel_id=p_channel
 AND bd.minted_at<=now_ms AND (bc.damage_dealt>0 OR bc.damage_received>0 OR bc.healing_others>0)
 AND (p_phase IN('claim','replay_visit') OR bd.minted_at+1800000>now_ms) FOR SHARE OF bc,bd;
 IF NOT FOUND THEN RAISE EXCEPTION 'Halloween source requires actual fight participation and live entry window' USING ERRCODE='23514'; END IF;
 IF p_phase IN('visit','replay_visit') THEN
  IF p_occurrence IS NULL OR octet_length(p_occurrence)<>32 OR p_command IS NOT NULL OR p_knife IS NOT NULL OR p_placement IS NOT NULL
  OR p_revision IS NOT NULL OR p_map IS NOT NULL OR p_wire IS NOT NULL THEN RAISE EXCEPTION 'invalid committed portal STEP occurrence' USING ERRCODE='23514'; END IF;
  IF p_phase='replay_visit' AND NOT EXISTS(SELECT 1 FROM game_pumpkin_reward_visits v WHERE v.character_id=p_character AND v.world_id=p_world
   AND v.death_id=p_death AND v.source_occurrence=p_occurrence AND v.deadline_ms>now_ms) THEN
   RAISE EXCEPTION 'Halloween entry replay requires its exact live committed first occurrence' USING ERRCODE='23514'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM game_pumpkin_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id()) THEN
 RAISE EXCEPTION 'Halloween source transaction already armed' USING ERRCODE='23514'; END IF;
 DELETE FROM game_pumpkin_source_context c WHERE c.backend_pid=pg_backend_pid() OR NOT EXISTS(SELECT 1 FROM pg_stat_activity a WHERE a.pid=c.backend_pid);
 INSERT INTO game_pumpkin_source_context VALUES(pg_backend_pid(),pg_current_xact_id(),p_world,p_channel,p_generation,p_character,p_session,p_connection,p_lease,p_phase,p_death,p_occurrence,p_command,p_knife,p_placement,p_revision,p_map,p_wire,knife);
 PERFORM 1 FROM game_durability_reconnect_sessions s JOIN game_durability_admission_character_guards cg ON cg.character_id=p_character
 JOIN game_durability_admission_account_guards ag ON ag.account_id=cg.account_id
 JOIN game_durability_admission_runtime_guards rg ON rg.scope_key='\x01'::bytea||uuid_send(p_world)||uuid_send(p_channel)
 WHERE s.game_session_id=p_session AND s.character_id=p_character FOR SHARE OF s,cg,ag,rg;
 IF NOT FOUND OR NOT game_pumpkin_skinning_current() THEN RAISE EXCEPTION 'stale Halloween Character/session/lease/scope fence' USING ERRCODE='23514'; END IF;
END $$;
CREATE FUNCTION game_pumpkin_visit_admit() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_pumpkin_source_context%ROWTYPE;
BEGIN
 SELECT * INTO c FROM game_pumpkin_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF NOT game_pumpkin_skinning_current() OR c.phase IS DISTINCT FROM 'visit'
 OR (NEW.world_id,NEW.death_id,NEW.character_id,NEW.source_game_session_id,NEW.source_occurrence)
 IS DISTINCT FROM(c.world_id,c.death_id,c.character_id,c.game_session_id,c.occurrence) THEN
 RAISE EXCEPTION 'Halloween visit requires committed native portal STEP and current participant' USING ERRCODE='23514'; END IF;
 NEW.first_entry_ms:=floor(extract(epoch FROM public.game_daily_effect_now())*1000)::bigint; NEW.deadline_ms:=NEW.first_entry_ms+300000;
 NEW.created_xact_id:=pg_current_xact_id(); RETURN NEW;
END $$;
CREATE TRIGGER game_pumpkin_visit_admit BEFORE INSERT ON game_pumpkin_reward_visits FOR EACH ROW EXECUTE FUNCTION game_pumpkin_visit_admit();
CREATE TRIGGER game_pumpkin_visit_immutable BEFORE UPDATE OR DELETE ON game_pumpkin_reward_visits FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_pumpkin_visit_no_truncate BEFORE TRUNCATE ON game_pumpkin_reward_visits FOR EACH STATEMENT EXECUTE FUNCTION game_world_reset_history_immutable();
REVOKE ALL ON game_pumpkin_reward_visits FROM PUBLIC;
GRANT SELECT,INSERT ON game_pumpkin_reward_visits TO oteryn_game_runtime;
GRANT SELECT ON game_pumpkin_reward_visits TO oteryn_game_control;
DO $$ DECLARE signature TEXT; BEGIN
 FOREACH signature IN ARRAY ARRAY['game_pumpkin_skinning_current()',
 'game_pumpkin_source_arm(uuid,uuid,numeric,uuid,numeric,bytea,uuid,uuid,numeric,numeric,text,uuid,bytea,numeric,uuid,bytea,numeric,bytea,bytea)',
 'game_pumpkin_visit_admit()'] LOOP
 EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',signature,current_schema());
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',signature);
 END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION game_pumpkin_source_arm(uuid,uuid,numeric,uuid,numeric,bytea,uuid,uuid,numeric,numeric,text,uuid,bytea,numeric,uuid,bytea,numeric,bytea,bytea) TO oteryn_game_runtime;

-- END SRV7 pumpkin-reward-visits.sql

-- BEGIN SRV7 pumpkin static skinning claims
-- HELD until actual native visit→static12816 USE_WITH RED.
CREATE TABLE game_pumpkin_skinning_receipts(
 transaction_id UUID PRIMARY KEY REFERENCES game_reward_claim_mint_receipts(transaction_id),character_id UUID NOT NULL,
 world_id UUID NOT NULL,death_id UUID NOT NULL,game_session_id UUID NOT NULL,command_id NUMERIC(20,0) NOT NULL,
 knife_id UUID NOT NULL,body_placement BYTEA NOT NULL CHECK(octet_length(body_placement)=40),body_revision NUMERIC(20,0) NOT NULL,
 map_digest BYTEA NOT NULL CHECK(octet_length(map_digest)=32),wire_binding BYTEA NOT NULL CHECK(octet_length(wire_binding)=32),
 used_at BIGINT NOT NULL CHECK(used_at>0),draw_index SMALLINT NOT NULL CHECK(draw_index BETWEEN 0 AND 12),
 source_item_id BIGINT NOT NULL,quantity BIGINT NOT NULL CHECK(quantity BETWEEN 1 AND 50),created_xact_id XID8 NOT NULL,
 UNIQUE(game_session_id,command_id),FOREIGN KEY(character_id,world_id,death_id) REFERENCES game_pumpkin_reward_visits(character_id,world_id,death_id));
CREATE INDEX game_pumpkin_skinning_personal_clock ON game_pumpkin_skinning_receipts(character_id,used_at DESC);
CREATE INDEX game_pumpkin_skinning_visit ON game_pumpkin_skinning_receipts(character_id,world_id,death_id);
CREATE FUNCTION game_pumpkin_skinning_draw(p_session UUID,p_nonce NUMERIC,p_source UUID,p_domain INTEGER,p_upper INTEGER)
RETURNS INTEGER LANGUAGE plpgsql IMMUTABLE STRICT AS $$
DECLARE command_bytes BYTEA; digest BYTEA; value NUMERIC; zone NUMERIC; counter INTEGER; n INTEGER;
BEGIN
 IF p_nonce<>trunc(p_nonce) OR p_nonce NOT BETWEEN 0 AND 18446744073709551615 OR (p_domain,p_upper) NOT IN((213,13),(214,50)) THEN
  RAISE EXCEPTION 'invalid closed Pumpkin skinning RNG domain' USING ERRCODE='23514'; END IF;
 command_bytes:=int8send((CASE WHEN p_nonce>9223372036854775807 THEN p_nonce-18446744073709551616 ELSE p_nonce END)::bigint);
 zone:=18446744073709551615-mod(18446744073709551615,p_upper);
 FOR counter IN 0..15 LOOP
  digest:=sha256(convert_to('oteryn:reward-bag-draw:v1','UTF8')||uuid_send(p_session)||command_bytes
   ||uuid_send(p_source)||set_byte(decode('00','hex'),0,p_domain)||int4send(counter));
  value:=0;
  FOR n IN 0..7 LOOP value:=value*256+get_byte(digest,n); END LOOP;
  IF value<zone THEN RETURN mod(value,p_upper)::integer; END IF;
 END LOOP;
 RAISE EXCEPTION 'Pumpkin skinning RNG rejection resource bound' USING ERRCODE='23514';
END $$;
CREATE OR REPLACE FUNCTION game_pumpkin_source_arm(p_world UUID,p_channel UUID,p_generation NUMERIC,p_node UUID,p_registration NUMERIC,p_secret BYTEA,
 p_character UUID,p_session UUID,p_connection NUMERIC,p_lease NUMERIC,p_phase TEXT,p_death UUID,p_occurrence BYTEA,p_command NUMERIC,
 p_knife UUID,p_placement BYTEA,p_revision NUMERIC,p_map BYTEA,p_wire BYTEA)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE knife JSONB; now_ms BIGINT;
BEGIN
 IF p_secret IS NULL OR octet_length(p_secret)<>32 OR p_phase IS NULL OR p_phase NOT IN('visit','replay_visit','claim')
 OR NOT game_node_prove_current_incarnation(p_node,p_registration,p_secret) OR NOT game_runtime_scope_assignment_history_valid() THEN
 RAISE EXCEPTION 'Halloween source requires current Node possession' USING ERRCODE='23514'; END IF;
 PERFORM 1 FROM game_runtime_scope_assignments a WHERE a.scope_key='\x01'::bytea||uuid_send(p_world)||uuid_send(p_channel)
 AND a.scope_kind=1 AND a.world_id=p_world AND a.channel_id=p_channel AND a.state=1 AND a.ownership_generation=p_generation
 AND a.holder_node_id=p_node AND a.holder_registration_revision=p_registration FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'stale Halloween Channel' USING ERRCODE='23514'; END IF;
 now_ms:=floor(extract(epoch FROM public.game_daily_effect_now())*1000)::bigint;
 PERFORM 1 FROM game_boss_reward_contributors bc JOIN game_boss_reward_deaths bd USING(world_id,death_id)
 WHERE bc.character_id=p_character AND bc.world_id=p_world AND bc.death_id=p_death
 AND bd.boss_key='oteryn:creature.the_mutated_pumpkin' AND bd.scope_kind=1 AND bd.settlement_outcome=1 AND bd.channel_id=p_channel
 AND bd.minted_at<=now_ms AND (bc.damage_dealt>0 OR bc.damage_received>0 OR bc.healing_others>0)
 AND (p_phase IN('claim','replay_visit') OR bd.minted_at+1800000>now_ms) FOR SHARE OF bc,bd;
 IF NOT FOUND THEN RAISE EXCEPTION 'Halloween source requires actual fight participation and live entry window' USING ERRCODE='23514'; END IF;
 IF p_phase IN('visit','replay_visit') THEN
  IF p_occurrence IS NULL OR octet_length(p_occurrence)<>32 OR p_command IS NOT NULL OR p_knife IS NOT NULL OR p_placement IS NOT NULL
  OR p_revision IS NOT NULL OR p_map IS NOT NULL OR p_wire IS NOT NULL THEN RAISE EXCEPTION 'invalid committed portal STEP occurrence' USING ERRCODE='23514'; END IF;
  IF p_phase='replay_visit' AND NOT EXISTS(SELECT 1 FROM game_pumpkin_reward_visits v WHERE v.character_id=p_character AND v.world_id=p_world
   AND v.death_id=p_death AND v.source_occurrence=p_occurrence AND v.deadline_ms>now_ms) THEN
   RAISE EXCEPTION 'Halloween entry replay requires its exact live committed first occurrence' USING ERRCODE='23514'; END IF;
 ELSE
  IF p_command IS NULL OR p_command<1 OR p_command<>trunc(p_command) OR p_command>18446744073709551615
  OR p_knife IS NULL OR p_placement IS NULL OR octet_length(p_placement)<>40 OR p_revision IS NULL OR p_revision<0 OR p_revision>18446744073709551615 OR p_revision<>trunc(p_revision)
  OR p_map IS NULL OR octet_length(p_map)<>32 OR p_map=decode(repeat('00',32),'hex') OR p_wire IS NULL OR octet_length(p_wire)<>32
  OR p_occurrence IS NOT NULL THEN RAISE EXCEPTION 'invalid source-qualified12816 map body' USING ERRCODE='23514'; END IF;
  PERFORM 1 FROM game_pumpkin_reward_visits v WHERE v.character_id=p_character AND v.world_id=p_world AND v.death_id=p_death AND v.deadline_ms>now_ms FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Halloween reward room visit expired or missing' USING ERRCODE='23514'; END IF;
  WITH RECURSIVE carried(id) AS (
   SELECT e.item_instance_id FROM game_item_container_entries e JOIN game_item_container_slots b ON b.character_id=e.character_id AND b.item_instance_id=e.parent_item_instance_id
   WHERE e.character_id=p_character AND e.world_id=p_world AND b.world_id=p_world
   UNION SELECT n.item_instance_id FROM game_item_nested_entries n JOIN carried c ON n.parent_item_instance_id=c.id WHERE n.world_id=p_world)
  SELECT to_jsonb(i) INTO knife FROM game_item_instances i WHERE i.item_instance_id=p_knife AND i.world_id=p_world AND i.lifecycle=1 AND i.quantity>0
   AND i.definition_family='Item' AND i.definition_production_key='oteryn:item.tibia.i5908' AND EXISTS(SELECT 1 FROM carried c WHERE c.id=i.item_instance_id) FOR UPDATE OF i;
  IF knife IS NULL THEN RAISE EXCEPTION 'Halloween skinning requires carried exact knife' USING ERRCODE='23514'; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM game_pumpkin_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id()) THEN
 RAISE EXCEPTION 'Halloween source transaction already armed' USING ERRCODE='23514'; END IF;
 DELETE FROM game_pumpkin_source_context c WHERE c.backend_pid=pg_backend_pid() OR NOT EXISTS(SELECT 1 FROM pg_stat_activity a WHERE a.pid=c.backend_pid);
 INSERT INTO game_pumpkin_source_context VALUES(pg_backend_pid(),pg_current_xact_id(),p_world,p_channel,p_generation,p_character,p_session,p_connection,p_lease,p_phase,p_death,p_occurrence,p_command,p_knife,p_placement,p_revision,p_map,p_wire,knife);
 PERFORM 1 FROM game_durability_reconnect_sessions s JOIN game_durability_admission_character_guards cg ON cg.character_id=p_character
 JOIN game_durability_admission_account_guards ag ON ag.account_id=cg.account_id
 JOIN game_durability_admission_runtime_guards rg ON rg.scope_key='\x01'::bytea||uuid_send(p_world)||uuid_send(p_channel)
 WHERE s.game_session_id=p_session AND s.character_id=p_character FOR SHARE OF s,cg,ag,rg;
 IF NOT FOUND OR NOT game_pumpkin_skinning_current() THEN RAISE EXCEPTION 'stale Halloween Character/session/lease/scope fence' USING ERRCODE='23514'; END IF;
END $$;
CREATE FUNCTION game_pumpkin_visit_draw_nonce(p_occurrence BYTEA) RETURNS NUMERIC LANGUAGE plpgsql IMMUTABLE STRICT AS $$
DECLARE n INTEGER; value NUMERIC:=0;
BEGIN
 IF octet_length(p_occurrence)<>32 THEN RAISE EXCEPTION 'invalid source visit occurrence' USING ERRCODE='23514'; END IF;
 FOR n IN 0..7 LOOP value:=value*256+get_byte(p_occurrence,n); END LOOP;RETURN value;
END $$;
CREATE FUNCTION game_pumpkin_skinning_admit() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_pumpkin_source_context%ROWTYPE; ids BIGINT[]:=ARRAY[8032,8178,6491,6525,8177,6571,6570,6574,2977,3594,3599,6569,6574];
 counts BIGINT[]:=ARRAY[1,1,1,1,20,1,1,50,1,50,50,50,50]; idx INTEGER; chosen_count BIGINT; rng_session UUID; rng_occurrence BYTEA; nonce NUMERIC;
BEGIN
 SELECT * INTO c FROM game_pumpkin_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF NOT game_pumpkin_skinning_current() OR c.phase IS DISTINCT FROM 'claim'
 OR(NEW.character_id,NEW.world_id,NEW.death_id,NEW.game_session_id,NEW.command_id,NEW.knife_id,NEW.body_placement,NEW.body_revision,NEW.map_digest,NEW.wire_binding)
 IS DISTINCT FROM(c.character_id,c.world_id,c.death_id,c.game_session_id,c.command_id,c.knife_id,c.body_placement,c.body_revision,c.map_digest,c.wire_binding) THEN
 RAISE EXCEPTION 'Halloween skinning lacks exact current static body and participant visit' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('oteryn:pumpkin-skinning:'||replace(NEW.character_id::text,'-',''),0));
 NEW.used_at:=floor(extract(epoch FROM public.game_daily_effect_now()))::bigint;
 IF EXISTS(SELECT 1 FROM game_pumpkin_skinning_receipts r WHERE r.character_id=NEW.character_id AND r.used_at>NEW.used_at-14400) THEN
 RAISE EXCEPTION 'Halloween skinning personal four-hour cooldown' USING ERRCODE='23514'; END IF;
 SELECT source_game_session_id,source_occurrence INTO rng_session,rng_occurrence FROM game_pumpkin_reward_visits
 WHERE(character_id,world_id,death_id)=(NEW.character_id,NEW.world_id,NEW.death_id);
 nonce:=game_pumpkin_visit_draw_nonce(rng_occurrence);
 idx:=game_pumpkin_skinning_draw(rng_session,nonce,NEW.death_id,213,13);
 chosen_count:=CASE WHEN ids[idx+1] IN(3594,6574) THEN game_pumpkin_skinning_draw(rng_session,nonce,NEW.death_id,214,50)+1 ELSE counts[idx+1] END;
 IF (NEW.draw_index,NEW.source_item_id,NEW.quantity) IS DISTINCT FROM(idx::smallint,ids[idx+1],chosen_count) THEN
 RAISE EXCEPTION 'Halloween skinning requires current quantity policy and exact uniform source entry' USING ERRCODE='23514'; END IF;
 NEW.created_xact_id:=pg_current_xact_id(); RETURN NEW;
END $$;
CREATE TRIGGER game_pumpkin_skinning_admit BEFORE INSERT ON game_pumpkin_skinning_receipts FOR EACH ROW EXECUTE FUNCTION game_pumpkin_skinning_admit();
CREATE FUNCTION game_pumpkin_skinning_complete() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_pumpkin_source_context%ROWTYPE; m game_reward_claim_mint_receipts%ROWTYPE; current_knife JSONB;
BEGIN
 SELECT * INTO c FROM game_pumpkin_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 SELECT * INTO m FROM game_reward_claim_mint_receipts WHERE transaction_id=NEW.transaction_id;
 SELECT to_jsonb(i) INTO current_knife FROM game_item_instances i WHERE i.item_instance_id=NEW.knife_id;
 IF NOT game_pumpkin_skinning_current() OR c.phase IS DISTINCT FROM 'claim' OR NEW.created_xact_id<>pg_current_xact_id()
 OR (NEW.character_id,NEW.world_id,NEW.death_id,NEW.game_session_id,NEW.command_id,NEW.knife_id,NEW.body_placement,NEW.body_revision,NEW.map_digest,NEW.wire_binding)
 IS DISTINCT FROM(c.character_id,c.world_id,c.death_id,c.game_session_id,c.command_id,c.knife_id,c.body_placement,c.body_revision,c.map_digest,c.wire_binding)
 OR m.created_xact_id IS DISTINCT FROM pg_current_xact_id()
 OR (m.character_id,m.game_session_id,m.command_id,m.quantity,m.claim_family,m.claim_production_key,m.claim_revision_ref)
 IS DISTINCT FROM(NEW.character_id,NEW.game_session_id,NEW.command_id,NEW.quantity,'RewardClaim',
 'oteryn:reward-claim.pumpkin-skinning.'||replace(NEW.game_session_id::text,'-','')||':'||NEW.command_id::text,
 'pumpkin-skinning-wiki-c5fbb7ddf71779e795806b92038a209770324cb06e6dd610b5335708765ed742')
 OR m.contents_capacity IS NOT NULL OR m.contents_plan IS DISTINCT FROM '[]'::jsonb OR m.root_text IS NOT NULL
 OR NOT EXISTS(SELECT 1 FROM game_item_instances i WHERE i.item_instance_id=m.item_instance_id AND i.minted_transaction_id=m.transaction_id
 AND i.definition_family='Item' AND i.definition_production_key='oteryn:item.tibia.i'||NEW.source_item_id::text AND i.quantity=NEW.quantity AND i.lifecycle=1)
 OR NOT EXISTS(SELECT 1 FROM game_account_achievements a JOIN game_character_roots r ON r.account_id=a.account_id
 WHERE r.character_id=NEW.character_id AND a.achievement_key='oteryn:achievement/mutated_presents')
 OR NOT EXISTS(SELECT 1 FROM game_pumpkin_reward_visits v WHERE(v.character_id,v.world_id,v.death_id)=(NEW.character_id,NEW.world_id,NEW.death_id)
 AND v.deadline_ms>floor(extract(epoch FROM public.game_daily_effect_now())*1000)::bigint)
 OR current_knife IS DISTINCT FROM c.knife_before THEN
 RAISE EXCEPTION 'Halloween skinning requires same-XID native reward, live immutable visit and unchanged knife' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_pumpkin_skinning_complete AFTER INSERT ON game_pumpkin_skinning_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_pumpkin_skinning_complete();
CREATE FUNCTION game_pumpkin_skinning_mint_complete() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM game_pumpkin_skinning_receipts r WHERE r.transaction_id=NEW.transaction_id AND r.created_xact_id=pg_current_xact_id()) THEN
 RAISE EXCEPTION 'Halloween source MINT requires same-XID staticbody skinning receipt' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_pumpkin_skinning_mint_complete AFTER INSERT ON game_reward_claim_mint_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW
 WHEN(NEW.claim_production_key LIKE 'oteryn:reward-claim.pumpkin-skinning.%') EXECUTE FUNCTION game_pumpkin_skinning_mint_complete();
CREATE TRIGGER game_pumpkin_skinning_immutable BEFORE UPDATE OR DELETE ON game_pumpkin_skinning_receipts FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_pumpkin_skinning_no_truncate BEFORE TRUNCATE ON game_pumpkin_skinning_receipts FOR EACH STATEMENT EXECUTE FUNCTION game_world_reset_history_immutable();
REVOKE ALL ON game_pumpkin_skinning_receipts,game_pumpkin_reward_visits FROM PUBLIC;
GRANT SELECT,INSERT ON game_pumpkin_skinning_receipts,game_pumpkin_reward_visits TO oteryn_game_runtime;
GRANT SELECT ON game_pumpkin_skinning_receipts,game_pumpkin_reward_visits TO oteryn_game_control;
DO $$ DECLARE signature TEXT; BEGIN
 FOREACH signature IN ARRAY ARRAY['game_pumpkin_skinning_current()',
 'game_pumpkin_source_arm(uuid,uuid,numeric,uuid,numeric,bytea,uuid,uuid,numeric,numeric,text,uuid,bytea,numeric,uuid,bytea,numeric,bytea,bytea)',
 'game_pumpkin_skinning_draw(uuid,numeric,uuid,integer,integer)','game_pumpkin_visit_draw_nonce(bytea)','game_pumpkin_visit_admit()',
 'game_pumpkin_skinning_admit()','game_pumpkin_skinning_complete()','game_pumpkin_skinning_mint_complete()'] LOOP
 EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',signature,current_schema());
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',signature);
 END LOOP;
END $$;
GRANT EXECUTE ON FUNCTION game_pumpkin_source_arm(uuid,uuid,numeric,uuid,numeric,bytea,uuid,uuid,numeric,numeric,text,uuid,bytea,numeric,uuid,bytea,numeric,bytea,bytea) TO oteryn_game_runtime;

-- END SRV7 pumpkin static skinning claims

-- BEGIN SRV7 exact Glider seven-part action bound
-- Pinned Crystal mounts.lua:20-36,111-140 consumes blueprint21897 and six
-- separate parts. The general five-extra bound remains unchanged for all other recipes.
CREATE FUNCTION game_srv7_glider_six_inputs(p JSONB) RETURNS BOOLEAN
LANGUAGE sql IMMUTABLE STRICT SET search_path=pg_catalog,pg_temp AS $$
 SELECT CASE WHEN jsonb_typeof(p) IS DISTINCT FROM 'array' OR jsonb_array_length(p)<>6 THEN FALSE ELSE
  (SELECT count(DISTINCT value->>'item')=6
   AND bool_and(((value->>'count')::numeric=1 AND (value->>'source_kind')::numeric IN(1,4)
    AND value->'before'->>'definition_family'='Item') IS TRUE)
   AND array_agg(value->'before'->>'definition_production_key' ORDER BY value->'before'->>'definition_production_key')=
    ARRAY['oteryn:item.tibia.i21898','oteryn:item.tibia.i21899','oteryn:item.tibia.i21901',
     'oteryn:item.tibia.i21902','oteryn:item.tibia.i21905','oteryn:item.tibia.i21906']::TEXT[]
   FROM jsonb_array_elements(p)) IS TRUE END
$$;
REVOKE ALL ON FUNCTION game_srv7_glider_six_inputs(JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION game_srv7_glider_six_inputs(JSONB) TO oteryn_game_runtime,oteryn_game_control;
ALTER TABLE game_item_consume_transform_records DROP CONSTRAINT game_item_action_extra_input_bound;
ALTER TABLE game_item_consume_transform_records ADD CONSTRAINT game_item_action_extra_input_bound
 CHECK(jsonb_typeof(extra_inputs)='array' AND (jsonb_array_length(extra_inputs)<=5 OR
  (recipe='oteryn:item-cosmetic.i21897.v1' AND consume_source AND source_count=1 AND source_kind IN(1,4)
   AND before_item->>'definition_family'='Item' AND before_item->>'definition_production_key'='oteryn:item.tibia.i21897'
   AND effects->>'kind'='cosmetic' AND outputs='[]'::jsonb AND game_srv7_glider_six_inputs(extra_inputs)) IS TRUE));

-- END SRV7 exact Glider seven-part action bound

-- Crystal201189f8 Hairycles212–216/451–456: no new Ape City quest writer.
DO $migration$
DECLARE body TEXT; old TEXT; replacement TEXT;
BEGIN
 body:=pg_get_functiondef('game_npc_cosmetic_receipt_guard()'::regprocedure);
 old:='WHEN ''kesar'' THEN ''oteryn:npc.kesar_the_younger_day'' ELSE NULL END';
 replacement:='WHEN ''kesar'' THEN ''oteryn:npc.kesar_the_younger_day'' WHEN ''hairycles'' THEN ''oteryn:npc.hairycles'' ELSE NULL END';
 IF position(old IN body)=0 THEN RAISE EXCEPTION 'Hairycles NPC identity guard boundary changed';END IF;
 body:=replace(body,old,replacement);
 old:='WHEN ''oteryn:npc-cosmetic/amber/finish'' THEN ARRAY[''oteryn:appearance-grant/npc/amber/citizen/addon1'']';
 IF position(old IN body)=0 THEN RAISE EXCEPTION 'Hairycles grant guard boundary changed';END IF;
 body:=replace(body,old,'WHEN ''oteryn:npc-cosmetic/hairycles/shaman'' THEN ARRAY[''oteryn:appearance-grant/npc/hairycles/shaman/base''] '||old);
 old:='(''oteryn:npc-cosmetic/amber/finish'',''oteryn:npc-cosmetic/kesar/council'')';
 IF position(old IN body)=0 THEN RAISE EXCEPTION 'Hairycles equivalent grant boundary changed';END IF;
 body:=replace(body,old,'(''oteryn:npc-cosmetic/amber/finish'',''oteryn:npc-cosmetic/kesar/council'',''oteryn:npc-cosmetic/hairycles/shaman'')');
 old:='WHEN ''oteryn:npc-cosmetic/kesar/council'' THEN ''{"oteryn:quest-progress/crystalserver/quest/u15_20/the_order_of_the_stag/kings_council":1}''::jsonb';
 IF position(old IN body)=0 THEN RAISE EXCEPTION 'Hairycles exact track boundary changed';END IF;
 body:=replace(body,old,'WHEN ''oteryn:npc-cosmetic/hairycles/shaman'' THEN ''{"oteryn:quest-progress/quest/u7_6/the_ape_city/shaman_outfit":1}''::jsonb '||old);
 old:='WHEN ''oteryn:npc-cosmetic/kesar/council'' THEN ''[]''::jsonb';
 IF position(old IN body)=0 THEN RAISE EXCEPTION 'Hairycles no-cost boundary changed';END IF;
 body:=replace(body,old,'WHEN ''oteryn:npc-cosmetic/hairycles/shaman'' THEN ''[]''::jsonb '||old);
 old:='    RETURN NULL;';
 IF position(old IN body)=0 THEN RAISE EXCEPTION 'Hairycles deferred prerequisite boundary changed';END IF;
 replacement:=$proof$
    IF NEW.source_key='oteryn:npc-cosmetic/hairycles/shaman' THEN
        PERFORM 1 FROM game_character_quest_tracks hair_stage
        WHERE hair_stage.character_id=NEW.character_id
            AND hair_stage.track_key='oteryn:quest-progress/quest/u7_6/the_ape_city/questline'
            AND hair_stage.quest_key='oteryn:quest.the_ape_city_quest' AND hair_stage.value=18 FOR SHARE;
        IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.track_changes) hair_change
            WHERE hair_change->>'key'='oteryn:quest-progress/quest/u7_6/the_ape_city/shaman_outfit'
                AND hair_change->>'quest'='oteryn:quest.the_ape_city_quest'
                AND (hair_change->>'before')::bigint IS NOT NULL AND (hair_change->>'before')::bigint<>1
                AND (hair_change->>'after')::bigint=1) THEN
            RAISE EXCEPTION 'Hairycles Shaman claim lacks completed quest and unclaimed source flag' USING ERRCODE='23514';
        END IF;
        IF NEW.grant_keys=ARRAY[]::TEXT[] AND NOT EXISTS(
            SELECT 1 FROM game_account_appearance_unlocks hair_unlock JOIN game_account_appearance_unlock_receipts hair_grant USING(grant_occurrence_id)
            WHERE hair_unlock.account_id=NEW.account_id AND hair_unlock.unlock_key='oteryn:appearance-grant/npc/hairycles/shaman/base'
                AND hair_grant.account_id=NEW.account_id AND hair_grant.content_revision='crystal-201189f-npc-cosmetics-v1') THEN
            RAISE EXCEPTION 'Hairycles cannot omit an unowned Shaman base grant' USING ERRCODE='23514';
        END IF;
    END IF;
    RETURN NULL;
$proof$;
 body:=replace(body,old,replacement);
 EXECUTE body;
END $migration$;

-- Hairycles is the sixth source-qualified permanent cosmetic NPC. Keep the
-- original five identities and admit only the exact Shaman source owner.
ALTER TABLE game_npc_cosmetic_receipts
 DROP CONSTRAINT game_npc_cosmetic_receipts_npc_key_check,
 ADD CONSTRAINT game_npc_cosmetic_receipts_npc_key_check
 CHECK(npc_key IN('oteryn:npc.amber','oteryn:npc.norma','oteryn:npc.tom','oteryn:npc.cledwyn','oteryn:npc.kesar_the_younger_day','oteryn:npc.hairycles'));

-- SRV7_SOURCE_COMPOSITION: horse-rentals.sql
-- S06 source-only temporary horse contracts, never Account appearance grants.
CREATE TABLE game_horse_station_worlds(
 world_id UUID PRIMARY KEY,generation BIGINT NOT NULL CHECK(generation>=0),started_seconds BIGINT NOT NULL,
 expires_seconds BIGINT NOT NULL,ended BOOLEAN NOT NULL,
 CHECK((generation=0 AND started_seconds=0 AND expires_seconds=0 AND ended) OR(generation>0 AND started_seconds>0 AND expires_seconds=started_seconds+86400)));
CREATE TABLE game_horse_rental_receipts(
 transaction_id UUID PRIMARY KEY,character_id UUID NOT NULL REFERENCES game_character_roots(character_id),world_id UUID NOT NULL,
 game_session_id UUID NOT NULL REFERENCES game_durability_reconnect_sessions(game_session_id),command_id NUMERIC(20,0) NOT NULL,
 npc_key TEXT NOT NULL CHECK(npc_key IN('oteryn:npc.appaloosa','oteryn:npc.palomino')),
 mount_id INTEGER NOT NULL CHECK(mount_id IN(22,25,26)),issued_seconds BIGINT NOT NULL CHECK(issued_seconds>0),
 expires_seconds BIGINT NOT NULL CHECK(expires_seconds=issued_seconds+86400),fee_transaction_id UUID NOT NULL REFERENCES game_item_fee_burns(transaction_id) DEFERRABLE INITIALLY DEFERRED,
 request_binding BYTEA NOT NULL CHECK(octet_length(request_binding)=32),committed_character_revision NUMERIC(20,0) NOT NULL,
 original_character_revision NUMERIC(20,0) NOT NULL CHECK(original_character_revision>=1),
 level_before BIGINT NOT NULL,level_after BIGINT NOT NULL CHECK(level_after=level_before),
 experience_before BIGINT NOT NULL,experience_after BIGINT NOT NULL CHECK(experience_after=experience_before),
 profile_revision TEXT NOT NULL,ruleset_revision TEXT NOT NULL,content_revision TEXT NOT NULL,
 simulation_revision TEXT NOT NULL,evidence_revision TEXT NOT NULL,declaration_revision TEXT NOT NULL,
 policy_revision TEXT NOT NULL,reward_revision TEXT NOT NULL,
 CHECK(committed_character_revision=original_character_revision+1 AND committed_character_revision<=18446744073709551615),
 UNIQUE(character_id,committed_character_revision),
 created_xact_id XID8 NOT NULL,UNIQUE(game_session_id,command_id));
CREATE INDEX game_horse_rental_character ON game_horse_rental_receipts(character_id,issued_seconds DESC);
CREATE INDEX game_horse_rental_fee ON game_horse_rental_receipts(fee_transaction_id);
CREATE TABLE game_horse_station_wave_claims(
 world_id UUID NOT NULL REFERENCES game_horse_station_worlds(world_id),generation BIGINT NOT NULL,channel_id UUID NOT NULL,
 wave SMALLINT NOT NULL CHECK(wave BETWEEN -1 AND 7),node_id UUID NOT NULL,registration NUMERIC NOT NULL,scope_generation NUMERIC NOT NULL,
 created_xact_id XID8 NOT NULL,PRIMARY KEY(world_id,generation,channel_id,wave,node_id,registration,scope_generation));
CREATE TABLE game_horse_station_catches(
 world_id UUID NOT NULL REFERENCES game_horse_station_worlds(world_id),generation BIGINT NOT NULL,channel_id UUID NOT NULL,
 movement_occurrence BYTEA NOT NULL CHECK(octet_length(movement_occurrence)=32),ended BOOLEAN NOT NULL,created_xact_id XID8 NOT NULL,
 PRIMARY KEY(world_id,generation,channel_id,movement_occurrence));
CREATE TABLE game_horse_rental_expiry_notices(
 transaction_id UUID PRIMARY KEY REFERENCES game_horse_rental_receipts(transaction_id),game_session_id UUID NOT NULL REFERENCES game_durability_reconnect_sessions(game_session_id),created_xact_id XID8 NOT NULL);
CREATE INDEX game_horse_rental_expiry_session ON game_horse_rental_expiry_notices(game_session_id);
CREATE TABLE game_horse_station_context(
 backend_pid INTEGER PRIMARY KEY,transaction_xid XID8 NOT NULL,world_id UUID NOT NULL,channel_id UUID NOT NULL,generation NUMERIC NOT NULL,
 node_id UUID NOT NULL,registration NUMERIC NOT NULL,phase TEXT NOT NULL CHECK(phase IN('node','rent','catch','notice')),
 character_id UUID,game_session_id UUID,connection NUMERIC,lease NUMERIC,command_id NUMERIC,npc_key TEXT,request_binding BYTEA,fee_id UUID,
 original_revision NUMERIC,progression_before JSONB,source_seed BYTEA,mount_id INTEGER,issued_seconds BIGINT,expires_seconds BIGINT,movement_occurrence BYTEA,notice_house TEXT);
REVOKE ALL ON game_horse_station_context FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
CREATE FUNCTION game_horse_station_draw(p_domain INTEGER,p_seed BYTEA,p_bound INTEGER) RETURNS INTEGER LANGUAGE plpgsql IMMUTABLE STRICT AS $$
DECLARE h BYTEA;v NUMERIC;lim NUMERIC;attempt INTEGER;j INTEGER;
BEGIN
 IF p_domain NOT BETWEEN 217 AND 221 OR p_bound<1 OR p_bound>100000 OR octet_length(p_seed)<>32 THEN RAISE EXCEPTION 'invalid horse source draw' USING ERRCODE='23514';END IF;
 lim:=floor(18446744073709551616::numeric/p_bound)*p_bound;
 FOR attempt IN 0..15 LOOP
 h:=sha256(convert_to('oteryn:horse-station-rng:v1','UTF8')||int4send(p_domain)||p_seed||int4send(attempt));v:=0;
 FOR j IN 0..7 LOOP v:=v*256+get_byte(h,j);END LOOP;
 IF v<lim THEN RETURN mod(v,p_bound)::integer+1;END IF;
 END LOOP;RAISE EXCEPTION 'horse source draw rejection budget' USING ERRCODE='23514';
END $$;
CREATE FUNCTION game_horse_station_current() RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM game_horse_station_context c JOIN game_runtime_scope_assignments a
 ON a.world_id=c.world_id AND((c.phase='notice' AND c.notice_house IS NOT NULL AND a.scope_kind=2 AND a.house_key=c.notice_house)
 OR(c.notice_house IS NULL AND a.scope_key='\x01'::bytea||uuid_send(c.world_id)||uuid_send(c.channel_id) AND a.scope_kind=1))
 WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id() AND a.state=1
 AND a.ownership_generation=c.generation AND a.holder_node_id=c.node_id AND a.holder_registration_revision=c.registration)
$$;
CREATE FUNCTION game_horse_rental_character_current() RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT game_horse_station_current() AND EXISTS(SELECT 1 FROM game_horse_station_context c
 JOIN game_durability_reconnect_sessions s ON s.game_session_id=c.game_session_id
 JOIN game_character_roots r ON r.character_id=c.character_id
 JOIN game_durability_admission_character_guards cg ON cg.character_id=c.character_id
 JOIN game_durability_admission_account_guards ag ON ag.account_id=cg.account_id
 JOIN game_runtime_scope_assignments a ON a.world_id=c.world_id AND a.state=1 AND a.ownership_generation=c.generation
 AND a.holder_node_id=c.node_id AND a.holder_registration_revision=c.registration
 AND((c.phase='notice' AND c.notice_house IS NOT NULL AND a.scope_kind=2 AND a.house_key=c.notice_house)
 OR(c.notice_house IS NULL AND a.scope_kind=1 AND a.channel_id=c.channel_id))
 JOIN game_durability_admission_runtime_guards rg ON rg.scope_key=a.scope_key
 WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id()
 AND s.character_id=c.character_id AND s.world_id=c.world_id AND s.runtime_scope_world_id=c.world_id
 AND((c.notice_house IS NULL AND s.runtime_scope_kind=1 AND s.runtime_scope_channel_id=c.channel_id AND s.runtime_scope_instance_id IS NULL AND s.runtime_scope_house_key IS NULL)
 OR(c.phase='notice' AND c.notice_house IS NOT NULL AND s.runtime_scope_kind=2 AND s.runtime_scope_instance_id IS NOT NULL AND s.runtime_scope_house_key=c.notice_house AND s.runtime_scope_channel_id IS NULL AND s.origin_channel_id=c.channel_id))
 AND s.current_generation=c.connection AND s.character_lease_generation=c.lease AND s.scope_ownership_generation=c.generation AND s.session_state IN(1,2)
 AND r.world_id=c.world_id AND r.account_id=s.account_id AND r.lifecycle=1
 AND cg.account_id=s.account_id AND cg.world_id=c.world_id AND cg.eligible
 AND cg.lease_generation=c.lease AND cg.holder_game_session_id=c.game_session_id
 AND ag.presence_character_id=c.character_id AND ag.holder_game_session_id=c.game_session_id AND rg.ready AND rg.ownership_generation=c.generation)
$$;
CREATE FUNCTION game_horse_station_arm_node(p_world UUID,p_channel UUID,p_generation NUMERIC,p_node UUID,p_registration NUMERIC,p_secret BYTEA)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF p_secret IS NULL OR octet_length(p_secret)<>32 OR game_node_prove_current_incarnation(p_node,p_registration,p_secret) IS DISTINCT FROM TRUE
 OR NOT game_runtime_scope_assignment_history_valid() THEN RAISE EXCEPTION 'horse source requires Node possession' USING ERRCODE='23514';END IF;
 PERFORM 1 FROM game_runtime_scope_assignments a WHERE a.scope_key='\x01'::bytea||uuid_send(p_world)||uuid_send(p_channel)
 AND a.scope_kind=1 AND a.world_id=p_world AND a.channel_id=p_channel AND a.state=1 AND a.ownership_generation=p_generation
 AND a.holder_node_id=p_node AND a.holder_registration_revision=p_registration FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'stale horse source Channel' USING ERRCODE='23514';END IF;
 DELETE FROM game_horse_station_context c WHERE c.backend_pid=pg_backend_pid() OR NOT EXISTS(SELECT 1 FROM pg_stat_activity a WHERE a.pid=c.backend_pid);
 INSERT INTO game_horse_station_context(backend_pid,transaction_xid,world_id,channel_id,generation,node_id,registration,phase)
 VALUES(pg_backend_pid(),pg_current_xact_id(),p_world,p_channel,p_generation,p_node,p_registration,'node');
END $$;
CREATE FUNCTION game_horse_rental_arm(p_world UUID,p_channel UUID,p_generation NUMERIC,p_node UUID,p_registration NUMERIC,p_secret BYTEA,
 p_character UUID,p_session UUID,p_connection NUMERIC,p_lease NUMERIC,p_command NUMERIC,p_npc TEXT,p_binding BYTEA,p_fee UUID)
RETURNS TABLE(mount_id INTEGER,expires_seconds BIGINT) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE n BIGINT;seed BYTEA;chosen INTEGER;progress_before JSONB;
BEGIN
 PERFORM game_horse_station_arm_node(p_world,p_channel,p_generation,p_node,p_registration,p_secret);
 IF p_npc NOT IN('oteryn:npc.appaloosa','oteryn:npc.palomino') OR p_npc IS NULL OR p_command IS NULL OR p_command<1 OR p_command>18446744073709551615
 OR p_binding IS NULL OR octet_length(p_binding)<>32 OR p_fee IS NULL THEN RAISE EXCEPTION 'invalid horse rental source' USING ERRCODE='23514';END IF;
 n:=floor(extract(epoch FROM public.game_daily_effect_now()))::bigint;
 seed:=sha256(uuid_send(p_world)||uuid_send(p_character)||uuid_send(p_session)||convert_to(p_command::text,'UTF8'));
 chosen:=(ARRAY[22,25,26])[game_horse_station_draw(217,seed,3)];
 SELECT to_jsonb(progression) INTO STRICT progress_before FROM game_character_progression_state progression WHERE progression.character_id=p_character FOR UPDATE;
 UPDATE game_horse_station_context SET phase='rent',character_id=p_character,game_session_id=p_session,connection=p_connection,lease=p_lease,
 command_id=p_command,npc_key=p_npc,request_binding=p_binding,fee_id=p_fee,original_revision=(SELECT r.character_revision FROM game_character_roots r WHERE r.character_id=p_character FOR UPDATE),progression_before=progress_before,source_seed=seed,mount_id=chosen,issued_seconds=n,expires_seconds=n+86400
 WHERE backend_pid=pg_backend_pid();
 IF NOT game_horse_rental_character_current() OR EXISTS(SELECT 1 FROM game_horse_rental_receipts r WHERE r.character_id=p_character AND r.expires_seconds>=n)
 OR EXISTS(SELECT 1 FROM game_horse_station_worlds w WHERE w.world_id=p_world AND NOT w.ended AND w.expires_seconds>n)
 OR EXISTS(SELECT 1 FROM game_item_fee_burns f WHERE f.transaction_id=p_fee) THEN
 RAISE EXCEPTION 'horse contract requires current Character and available stable' USING ERRCODE='23514';END IF;
 RETURN QUERY SELECT chosen,n+86400;
END $$;
CREATE FUNCTION game_horse_rental_admit() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_horse_station_context%ROWTYPE;
BEGIN
 SELECT*INTO c FROM game_horse_station_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF game_horse_rental_character_current() IS DISTINCT FROM TRUE OR c.phase IS DISTINCT FROM'rent'
 OR NEW.committed_character_revision IS DISTINCT FROM c.original_revision+1
 OR NEW.original_character_revision IS DISTINCT FROM c.original_revision
 OR (c.progression_before->>'character_revision')::numeric IS DISTINCT FROM c.original_revision
 OR NEW.level_before IS DISTINCT FROM (c.progression_before->>'level')::bigint
 OR NEW.experience_before IS DISTINCT FROM (c.progression_before->>'total_experience')::bigint
 OR NEW.profile_revision IS DISTINCT FROM c.progression_before->>'profile_revision'
 OR NEW.ruleset_revision IS DISTINCT FROM c.progression_before->>'ruleset_revision'
 OR NEW.content_revision IS DISTINCT FROM c.progression_before->>'content_revision'
 OR NEW.simulation_revision IS DISTINCT FROM c.progression_before->>'simulation_revision'
 OR NEW.evidence_revision IS DISTINCT FROM c.progression_before->>'evidence_revision'
 OR NEW.declaration_revision IS DISTINCT FROM c.progression_before->>'declaration_revision'
 OR NEW.policy_revision IS DISTINCT FROM c.progression_before->>'policy_revision'
 OR NEW.reward_revision IS DISTINCT FROM c.progression_before->>'reward_revision'
 OR(NEW.character_id,NEW.world_id,NEW.game_session_id,NEW.command_id,NEW.npc_key,NEW.mount_id,NEW.issued_seconds,NEW.expires_seconds,NEW.fee_transaction_id,NEW.request_binding,NEW.transaction_id)
 IS DISTINCT FROM(c.character_id,c.world_id,c.game_session_id,c.command_id,c.npc_key,c.mount_id,c.issued_seconds,c.expires_seconds,c.fee_id,c.request_binding,c.fee_id) THEN
 RAISE EXCEPTION 'horse rental requires current source fee intent' USING ERRCODE='23514';END IF;
 NEW.created_xact_id:=pg_current_xact_id();RETURN NEW;
END $$;
CREATE TRIGGER game_horse_rental_admit BEFORE INSERT ON game_horse_rental_receipts FOR EACH ROW EXECUTE FUNCTION game_horse_rental_admit();
CREATE TRIGGER game_horse_rental_immutable BEFORE UPDATE OR DELETE ON game_horse_rental_receipts FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_horse_rental_no_truncate BEFORE TRUNCATE ON game_horse_rental_receipts FOR EACH STATEMENT EXECUTE FUNCTION game_world_reset_history_immutable();
CREATE FUNCTION game_horse_rental_complete() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_horse_station_context%ROWTYPE;
BEGIN
 SELECT*INTO c FROM game_horse_station_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF game_horse_rental_character_current() IS DISTINCT FROM TRUE OR NEW.created_xact_id<>pg_current_xact_id() OR NOT EXISTS(
 SELECT 1 FROM game_item_fee_burns f WHERE f.transaction_id=NEW.fee_transaction_id AND f.character_id=NEW.character_id AND f.world_id=NEW.world_id
 AND f.created_xact_id=pg_current_xact_id() AND f.channel_id=c.channel_id AND f.runtime_scope_ownership_generation=c.generation AND f.cause_kind=473 AND f.fee_gold_units=500
 AND f.purchase_service_key='oteryn:service.horse-station.rental' AND f.committed_character_revision=NEW.committed_character_revision) THEN
 RAISE EXCEPTION 'horse rental requires reciprocal audited500gold same transaction' USING ERRCODE='23514';END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_horse_rental_complete AFTER INSERT ON game_horse_rental_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_horse_rental_complete();
-- World mutation is driven only by this admitted source receipt or secret-backed catch/cadence.
CREATE FUNCTION game_horse_station_world_admit() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_horse_station_context%ROWTYPE;
BEGIN
 SELECT*INTO c FROM game_horse_station_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF game_horse_station_current() IS DISTINCT FROM TRUE OR NEW.world_id IS DISTINCT FROM c.world_id THEN RAISE EXCEPTION 'horse world requires current Node' USING ERRCODE='23514';END IF;
 IF TG_OP='INSERT' AND NEW.generation=0 AND NEW.ended AND NEW.started_seconds=0 AND NEW.expires_seconds=0 THEN RETURN NEW;END IF;
 IF c.phase='rent' AND game_horse_rental_character_current() AND EXISTS(SELECT 1 FROM game_horse_rental_receipts r WHERE r.transaction_id=c.fee_id AND r.created_xact_id=pg_current_xact_id())
 AND game_horse_station_draw(218,c.source_seed,10)<=3 AND(TG_OP='INSERT' AND NEW.generation=1 OR TG_OP='UPDATE' AND NEW.generation=OLD.generation+1)
 AND NEW.started_seconds=c.issued_seconds AND NEW.expires_seconds=c.issued_seconds+86400 AND NOT NEW.ended THEN RETURN NEW;END IF;
 IF TG_OP='UPDATE' AND NEW.generation=OLD.generation AND NEW.started_seconds=OLD.started_seconds AND NEW.expires_seconds=OLD.expires_seconds AND NEW.ended
 AND(c.phase='catch' AND EXISTS(SELECT 1 FROM game_horse_station_catches h WHERE h.world_id=c.world_id AND h.generation=OLD.generation AND h.channel_id=c.channel_id AND h.movement_occurrence=c.movement_occurrence AND h.ended AND h.created_xact_id=pg_current_xact_id()) OR c.phase='node' AND floor(extract(epoch FROM public.game_daily_effect_now()))::bigint>=OLD.expires_seconds) THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'horse world source transition refused' USING ERRCODE='23514';
END $$;
CREATE TRIGGER game_horse_station_world_admit BEFORE INSERT OR UPDATE ON game_horse_station_worlds FOR EACH ROW EXECUTE FUNCTION game_horse_station_world_admit();
CREATE TRIGGER game_horse_station_world_no_delete BEFORE DELETE ON game_horse_station_worlds FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_horse_station_world_no_truncate BEFORE TRUNCATE ON game_horse_station_worlds FOR EACH STATEMENT EXECUTE FUNCTION game_world_reset_history_immutable();
CREATE FUNCTION game_horse_rental_start_world() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_horse_station_context%ROWTYPE;
BEGIN
 SELECT*INTO c FROM game_horse_station_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF game_horse_rental_character_current() IS DISTINCT FROM TRUE OR NEW.created_xact_id<>pg_current_xact_id() THEN RAISE EXCEPTION 'horse rental source lost' USING ERRCODE='23514';END IF;
 IF game_horse_station_draw(218,c.source_seed,10)<=3 THEN
 INSERT INTO game_horse_station_worlds(world_id,generation,started_seconds,expires_seconds,ended) VALUES(NEW.world_id,1,NEW.issued_seconds,NEW.issued_seconds+86400,FALSE)
 ON CONFLICT(world_id)DO UPDATE SET generation=game_horse_station_worlds.generation+1,started_seconds=EXCLUDED.started_seconds,expires_seconds=EXCLUDED.expires_seconds,ended=FALSE;
 END IF;RETURN NULL;
END $$;
CREATE TRIGGER game_horse_rental_start_world AFTER INSERT ON game_horse_rental_receipts FOR EACH ROW EXECUTE FUNCTION game_horse_rental_start_world();
CREATE FUNCTION game_horse_station_wave_admit() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_horse_station_context%ROWTYPE;w game_horse_station_worlds%ROWTYPE;n BIGINT;expected INTEGER;
BEGIN
 SELECT*INTO c FROM game_horse_station_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 SELECT*INTO w FROM game_horse_station_worlds WHERE world_id=c.world_id;
 n:=floor(extract(epoch FROM public.game_daily_effect_now()))::bigint;
 expected:=CASE WHEN NOT w.ended AND w.expires_seconds>n THEN((n-w.started_seconds)/10800)::integer ELSE-1 END;
 IF game_horse_station_current() IS DISTINCT FROM TRUE OR c.phase IS DISTINCT FROM'node'
 OR(NEW.world_id,NEW.channel_id,NEW.generation,NEW.wave,NEW.node_id,NEW.registration,NEW.scope_generation)IS DISTINCT FROM(c.world_id,c.channel_id,w.generation,expected::smallint,c.node_id,c.registration,c.generation) THEN
 RAISE EXCEPTION 'horse physical source slot requires current World and Channel' USING ERRCODE='23514';END IF;
 NEW.created_xact_id:=pg_current_xact_id();RETURN NEW;
END $$;
CREATE TRIGGER game_horse_station_wave_admit BEFORE INSERT ON game_horse_station_wave_claims FOR EACH ROW EXECUTE FUNCTION game_horse_station_wave_admit();
CREATE TRIGGER game_horse_station_wave_immutable BEFORE UPDATE OR DELETE ON game_horse_station_wave_claims FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_horse_station_wave_no_truncate BEFORE TRUNCATE ON game_horse_station_wave_claims FOR EACH STATEMENT EXECUTE FUNCTION game_world_reset_history_immutable();
CREATE FUNCTION game_horse_station_refresh_claim() RETURNS TABLE(generation BIGINT,started_seconds BIGINT,expires_seconds BIGINT,ended BOOLEAN,wave SMALLINT,claimed BOOLEAN)
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_horse_station_context%ROWTYPE;w game_horse_station_worlds%ROWTYPE;n BIGINT;s SMALLINT;
BEGIN
 SELECT*INTO c FROM game_horse_station_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF game_horse_station_current() IS DISTINCT FROM TRUE OR c.phase IS DISTINCT FROM'node' THEN RAISE EXCEPTION 'horse cadence requires current Node' USING ERRCODE='23514';END IF;
 INSERT INTO game_horse_station_worlds VALUES(c.world_id,0,0,0,TRUE)ON CONFLICT(world_id)DO NOTHING;
 SELECT*INTO w FROM game_horse_station_worlds WHERE world_id=c.world_id FOR UPDATE;
 n:=floor(extract(epoch FROM public.game_daily_effect_now()))::bigint;
 IF NOT w.ended AND w.expires_seconds<=n THEN UPDATE game_horse_station_worlds SET ended=TRUE WHERE world_id=c.world_id;w.ended:=TRUE;END IF;
 s:=CASE WHEN NOT w.ended AND w.expires_seconds>n THEN((n-w.started_seconds)/10800)::smallint ELSE-1 END;
 INSERT INTO game_horse_station_wave_claims(world_id,generation,channel_id,wave,node_id,registration,scope_generation,created_xact_id)VALUES(c.world_id,w.generation,c.channel_id,s,c.node_id,c.registration,c.generation,pg_current_xact_id())ON CONFLICT DO NOTHING;
 -- A retried ambiguous commit and a newly admitted owner must reconstruct its
 -- ephemeral native actors. The current runtime suppresses an already installed slot.
 RETURN QUERY SELECT w.generation,w.started_seconds,w.expires_seconds,w.ended,s,TRUE;
END $$;
CREATE FUNCTION game_horse_station_catch(p_occurrence BYTEA) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_horse_station_context%ROWTYPE;w game_horse_station_worlds%ROWTYPE;n BIGINT;result BOOLEAN;seed BYTEA;
BEGIN
 SELECT*INTO c FROM game_horse_station_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF game_horse_station_current() IS DISTINCT FROM TRUE OR c.phase IS DISTINCT FROM'node' OR p_occurrence IS NULL OR octet_length(p_occurrence)<>32 THEN
 RAISE EXCEPTION 'horse catch requires current admitted monster source step' USING ERRCODE='23514';END IF;
 INSERT INTO game_horse_station_worlds VALUES(c.world_id,0,0,0,TRUE)ON CONFLICT(world_id)DO NOTHING;
 SELECT*INTO w FROM game_horse_station_worlds WHERE world_id=c.world_id FOR UPDATE;
 n:=floor(extract(epoch FROM public.game_daily_effect_now()))::bigint;
 SELECT ended INTO result FROM game_horse_station_catches WHERE world_id=c.world_id AND generation=w.generation AND channel_id=c.channel_id AND movement_occurrence=p_occurrence;
 IF FOUND THEN RETURN result;END IF;
 IF w.world_id IS NULL OR w.ended OR w.expires_seconds<=n THEN RETURN FALSE;END IF;
 seed:=sha256(uuid_send(c.world_id)||int8send(w.generation)||uuid_send(c.channel_id)||p_occurrence);
 result:=game_horse_station_draw(219,seed,30)=1;
 UPDATE game_horse_station_context SET phase='catch',movement_occurrence=p_occurrence WHERE backend_pid=pg_backend_pid();
 INSERT INTO game_horse_station_catches VALUES(c.world_id,w.generation,c.channel_id,p_occurrence,result,pg_current_xact_id());
 IF result THEN UPDATE game_horse_station_worlds SET ended=TRUE WHERE world_id=c.world_id;END IF;
 RETURN result;
END $$;
CREATE FUNCTION game_horse_station_catch_admit() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_horse_station_context%ROWTYPE;w game_horse_station_worlds%ROWTYPE;seed BYTEA;
BEGIN
 SELECT*INTO c FROM game_horse_station_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 SELECT*INTO w FROM game_horse_station_worlds WHERE world_id=c.world_id;
 seed:=sha256(uuid_send(c.world_id)||int8send(w.generation)||uuid_send(c.channel_id)||c.movement_occurrence);
 IF game_horse_station_current() IS DISTINCT FROM TRUE OR c.phase IS DISTINCT FROM'catch'
 OR(NEW.world_id,NEW.channel_id,NEW.generation,NEW.movement_occurrence,NEW.ended)IS DISTINCT FROM(c.world_id,c.channel_id,w.generation,c.movement_occurrence,game_horse_station_draw(219,seed,30)=1)THEN
 RAISE EXCEPTION 'horse catch requires exact source occurrence and draw' USING ERRCODE='23514';END IF;
 NEW.created_xact_id:=pg_current_xact_id();RETURN NEW;
END $$;
CREATE TRIGGER game_horse_station_catch_admit BEFORE INSERT ON game_horse_station_catches FOR EACH ROW EXECUTE FUNCTION game_horse_station_catch_admit();
CREATE TRIGGER game_horse_station_catch_immutable BEFORE UPDATE OR DELETE ON game_horse_station_catches FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_horse_station_catch_no_truncate BEFORE TRUNCATE ON game_horse_station_catches FOR EACH STATEMENT EXECUTE FUNCTION game_world_reset_history_immutable();
GRANT SELECT,INSERT ON game_horse_rental_receipts,game_horse_station_wave_claims,game_horse_station_catches,game_horse_rental_expiry_notices TO oteryn_game_runtime;
GRANT SELECT,INSERT,UPDATE ON game_horse_station_worlds TO oteryn_game_runtime;
CREATE FUNCTION game_horse_rental_expiry_notice(p_character UUID,p_session UUID,p_connection NUMERIC,p_lease NUMERIC) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_horse_station_context%ROWTYPE;r game_horse_rental_receipts%ROWTYPE;n BIGINT;rows INTEGER;
BEGIN
 IF game_horse_station_current() IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'horse expiry requires current Node' USING ERRCODE='23514';END IF;
 UPDATE game_horse_station_context SET phase='notice',character_id=p_character,game_session_id=p_session,connection=p_connection,lease=p_lease WHERE backend_pid=pg_backend_pid();
 IF game_horse_rental_character_current() IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'horse expiry requires current Character' USING ERRCODE='23514';END IF;
 SELECT*INTO r FROM game_horse_rental_receipts WHERE character_id=p_character ORDER BY issued_seconds DESC,transaction_id DESC LIMIT 1;
 n:=floor(extract(epoch FROM public.game_daily_effect_now()))::bigint;
 IF r.transaction_id IS NULL OR r.expires_seconds>=n THEN RETURN FALSE;END IF;
 UPDATE game_horse_station_context SET fee_id=r.transaction_id WHERE backend_pid=pg_backend_pid();
 INSERT INTO game_horse_rental_expiry_notices VALUES(r.transaction_id,p_session,pg_current_xact_id())ON CONFLICT DO NOTHING;
 GET DIAGNOSTICS rows=ROW_COUNT;RETURN rows=1;
END $$;
CREATE FUNCTION game_horse_rental_expiry_admit() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_horse_station_context%ROWTYPE;
BEGIN
 SELECT*INTO c FROM game_horse_station_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF game_horse_rental_character_current() IS DISTINCT FROM TRUE OR c.phase IS DISTINCT FROM'notice'
 OR(NEW.transaction_id,NEW.game_session_id)IS DISTINCT FROM(c.fee_id,c.game_session_id)
 OR NOT EXISTS(SELECT 1 FROM game_horse_rental_receipts r WHERE r.transaction_id=c.fee_id AND r.character_id=c.character_id
 AND r.expires_seconds<floor(extract(epoch FROM public.game_daily_effect_now()))::bigint) THEN
 RAISE EXCEPTION 'horse expiry notice requires current contract source' USING ERRCODE='23514';END IF;
 NEW.created_xact_id:=pg_current_xact_id();RETURN NEW;
END $$;
CREATE TRIGGER game_horse_rental_expiry_admit BEFORE INSERT ON game_horse_rental_expiry_notices FOR EACH ROW EXECUTE FUNCTION game_horse_rental_expiry_admit();
CREATE TRIGGER game_horse_rental_expiry_immutable BEFORE UPDATE OR DELETE ON game_horse_rental_expiry_notices FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_horse_rental_expiry_no_truncate BEFORE TRUNCATE ON game_horse_rental_expiry_notices FOR EACH STATEMENT EXECUTE FUNCTION game_world_reset_history_immutable();

CREATE FUNCTION game_horse_rental_arm_notice(p_world UUID,p_character UUID,p_session UUID,p_connection NUMERIC,p_lease NUMERIC,p_generation NUMERIC,p_node UUID,p_registration NUMERIC,p_secret BYTEA)
RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE s game_durability_reconnect_sessions%ROWTYPE;
BEGIN
 IF p_secret IS NULL OR octet_length(p_secret)<>32 OR game_node_prove_current_incarnation(p_node,p_registration,p_secret) IS DISTINCT FROM TRUE
 OR NOT game_runtime_scope_assignment_history_valid() THEN RAISE EXCEPTION 'horse expiry requires current Node possession' USING ERRCODE='23514';END IF;
 SELECT * INTO s FROM game_durability_reconnect_sessions WHERE game_session_id=p_session AND character_id=p_character AND world_id=p_world FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'horse expiry current session missing' USING ERRCODE='23514';END IF;
 DELETE FROM game_horse_station_context c WHERE c.backend_pid=pg_backend_pid() OR NOT EXISTS(SELECT 1 FROM pg_stat_activity a WHERE a.pid=c.backend_pid);
 INSERT INTO game_horse_station_context(backend_pid,transaction_xid,world_id,channel_id,generation,node_id,registration,phase,character_id,game_session_id,connection,lease,notice_house)
 VALUES(pg_backend_pid(),pg_current_xact_id(),p_world,COALESCE(s.runtime_scope_channel_id,s.origin_channel_id),p_generation,p_node,p_registration,'notice',p_character,p_session,p_connection,p_lease,s.runtime_scope_house_key);
 IF game_horse_rental_character_current() IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'horse expiry stale Character/session/lease/scope' USING ERRCODE='23514';END IF;
 RETURN game_horse_rental_expiry_notice(p_character,p_session,p_connection,p_lease);
END $$;
CREATE FUNCTION game_horse_rental_fee_current(p_fee UUID,p_character UUID,p_world UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT game_horse_rental_character_current() AND EXISTS(SELECT 1 FROM game_horse_station_context c WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id()
 AND c.phase='rent' AND c.fee_id=p_fee AND c.character_id=p_character AND c.world_id=p_world)
$$;
CREATE FUNCTION game_horse_rental_fee_complete(p_fee UUID,p_character UUID,p_world UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT game_horse_rental_fee_current(p_fee,p_character,p_world) AND EXISTS(SELECT 1 FROM game_horse_rental_receipts r JOIN game_item_fee_burns f ON f.transaction_id=r.fee_transaction_id
 JOIN game_character_roots cr ON cr.character_id=r.character_id AND cr.character_revision=r.committed_character_revision
 WHERE r.transaction_id=p_fee AND r.fee_transaction_id=p_fee AND r.character_id=p_character AND r.world_id=p_world
 AND r.created_xact_id=pg_current_xact_id() AND f.created_xact_id=pg_current_xact_id() AND f.cause_kind=473 AND f.fee_gold_units=500
 AND f.committed_character_revision=r.committed_character_revision AND cr.xmin=pg_current_xact_id()::xid)
$$;

-- This immutable rental receipt owns the single edge already advanced by the
-- fee composition. Unchanged XP/level and original pins are privately captured.
DO $rental_chain$ DECLARE definition TEXT; BEGIN
 definition:=rtrim(pg_get_viewdef('game_character_hazard_revision_chain'::regclass,true),E';\n ');
 IF position('game_horse_rental_receipts' IN definition)>0 THEN RAISE EXCEPTION 'rental edge already installed';END IF;
 EXECUTE 'CREATE OR REPLACE VIEW game_character_hazard_revision_chain WITH (security_invoker=true) AS '
 ||definition||' UNION ALL SELECT character_id,original_character_revision,committed_character_revision,'
 ||'level_before,level_after,experience_before,experience_after,profile_revision,ruleset_revision,'
 ||'content_revision,simulation_revision,evidence_revision,declaration_revision,policy_revision,reward_revision '
 ||'FROM game_horse_rental_receipts';
END $rental_chain$;
CREATE CONSTRAINT TRIGGER game_horse_rental_character_chain AFTER INSERT ON game_horse_rental_receipts
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_character_progression_consistency_guard();

-- SRV7_SOURCE_COMPOSITION: npc-source-context.sql
-- Draft: finite Source-program context. Actual program/policy rows are generated
-- from the reviewed source input; runtime cannot insert or edit those rows.
CREATE TABLE game_npc_source_programs (
 program_sha256 BYTEA PRIMARY KEY CHECK(octet_length(program_sha256)=32),
 source_bytes BYTEA NOT NULL CHECK(octet_length(source_bytes)<=2097152),
 CHECK(sha256(source_bytes)=program_sha256)
);
CREATE TABLE game_npc_source_policies (
 program_sha256 BYTEA NOT NULL REFERENCES game_npc_source_programs(program_sha256),
 source_key TEXT NOT NULL CHECK(octet_length(source_key) BETWEEN 1 AND 256),
 npc_key TEXT NOT NULL CHECK(octet_length(npc_key) BETWEEN 1 AND 128),
 track_keys TEXT[] NOT NULL CHECK(cardinality(track_keys)<=512),
 writable_tracks JSONB NOT NULL CHECK(jsonb_typeof(writable_tracks)='object'),
 allowed_grant_keys TEXT[] NOT NULL CHECK(cardinality(allowed_grant_keys)<=2),
 item_costs JSONB NOT NULL CHECK(jsonb_typeof(item_costs)='array' AND jsonb_array_length(item_costs)<=32),
 effects JSONB NOT NULL CHECK(jsonb_typeof(effects)='array' AND jsonb_array_length(effects)<=64),
 fee_service_key TEXT, fee_gold_units BIGINT CHECK(fee_gold_units>0),
 enabled BOOLEAN NOT NULL DEFAULT FALSE,
 PRIMARY KEY(program_sha256,source_key),
 CHECK((fee_service_key IS NULL)=(fee_gold_units IS NULL))
);
REVOKE ALL ON game_npc_source_programs,game_npc_source_policies FROM PUBLIC;
GRANT SELECT ON game_npc_source_programs,game_npc_source_policies TO oteryn_game_runtime;
CREATE TABLE game_npc_source_context (
 backend_pid INTEGER PRIMARY KEY, transaction_xid XID8 NOT NULL,
 node_id UUID NOT NULL,registration NUMERIC(20,0) NOT NULL,
 character_id UUID NOT NULL,account_id UUID NOT NULL,world_id UUID NOT NULL,channel_id UUID NOT NULL,
 game_session_id UUID NOT NULL,command_id NUMERIC(20,0) NOT NULL,
 connection_generation NUMERIC(20,0) NOT NULL,lease_generation NUMERIC(20,0) NOT NULL,scope_generation NUMERIC(20,0) NOT NULL,
 original_revision NUMERIC(20,0) NOT NULL,
 program_sha256 BYTEA NOT NULL,source_key TEXT NOT NULL,npc_key TEXT NOT NULL,
 npc_transaction_id UUID NOT NULL,request_binding BYTEA NOT NULL,
 before_state JSONB NOT NULL,expected_plan JSONB NOT NULL,plan_sha256 BYTEA NOT NULL,
 cost_transaction_id UUID,fee_transaction_id UUID,captured BOOLEAN NOT NULL DEFAULT FALSE,
 FOREIGN KEY(program_sha256,source_key) REFERENCES game_npc_source_policies(program_sha256,source_key)
);
CREATE INDEX game_npc_source_context_program ON game_npc_source_context(program_sha256,source_key);
REVOKE ALL ON game_npc_source_context FROM PUBLIC,oteryn_game_runtime;
ALTER TABLE game_npc_cosmetic_receipts
 ADD COLUMN program_sha256 BYTEA CHECK(program_sha256 IS NULL OR octet_length(program_sha256)=32),
 ADD COLUMN plan_sha256 BYTEA CHECK(plan_sha256 IS NULL OR octet_length(plan_sha256)=32),
 ADD COLUMN fee_transaction_id UUID UNIQUE;
-- Immutable cost records capture the actual equipment epoch before worn materials
-- are removed. The existing proof basis already hashes the whole stamped row.
ALTER TABLE game_srv7_item_costs ADD COLUMN equipment_before JSONB;
DO $migration$ DECLARE body TEXT;needle TEXT;BEGIN
 body:=pg_get_functiondef('game_srv7_cost_admit()'::regprocedure);
 needle:=' NEW.created_xact_id:=pg_current_xact_id();';
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'NPC full equipment capture boundary changed';END IF;
 EXECUTE replace(body,needle,$capture$
 IF NEW.equipment_revision_before IS NOT NULL THEN
  SELECT to_jsonb(npc_equipment_before) INTO STRICT NEW.equipment_before
   FROM game_character_equipment_state npc_equipment_before WHERE npc_equipment_before.character_id=NEW.character_id FOR UPDATE;
  IF (NEW.equipment_before->>'revision')::numeric IS DISTINCT FROM NEW.equipment_revision_before THEN
   RAISE EXCEPTION 'NPC material equipment capture differs from actual epoch' USING ERRCODE='23514';END IF;
 ELSE NEW.equipment_before:=NULL;END IF;
 NEW.created_xact_id:=pg_current_xact_id();$capture$);
END $migration$;

-- No source language executes: only these four closed integer expressions.
CREATE FUNCTION game_npc_source_expression(p_expr JSONB,p_tracks JSONB,p_now BIGINT) RETURNS BIGINT
LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE result BIGINT;BEGIN
 CASE p_expr->>'op'
 WHEN 'literal' THEN result:=(p_expr->>'value')::bigint;
 WHEN 'now' THEN result:=p_now;
 WHEN 'now_plus' THEN result:=p_now+(p_expr->>'seconds')::bigint;
 WHEN 'add' THEN
  result:=coalesce((p_tracks->>(p_expr->>'storage'))::bigint,-1)+(p_expr->>'amount')::bigint;
  IF p_expr ? 'clamp_min' THEN result:=greatest(result,(p_expr->>'clamp_min')::bigint);END IF;
  IF p_expr ? 'clamp_max' THEN result:=least(result,(p_expr->>'clamp_max')::bigint);END IF;
 ELSE RAISE EXCEPTION 'unknown finite NPC integer expression' USING ERRCODE='23514';
 END CASE;
 IF result IS NULL THEN RAISE EXCEPTION 'incomplete finite NPC integer expression' USING ERRCODE='23514';END IF;
 RETURN result;
END $$;

CREATE TABLE game_npc_source_clock (
 backend_pid INTEGER PRIMARY KEY, transaction_xid XID8 NOT NULL,node_id UUID NOT NULL, registration NUMERIC(20,0) NOT NULL,now_seconds BIGINT NOT NULL
);
REVOKE ALL ON game_npc_source_clock FROM PUBLIC,oteryn_game_runtime;
CREATE FUNCTION game_npc_source_observe_clock(p_node UUID,p_registration NUMERIC,p_secret BYTEA) RETURNS BIGINT
 LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE observed BIGINT;BEGIN
 IF game_node_prove_current_incarnation(p_node,p_registration,p_secret) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'NPC source clock lacks current Node possession' USING ERRCODE='23514';END IF;
 SELECT now_seconds INTO observed FROM game_npc_source_clock WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id() AND node_id=p_node AND registration=p_registration;
 IF observed IS NOT NULL THEN RETURN observed;END IF;
 IF EXISTS(SELECT 1 FROM game_npc_source_clock WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id()) THEN
  RAISE EXCEPTION 'NPC source clock already belongs to another Node' USING ERRCODE='23514';END IF;
 DELETE FROM game_npc_source_clock WHERE backend_pid=pg_backend_pid() OR backend_pid NOT IN(SELECT pid FROM pg_stat_activity);
 observed:=floor(extract(epoch FROM game_daily_effect_now()))::bigint;
 INSERT INTO game_npc_source_clock VALUES(pg_backend_pid(),pg_current_xact_id(),p_node,p_registration,observed);
 RETURN observed;
END $$;
CREATE FUNCTION game_npc_arm_source(p_node UUID,p_registration NUMERIC,p_secret BYTEA,
 p_context JSONB,p_program BYTEA,p_before JSONB,p_plan JSONB) RETURNS BYTEA
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE policy game_npc_source_policies%ROWTYPE;s game_durability_reconnect_sessions%ROWTYPE;
 root game_character_roots%ROWTYPE; actual_tracks JSONB;actor_sex TEXT;change JSONB;rule JSONB;change_count INTEGER;
BEGIN
 IF game_node_prove_current_incarnation(p_node,p_registration,p_secret) IS DISTINCT FROM TRUE
  OR game_runtime_scope_assignment_history_valid() IS DISTINCT FROM TRUE
  OR jsonb_typeof(p_context) IS DISTINCT FROM 'object' OR jsonb_typeof(p_before) IS DISTINCT FROM 'object'
  OR jsonb_typeof(p_plan) IS DISTINCT FROM 'object' OR octet_length(p_before::text)>196608 OR octet_length(p_plan::text)>196608 THEN
  RAISE EXCEPTION 'NPC source arm lacks current Node/closed native observation' USING ERRCODE='23514';END IF;
 SELECT * INTO policy FROM game_npc_source_policies WHERE program_sha256=p_program AND source_key=p_context->>'source_key';
 IF policy.source_key IS NULL OR NOT policy.enabled OR policy.npc_key IS DISTINCT FROM p_context->>'npc_key' THEN
  RAISE EXCEPTION 'NPC source is not in the active finite program' USING ERRCODE='23514';END IF;
 SELECT * INTO s FROM game_durability_reconnect_sessions WHERE game_session_id=(p_context->>'game_session_id')::uuid FOR UPDATE;
 SELECT * INTO root FROM game_character_roots WHERE character_id=s.character_id FOR UPDATE;
 IF s.game_session_id IS NULL OR root.character_id IS NULL OR s.session_state<>2 OR s.current_transport_ref IS NULL OR root.lifecycle<>1
  OR s.character_id IS DISTINCT FROM (p_context->>'character_id')::uuid OR s.account_id IS DISTINCT FROM root.account_id
  OR s.world_id IS DISTINCT FROM (p_context->>'world_id')::uuid OR s.runtime_scope_kind<>1
  OR s.runtime_scope_world_id IS DISTINCT FROM s.world_id OR s.runtime_scope_channel_id IS DISTINCT FROM (p_context->>'channel_id')::uuid
  OR s.current_generation IS DISTINCT FROM (p_context->>'connection_generation')::numeric
  OR s.character_lease_generation IS DISTINCT FROM (p_context->>'lease_generation')::numeric
  OR s.scope_ownership_generation IS DISTINCT FROM (p_context->>'scope_generation')::numeric
  OR root.character_revision IS DISTINCT FROM (p_context->>'original_revision')::numeric
  OR root.character_revision>=18446744073709551615
  OR NOT EXISTS(SELECT 1 FROM game_runtime_scope_assignments assignment
   JOIN game_durability_admission_runtime_guards runtime_guard ON runtime_guard.scope_key=assignment.scope_key
   JOIN game_durability_admission_character_guards character_guard ON character_guard.character_id=s.character_id AND character_guard.account_id=s.account_id
   JOIN game_durability_admission_account_guards account_guard ON account_guard.account_id=s.account_id
   WHERE assignment.scope_kind=1 AND assignment.world_id=s.world_id AND assignment.channel_id=s.runtime_scope_channel_id
    AND assignment.state=1 AND assignment.ownership_generation=s.scope_ownership_generation
    AND assignment.holder_node_id=p_node AND assignment.holder_registration_revision=p_registration
    AND runtime_guard.ready AND runtime_guard.ownership_generation=assignment.ownership_generation
    AND character_guard.eligible AND character_guard.holder_game_session_id=s.game_session_id AND character_guard.lease_generation=s.character_lease_generation
    AND account_guard.presence_character_id=s.character_id AND account_guard.holder_game_session_id=s.game_session_id)
  OR EXISTS(SELECT 1 FROM game_character_pending_respawns WHERE character_id=s.character_id)
  OR EXISTS(SELECT 1 FROM game_character_pending_arrivals WHERE character_id=s.character_id) THEN
  RAISE EXCEPTION 'NPC source observation lost its exact current Character/Channel fence' USING ERRCODE='23514';END IF;
 PERFORM 1 FROM game_runtime_scope_assignments assignment WHERE assignment.scope_kind=1 AND assignment.world_id=s.world_id
  AND assignment.channel_id=s.runtime_scope_channel_id AND assignment.state=1 AND assignment.ownership_generation=s.scope_ownership_generation
  AND assignment.holder_node_id=p_node AND assignment.holder_registration_revision=p_registration FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'NPC source Channel changed before private capture' USING ERRCODE='23514';END IF;
 actor_sex:=CASE root.sex WHEN 1 THEN 'female' WHEN 2 THEN 'male' ELSE NULL END;
 SELECT coalesce(jsonb_object_agg(track_key,value),'{}'::jsonb) INTO actual_tracks FROM game_character_quest_tracks
  WHERE character_id=s.character_id AND track_key=ANY(policy.track_keys);
 IF actor_sex IS NULL OR p_before->>'name' IS DISTINCT FROM root.name OR p_before->>'sex' IS DISTINCT FROM actor_sex OR p_before->'tracks' IS DISTINCT FROM actual_tracks
  OR p_plan->>'source_key' IS DISTINCT FROM policy.source_key OR jsonb_typeof(p_plan->'changes') IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_plan->'changes')>8 OR jsonb_typeof(p_plan->'grant_keys') IS DISTINCT FROM 'array'
  OR jsonb_array_length(p_plan->'grant_keys')>2 THEN
  RAISE EXCEPTION 'NPC source plan differs from actual locked before state' USING ERRCODE='23514';END IF;
 IF jsonb_typeof(p_before->'achievement_progress') IS DISTINCT FROM 'object' OR EXISTS(
  SELECT 1 FROM jsonb_each_text(p_before->'achievement_progress') npc_progress_before
  WHERE npc_progress_before.value::bigint IS DISTINCT FROM coalesce((SELECT npc_progress.progress FROM game_character_achievement_progress npc_progress WHERE npc_progress.character_id=s.character_id AND npc_progress.achievement_key=npc_progress_before.key),0)) THEN
  RAISE EXCEPTION 'NPC source progress observation differs from locked actual state' USING ERRCODE='23514';END IF;
 IF p_plan->'effects' IS DISTINCT FROM policy.effects
  OR (p_before->>'level')::bigint IS DISTINCT FROM (SELECT progression.level FROM game_character_progression_state progression WHERE progression.character_id=s.character_id AND progression.character_revision=root.character_revision)
  OR p_plan->'costs' IS DISTINCT FROM policy.item_costs
  OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(p_plan->'grant_keys') AS npc_grant(value) WHERE NOT npc_grant.value=ANY(policy.allowed_grant_keys))
  OR (SELECT count(DISTINCT value) FROM jsonb_array_elements_text(p_plan->'grant_keys'))<>jsonb_array_length(p_plan->'grant_keys')
  OR (p_before->>'now') IS NULL OR NOT EXISTS(SELECT 1 FROM game_npc_source_clock npc_clock WHERE npc_clock.backend_pid=pg_backend_pid() AND npc_clock.transaction_xid=pg_current_xact_id() AND npc_clock.node_id=p_node AND npc_clock.registration=p_registration AND npc_clock.now_seconds=(p_before->>'now')::bigint) THEN
  RAISE EXCEPTION 'NPC source plan changes its static costs/grants or source clock' USING ERRCODE='23514';END IF;
 SELECT count(*) INTO change_count FROM jsonb_object_keys(policy.writable_tracks);
 IF change_count<>jsonb_array_length(p_plan->'changes') OR
  (SELECT count(DISTINCT value->>'key') FROM jsonb_array_elements(p_plan->'changes'))<>change_count THEN
  RAISE EXCEPTION 'NPC source plan changes its exact track set' USING ERRCODE='23514';END IF;
 FOR change IN SELECT value FROM jsonb_array_elements(p_plan->'changes') LOOP
  rule:=policy.writable_tracks->(change->>'key');
  IF rule IS NULL OR change->>'quest' IS DISTINCT FROM rule->>'quest'
   OR (change->>'before')::bigint IS DISTINCT FROM coalesce((actual_tracks->>(change->>'key'))::bigint,-1)
   OR (change->>'after')::bigint IS DISTINCT FROM game_npc_source_expression(rule->'value',actual_tracks,(p_before->>'now')::bigint) THEN
   RAISE EXCEPTION 'NPC source track delta differs from actual before and finite expression' USING ERRCODE='23514';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM game_npc_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id()) THEN
  RAISE EXCEPTION 'NPC source observation is sealed once per transaction' USING ERRCODE='23514';END IF;
 DELETE FROM game_npc_source_context WHERE backend_pid=pg_backend_pid() OR backend_pid NOT IN(SELECT pid FROM pg_stat_activity);
 INSERT INTO game_npc_source_context(backend_pid,transaction_xid,node_id,registration,character_id,account_id,world_id,channel_id,
 game_session_id,command_id,connection_generation,lease_generation,scope_generation,original_revision,program_sha256,source_key,npc_key,
 npc_transaction_id,request_binding,before_state,expected_plan,plan_sha256)
 VALUES(pg_backend_pid(),pg_current_xact_id(),p_node,p_registration,s.character_id,s.account_id,s.world_id,s.runtime_scope_channel_id,
 s.game_session_id,(p_context->>'command_id')::numeric,s.current_generation,s.character_lease_generation,s.scope_ownership_generation,root.character_revision,
 p_program,policy.source_key,policy.npc_key,(p_context->>'npc_transaction_id')::uuid,decode(p_context->>'request_binding','hex'),p_before,p_plan,sha256(convert_to(p_plan::text,'UTF8')));
 RETURN sha256(convert_to(p_plan::text,'UTF8'));
END $$;

CREATE FUNCTION game_npc_source_bind_cost(p_cost UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_npc_source_context%ROWTYPE; r game_srv7_item_costs%ROWTYPE;
BEGIN
 SELECT * INTO c FROM game_npc_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id() FOR UPDATE;
 SELECT * INTO r FROM game_srv7_item_costs WHERE transaction_id=p_cost;
 IF c.character_id IS NULL OR c.captured OR c.cost_transaction_id IS NOT NULL OR p_cost=c.npc_transaction_id OR p_cost IS NOT DISTINCT FROM c.fee_transaction_id OR r.created_xact_id<>pg_current_xact_id()
  OR r.character_id IS DISTINCT FROM c.character_id OR r.game_session_id IS DISTINCT FROM c.game_session_id
  OR r.command_id IS DISTINCT FROM c.command_id OR r.cause_kind IS DISTINCT FROM 'npc_cosmetic' OR r.source_key IS DISTINCT FROM c.source_key
  OR r.requirements IS DISTINCT FROM c.expected_plan->'costs' THEN
  RAISE EXCEPTION 'NPC source cost is not its exact current physical cost' USING ERRCODE='23514';END IF;
 UPDATE game_npc_source_context SET cost_transaction_id=p_cost WHERE backend_pid=pg_backend_pid();
END $$;
CREATE FUNCTION game_npc_source_bind_fee(p_fee UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_npc_source_context%ROWTYPE;p game_npc_source_policies%ROWTYPE;
BEGIN
 SELECT * INTO c FROM game_npc_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id() FOR UPDATE;
 SELECT * INTO p FROM game_npc_source_policies WHERE program_sha256=c.program_sha256 AND source_key=c.source_key;
 IF c.character_id IS NULL OR c.captured OR c.fee_transaction_id IS NOT NULL OR p_fee=c.npc_transaction_id OR p_fee IS NOT DISTINCT FROM c.cost_transaction_id OR p.fee_gold_units IS NULL
  OR p.fee_gold_units IS DISTINCT FROM (c.expected_plan->'fee'->>'gold')::bigint
  OR p.fee_service_key IS DISTINCT FROM c.expected_plan->'fee'->>'service' OR game_character_is_uuid_v7(p_fee) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'NPC source fee is not its exact declared native service' USING ERRCODE='23514';END IF;
 UPDATE game_npc_source_context SET fee_transaction_id=p_fee WHERE backend_pid=pg_backend_pid();
END $$;
CREATE FUNCTION game_npc_source_effect_current(p_parent UUID,p_source TEXT,p_effect JSONB) RETURNS BOOLEAN LANGUAGE sql SECURITY DEFINER AS $$
 SELECT EXISTS(SELECT 1 FROM game_npc_source_context c
  JOIN game_runtime_scope_assignments assignment ON assignment.scope_kind=1 AND assignment.world_id=c.world_id AND assignment.channel_id=c.channel_id
  JOIN game_durability_reconnect_sessions session ON session.game_session_id=c.game_session_id
  WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id() AND c.npc_transaction_id=p_parent AND c.source_key=p_source
   AND assignment.state=1 AND assignment.ownership_generation=c.scope_generation AND assignment.holder_node_id=c.node_id AND assignment.holder_registration_revision=c.registration
   AND session.character_id=c.character_id AND session.current_generation=c.connection_generation AND session.character_lease_generation=c.lease_generation
   AND session.scope_ownership_generation=c.scope_generation AND session.session_state=2
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(c.expected_plan->'effects') effect WHERE effect.value=p_effect))
$$;
CREATE FUNCTION game_npc_source_parent_current(p_parent UUID,p_source TEXT) RETURNS BOOLEAN LANGUAGE sql SECURITY DEFINER AS $$
 SELECT EXISTS(SELECT 1 FROM game_npc_source_context c JOIN game_npc_cosmetic_receipts parent ON parent.transaction_id=c.npc_transaction_id
  WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id() AND c.npc_transaction_id=p_parent AND c.source_key=p_source
   AND parent.created_xact_id=pg_current_xact_id() AND parent.character_id=c.character_id AND parent.game_session_id=c.game_session_id
   AND parent.command_id=c.command_id AND parent.source_key=c.source_key AND parent.program_sha256=c.program_sha256 AND parent.plan_sha256=c.plan_sha256
   AND parent.original_character_revision=c.original_revision AND parent.committed_character_revision=c.original_revision+1)
$$;

CREATE FUNCTION game_npc_source_fee_current(p_fee UUID,p_character UUID,p_world UUID) RETURNS BOOLEAN LANGUAGE sql SECURITY DEFINER AS $$
 SELECT EXISTS(SELECT 1 FROM game_npc_source_context c WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id()
  AND c.fee_transaction_id=p_fee AND c.character_id=p_character AND c.world_id=p_world)
$$;
CREATE FUNCTION game_npc_cash_prior_equipment(p_fee UUID,p_character UUID,p_world UUID)
RETURNS TABLE(equipment_before JSONB,cost_transaction_id UUID) LANGUAGE sql SECURITY DEFINER AS $$
 SELECT cost.equipment_before,cost.transaction_id FROM game_npc_source_context c
 JOIN game_srv7_item_costs cost ON cost.transaction_id=c.cost_transaction_id
 WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id() AND c.fee_transaction_id=p_fee
  AND c.character_id=p_character AND c.world_id=p_world AND cost.created_xact_id=pg_current_xact_id()
  AND cost.character_id=c.character_id AND cost.game_session_id=c.game_session_id AND cost.command_id=c.command_id
  AND cost.cause_kind='npc_cosmetic' AND cost.source_key=c.source_key AND cost.equipment_before IS NOT NULL
$$;
CREATE FUNCTION game_npc_source_fee_complete(p_fee UUID,p_character UUID,p_world UUID) RETURNS BOOLEAN LANGUAGE sql SECURITY DEFINER AS $$
 SELECT EXISTS(SELECT 1 FROM game_npc_source_context c JOIN game_npc_cosmetic_receipts receipt ON receipt.transaction_id=c.npc_transaction_id
  JOIN game_character_roots root ON root.character_id=c.character_id
  WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id() AND c.fee_transaction_id=p_fee
   AND c.character_id=p_character AND c.world_id=p_world AND receipt.created_xact_id=pg_current_xact_id()
   AND receipt.character_id=c.character_id AND receipt.game_session_id=c.game_session_id AND receipt.command_id=c.command_id
   AND receipt.fee_transaction_id=p_fee AND receipt.cost_transaction_id IS NOT DISTINCT FROM c.cost_transaction_id
   AND receipt.program_sha256=c.program_sha256 AND receipt.plan_sha256=c.plan_sha256 AND receipt.source_key=c.source_key
   AND receipt.original_character_revision=c.original_revision AND receipt.committed_character_revision=c.original_revision+1
   AND root.character_revision=receipt.committed_character_revision)
$$;
DO $privileges$ DECLARE signature TEXT;BEGIN
 FOREACH signature IN ARRAY ARRAY[
 'game_npc_source_expression(jsonb,jsonb,bigint)','game_npc_source_observe_clock(uuid,numeric,bytea)','game_npc_arm_source(uuid,numeric,bytea,jsonb,bytea,jsonb,jsonb)','game_npc_source_bind_cost(uuid)','game_npc_source_bind_fee(uuid)',
 'game_npc_source_effect_current(uuid,text,jsonb)','game_npc_source_parent_current(uuid,text)','game_npc_source_fee_current(uuid,uuid,uuid)','game_npc_cash_prior_equipment(uuid,uuid,uuid)','game_npc_source_fee_complete(uuid,uuid,uuid)'] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',signature,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',signature);
  EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO oteryn_game_runtime',signature);
 END LOOP;
END $privileges$;

