-- SRV7_SOURCE_COMPOSITION: npc-source-program-guards.sql
-- Programme receipts are admitted only by the private same-XID Node observation.
ALTER TABLE game_npc_cosmetic_receipts DROP CONSTRAINT game_npc_cosmetic_receipts_npc_key_check;
ALTER TABLE game_npc_cosmetic_receipts ADD CONSTRAINT game_npc_cosmetic_receipts_npc_key_check CHECK(
 npc_key IN('oteryn:npc.amber','oteryn:npc.norma','oteryn:npc.tom','oteryn:npc.cledwyn','oteryn:npc.kesar_the_younger_day','oteryn:npc.hairycles') OR program_sha256 IS NOT NULL);
DO $migration$ DECLARE constraint_name TEXT;BEGIN
 SELECT conname INTO STRICT constraint_name FROM pg_constraint WHERE conrelid='game_npc_cosmetic_receipts'::regclass
  AND contype='c' AND pg_get_expr(conbin,conrelid) LIKE '%cardinality(grant_keys)%';
 EXECUTE format('ALTER TABLE game_npc_cosmetic_receipts DROP CONSTRAINT %I',constraint_name);
END $migration$;
ALTER TABLE game_npc_cosmetic_receipts ADD CHECK(cardinality(grant_keys)<=2 AND (program_sha256 IS NOT NULL OR cardinality(grant_keys)<=1));
CREATE FUNCTION game_npc_program_receipt_admit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE npc_ctx game_npc_source_context%ROWTYPE;BEGIN
 IF NEW.program_sha256 IS NULL THEN
  IF NEW.plan_sha256 IS NOT NULL OR NEW.fee_transaction_id IS NOT NULL THEN RAISE EXCEPTION 'legacy NPC receipt claims a programme child' USING ERRCODE='23514';END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO npc_ctx FROM game_npc_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id() FOR UPDATE;
 IF npc_ctx.backend_pid IS NULL OR npc_ctx.captured OR npc_ctx.program_sha256 IS DISTINCT FROM NEW.program_sha256
  OR npc_ctx.plan_sha256 IS DISTINCT FROM NEW.plan_sha256 OR npc_ctx.npc_transaction_id IS DISTINCT FROM NEW.transaction_id
  OR npc_ctx.character_id IS DISTINCT FROM NEW.character_id OR npc_ctx.account_id IS DISTINCT FROM NEW.account_id
  OR npc_ctx.game_session_id IS DISTINCT FROM NEW.game_session_id OR npc_ctx.command_id IS DISTINCT FROM NEW.command_id
  OR npc_ctx.source_key IS DISTINCT FROM NEW.source_key OR npc_ctx.npc_key IS DISTINCT FROM NEW.npc_key
  OR npc_ctx.request_binding IS DISTINCT FROM NEW.request_binding OR npc_ctx.original_revision IS DISTINCT FROM NEW.original_character_revision
  OR NEW.committed_character_revision IS DISTINCT FROM NEW.original_character_revision+1
  OR npc_ctx.cost_transaction_id IS DISTINCT FROM NEW.cost_transaction_id OR npc_ctx.fee_transaction_id IS DISTINCT FROM NEW.fee_transaction_id
  OR npc_ctx.expected_plan->'changes' IS DISTINCT FROM NEW.track_changes
  OR npc_ctx.expected_plan->'grant_keys' IS DISTINCT FROM to_jsonb(NEW.grant_keys)
  OR npc_ctx.expected_plan->'outcome' IS DISTINCT FROM NEW.outcome THEN
  RAISE EXCEPTION 'NPC programme receipt lacks its sealed source plan' USING ERRCODE='23514';END IF;
 UPDATE game_npc_source_context SET captured=TRUE WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 NEW.created_xact_id:=pg_current_xact_id();RETURN NEW;
END $$;
CREATE TRIGGER game_npc_program_receipt_admit BEFORE INSERT ON game_npc_cosmetic_receipts FOR EACH ROW EXECUTE FUNCTION game_npc_program_receipt_admit();
CREATE FUNCTION game_npc_program_receipt_complete(npc_receipt game_npc_cosmetic_receipts) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE npc_ctx game_npc_source_context%ROWTYPE;npc_change JSONB;npc_grant TEXT;npc_effect JSONB;npc_achievement TEXT;npc_progress BIGINT;BEGIN
 SELECT * INTO npc_ctx FROM game_npc_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF npc_ctx.npc_transaction_id IS DISTINCT FROM npc_receipt.transaction_id OR npc_ctx.captured IS DISTINCT FROM TRUE
  OR npc_receipt.created_xact_id IS DISTINCT FROM pg_current_xact_id()
  OR NOT EXISTS(SELECT 1 FROM game_character_roots npc_root WHERE npc_root.character_id=npc_receipt.character_id
   AND npc_root.account_id=npc_receipt.account_id AND npc_root.character_revision=npc_receipt.committed_character_revision)
  OR NOT EXISTS(SELECT 1 FROM game_character_progression_state npc_progress WHERE npc_progress.character_id=npc_receipt.character_id
   AND npc_progress.character_revision=npc_receipt.committed_character_revision)
  OR (npc_ctx.expected_plan->'costs'='[]'::jsonb) IS DISTINCT FROM (npc_receipt.cost_transaction_id IS NULL) THEN
  RAISE EXCEPTION 'NPC programme did not finish its single Character edge' USING ERRCODE='23514';END IF;
 IF npc_receipt.cost_transaction_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM game_srv7_item_costs npc_cost
  WHERE npc_cost.transaction_id=npc_receipt.cost_transaction_id AND npc_cost.character_id=npc_receipt.character_id
   AND npc_cost.source_key=npc_receipt.source_key AND npc_cost.game_session_id=npc_receipt.game_session_id
   AND npc_cost.command_id=npc_receipt.command_id AND npc_cost.requirements=npc_ctx.expected_plan->'costs'
   AND npc_cost.created_xact_id=pg_current_xact_id()) THEN
  RAISE EXCEPTION 'NPC programme did not finish its exact item cost child' USING ERRCODE='23514';END IF;
 FOR npc_change IN SELECT value FROM jsonb_array_elements(npc_receipt.track_changes) LOOP
  IF NOT EXISTS(SELECT 1 FROM game_character_quest_tracks npc_track WHERE npc_track.character_id=npc_receipt.character_id
   AND npc_track.track_key=npc_change->>'key' AND npc_track.quest_key=npc_change->>'quest'
   AND npc_track.value=(npc_change->>'after')::bigint AND npc_track.committed_character_revision=npc_receipt.committed_character_revision) THEN
   RAISE EXCEPTION 'NPC programme lost a source track successor' USING ERRCODE='23514';END IF;
 END LOOP;
 FOR npc_effect IN SELECT value FROM jsonb_array_elements(npc_ctx.expected_plan->'effects') LOOP
  IF npc_effect->>'kind' IN('achievement','achievement_progress') THEN
   npc_achievement:='oteryn:achievement/'||trim(both '_' from regexp_replace(lower(npc_effect->>'name'),'[^a-z0-9]+','_','g'));
   IF npc_effect->>'kind'='achievement_progress' THEN
    IF NOT (npc_ctx.before_state->'achievement_progress' ? npc_achievement) THEN
     RAISE EXCEPTION 'NPC source progress lacks actual predecessor observation' USING ERRCODE='23514';END IF;
    npc_progress:=greatest((npc_ctx.before_state->'achievement_progress'->>npc_achievement)::bigint,least((npc_effect->>'target')::bigint,(npc_ctx.before_state->'achievement_progress'->>npc_achievement)::bigint+1));
    IF NOT EXISTS(SELECT 1 FROM game_character_achievement_progress npc_progress_row WHERE npc_progress_row.character_id=npc_receipt.character_id AND npc_progress_row.achievement_key=npc_achievement AND npc_progress_row.progress=npc_progress) THEN
     RAISE EXCEPTION 'NPC source did not finish achievement progress' USING ERRCODE='23514';END IF;
   END IF;
   IF (npc_effect->>'kind'='achievement' OR npc_progress=(npc_effect->>'target')::bigint) AND NOT EXISTS(SELECT 1 FROM game_account_achievements npc_achievement_row WHERE npc_achievement_row.account_id=npc_receipt.account_id AND npc_achievement_row.achievement_key=npc_achievement) THEN
    RAISE EXCEPTION 'NPC source did not finish its achievement successor' USING ERRCODE='23514';END IF;
  END IF;
 END LOOP;
 FOREACH npc_grant IN ARRAY npc_receipt.grant_keys LOOP
  IF NOT EXISTS(SELECT 1 FROM game_account_appearance_unlock_receipts npc_unlock
   JOIN game_account_appearance_unlocks npc_owned USING(account_id,unlock_key,grant_occurrence_id)
   WHERE npc_unlock.account_id=npc_receipt.account_id AND npc_unlock.granting_character_id=npc_receipt.character_id
    AND npc_unlock.unlock_key=npc_grant AND npc_unlock.source_kind='npc'
    AND npc_unlock.content_revision='crystal-201189f-npc-cosmetics-v1' AND npc_unlock.source_event_id=uuid_send(npc_receipt.transaction_id)) THEN
   RAISE EXCEPTION 'NPC programme lost an exact account grant successor' USING ERRCODE='23514';END IF;
 END LOOP;
END $$;
DO $migration$ DECLARE npc_definition TEXT;npc_begin INTEGER;BEGIN
 npc_definition:=pg_get_functiondef('game_npc_cosmetic_receipt_guard()'::regprocedure);
 npc_begin:=regexp_instr(npc_definition,E'\\mBEGIN\\M',1,1,0,'i');
 IF npc_begin=0 THEN RAISE EXCEPTION 'NPC receipt guard boundary changed';END IF;
 EXECUTE overlay(npc_definition placing E'BEGIN\n IF NEW.program_sha256 IS NOT NULL THEN PERFORM game_npc_program_receipt_complete(NEW); RETURN NULL;END IF;\n' from npc_begin for 5);
END $migration$;
DO $migration$ DECLARE npc_function TEXT;BEGIN
 FOREACH npc_function IN ARRAY ARRAY['game_npc_program_receipt_admit()','game_npc_program_receipt_complete(game_npc_cosmetic_receipts)'] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',npc_function,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',npc_function);
 END LOOP;
END $migration$;


-- SRV7_SOURCE_COMPOSITION: npc-fee-carried-cash.sql
-- Closed NPC473/474 physical cash. Original Gem proofs/SQL are unchanged.
CREATE FUNCTION game_npc_cash_context_current(p_fee UUID,p_character UUID,p_world UUID)RETURNS BOOLEAN LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN IF game_horse_rental_fee_current(p_fee,p_character,p_world) THEN RETURN TRUE;END IF;RETURN game_npc_source_fee_current(p_fee,p_character,p_world);END $$;
CREATE FUNCTION game_npc_cash_source_complete(p_fee UUID,p_character UUID,p_world UUID)RETURNS BOOLEAN LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN IF game_horse_rental_fee_complete(p_fee,p_character,p_world) THEN RETURN TRUE;END IF;RETURN game_npc_source_fee_complete(p_fee,p_character,p_world);END $$;
CREATE TABLE IF NOT EXISTS game_npc_fee_cash_records (
 transaction_id UUID PRIMARY KEY REFERENCES game_item_fee_burns(transaction_id),
 character_id UUID NOT NULL REFERENCES game_character_roots,
 world_id UUID NOT NULL,
 backpack_item_instance_id UUID REFERENCES game_item_instances,
 backpack_capacity SMALLINT NOT NULL CHECK(backpack_capacity BETWEEN 0 AND 20),
 backpack_ordinals JSONB NOT NULL CHECK(jsonb_typeof(backpack_ordinals)='array' AND jsonb_array_length(backpack_ordinals)<=20),
 inputs JSONB NOT NULL CHECK(jsonb_typeof(inputs)='array' AND jsonb_array_length(inputs)<=508),
 equipment_cost_transaction_id UUID REFERENCES game_srv7_item_costs(transaction_id),
 equipment_before JSONB CHECK(equipment_before IS NULL OR jsonb_typeof(equipment_before)='object'),
 created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),
 CHECK((backpack_item_instance_id IS NULL)=(backpack_capacity=0))
);
-- FK lookups and deferred current-transaction evidence must not scan historical payments.
CREATE INDEX IF NOT EXISTS game_npc_fee_cash_character_xact
 ON game_npc_fee_cash_records(character_id,created_xact_id);
CREATE INDEX IF NOT EXISTS game_npc_fee_cash_current_world
 ON game_npc_fee_cash_records(created_xact_id,world_id);
CREATE INDEX IF NOT EXISTS game_npc_fee_cash_backpack
 ON game_npc_fee_cash_records(backpack_item_instance_id) WHERE backpack_item_instance_id IS NOT NULL;

ALTER TABLE game_npc_fee_cash_records ADD CHECK(equipment_cost_transaction_id IS NULL OR equipment_cost_transaction_id<>transaction_id);
CREATE INDEX game_npc_fee_cash_equipment_cost ON game_npc_fee_cash_records(equipment_cost_transaction_id) WHERE equipment_cost_transaction_id IS NOT NULL;
ALTER TABLE game_npc_fee_cash_records ADD CHECK(equipment_before IS NOT NULL OR equipment_cost_transaction_id IS NULL);

CREATE OR REPLACE FUNCTION game_npc_cash_admit() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
DECLARE line JSONB; item game_item_instances%ROWTYPE; current_equipment JSONB; material_equipment JSONB; current_sources JSONB; prior_cost UUID;
BEGIN
 SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]'::jsonb) INTO current_sources FROM game_atelier_carried_coin_sources(NEW.character_id,NEW.world_id) c;
 IF game_npc_cash_context_current(NEW.transaction_id,NEW.character_id,NEW.world_id) IS DISTINCT FROM TRUE
 OR NOT EXISTS(SELECT 1 FROM game_item_fee_burns f WHERE f.transaction_id=NEW.transaction_id AND f.created_xact_id=pg_current_xact_id()
   AND f.cause_kind IN (473,474) AND f.character_id=NEW.character_id AND f.world_id=NEW.world_id
   AND f.backpack_item_instance_id IS NOT DISTINCT FROM NEW.backpack_item_instance_id)
  OR NEW.backpack_item_instance_id IS DISTINCT FROM (SELECT s.item_instance_id FROM game_item_container_slots s WHERE s.character_id=NEW.character_id AND s.world_id=NEW.world_id)
  OR NEW.backpack_ordinals IS DISTINCT FROM coalesce((SELECT jsonb_agg(e.placement_ordinal ORDER BY e.placement_ordinal DESC) FROM game_item_container_entries e WHERE e.parent_item_instance_id=NEW.backpack_item_instance_id),'[]'::jsonb)
  OR jsonb_array_length(NEW.inputs)<>jsonb_array_length(current_sources)
  OR (SELECT count(DISTINCT l->>'item') FROM jsonb_array_elements(NEW.inputs) l)<>jsonb_array_length(NEW.inputs) THEN
  RAISE EXCEPTION 'NPC source coin proof requires the current complete carried sources' USING ERRCODE='23514';
 END IF;
 FOR line IN SELECT value FROM jsonb_array_elements(NEW.inputs) LOOP
  SELECT * INTO item FROM game_item_instances WHERE item_instance_id=(line->>'item')::uuid FOR UPDATE;
  IF item.item_instance_id IS NULL OR to_jsonb(item) IS DISTINCT FROM line->'before' OR item.world_id<>NEW.world_id OR item.lifecycle<>1
   OR item.definition_family<>'Item' OR game_item_coin_worth(item.definition_production_key) IS NULL OR item.quantity NOT BETWEEN 1 AND 100
   OR (line->>'burned')::int NOT BETWEEN 0 AND item.quantity
   OR EXISTS(SELECT 1 FROM game_item_keys WHERE item_instance_id=item.item_instance_id)
   OR EXISTS(SELECT 1 FROM game_item_timed_states WHERE item_instance_id=item.item_instance_id)
   OR EXISTS(SELECT 1 FROM game_item_texts WHERE item_instance_id=item.item_instance_id)
   OR EXISTS(SELECT 1 FROM game_item_imbuements WHERE item_instance_id=item.item_instance_id)
   OR NOT game_atelier_coin_source_present(NEW.character_id,NEW.world_id,line)
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(current_sources) c WHERE (c->>'item_instance_id')::uuid=item.item_instance_id
    AND c->'selection_order'=line->'selection_order' AND c->'surface'=line->'surface' AND c->'slot'=line->'slot'
    AND c->>'parent_item_instance_id' IS NOT DISTINCT FROM line->>'parent' AND (c->>'placement_ordinal')::numeric=(line->>'ordinal')::numeric) THEN
   RAISE EXCEPTION 'NPC source coin input is not its unchanged carried leaf' USING ERRCODE='23514';
  END IF;
 END LOOP;
 IF (NEW.equipment_before IS NOT NULL) IS DISTINCT FROM EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.inputs) l WHERE (l->>'surface')::int=3 AND (l->>'burned')::int>0) THEN
  RAISE EXCEPTION 'NPC source coin equipment proof shape mismatch' USING ERRCODE='23514';
 END IF;
 IF NEW.equipment_before IS NOT NULL THEN
  SELECT to_jsonb(s) INTO current_equipment FROM game_character_equipment_state s WHERE s.character_id=NEW.character_id FOR UPDATE;
  SELECT a.equipment_before,a.cost_transaction_id INTO material_equipment,prior_cost FROM game_npc_cash_prior_equipment(NEW.transaction_id,NEW.character_id,NEW.world_id) a;
  IF (material_equipment IS NULL AND(NEW.equipment_before IS DISTINCT FROM current_equipment OR NEW.equipment_cost_transaction_id IS NOT NULL))
    OR (material_equipment IS NOT NULL AND (NEW.equipment_before IS DISTINCT FROM material_equipment OR NEW.equipment_cost_transaction_id IS DISTINCT FROM prior_cost
      OR (current_equipment->>'revision')::numeric<>(material_equipment->>'revision')::numeric+1
      OR (current_equipment->>'last_transaction_id')::uuid IS DISTINCT FROM prior_cost)) THEN
   RAISE EXCEPTION 'NPC source coin equipment requires the original shared epoch' USING ERRCODE='23514';
  END IF;
 END IF;
 NEW.created_xact_id:=pg_current_xact_id(); RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION game_npc_cash_complete(p_transaction UUID) RETURNS void LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
DECLARE r game_npc_fee_cash_records%ROWTYPE; f game_item_fee_burns%ROWTYPE; line JSONB; item game_item_instances%ROWTYPE;
 burn game_item_fee_burn_lines%ROWTYPE; position INT:=0; remaining BIGINT; worth BIGINT; before_quantity BIGINT; amount BIGINT;
 first_item UUID; outputs INT; payer UUID; equipment JSONB; last_worth BIGINT;
BEGIN
 SELECT * INTO r FROM game_npc_fee_cash_records WHERE transaction_id=p_transaction;
 SELECT * INTO f FROM game_item_fee_burns WHERE transaction_id=p_transaction;
 IF r.transaction_id IS NULL OR f.transaction_id IS NULL OR r.created_xact_id<>pg_current_xact_id() OR f.created_xact_id<>pg_current_xact_id()
  OR f.cause_kind NOT IN (473,474) OR f.character_id<>r.character_id OR f.world_id<>r.world_id OR f.backpack_item_instance_id IS DISTINCT FROM r.backpack_item_instance_id
  OR f.backpack_item_instance_id IS DISTINCT FROM (SELECT s.item_instance_id FROM game_item_container_slots s WHERE s.character_id=f.character_id AND s.world_id=f.world_id)
  OR NOT EXISTS(SELECT 1 FROM game_character_roots cr WHERE cr.character_id=f.character_id AND cr.world_id=f.world_id AND cr.character_revision=f.committed_character_revision AND cr.xmin=pg_current_xact_id()::xid)
  OR game_npc_cash_source_complete(f.transaction_id,f.character_id,f.world_id) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'NPC source coin payment requires its fresh Character receipt' USING ERRCODE='23514';
 END IF;
 remaining:=f.fee_gold_units-f.bank_debit_gold_units;
 FOR line IN SELECT l FROM jsonb_array_elements(r.inputs) l ORDER BY game_item_coin_worth(l->'before'->>'definition_production_key'),(l->'before'->>'quantity')::bigint,(l->>'selection_order')::bigint LOOP
  worth:=game_item_coin_worth(line->'before'->>'definition_production_key'); before_quantity:=(line->'before'->>'quantity')::bigint;
  amount:=least(before_quantity,(remaining+worth-1)/worth);
  IF amount IS DISTINCT FROM (line->>'burned')::bigint THEN RAISE EXCEPTION 'NPC source coins must follow donor denomination and stack-worth order' USING ERRCODE='23514'; END IF;
  SELECT * INTO STRICT item FROM game_item_instances WHERE item_instance_id=(line->>'item')::uuid;
  IF amount=0 THEN
   IF to_jsonb(item) IS DISTINCT FROM line->'before' OR NOT game_atelier_coin_source_present(r.character_id,r.world_id,line) THEN
    RAISE EXCEPTION 'unselected NPC source coins must remain unchanged' USING ERRCODE='23514';
   END IF;
   CONTINUE;
  END IF;
  position:=position+1; last_worth:=worth;
  SELECT * INTO burn FROM game_item_fee_burn_lines WHERE transaction_id=p_transaction AND line_ordinal=position;
  IF position=1 THEN first_item:=item.item_instance_id; END IF;
  IF burn.item_instance_id IS DISTINCT FROM item.item_instance_id OR burn.created_xact_id<>pg_current_xact_id()
   OR burn.coin_worth<>worth OR burn.quantity_before<>before_quantity OR burn.quantity_after<>before_quantity-amount OR burn.placement_ordinal<>(line->>'ordinal')::numeric
   OR item.quantity<>burn.quantity_after OR item.lifecycle<>(CASE WHEN burn.quantity_after=0 THEN 2 ELSE 1 END)
   OR item.last_transaction_id IS DISTINCT FROM p_transaction OR item.state_revision<>(line->'before'->>'state_revision')::numeric+1
   OR (to_jsonb(item)-ARRAY['quantity','lifecycle','last_transaction_id','state_revision']) IS DISTINCT FROM ((line->'before')-ARRAY['quantity','lifecycle','last_transaction_id','state_revision'])
   OR NOT EXISTS(SELECT 1 FROM game_item_transfer_quantity_evidence e WHERE e.item_instance_id=item.item_instance_id AND e.transaction_id=p_transaction AND e.quantity_before=before_quantity)
   OR (burn.quantity_after>0 AND NOT game_atelier_coin_source_present(r.character_id,r.world_id,line))
   OR (burn.quantity_after=0 AND (EXISTS(SELECT 1 FROM game_item_container_entries e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_item_nested_entries e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_character_equipment_slots e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_item_container_slots e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_item_ground_locations e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_item_corpse_container_entries e WHERE e.item_instance_id=item.item_instance_id))) THEN
   RAISE EXCEPTION 'NPC source coin burn lacks exact before/after custody' USING ERRCODE='23514';
  END IF;
  remaining:=greatest(remaining-amount*worth,0);
 END LOOP;
 IF remaining<>0 OR position<>f.line_count OR (SELECT count(*) FROM game_item_fee_burn_lines WHERE transaction_id=p_transaction)<>position
  OR (SELECT coalesce(sum((quantity_before-quantity_after)*coin_worth),0) FROM game_item_fee_burn_lines WHERE transaction_id=p_transaction)<>f.burned_gold_units
  OR (position>0 AND f.change_gold_units>=last_worth)
  OR (f.bank_debit_gold_units>0 AND EXISTS(SELECT 1 FROM jsonb_array_elements(r.inputs) l WHERE (l->>'burned')::bigint<>(l->'before'->>'quantity')::bigint)) THEN
  RAISE EXCEPTION 'NPC source coin payment is not the exact coins-first plan' USING ERRCODE='23514';
 END IF;
 SELECT account_id INTO STRICT payer FROM game_character_roots WHERE character_id=f.character_id;
 IF (SELECT count(*) FROM game_account_bank_entries WHERE fee_transaction_id=p_transaction)<>(f.bank_debit_gold_units>0)::int
  OR (f.bank_debit_gold_units>0 AND NOT EXISTS(SELECT 1 FROM game_account_bank_entries e WHERE e.fee_transaction_id=p_transaction AND e.kind=5
   AND e.amount=f.bank_debit_gold_units AND e.account_id=payer AND e.world_id=f.world_id AND e.acting_character_id=f.character_id AND e.created_xact_id=pg_current_xact_id())) THEN
  RAISE EXCEPTION 'NPC source bank residual requires its one exact ledger debit' USING ERRCODE='23514';
 END IF;
 outputs:=(f.change_gold_units/100>0)::int+(f.change_gold_units%100>0)::int;
 IF (SELECT count(*) FROM game_item_instances WHERE minted_transaction_id=p_transaction)<>outputs
  OR (SELECT count(*) FROM game_item_instances WHERE last_transaction_id=p_transaction)<>position
  OR (SELECT count(*) FROM game_item_container_entries WHERE parent_item_instance_id=r.backpack_item_instance_id)>r.backpack_capacity
  OR (outputs>0 AND (r.backpack_item_instance_id IS NULL OR f.change_placement_ordinal<>1+coalesce((SELECT max(value::text::numeric) FROM jsonb_array_elements(r.backpack_ordinals)),0)))
  OR EXISTS(SELECT 1 FROM (VALUES (f.change_platinum_item_instance_id,'oteryn:item.tibia.i3035',f.change_gold_units/100,f.change_placement_ordinal),
    (f.change_gold_item_instance_id,'oteryn:item.tibia.i3031',f.change_gold_units%100,f.change_placement_ordinal+(f.change_gold_units/100>0)::int)) o(id,key,quantity,ordinal)
   WHERE o.quantity>0 AND NOT EXISTS(SELECT 1 FROM game_item_instances i JOIN game_item_container_entries e USING(item_instance_id,world_id)
    WHERE i.item_instance_id=o.id AND i.world_id=f.world_id AND i.definition_family='Item' AND i.definition_production_key=o.key AND i.quantity=o.quantity AND i.lifecycle=1
     AND i.minted_transaction_id=p_transaction AND i.last_transaction_id IS NULL AND e.character_id=f.character_id AND e.parent_item_instance_id=r.backpack_item_instance_id
     AND e.placement_ordinal=o.ordinal AND e.placed_transaction_id=p_transaction)) THEN
  RAISE EXCEPTION 'NPC source change requires its bounded exact fresh main-backpack outputs' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM game_item_audit_outbox a WHERE a.transaction_id=p_transaction AND a.event_id=f.event_id AND a.item_instance_id IS NOT DISTINCT FROM first_item
   AND a.occurred_at=f.occurred_at AND a.envelope_sha256=f.envelope_sha256 AND a.created_xact_id=pg_current_xact_id() AND a.publication_state=1 AND a.published_at IS NULL)
  OR (SELECT count(*) FROM game_item_audit_outbox WHERE transaction_id=p_transaction)<>1 THEN
  RAISE EXCEPTION 'NPC source coin payment requires one atomic audit event' USING ERRCODE='23514';
 END IF;
 IF r.equipment_before IS NOT NULL THEN
  SELECT to_jsonb(s) INTO equipment FROM game_character_equipment_state s WHERE s.character_id=r.character_id;
  IF equipment IS NULL OR (equipment->>'revision')::numeric<>(r.equipment_before->>'revision')::numeric+1 OR (equipment->>'last_transaction_id')::uuid IS DISTINCT FROM coalesce(r.equipment_cost_transaction_id,p_transaction)
   OR (equipment-ARRAY['revision','last_transaction_id']) IS DISTINCT FROM (r.equipment_before-ARRAY['revision','last_transaction_id']) THEN
   RAISE EXCEPTION 'NPC source coin equipment requires one shared successor' USING ERRCODE='23514';
  END IF;
 END IF;
END $$;

CREATE OR REPLACE FUNCTION game_npc_cash_consistent() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
BEGIN PERFORM game_npc_cash_complete(NEW.transaction_id); RETURN NULL; END $$;
DROP TRIGGER IF EXISTS game_npc_cash_admit ON game_npc_fee_cash_records;
CREATE TRIGGER game_npc_cash_admit BEFORE INSERT ON game_npc_fee_cash_records FOR EACH ROW EXECUTE FUNCTION game_npc_cash_admit();
DROP TRIGGER IF EXISTS game_npc_cash_consistent ON game_npc_fee_cash_records;
CREATE CONSTRAINT TRIGGER game_npc_cash_consistent AFTER INSERT ON game_npc_fee_cash_records DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_cash_consistent();
DROP TRIGGER IF EXISTS game_npc_cash_immutable ON game_npc_fee_cash_records;
CREATE TRIGGER game_npc_cash_immutable BEFORE UPDATE OR DELETE ON game_npc_fee_cash_records FOR EACH ROW EXECUTE FUNCTION game_item_immutable();
DROP TRIGGER IF EXISTS game_npc_cash_no_truncate ON game_npc_fee_cash_records;
CREATE TRIGGER game_npc_cash_no_truncate BEFORE TRUNCATE ON game_npc_fee_cash_records EXECUTE FUNCTION game_item_reject_truncate();

-- Extend existing proof functions without replacing any other owner's guard chain.
DO $migration$
DECLARE n TEXT; body TEXT; arm TEXT; begin_at INT;
BEGIN
 FOREACH n IN ARRAY ARRAY['game_item_fee_burn_consistency_guard','game_item_nested_entry_proven','game_equipment_slot_proven','game_equipment_state_proven'] LOOP
  body:=pg_get_functiondef((n||'()')::regprocedure);
  IF position('game_npc_fee_cash_records' IN body)>0 THEN CONTINUE; END IF;
  IF n='game_item_fee_burn_consistency_guard' THEN
   arm:=$arm$
 IF NEW.cause_kind IN (473,474) THEN
  PERFORM game_npc_cash_complete(NEW.transaction_id); RETURN NULL;
 END IF;
$arm$;
  ELSIF n='game_item_nested_entry_proven' THEN
   arm:=$arm$
 IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM game_npc_fee_cash_records r,LATERAL jsonb_array_elements(r.inputs) l
  WHERE r.created_xact_id=pg_current_xact_id() AND r.world_id=OLD.world_id AND (l->>'surface')::int=2 AND (l->>'item')::uuid=OLD.item_instance_id
   AND (l->>'parent')::uuid=OLD.parent_item_instance_id AND (l->>'ordinal')::numeric=OLD.placement_ordinal AND (l->>'burned')::bigint=(l->'before'->>'quantity')::bigint) THEN
  PERFORM game_npc_cash_complete(r.transaction_id) FROM game_npc_fee_cash_records r,LATERAL jsonb_array_elements(r.inputs) l
   WHERE r.created_xact_id=pg_current_xact_id() AND (l->>'item')::uuid=OLD.item_instance_id; RETURN NULL;
 END IF;
$arm$;
  ELSIF n='game_equipment_slot_proven' THEN
   arm:=$arm$
 IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM game_npc_fee_cash_records r,LATERAL jsonb_array_elements(r.inputs) l
  WHERE r.created_xact_id=pg_current_xact_id() AND r.character_id=OLD.character_id AND r.world_id=OLD.world_id AND r.equipment_before IS NOT NULL
   AND (l->>'surface')::int=3 AND (l->>'item')::uuid=OLD.item_instance_id AND (l->>'slot')::smallint=OLD.slot AND (l->>'burned')::bigint=(l->'before'->>'quantity')::bigint) THEN
  PERFORM game_npc_cash_complete(r.transaction_id) FROM game_npc_fee_cash_records r WHERE r.created_xact_id=pg_current_xact_id() AND r.character_id=OLD.character_id; RETURN NULL;
 END IF;
$arm$;
  ELSE
   arm:=$arm$
 IF EXISTS(SELECT 1 FROM game_npc_fee_cash_records r WHERE r.transaction_id=NEW.last_transaction_id AND r.character_id=NEW.character_id
  AND r.created_xact_id=pg_current_xact_id() AND r.equipment_before=to_jsonb(OLD)) THEN
  PERFORM game_npc_cash_complete(NEW.last_transaction_id); RETURN NULL;
 END IF;
$arm$;
  END IF;
  begin_at:=regexp_instr(body,E'\\mBEGIN\\M',1,1,0,'i');
  IF begin_at=0 THEN RAISE EXCEPTION 'missing carried coin guard anchor: %',n; END IF;
  EXECUTE overlay(body placing E'BEGIN\n'||arm from begin_at for 5);
 END LOOP;
END $migration$;


DO $npc_cash_causes$ DECLARE old TEXT;BEGIN
 SELECT pg_get_expr(conbin,conrelid)INTO STRICT old FROM pg_constraint WHERE conrelid='game_item_fee_burns'::regclass AND conname='game_item_fee_burns_cause_kind_check';
 ALTER TABLE game_item_fee_burns DROP CONSTRAINT game_item_fee_burns_cause_kind_check;
 EXECUTE 'ALTER TABLE game_item_fee_burns ADD CONSTRAINT game_item_fee_burns_cause_kind_check CHECK(('||old||')OR cause_kind IN(473,474))';
END $npc_cash_causes$;
DO $npc_cash_checks$ DECLARE n TEXT;old TEXT;BEGIN
 FOREACH n IN ARRAY ARRAY['game_item_fee_burns_line_count_check','game_item_fee_burns_bank_only']LOOP
 SELECT pg_get_expr(conbin,conrelid)INTO STRICT old FROM pg_constraint WHERE conrelid='game_item_fee_burns'::regclass AND conname=n;
 EXECUTE format('ALTER TABLE game_item_fee_burns DROP CONSTRAINT %I,ADD CONSTRAINT %I CHECK((%s)OR(cause_kind IN(473,474)AND line_count BETWEEN 0 AND 508 AND((line_count=0)=(burned_gold_units=0))AND(line_count>0 OR bank_debit_gold_units=fee_gold_units)))',n,n,old);
 END LOOP;
END $npc_cash_checks$;
REVOKE ALL ON game_npc_fee_cash_records FROM PUBLIC;
GRANT SELECT,INSERT ON game_npc_fee_cash_records TO oteryn_game_runtime;


-- SRV7_SOURCE_COMPOSITION: horse-rental-no-permanent.sql
-- A temporary personal rental can never become a permanent Account unlock,
-- regardless of a forged source-kind/provenance or a historical receipt.
CREATE FUNCTION game_horse_rental_no_permanent_grant()RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
 IF NEW.unlock_key IN('oteryn:rental.horse.22','oteryn:rental.horse.25','oteryn:rental.horse.26')THEN
  RAISE EXCEPTION 'temporary horse rentals are Character contracts, never Account appearance grants' USING ERRCODE='23514';
 END IF;RETURN NEW;
END $$;
CREATE TRIGGER game_horse_rental_no_permanent_receipt BEFORE INSERT ON game_account_appearance_unlock_receipts
 FOR EACH ROW EXECUTE FUNCTION game_horse_rental_no_permanent_grant();
CREATE TRIGGER game_horse_rental_no_permanent_fact BEFORE INSERT ON game_account_appearance_unlocks
 FOR EACH ROW EXECUTE FUNCTION game_horse_rental_no_permanent_grant();


-- SRV7_SOURCE_COMPOSITION: npc-source-paid-cash-minimum.sql
CREATE FUNCTION game_npc_source_fee_cash_minimum(p_fee UUID,p_character UUID,p_world UUID) RETURNS BIGINT LANGUAGE sql SECURITY DEFINER AS $$
 SELECT coalesce((SELECT sum((npc_effect.value->>'gold')::bigint) FROM jsonb_array_elements(npc_policy.effects) npc_effect WHERE npc_effect.value->>'kind'='consume_money'),0)::bigint
 FROM game_npc_source_context npc_context JOIN game_npc_source_policies npc_policy ON npc_policy.program_sha256=npc_context.program_sha256 AND npc_policy.source_key=npc_context.source_key
 WHERE npc_context.backend_pid=pg_backend_pid() AND npc_context.transaction_xid=pg_current_xact_id() AND npc_context.fee_transaction_id=p_fee AND npc_context.character_id=p_character AND npc_context.world_id=p_world AND npc_policy.enabled
$$;
DO $$BEGIN EXECUTE format('ALTER FUNCTION game_npc_source_fee_cash_minimum(uuid,uuid,uuid) SET search_path=pg_catalog,%I,pg_temp',current_schema());END $$;
REVOKE ALL ON FUNCTION game_npc_source_fee_cash_minimum(uuid,uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION game_npc_source_fee_cash_minimum(uuid,uuid,uuid) TO oteryn_game_runtime;


-- SRV7_SOURCE_COMPOSITION: npc-cash-source-mode.sql
CREATE FUNCTION game_npc_cash_minimum(p_fee UUID,p_character UUID,p_world UUID) RETURNS BIGINT LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN IF game_horse_rental_fee_current(p_fee,p_character,p_world) THEN RETURN 0;END IF;
RETURN game_npc_source_fee_cash_minimum(p_fee,p_character,p_world);END $$;

CREATE OR REPLACE FUNCTION game_npc_cash_complete(p_transaction UUID) RETURNS void LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
DECLARE r game_npc_fee_cash_records%ROWTYPE; f game_item_fee_burns%ROWTYPE; line JSONB; item game_item_instances%ROWTYPE;
 burn game_item_fee_burn_lines%ROWTYPE; position INT:=0; remaining BIGINT; worth BIGINT; before_quantity BIGINT; amount BIGINT;
 first_item UUID; outputs INT; payer UUID; equipment JSONB; last_worth BIGINT; minimum_carried BIGINT;
BEGIN
 SELECT * INTO r FROM game_npc_fee_cash_records WHERE transaction_id=p_transaction;
 SELECT * INTO f FROM game_item_fee_burns WHERE transaction_id=p_transaction;
 minimum_carried:=game_npc_cash_minimum(p_transaction,r.character_id,r.world_id);
 IF r.transaction_id IS NULL OR f.transaction_id IS NULL OR r.created_xact_id<>pg_current_xact_id() OR f.created_xact_id<>pg_current_xact_id()
  OR minimum_carried IS NULL OR minimum_carried<0 OR minimum_carried>f.fee_gold_units OR f.fee_gold_units-f.bank_debit_gold_units<minimum_carried
  OR f.cause_kind NOT IN (473,474) OR f.character_id<>r.character_id OR f.world_id<>r.world_id OR f.backpack_item_instance_id IS DISTINCT FROM r.backpack_item_instance_id
  OR f.backpack_item_instance_id IS DISTINCT FROM (SELECT s.item_instance_id FROM game_item_container_slots s WHERE s.character_id=f.character_id AND s.world_id=f.world_id)
  OR NOT EXISTS(SELECT 1 FROM game_character_roots cr WHERE cr.character_id=f.character_id AND cr.world_id=f.world_id AND cr.character_revision=f.committed_character_revision AND cr.xmin=pg_current_xact_id()::xid)
  OR game_npc_cash_source_complete(f.transaction_id,f.character_id,f.world_id) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'NPC source coin payment requires its fresh Character receipt' USING ERRCODE='23514';
 END IF;
 remaining:=f.fee_gold_units-f.bank_debit_gold_units;
 FOR line IN SELECT l FROM jsonb_array_elements(r.inputs) l ORDER BY game_item_coin_worth(l->'before'->>'definition_production_key'),(l->'before'->>'quantity')::bigint,(l->>'selection_order')::bigint LOOP
  worth:=game_item_coin_worth(line->'before'->>'definition_production_key'); before_quantity:=(line->'before'->>'quantity')::bigint;
  amount:=least(before_quantity,(remaining+worth-1)/worth);
  IF amount IS DISTINCT FROM (line->>'burned')::bigint THEN RAISE EXCEPTION 'NPC source coins must follow donor denomination and stack-worth order' USING ERRCODE='23514'; END IF;
  SELECT * INTO STRICT item FROM game_item_instances WHERE item_instance_id=(line->>'item')::uuid;
  IF amount=0 THEN
   IF to_jsonb(item) IS DISTINCT FROM line->'before' OR NOT game_atelier_coin_source_present(r.character_id,r.world_id,line) THEN
    RAISE EXCEPTION 'unselected NPC source coins must remain unchanged' USING ERRCODE='23514';
   END IF;
   CONTINUE;
  END IF;
  position:=position+1; last_worth:=worth;
  SELECT * INTO burn FROM game_item_fee_burn_lines WHERE transaction_id=p_transaction AND line_ordinal=position;
  IF position=1 THEN first_item:=item.item_instance_id; END IF;
  IF burn.item_instance_id IS DISTINCT FROM item.item_instance_id OR burn.created_xact_id<>pg_current_xact_id()
   OR burn.coin_worth<>worth OR burn.quantity_before<>before_quantity OR burn.quantity_after<>before_quantity-amount OR burn.placement_ordinal<>(line->>'ordinal')::numeric
   OR item.quantity<>burn.quantity_after OR item.lifecycle<>(CASE WHEN burn.quantity_after=0 THEN 2 ELSE 1 END)
   OR item.last_transaction_id IS DISTINCT FROM p_transaction OR item.state_revision<>(line->'before'->>'state_revision')::numeric+1
   OR (to_jsonb(item)-ARRAY['quantity','lifecycle','last_transaction_id','state_revision']) IS DISTINCT FROM ((line->'before')-ARRAY['quantity','lifecycle','last_transaction_id','state_revision'])
   OR NOT EXISTS(SELECT 1 FROM game_item_transfer_quantity_evidence e WHERE e.item_instance_id=item.item_instance_id AND e.transaction_id=p_transaction AND e.quantity_before=before_quantity)
   OR (burn.quantity_after>0 AND NOT game_atelier_coin_source_present(r.character_id,r.world_id,line))
   OR (burn.quantity_after=0 AND (EXISTS(SELECT 1 FROM game_item_container_entries e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_item_nested_entries e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_character_equipment_slots e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_item_container_slots e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_item_ground_locations e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_item_corpse_container_entries e WHERE e.item_instance_id=item.item_instance_id))) THEN
   RAISE EXCEPTION 'NPC source coin burn lacks exact before/after custody' USING ERRCODE='23514';
  END IF;
  remaining:=greatest(remaining-amount*worth,0);
 END LOOP;
 IF remaining<>0 OR position<>f.line_count OR (SELECT count(*) FROM game_item_fee_burn_lines WHERE transaction_id=p_transaction)<>position
  OR (SELECT coalesce(sum((quantity_before-quantity_after)*coin_worth),0) FROM game_item_fee_burn_lines WHERE transaction_id=p_transaction)<>f.burned_gold_units
  OR (position>0 AND f.change_gold_units>=last_worth)
  OR (f.bank_debit_gold_units>0 AND EXISTS(SELECT 1 FROM jsonb_array_elements(r.inputs) l WHERE (l->>'burned')::bigint<>(l->'before'->>'quantity')::bigint)) THEN
  RAISE EXCEPTION 'NPC source coin payment is not the exact coins-first plan' USING ERRCODE='23514';
 END IF;
 SELECT account_id INTO STRICT payer FROM game_character_roots WHERE character_id=f.character_id;
 IF (SELECT count(*) FROM game_account_bank_entries WHERE fee_transaction_id=p_transaction)<>(f.bank_debit_gold_units>0)::int
  OR (f.bank_debit_gold_units>0 AND NOT EXISTS(SELECT 1 FROM game_account_bank_entries e WHERE e.fee_transaction_id=p_transaction AND e.kind=5
   AND e.amount=f.bank_debit_gold_units AND e.account_id=payer AND e.world_id=f.world_id AND e.acting_character_id=f.character_id AND e.created_xact_id=pg_current_xact_id())) THEN
  RAISE EXCEPTION 'NPC source bank residual requires its one exact ledger debit' USING ERRCODE='23514';
 END IF;
 outputs:=(f.change_gold_units/100>0)::int+(f.change_gold_units%100>0)::int;
 IF (SELECT count(*) FROM game_item_instances WHERE minted_transaction_id=p_transaction)<>outputs
  OR (SELECT count(*) FROM game_item_instances WHERE last_transaction_id=p_transaction)<>position
  OR (SELECT count(*) FROM game_item_container_entries WHERE parent_item_instance_id=r.backpack_item_instance_id)>r.backpack_capacity
  OR (outputs>0 AND (r.backpack_item_instance_id IS NULL OR f.change_placement_ordinal<>1+coalesce((SELECT max(value::text::numeric) FROM jsonb_array_elements(r.backpack_ordinals)),0)))
  OR EXISTS(SELECT 1 FROM (VALUES (f.change_platinum_item_instance_id,'oteryn:item.tibia.i3035',f.change_gold_units/100,f.change_placement_ordinal),
    (f.change_gold_item_instance_id,'oteryn:item.tibia.i3031',f.change_gold_units%100,f.change_placement_ordinal+(f.change_gold_units/100>0)::int)) o(id,key,quantity,ordinal)
   WHERE o.quantity>0 AND NOT EXISTS(SELECT 1 FROM game_item_instances i JOIN game_item_container_entries e USING(item_instance_id,world_id)
    WHERE i.item_instance_id=o.id AND i.world_id=f.world_id AND i.definition_family='Item' AND i.definition_production_key=o.key AND i.quantity=o.quantity AND i.lifecycle=1
     AND i.minted_transaction_id=p_transaction AND i.last_transaction_id IS NULL AND e.character_id=f.character_id AND e.parent_item_instance_id=r.backpack_item_instance_id
     AND e.placement_ordinal=o.ordinal AND e.placed_transaction_id=p_transaction)) THEN
  RAISE EXCEPTION 'NPC source change requires its bounded exact fresh main-backpack outputs' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM game_item_audit_outbox a WHERE a.transaction_id=p_transaction AND a.event_id=f.event_id AND a.item_instance_id IS NOT DISTINCT FROM first_item
   AND a.occurred_at=f.occurred_at AND a.envelope_sha256=f.envelope_sha256 AND a.created_xact_id=pg_current_xact_id() AND a.publication_state=1 AND a.published_at IS NULL)
  OR (SELECT count(*) FROM game_item_audit_outbox WHERE transaction_id=p_transaction)<>1 THEN
  RAISE EXCEPTION 'NPC source coin payment requires one atomic audit event' USING ERRCODE='23514';
 END IF;
 IF r.equipment_before IS NOT NULL THEN
  SELECT to_jsonb(s) INTO equipment FROM game_character_equipment_state s WHERE s.character_id=r.character_id;
  IF equipment IS NULL OR (equipment->>'revision')::numeric<>(r.equipment_before->>'revision')::numeric+1 OR (equipment->>'last_transaction_id')::uuid IS DISTINCT FROM coalesce(r.equipment_cost_transaction_id,p_transaction)
   OR (equipment-ARRAY['revision','last_transaction_id']) IS DISTINCT FROM (r.equipment_before-ARRAY['revision','last_transaction_id']) THEN
   RAISE EXCEPTION 'NPC source coin equipment requires one shared successor' USING ERRCODE='23514';
  END IF;
 END IF;
END $$;



-- SRV7_SOURCE_COMPOSITION: npc-grant-namespace.sql
-- Every grant in the NPC namespace belongs to an actual reciprocal NPC receipt.
-- A claimed alternative source_kind/provenance is not a separate authority.
CREATE FUNCTION game_npc_grant_namespace_proven() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE npc_namespace_proof JSONB;
BEGIN
 IF NEW.unlock_key NOT LIKE 'oteryn:appearance-grant/npc/%' THEN RETURN NEW;END IF;
 IF TG_TABLE_NAME='game_account_appearance_unlock_receipts' THEN
  npc_namespace_proof:=to_jsonb(NEW);
 ELSE
  SELECT to_jsonb(npc_namespace_receipt) INTO npc_namespace_proof
   FROM game_account_appearance_unlock_receipts npc_namespace_receipt
   WHERE npc_namespace_receipt.grant_occurrence_id=NEW.grant_occurrence_id
    AND npc_namespace_receipt.account_id=NEW.account_id AND npc_namespace_receipt.unlock_key=NEW.unlock_key;
 END IF;
 IF npc_namespace_proof IS NULL OR npc_namespace_proof->>'source_kind' IS DISTINCT FROM 'npc'
  OR npc_namespace_proof->>'content_revision' IS DISTINCT FROM 'crystal-201189f-npc-cosmetics-v1'
  OR NOT EXISTS(SELECT 1 FROM game_npc_cosmetic_receipts npc_namespace_parent
   WHERE npc_namespace_parent.account_id=NEW.account_id
    AND npc_namespace_parent.character_id=(npc_namespace_proof->>'granting_character_id')::uuid
    AND NEW.unlock_key=ANY(npc_namespace_parent.grant_keys)
    AND uuid_send(npc_namespace_parent.transaction_id)=(npc_namespace_proof->>'source_event_id')::bytea
    AND npc_namespace_parent.created_xact_id=pg_current_xact_id()) THEN
  RAISE EXCEPTION 'NPC grant namespace requires its actual source parent' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
DO $$BEGIN EXECUTE format('ALTER FUNCTION game_npc_grant_namespace_proven() SET search_path=pg_catalog,%I,pg_temp',current_schema());END $$;
REVOKE ALL ON FUNCTION game_npc_grant_namespace_proven() FROM PUBLIC;
CREATE TRIGGER game_npc_grant_namespace_receipt BEFORE INSERT ON game_account_appearance_unlock_receipts
 FOR EACH ROW EXECUTE FUNCTION game_npc_grant_namespace_proven();
CREATE TRIGGER game_npc_grant_namespace_fact BEFORE INSERT ON game_account_appearance_unlocks
 FOR EACH ROW EXECUTE FUNCTION game_npc_grant_namespace_proven();


-- SRV7_SOURCE_COMPOSITION: npc-fee-purchase-causes.sql
-- NPC cash keeps all existing purchase-cause shapes. New typed causes have
-- their own exact service/price shape plus the existing reciprocal source guards.
CREATE INDEX game_npc_source_policies_fee_service_price
 ON game_npc_source_policies(fee_service_key,fee_gold_units)
 WHERE fee_service_key IS NOT NULL;
CREATE FUNCTION game_npc_source_fee_purchase_shape(p_service TEXT,p_gold BIGINT)
 RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER
 SET search_path=pg_catalog,public,pg_temp AS $$
 SELECT p_service IS NOT NULL AND p_gold>0 AND EXISTS(
  SELECT 1 FROM game_npc_source_policies source_policy
  WHERE source_policy.fee_service_key=p_service AND source_policy.fee_gold_units=p_gold)
$$;
REVOKE ALL ON FUNCTION game_npc_source_fee_purchase_shape(TEXT,BIGINT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION game_npc_source_fee_purchase_shape(TEXT,BIGINT) TO oteryn_game_runtime;
DO $npc_purchase_causes$
DECLARE original_expression TEXT;
BEGIN
 SELECT pg_get_expr(conbin,conrelid) INTO STRICT original_expression
 FROM pg_constraint WHERE conrelid='game_item_fee_burns'::regclass
 AND conname='game_item_fee_burns_purchase_cause';
 ALTER TABLE game_item_fee_burns DROP CONSTRAINT game_item_fee_burns_purchase_cause;
 EXECUTE 'ALTER TABLE game_item_fee_burns ADD CONSTRAINT game_item_fee_burns_purchase_cause CHECK('
 ||'CASE cause_kind WHEN 473 THEN (charm_key IS NULL AND '
 ||'(purchase_service_key=''oteryn:service.horse-station.rental'') IS TRUE AND fee_gold_units=500) '
 ||'WHEN 474 THEN (charm_key IS NULL AND game_npc_source_fee_purchase_shape(purchase_service_key,fee_gold_units) IS TRUE) '
 ||'ELSE ('||original_expression||') END)';
END $npc_purchase_causes$;

-- SRV7_SOURCE_COMPOSITION: npc-ajax-actor-effect.sql
-- Closed child; no second Character revision/transaction or post-commit writer.
CREATE TABLE game_npc_source_actor_effects (
 npc_transaction_id UUID PRIMARY KEY REFERENCES game_npc_cosmetic_receipts(transaction_id),
 character_id UUID NOT NULL REFERENCES game_character_roots(character_id),
 game_session_id UUID NOT NULL,
 command_id NUMERIC(20,0) NOT NULL CHECK(command_id BETWEEN 1 AND 18446744073709551615),
 source_key TEXT NOT NULL CHECK(source_key='oteryn:npc-cosmetic/ajax/barbarian-fire'),
 program_sha256 BYTEA NOT NULL CHECK(octet_length(program_sha256)=32),
 committed_revision NUMERIC(20,0) NOT NULL,
 observation JSONB NOT NULL CHECK(jsonb_typeof(observation)='object' AND octet_length(observation::text)<=65536),
 created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),
 UNIQUE(game_session_id,command_id)
);
CREATE INDEX game_npc_source_actor_effects_character ON game_npc_source_actor_effects(character_id);
REVOKE ALL ON game_npc_source_actor_effects FROM PUBLIC;
GRANT SELECT,INSERT ON game_npc_source_actor_effects TO oteryn_game_runtime;
CREATE TABLE game_npc_source_actor_snapshot_proofs (
 backend_pid INTEGER PRIMARY KEY,transaction_xid XID8 NOT NULL,
 npc_transaction_id UUID NOT NULL,character_id UUID NOT NULL,
 conditions_sha256 BYTEA NOT NULL CHECK(octet_length(conditions_sha256)=32)
);
REVOKE ALL ON game_npc_source_actor_snapshot_proofs FROM PUBLIC,oteryn_game_runtime;
CREATE FUNCTION game_npc_source_actor_effect_admit() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_npc_source_context%ROWTYPE;r game_npc_cosmetic_receipts%ROWTYPE;BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'immutable NPC actor effect'; END IF;
 SELECT * INTO c FROM game_npc_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 SELECT * INTO r FROM game_npc_cosmetic_receipts WHERE transaction_id=NEW.npc_transaction_id;
 IF c.backend_pid IS NULL OR c.captured IS DISTINCT FROM TRUE
  OR c.npc_key<>'oteryn:npc.ajax' OR c.source_key<>'oteryn:npc-cosmetic/ajax/barbarian-fire'
  OR NEW.npc_transaction_id IS DISTINCT FROM c.npc_transaction_id
  OR NEW.character_id IS DISTINCT FROM c.character_id OR NEW.game_session_id IS DISTINCT FROM c.game_session_id
  OR NEW.command_id IS DISTINCT FROM c.command_id OR NEW.program_sha256 IS DISTINCT FROM c.program_sha256
  OR NEW.source_key IS DISTINCT FROM c.source_key OR NEW.committed_revision IS DISTINCT FROM c.original_revision+1
  OR NEW.observation IS DISTINCT FROM c.before_state->'actor_effect'
  OR NEW.observation->>'kind' IS DISTINCT FROM 'ajax_fire'
  OR game_npc_source_parent_current(NEW.npc_transaction_id,NEW.source_key) IS DISTINCT FROM TRUE
  OR game_npc_source_effect_current(NEW.npc_transaction_id,NEW.source_key,'{"kind":"condition_damage","condition":"FIRE","delayed":true,"ticks":10,"interval_ms":2000,"damage_per_tick":10}'::jsonb) IS DISTINCT FROM TRUE
  OR NEW.observation->>'lease_generation' IS DISTINCT FROM c.lease_generation::text
  OR r.character_id IS DISTINCT FROM NEW.character_id OR r.game_session_id IS DISTINCT FROM NEW.game_session_id
  OR r.command_id IS DISTINCT FROM NEW.command_id OR r.source_key IS DISTINCT FROM NEW.source_key
  OR r.program_sha256 IS DISTINCT FROM NEW.program_sha256 OR r.created_xact_id IS DISTINCT FROM pg_current_xact_id()
  OR r.committed_character_revision IS DISTINCT FROM NEW.committed_revision
  OR NOT ((c.expected_plan->'effects') @> '[{"kind":"condition_damage","condition":"FIRE","delayed":true,"ticks":10,"interval_ms":2000,"damage_per_tick":10}]'::jsonb)
  OR NOT EXISTS(SELECT 1 FROM game_character_roots WHERE character_id=NEW.character_id AND character_revision=NEW.committed_revision)
 THEN RAISE EXCEPTION 'NPC actor effect lacks exact source/Node/actor/parent proof';END IF;
 NEW.created_xact_id:=pg_current_xact_id();RETURN NEW;
END $$;
CREATE TRIGGER game_npc_source_actor_effect_admit BEFORE INSERT OR UPDATE OR DELETE ON game_npc_source_actor_effects FOR EACH ROW EXECUTE FUNCTION game_npc_source_actor_effect_admit();
CREATE FUNCTION game_npc_source_actor_snapshot_capture() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_npc_source_context%ROWTYPE;o JSONB;BEGIN
 SELECT * INTO c FROM game_npc_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 IF c.backend_pid IS NULL OR c.before_state->'actor_effect' IS NULL OR c.before_state->'actor_effect'='null'::jsonb THEN RETURN NEW;END IF;
 o:=c.before_state->'actor_effect';
 IF NEW.character_id IS DISTINCT FROM c.character_id OR NEW.character_lease_generation IS DISTINCT FROM c.lease_generation
  OR NEW.snapshot IS DISTINCT FROM o->'conditions_after' OR encode(NEW.content_digest,'hex') IS DISTINCT FROM o->>'content_digest'
 THEN RAISE EXCEPTION 'NPC source actor snapshot differs from sealed native after';END IF;
 INSERT INTO game_npc_source_actor_snapshot_proofs VALUES(pg_backend_pid(),pg_current_xact_id(),c.npc_transaction_id,c.character_id,sha256(convert_to(NEW.snapshot::text,'UTF8')))
 ON CONFLICT(backend_pid) DO UPDATE SET transaction_xid=EXCLUDED.transaction_xid,npc_transaction_id=EXCLUDED.npc_transaction_id,character_id=EXCLUDED.character_id,conditions_sha256=EXCLUDED.conditions_sha256;
 RETURN NEW;
END $$;
CREATE TRIGGER game_npc_source_actor_snapshot_capture AFTER INSERT OR UPDATE ON game_character_condition_snapshots FOR EACH ROW EXECUTE FUNCTION game_npc_source_actor_snapshot_capture();
CREATE FUNCTION game_npc_source_actor_effect_complete() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM game_npc_source_actor_snapshot_proofs p JOIN game_character_condition_snapshots s ON s.character_id=p.character_id
 WHERE p.backend_pid=pg_backend_pid() AND p.transaction_xid=pg_current_xact_id() AND p.npc_transaction_id=NEW.npc_transaction_id
 AND p.character_id=NEW.character_id AND p.conditions_sha256=sha256(convert_to(s.snapshot::text,'UTF8'))
 AND s.snapshot=NEW.observation->'conditions_after' AND encode(s.content_digest,'hex')=NEW.observation->>'content_digest'
 AND s.character_lease_generation=(NEW.observation->>'lease_generation')::numeric)
 THEN RAISE EXCEPTION 'NPC actor effect requires same-XID exact condition snapshot';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_npc_source_actor_effect_complete AFTER INSERT ON game_npc_source_actor_effects DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_source_actor_effect_complete();

CREATE FUNCTION game_npc_source_ajax_child_required() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NEW.source_key='oteryn:npc-cosmetic/ajax/barbarian-fire' AND NOT EXISTS(SELECT 1 FROM game_npc_source_actor_effects a WHERE a.npc_transaction_id=NEW.transaction_id AND a.created_xact_id=NEW.created_xact_id)
 THEN RAISE EXCEPTION 'Ajax FIRE source parent requires native actor child';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_npc_source_ajax_child_required AFTER INSERT ON game_npc_cosmetic_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_source_ajax_child_required();

-- Recheck after every later snapshot mutation, including DELETE, so an early
-- SET CONSTRAINTS cannot validate a child then remove its successor snapshot.
CREATE FUNCTION game_npc_source_actor_snapshot_complete() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE char_id UUID; a game_npc_source_actor_effects%ROWTYPE;
BEGIN
 char_id:=CASE WHEN TG_OP='DELETE' THEN OLD.character_id ELSE NEW.character_id END;
 FOR a IN SELECT * FROM game_npc_source_actor_effects WHERE character_id=char_id AND created_xact_id=pg_current_xact_id()
 LOOP
  IF NOT EXISTS(SELECT 1 FROM game_character_condition_snapshots s
    WHERE s.character_id=a.character_id AND s.snapshot=a.observation->'conditions_after'
    AND encode(s.content_digest,'hex')=a.observation->>'content_digest'
    AND s.character_lease_generation=(a.observation->>'lease_generation')::numeric)
  THEN RAISE EXCEPTION 'NPC actor child lost its exact condition snapshot';END IF;
 END LOOP;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_npc_source_actor_snapshot_complete AFTER INSERT OR UPDATE OR DELETE ON game_character_condition_snapshots DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_source_actor_snapshot_complete();

DO $actor_effect_paths$ DECLARE signature TEXT; BEGIN
 FOREACH signature IN ARRAY ARRAY['game_npc_source_actor_effect_admit()',
 'game_npc_source_actor_snapshot_capture()','game_npc_source_actor_effect_complete()',
 'game_npc_source_ajax_child_required()','game_npc_source_actor_snapshot_complete()'] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',signature,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_runtime',signature);
 END LOOP;
END $actor_effect_paths$;

-- SRV7_SOURCE_COMPOSITION: npc-cash-proof-cache.sql
-- Incremental 0993 composition over the original cash block only. The full
-- npc-fee-carried-cash.sql already includes this proof cache; never concatenate
-- that full template with this incremental leaf when rebuilding a migration.
-- A successful full physical proof is shared by deferred custody callbacks in
-- the same SQL statement. Later statements and every footprint mutation require
-- the complete proof again, including SET CONSTRAINTS followed by more writes.
CREATE TABLE game_npc_cash_verified (
 backend_pid INTEGER NOT NULL,
 transaction_xid XID8 NOT NULL,
 fee_transaction_id UUID NOT NULL,
 statement_started TIMESTAMPTZ NOT NULL,
 PRIMARY KEY(backend_pid,fee_transaction_id)
);
REVOKE ALL ON game_npc_cash_verified FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
CREATE FUNCTION game_npc_cash_invalidate() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 DELETE FROM game_npc_cash_verified WHERE backend_pid=pg_backend_pid();
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION game_npc_cash_invalidate() FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
DO $cash_invalidation$ DECLARE relation TEXT;BEGIN
 -- Complete physical proof read-set, including the custody-presence helper.
 FOREACH relation IN ARRAY ARRAY[
 'game_npc_fee_cash_records','game_item_fee_burns','game_item_fee_burn_lines',
 'game_item_instances','game_character_roots','game_account_bank_entries',
 'game_item_container_entries','game_item_nested_entries','game_item_container_slots',
 'game_character_equipment_slots','game_character_equipment_state',
 'game_item_ground_locations','game_item_corpse_container_entries',
 'game_item_transfer_quantity_evidence','game_item_audit_outbox',
 'game_item_keys','game_item_timed_states','game_item_texts','game_item_imbuements',
 'game_horse_rental_receipts','game_horse_station_context','game_npc_source_context',
 'game_npc_cosmetic_receipts','game_srv7_item_costs',
 'game_runtime_scope_assignments','game_durability_reconnect_sessions',
 'game_durability_admission_character_guards','game_durability_admission_account_guards',
 'game_durability_admission_runtime_guards'] LOOP
  EXECUTE format('CREATE TRIGGER game_npc_cash_invalidate AFTER INSERT OR UPDATE OR DELETE OR TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION game_npc_cash_invalidate()',relation);
 END LOOP;
END $cash_invalidation$;

CREATE OR REPLACE FUNCTION game_npc_cash_complete(p_transaction UUID) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r game_npc_fee_cash_records%ROWTYPE; f game_item_fee_burns%ROWTYPE; line JSONB; item game_item_instances%ROWTYPE;
 burn game_item_fee_burn_lines%ROWTYPE; position INT:=0; remaining BIGINT; worth BIGINT; before_quantity BIGINT; amount BIGINT;
 first_item UUID; outputs INT; payer UUID; equipment JSONB; last_worth BIGINT; minimum_carried BIGINT;
BEGIN
 SELECT * INTO r FROM game_npc_fee_cash_records WHERE transaction_id=p_transaction;
 SELECT * INTO f FROM game_item_fee_burns WHERE transaction_id=p_transaction;
 minimum_carried:=game_npc_cash_minimum(p_transaction,r.character_id,r.world_id);
 IF r.transaction_id IS NULL OR f.transaction_id IS NULL OR r.created_xact_id<>pg_current_xact_id() OR f.created_xact_id<>pg_current_xact_id()
  OR minimum_carried IS NULL OR minimum_carried<0 OR minimum_carried>f.fee_gold_units OR f.fee_gold_units-f.bank_debit_gold_units<minimum_carried
  OR f.cause_kind NOT IN (473,474) OR f.character_id<>r.character_id OR f.world_id<>r.world_id OR f.backpack_item_instance_id IS DISTINCT FROM r.backpack_item_instance_id
  OR f.backpack_item_instance_id IS DISTINCT FROM (SELECT s.item_instance_id FROM game_item_container_slots s WHERE s.character_id=f.character_id AND s.world_id=f.world_id)
  OR NOT EXISTS(SELECT 1 FROM game_character_roots cr WHERE cr.character_id=f.character_id AND cr.world_id=f.world_id AND cr.character_revision=f.committed_character_revision AND cr.xmin=pg_current_xact_id()::xid)
  OR game_npc_cash_source_complete(f.transaction_id,f.character_id,f.world_id) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'NPC source coin payment requires its fresh Character receipt' USING ERRCODE='23514';
 END IF;
 -- Authority and immutable parent completion above are deliberately rechecked
 -- even when another custody callback already proved this physical batch.
 IF EXISTS(SELECT 1 FROM game_npc_cash_verified v
  WHERE v.backend_pid=pg_backend_pid() AND v.transaction_xid=pg_current_xact_id()
   AND v.fee_transaction_id=p_transaction AND v.statement_started=statement_timestamp()) THEN
  RETURN;
 END IF;
 remaining:=f.fee_gold_units-f.bank_debit_gold_units;
 FOR line IN SELECT l FROM jsonb_array_elements(r.inputs) l ORDER BY game_item_coin_worth(l->'before'->>'definition_production_key'),(l->'before'->>'quantity')::bigint,(l->>'selection_order')::bigint LOOP
  worth:=game_item_coin_worth(line->'before'->>'definition_production_key'); before_quantity:=(line->'before'->>'quantity')::bigint;
  amount:=least(before_quantity,(remaining+worth-1)/worth);
  IF amount IS DISTINCT FROM (line->>'burned')::bigint THEN RAISE EXCEPTION 'NPC source coins must follow donor denomination and stack-worth order' USING ERRCODE='23514'; END IF;
  SELECT * INTO STRICT item FROM game_item_instances WHERE item_instance_id=(line->>'item')::uuid;
  IF amount=0 THEN
   IF to_jsonb(item) IS DISTINCT FROM line->'before' OR NOT game_atelier_coin_source_present(r.character_id,r.world_id,line) THEN
    RAISE EXCEPTION 'unselected NPC source coins must remain unchanged' USING ERRCODE='23514';
   END IF;
   CONTINUE;
  END IF;
  position:=position+1; last_worth:=worth;
  SELECT * INTO burn FROM game_item_fee_burn_lines WHERE transaction_id=p_transaction AND line_ordinal=position;
  IF position=1 THEN first_item:=item.item_instance_id; END IF;
  IF burn.item_instance_id IS DISTINCT FROM item.item_instance_id OR burn.created_xact_id<>pg_current_xact_id()
   OR burn.coin_worth<>worth OR burn.quantity_before<>before_quantity OR burn.quantity_after<>before_quantity-amount OR burn.placement_ordinal<>(line->>'ordinal')::numeric
   OR item.quantity<>burn.quantity_after OR item.lifecycle<>(CASE WHEN burn.quantity_after=0 THEN 2 ELSE 1 END)
   OR item.last_transaction_id IS DISTINCT FROM p_transaction OR item.state_revision<>(line->'before'->>'state_revision')::numeric+1
   OR (to_jsonb(item)-ARRAY['quantity','lifecycle','last_transaction_id','state_revision']) IS DISTINCT FROM ((line->'before')-ARRAY['quantity','lifecycle','last_transaction_id','state_revision'])
   OR NOT EXISTS(SELECT 1 FROM game_item_transfer_quantity_evidence e WHERE e.item_instance_id=item.item_instance_id AND e.transaction_id=p_transaction AND e.quantity_before=before_quantity)
   OR (burn.quantity_after>0 AND NOT game_atelier_coin_source_present(r.character_id,r.world_id,line))
   OR (burn.quantity_after=0 AND (EXISTS(SELECT 1 FROM game_item_container_entries e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_item_nested_entries e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_character_equipment_slots e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_item_container_slots e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_item_ground_locations e WHERE e.item_instance_id=item.item_instance_id)
     OR EXISTS(SELECT 1 FROM game_item_corpse_container_entries e WHERE e.item_instance_id=item.item_instance_id))) THEN
   RAISE EXCEPTION 'NPC source coin burn lacks exact before/after custody' USING ERRCODE='23514';
  END IF;
  remaining:=greatest(remaining-amount*worth,0);
 END LOOP;
 IF remaining<>0 OR position<>f.line_count OR (SELECT count(*) FROM game_item_fee_burn_lines WHERE transaction_id=p_transaction)<>position
  OR (SELECT coalesce(sum((quantity_before-quantity_after)*coin_worth),0) FROM game_item_fee_burn_lines WHERE transaction_id=p_transaction)<>f.burned_gold_units
  OR (position>0 AND f.change_gold_units>=last_worth)
  OR (f.bank_debit_gold_units>0 AND EXISTS(SELECT 1 FROM jsonb_array_elements(r.inputs) l WHERE (l->>'burned')::bigint<>(l->'before'->>'quantity')::bigint)) THEN
  RAISE EXCEPTION 'NPC source coin payment is not the exact coins-first plan' USING ERRCODE='23514';
 END IF;
 SELECT account_id INTO STRICT payer FROM game_character_roots WHERE character_id=f.character_id;
 IF (SELECT count(*) FROM game_account_bank_entries WHERE fee_transaction_id=p_transaction)<>(f.bank_debit_gold_units>0)::int
  OR (f.bank_debit_gold_units>0 AND NOT EXISTS(SELECT 1 FROM game_account_bank_entries e WHERE e.fee_transaction_id=p_transaction AND e.kind=5
   AND e.amount=f.bank_debit_gold_units AND e.account_id=payer AND e.world_id=f.world_id AND e.acting_character_id=f.character_id AND e.created_xact_id=pg_current_xact_id())) THEN
  RAISE EXCEPTION 'NPC source bank residual requires its one exact ledger debit' USING ERRCODE='23514';
 END IF;
 outputs:=(f.change_gold_units/100>0)::int+(f.change_gold_units%100>0)::int;
 IF (SELECT count(*) FROM game_item_instances WHERE minted_transaction_id=p_transaction)<>outputs
  OR (SELECT count(*) FROM game_item_instances WHERE last_transaction_id=p_transaction)<>position
  OR (SELECT count(*) FROM game_item_container_entries WHERE parent_item_instance_id=r.backpack_item_instance_id)>r.backpack_capacity
  OR (outputs>0 AND (r.backpack_item_instance_id IS NULL OR f.change_placement_ordinal<>1+coalesce((SELECT max(value::text::numeric) FROM jsonb_array_elements(r.backpack_ordinals)),0)))
  OR EXISTS(SELECT 1 FROM (VALUES (f.change_platinum_item_instance_id,'oteryn:item.tibia.i3035',f.change_gold_units/100,f.change_placement_ordinal),
    (f.change_gold_item_instance_id,'oteryn:item.tibia.i3031',f.change_gold_units%100,f.change_placement_ordinal+(f.change_gold_units/100>0)::int)) o(id,key,quantity,ordinal)
   WHERE o.quantity>0 AND NOT EXISTS(SELECT 1 FROM game_item_instances i JOIN game_item_container_entries e USING(item_instance_id,world_id)
    WHERE i.item_instance_id=o.id AND i.world_id=f.world_id AND i.definition_family='Item' AND i.definition_production_key=o.key AND i.quantity=o.quantity AND i.lifecycle=1
     AND i.minted_transaction_id=p_transaction AND i.last_transaction_id IS NULL AND e.character_id=f.character_id AND e.parent_item_instance_id=r.backpack_item_instance_id
     AND e.placement_ordinal=o.ordinal AND e.placed_transaction_id=p_transaction)) THEN
  RAISE EXCEPTION 'NPC source change requires its bounded exact fresh main-backpack outputs' USING ERRCODE='23514';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM game_item_audit_outbox a WHERE a.transaction_id=p_transaction AND a.event_id=f.event_id AND a.item_instance_id IS NOT DISTINCT FROM first_item
   AND a.occurred_at=f.occurred_at AND a.envelope_sha256=f.envelope_sha256 AND a.created_xact_id=pg_current_xact_id() AND a.publication_state=1 AND a.published_at IS NULL)
  OR (SELECT count(*) FROM game_item_audit_outbox WHERE transaction_id=p_transaction)<>1 THEN
  RAISE EXCEPTION 'NPC source coin payment requires one atomic audit event' USING ERRCODE='23514';
 END IF;
 IF r.equipment_before IS NOT NULL THEN
  SELECT to_jsonb(s) INTO equipment FROM game_character_equipment_state s WHERE s.character_id=r.character_id;
  IF equipment IS NULL OR (equipment->>'revision')::numeric<>(r.equipment_before->>'revision')::numeric+1 OR (equipment->>'last_transaction_id')::uuid IS DISTINCT FROM coalesce(r.equipment_cost_transaction_id,p_transaction)
   OR (equipment-ARRAY['revision','last_transaction_id']) IS DISTINCT FROM (r.equipment_before-ARRAY['revision','last_transaction_id']) THEN
   RAISE EXCEPTION 'NPC source coin equipment requires one shared successor' USING ERRCODE='23514';
  END IF;
 END IF;
 -- Only a successful, unchanged full proof may create this private memo.
 DELETE FROM game_npc_cash_verified v WHERE (v.backend_pid=pg_backend_pid()
  AND v.transaction_xid<>pg_current_xact_id())
  OR NOT EXISTS(SELECT 1 FROM pg_stat_activity a WHERE a.pid=v.backend_pid);
 INSERT INTO game_npc_cash_verified(backend_pid,transaction_xid,fee_transaction_id,statement_started)
 VALUES(pg_backend_pid(),pg_current_xact_id(),p_transaction,statement_timestamp())
 ON CONFLICT(backend_pid,fee_transaction_id) DO UPDATE
 SET transaction_xid=EXCLUDED.transaction_xid,statement_started=EXCLUDED.statement_started;
END $$;


REVOKE ALL ON FUNCTION game_npc_cash_complete(UUID) FROM PUBLIC,oteryn_game_control;
GRANT EXECUTE ON FUNCTION game_npc_cash_complete(UUID) TO oteryn_game_runtime;

-- SRV7_SOURCE_COMPOSITION: npc-source-greet.sql
-- One genuine native conversation-owner greeting, never a text-derived claim.
CREATE TABLE game_npc_source_greet_occurrences(
 game_session_id UUID NOT NULL,connection_generation NUMERIC(20,0) NOT NULL,
 conversation_generation NUMERIC(20,0) NOT NULL CHECK(conversation_generation>=1),
 npc_identity BYTEA NOT NULL CHECK(octet_length(npc_identity)=16),
 npc_generation NUMERIC(20,0) NOT NULL CHECK(npc_generation>=1),source_key TEXT NOT NULL,
 parent_transaction_id UUID NOT NULL UNIQUE REFERENCES game_npc_cosmetic_receipts(transaction_id),
 actor_identity BYTEA NOT NULL CHECK(octet_length(actor_identity)=16),
 catalogue_revision TEXT NOT NULL CHECK(octet_length(catalogue_revision) BETWEEN 1 AND 256),
 movement_revision NUMERIC(20,0) NOT NULL CHECK(movement_revision>=1),
 created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id(),
 PRIMARY KEY(game_session_id,connection_generation,conversation_generation,npc_identity,npc_generation,source_key)
);
REVOKE ALL ON game_npc_source_greet_occurrences FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
GRANT SELECT ON game_npc_source_greet_occurrences TO oteryn_game_runtime;
CREATE TRIGGER game_npc_source_greet_immutable BEFORE UPDATE OR DELETE ON game_npc_source_greet_occurrences FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_npc_source_greet_no_truncate BEFORE TRUNCATE ON game_npc_source_greet_occurrences FOR EACH STATEMENT EXECUTE FUNCTION game_character_reject_truncate();
CREATE FUNCTION game_npc_source_greet_capture() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_npc_source_context%ROWTYPE;g JSONB;
BEGIN
 IF NEW.program_sha256 IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO c FROM game_npc_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id() AND npc_transaction_id=NEW.transaction_id;
 g:=c.before_state->'greet';
 IF NEW.source_key<>'oteryn:npc-cosmetic/ajax/barbarian-greet' THEN
  IF g IS NOT NULL AND g<>'null'::jsonb THEN RAISE EXCEPTION 'greeting observation cannot authorize a Say source' USING ERRCODE='23514';END IF;
  RETURN NULL;
 END IF;
 IF game_npc_source_parent_current(NEW.transaction_id,NEW.source_key) IS DISTINCT FROM TRUE
  OR c.npc_key IS DISTINCT FROM 'oteryn:npc.ajax' OR jsonb_typeof(g) IS DISTINCT FROM 'object'
  OR g->>'game_session_id' IS DISTINCT FROM c.game_session_id::text
  OR g->>'connection_generation' IS DISTINCT FROM c.connection_generation::text
  OR g->>'command_id' IS DISTINCT FROM c.command_id::text
  OR coalesce(g->>'actor_identity','')!~'^[0-9a-f]{32}$' OR coalesce(g->>'npc_identity','')!~'^[0-9a-f]{32}$'
  OR g->>'actor_identity'=repeat('0',32) OR g->>'npc_identity'=repeat('0',32)
  OR coalesce(g->>'npc_generation','')!~'^[1-9][0-9]{0,19}$'
  OR coalesce(g->>'conversation_generation','')!~'^[1-9][0-9]{0,19}$'
  OR coalesce(g->>'movement_revision','')!~'^[1-9][0-9]{0,19}$'
  OR coalesce(octet_length(g->>'catalogue_revision'),0) NOT BETWEEN 1 AND 256
  OR (g->>'catalogue_revision')~'[[:cntrl:]]' THEN
  RAISE EXCEPTION 'source Greet requires exact sealed current native occurrence' USING ERRCODE='23514';END IF;
 INSERT INTO game_npc_source_greet_occurrences VALUES(c.game_session_id,c.connection_generation,
  (g->>'conversation_generation')::numeric,decode(g->>'npc_identity','hex'),(g->>'npc_generation')::numeric,
  NEW.source_key,NEW.transaction_id,decode(g->>'actor_identity','hex'),g->>'catalogue_revision',
  (g->>'movement_revision')::numeric,pg_current_xact_id());
 RETURN NULL;
END $$;
REVOKE ALL ON FUNCTION game_npc_source_greet_capture() FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
DO $path$ BEGIN EXECUTE format('ALTER FUNCTION game_npc_source_greet_capture() SET search_path=pg_catalog,%I,pg_temp',current_schema());END $path$;
CREATE TRIGGER game_npc_source_greet_capture AFTER INSERT ON game_npc_cosmetic_receipts FOR EACH ROW EXECUTE FUNCTION game_npc_source_greet_capture();

-- SRV7_SOURCE_COMPOSITION: npc-royal-kit-proof.sql
-- Only the old shop-only transaction FK is replaced by the existing strict
-- deferred shop proof OR the closed paid Royal Inbox MINT proof below.
-- Keep item/catalogue FKs and unique mint_transaction_id unchanged.
DO $royal_origin_fk$ DECLARE fk_name TEXT; fk_count INTEGER;BEGIN
 SELECT count(*),min(constraint_row.conname) INTO fk_count,fk_name FROM pg_constraint constraint_row
 WHERE constraint_row.conrelid='game_house_furniture_kit_origins'::regclass
  AND constraint_row.contype='f' AND constraint_row.confrelid='game_npc_trades'::regclass
  AND constraint_row.conkey=ARRAY[(SELECT attnum FROM pg_attribute WHERE attrelid=constraint_row.conrelid AND attname='mint_transaction_id')]::smallint[];
 IF fk_count<>1 THEN RAISE EXCEPTION 'expected exactly one legacy shop-only kit origin FK';END IF;
 EXECUTE format('ALTER TABLE game_house_furniture_kit_origins DROP CONSTRAINT %I',fk_name);
END $royal_origin_fk$;
-- Royal base purchase is a distinct source class, never an NPCtrade claim.
ALTER TABLE game_house_furniture_kit_catalogue DROP CONSTRAINT game_house_furniture_kit_catalogue_source_row_check,
 ADD CONSTRAINT game_house_furniture_kit_catalogue_source_row_check
 CHECK(source_row BETWEEN 0 AND 1674 OR source_row BETWEEN 1000000 AND 1000904 OR source_row BETWEEN 2000000 AND 2000002);
INSERT INTO game_house_furniture_kit_catalogue(source_row,target_key,price_gold,source_line,npc_key) VALUES
(2000000,'oteryn:item.tibia.i31510',500000000,137,'oteryn:npc.king_tibianus'),
(2000001,'oteryn:item.tibia.i31510',500000000,84,'oteryn:npc.queen_eloise'),
(2000002,'oteryn:item.tibia.i31510',500000000,89,'oteryn:npc.emperor_kruzak');
CREATE TABLE game_npc_royal_kit_mints(
 parent_transaction_id UUID PRIMARY KEY REFERENCES game_npc_cosmetic_receipts(transaction_id),
 fee_transaction_id UUID NOT NULL UNIQUE REFERENCES game_item_fee_burns(transaction_id),
 mint_transaction_id UUID NOT NULL UNIQUE REFERENCES game_reward_claim_inbox_mint_receipts(transaction_id),
 item_instance_id UUID NOT NULL UNIQUE REFERENCES game_item_instances(item_instance_id),
 source_row INTEGER NOT NULL CHECK(source_row BETWEEN 2000000 AND 2000002),
 source_key TEXT NOT NULL,program_sha256 BYTEA NOT NULL CHECK(octet_length(program_sha256)=32),
 plan_sha256 BYTEA NOT NULL CHECK(octet_length(plan_sha256)=32),
 target_key TEXT NOT NULL CHECK(target_key='oteryn:item.tibia.i31510'),
 created_xact_id xid8 NOT NULL DEFAULT pg_current_xact_id());
REVOKE ALL ON game_npc_royal_kit_mints FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
GRANT SELECT,INSERT ON game_npc_royal_kit_mints TO oteryn_game_runtime;
CREATE TRIGGER game_npc_royal_kit_stamp BEFORE INSERT ON game_npc_royal_kit_mints FOR EACH ROW EXECUTE FUNCTION game_item_stamp_created_xact_id();
CREATE TRIGGER game_npc_royal_kit_immutable BEFORE UPDATE OR DELETE ON game_npc_royal_kit_mints FOR EACH ROW EXECUTE FUNCTION game_item_immutable();
CREATE TRIGGER game_npc_royal_kit_no_truncate BEFORE TRUNCATE ON game_npc_royal_kit_mints FOR EACH STATEMENT EXECUTE FUNCTION game_item_reject_truncate();
-- Existing accepted R1 CharacterInbox delivery translation; source free-slot20
-- remains a separate admission rule, not the mint-output batch limit.
CREATE FUNCTION game_npc_royal_inbox_admit(p_parent UUID,p_source TEXT) RETURNS BOOLEAN
LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE royal_character UUID; royal_count BIGINT; BEGIN
 IF p_source NOT IN('oteryn:npc-cosmetic/king_tibianus/golden-buy-armor','oteryn:npc-cosmetic/queen_eloise/golden-buy-armor','oteryn:npc-cosmetic/emperor_kruzak/golden-buy-armor')
  OR NOT EXISTS(SELECT 1 FROM game_npc_source_context royal_context,
   LATERAL jsonb_array_elements(royal_context.expected_plan->'effects') royal_effect
   WHERE royal_context.npc_transaction_id=p_parent AND royal_context.source_key=p_source
    AND royal_effect.value->>'kind'='mint_store_decoration_kit' AND royal_effect.value->>'source_target'='31510'
    AND royal_effect.value->>'requires_free_store_inbox_entry'='true'
    AND game_npc_source_effect_current(p_parent,p_source,royal_effect.value)) THEN RETURN FALSE; END IF;
 SELECT character_id INTO STRICT royal_character FROM game_npc_source_context WHERE npc_transaction_id=p_parent
  AND backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 INSERT INTO game_character_inbox_counters(character_id) VALUES(royal_character) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM game_character_inbox_counters WHERE character_id=royal_character FOR UPDATE;
 SELECT count(*) INTO royal_count FROM game_item_character_inbox_locations WHERE character_id=royal_character;
 RETURN royal_count<20;
END $$;
CREATE FUNCTION game_npc_royal_kit_proven(p_parent UUID,p_item UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT EXISTS(SELECT 1 FROM game_npc_royal_kit_mints royal_child
 JOIN game_npc_cosmetic_receipts royal_parent ON royal_parent.transaction_id=royal_child.parent_transaction_id
 JOIN game_item_fee_burns royal_fee ON royal_fee.transaction_id=royal_child.fee_transaction_id
 JOIN game_house_furniture_kit_catalogue royal_catalogue ON royal_catalogue.source_row=royal_child.source_row
 JOIN game_reward_claim_inbox_mint_receipts royal_mint ON royal_mint.transaction_id=royal_child.mint_transaction_id
 JOIN game_reward_claim_inbox_mint_reservations royal_reservation ON royal_reservation.transaction_id=royal_mint.transaction_id
 JOIN game_reward_claim_inbox_mint_lines royal_line ON royal_line.transaction_id=royal_mint.transaction_id
 JOIN game_item_instances royal_item ON royal_item.item_instance_id=royal_child.item_instance_id
 JOIN game_item_character_inbox_locations royal_inbox ON royal_inbox.item_instance_id=royal_item.item_instance_id
 JOIN game_house_furniture_kit_origins royal_origin ON royal_origin.item_instance_id=royal_item.item_instance_id
 WHERE royal_child.parent_transaction_id=p_parent AND royal_child.item_instance_id=p_item
  AND game_npc_source_parent_current(royal_parent.transaction_id,royal_parent.source_key)
  AND EXISTS(SELECT 1 FROM game_npc_source_context royal_context,
    LATERAL jsonb_array_elements(royal_context.expected_plan->'effects') royal_effect
    WHERE royal_context.npc_transaction_id=royal_parent.transaction_id
     AND royal_effect.value->>'kind'='mint_store_decoration_kit'
     AND royal_effect.value->>'source_target'='31510'
     AND royal_effect.value->>'requires_free_store_inbox_entry'='true'
     AND game_npc_source_effect_current(royal_parent.transaction_id,royal_parent.source_key,royal_effect.value))
  AND royal_parent.source_key=royal_child.source_key
  AND royal_parent.source_key='oteryn:npc-cosmetic/'||substring(royal_catalogue.npc_key FROM 12)||'/golden-buy-armor'
  AND royal_parent.npc_key=royal_catalogue.npc_key AND royal_parent.fee_transaction_id=royal_fee.transaction_id
  AND royal_parent.program_sha256=royal_child.program_sha256 AND royal_parent.plan_sha256=royal_child.plan_sha256
  AND royal_fee.character_id=royal_parent.character_id AND royal_fee.fee_gold_units=500000000
  AND royal_child.created_xact_id=pg_current_xact_id() AND royal_fee.created_xact_id=pg_current_xact_id()
  AND royal_mint.created_xact_id=pg_current_xact_id() AND royal_line.created_xact_id=pg_current_xact_id()
  AND royal_mint.game_session_id=royal_parent.game_session_id AND royal_mint.command_id=royal_parent.command_id
  AND royal_mint.character_id=royal_parent.character_id AND royal_mint.item_count=1
  AND convert_from(royal_reservation.mint_spec,'UTF8')::jsonb->'claim'=jsonb_build_object('family','NpcCosmetic','key',royal_child.source_key,'revision',encode(royal_child.program_sha256,'hex'))
  AND royal_line.output_index=1 AND royal_line.source_line=0 AND royal_line.quantity=1
  AND royal_line.item_instance_id=royal_item.item_instance_id
  AND royal_line.definition_family='Item' AND royal_line.definition_production_key='oteryn:item.tibia.i23398'
  AND royal_line.definition_revision_ref=royal_origin.target_revision
  AND royal_item.definition_family='Item' AND royal_item.definition_production_key='oteryn:item.tibia.i23398'
  AND royal_item.definition_revision_ref=royal_line.definition_revision_ref AND royal_item.quantity=1
  AND royal_item.state_revision=1 AND royal_item.lifecycle=1 AND royal_item.last_transaction_id IS NULL
  AND royal_item.minted_transaction_id=royal_mint.transaction_id AND royal_item.world_id=royal_mint.world_id
  AND (SELECT count(*) FROM game_item_character_inbox_locations royal_slot WHERE royal_slot.character_id=royal_parent.character_id)<=20
  AND royal_inbox.character_id=royal_parent.character_id AND royal_inbox.world_id=royal_mint.world_id
  AND royal_origin.mint_transaction_id=royal_mint.transaction_id AND royal_origin.source_row=royal_child.source_row
  AND royal_origin.target_key=royal_child.target_key AND royal_origin.created_xact_id=pg_current_xact_id())
$$;
CREATE FUNCTION game_npc_royal_kit_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN
 IF NOT game_npc_royal_kit_proven(NEW.parent_transaction_id,NEW.item_instance_id) THEN
  RAISE EXCEPTION 'royal display kit requires its exact paid NPC source and native Inbox mint' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_npc_royal_kit_complete AFTER INSERT ON game_npc_royal_kit_mints
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_royal_kit_complete();
CREATE FUNCTION game_npc_royal_kit_parent_complete() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN
 IF NEW.source_key IN('oteryn:npc-cosmetic/king_tibianus/golden-buy-armor','oteryn:npc-cosmetic/queen_eloise/golden-buy-armor','oteryn:npc-cosmetic/emperor_kruzak/golden-buy-armor')
  AND NOT EXISTS(SELECT 1 FROM game_npc_royal_kit_mints royal_child WHERE royal_child.parent_transaction_id=NEW.transaction_id
   AND game_npc_royal_kit_proven(NEW.transaction_id,royal_child.item_instance_id)) THEN
  RAISE EXCEPTION 'royal base purchase requires its native Inbox display kit' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_npc_royal_kit_parent_complete AFTER INSERT ON game_npc_cosmetic_receipts
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_royal_kit_parent_complete();
-- Existing shop-origin proof remains unchanged for every other source class.
DO $migration$ DECLARE body TEXT; needle TEXT; BEGIN
 body:=pg_get_functiondef('game_house_furniture_kit_origin_proven()'::regprocedure);needle:=E'BEGIN\n';
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'missing original kit proof'; END IF;
 EXECUTE replace(body,needle,needle||$royal$
 IF NEW.source_row BETWEEN 2000000 AND 2000002 THEN
  IF NOT EXISTS(SELECT 1 FROM game_npc_royal_kit_mints royal_child WHERE royal_child.item_instance_id=NEW.item_instance_id
   AND game_npc_royal_kit_proven(royal_child.parent_transaction_id,NEW.item_instance_id)) THEN
   RAISE EXCEPTION 'royal origin requires its same-transaction paid NPC source' USING ERRCODE='23514'; END IF;
  RETURN NULL;
 END IF;
$royal$);
END $migration$;
DO $$ BEGIN
 EXECUTE format('ALTER FUNCTION game_npc_royal_inbox_admit(UUID,TEXT) SET search_path=pg_catalog,%I,pg_temp',current_schema());
 EXECUTE format('ALTER FUNCTION game_npc_royal_kit_proven(UUID,UUID) SET search_path=pg_catalog,%I,pg_temp',current_schema());
 EXECUTE format('ALTER FUNCTION game_npc_royal_kit_parent_complete() SET search_path=pg_catalog,%I,pg_temp',current_schema());
 EXECUTE format('ALTER FUNCTION game_npc_royal_kit_complete() SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $$;
REVOKE ALL ON FUNCTION game_npc_royal_kit_proven(UUID,UUID),game_npc_royal_kit_complete(),game_npc_royal_kit_parent_complete() FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;

REVOKE ALL ON FUNCTION game_npc_royal_inbox_admit(UUID,TEXT) FROM PUBLIC,oteryn_game_control;
GRANT EXECUTE ON FUNCTION game_npc_royal_inbox_admit(UUID,TEXT) TO oteryn_game_runtime;

-- SRV7_SOURCE_COMPOSITION: lynda-wedding.sql
-- Closed Lynda outfit acquisition, Crystal201189f lynda.lua166-210/244-260.
CREATE TABLE game_lynda_wedding_receipts(
 transaction_id UUID PRIMARY KEY,game_session_id UUID NOT NULL REFERENCES game_durability_reconnect_sessions,
 command_id NUMERIC(20,0)NOT NULL,character_id UUID NOT NULL REFERENCES game_character_roots,
 partner_character_id UUID NOT NULL REFERENCES game_character_roots,world_id UUID NOT NULL,
 operation TEXT NOT NULL CHECK(operation IN('propose','accept','cancel')),
 request_binding BYTEA NOT NULL CHECK(octet_length(request_binding)=32),cost_transaction_id UUID REFERENCES game_srv7_item_costs,
 original_revision NUMERIC(20,0) NOT NULL,committed_revision NUMERIC(20,0)NOT NULL CHECK(committed_revision=original_revision+1),
 level_before BIGINT NOT NULL,level_after BIGINT NOT NULL CHECK(level_after=level_before),
 experience_before BIGINT NOT NULL,experience_after BIGINT NOT NULL CHECK(experience_after=experience_before),
 profile_revision TEXT NOT NULL,ruleset_revision TEXT NOT NULL,content_revision TEXT NOT NULL,
 simulation_revision TEXT NOT NULL,evidence_revision TEXT NOT NULL,declaration_revision TEXT NOT NULL,
 policy_revision TEXT NOT NULL,reward_revision TEXT NOT NULL,UNIQUE(character_id,committed_revision),
 prior_proposal_id UUID REFERENCES game_lynda_wedding_receipts,actor_account UUID NOT NULL,partner_account UUID NOT NULL,
 source_sha256 BYTEA NOT NULL CHECK(source_sha256=decode('c02b3072ac121d52ccd9e4e6d911942633bddbd9489c9325f66e375e8f5207a9','hex')),
 outcome JSONB NOT NULL CHECK(jsonb_typeof(outcome)='object'AND octet_length(outcome::text)<=4096),created_xact_id XID8 NOT NULL,
 UNIQUE(game_session_id,command_id),CHECK(character_id<>partner_character_id),CHECK((operation='cancel')=(cost_transaction_id IS NULL)));
CREATE INDEX game_lynda_wedding_actor ON game_lynda_wedding_receipts(character_id);
CREATE INDEX game_lynda_wedding_partner ON game_lynda_wedding_receipts(partner_character_id);
CREATE INDEX game_lynda_wedding_cost ON game_lynda_wedding_receipts(cost_transaction_id);
CREATE INDEX game_lynda_wedding_prior ON game_lynda_wedding_receipts(prior_proposal_id);
CREATE TABLE game_lynda_wedding_states(character_id UUID PRIMARY KEY REFERENCES game_character_roots,
 status SMALLINT NOT NULL CHECK(status IN(0,1,2,3)),partner_character_id UUID REFERENCES game_character_roots,
 last_transaction_id UUID NOT NULL REFERENCES game_lynda_wedding_receipts,
 CHECK((status=0)=(partner_character_id IS NULL)),CHECK(character_id IS DISTINCT FROM partner_character_id));
CREATE INDEX game_lynda_wedding_state_partner ON game_lynda_wedding_states(partner_character_id);
CREATE INDEX game_lynda_wedding_state_receipt ON game_lynda_wedding_states(last_transaction_id);
CREATE TABLE game_lynda_wedding_context(backend_pid INTEGER PRIMARY KEY,transaction_xid XID8 NOT NULL,
 node_id UUID NOT NULL,registration NUMERIC NOT NULL,world_id UUID NOT NULL,channel_id UUID NOT NULL,
 scope_generation NUMERIC NOT NULL,character_id UUID NOT NULL,partner_id UUID NOT NULL,
 actor_account UUID NOT NULL,partner_account UUID NOT NULL,game_session UUID NOT NULL,command_id NUMERIC NOT NULL,
 connection NUMERIC NOT NULL,lease NUMERIC NOT NULL,original_revision NUMERIC NOT NULL,parent UUID NOT NULL,
 operation TEXT NOT NULL,request_binding BYTEA NOT NULL,prior_proposal UUID,cost_transaction UUID,progression_before JSONB NOT NULL);
REVOKE ALL ON game_lynda_wedding_context FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;
CREATE FUNCTION game_lynda_wedding_current()RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT game_node_registration_history_valid()AND game_runtime_scope_assignment_history_valid()AND EXISTS(
 SELECT 1 FROM game_lynda_wedding_context c JOIN game_durability_reconnect_sessions s ON s.game_session_id=c.game_session
 JOIN game_character_roots r ON r.character_id=c.character_id JOIN game_character_roots p ON p.character_id=c.partner_id
 JOIN game_durability_admission_character_guards cg ON cg.character_id=c.character_id
 JOIN game_durability_admission_account_guards ag ON ag.account_id=c.actor_account
 JOIN game_runtime_scope_assignments a ON a.scope_key='\x01'::bytea||uuid_send(c.world_id)||uuid_send(c.channel_id)
 JOIN game_durability_admission_runtime_guards rg ON rg.scope_key=a.scope_key
 JOIN game_node_registrations n ON n.node_id=c.node_id AND n.registration_revision=c.registration
 WHERE c.backend_pid=pg_backend_pid()AND c.transaction_xid=pg_current_xact_id()AND n.state=1
 AND NOT EXISTS(SELECT 1 FROM game_node_registration_endings e WHERE e.node_id=c.node_id)
 AND a.state=1 AND a.scope_kind=1 AND a.ownership_generation=c.scope_generation AND a.holder_node_id=c.node_id AND a.holder_registration_revision=c.registration
 AND r.lifecycle=1 AND p.lifecycle=1 AND r.world_id=c.world_id AND p.world_id=c.world_id
 AND r.account_id=c.actor_account AND p.account_id=c.partner_account
 AND s.character_id=c.character_id AND s.account_id=c.actor_account AND s.world_id=c.world_id AND s.session_state=2 AND s.current_transport_ref IS NOT NULL
 AND s.runtime_scope_kind=1 AND s.runtime_scope_world_id=c.world_id AND s.runtime_scope_channel_id=c.channel_id
 AND s.current_generation=c.connection AND s.character_lease_generation=c.lease AND s.scope_ownership_generation=c.scope_generation
 AND cg.eligible AND cg.account_id=c.actor_account AND cg.world_id=c.world_id AND cg.lease_generation=c.lease AND cg.holder_game_session_id=c.game_session
 AND ag.presence_character_id=c.character_id AND ag.holder_game_session_id=c.game_session AND rg.ready AND rg.ownership_generation=c.scope_generation)
$$;
CREATE FUNCTION game_lynda_wedding_arm(p_node UUID,p_registration NUMERIC,p_secret BYTEA,p JSONB)RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE actor game_character_roots%ROWTYPE;partner game_character_roots%ROWTYPE;a game_lynda_wedding_states%ROWTYPE;b game_lynda_wedding_states%ROWTYPE;
 proposed UUID;operation TEXT;progress_before JSONB;BEGIN
 IF game_node_prove_current_incarnation(p_node,p_registration,p_secret)IS DISTINCT FROM TRUE
 OR jsonb_typeof(p)IS DISTINCT FROM'object'OR(p->>'actor')::uuid=(p->>'partner')::uuid THEN
 RAISE EXCEPTION 'Lynda requires current Node and two real Characters' USING ERRCODE='23514';END IF;
 PERFORM 1 FROM game_character_roots WHERE character_id IN((p->>'actor')::uuid,(p->>'partner')::uuid)ORDER BY character_id FOR UPDATE;
 SELECT*INTO actor FROM game_character_roots WHERE character_id=(p->>'actor')::uuid;
 SELECT*INTO partner FROM game_character_roots WHERE character_id=(p->>'partner')::uuid;
 SELECT to_jsonb(progression) INTO STRICT progress_before FROM game_character_progression_state progression WHERE progression.character_id=actor.character_id FOR UPDATE;
 SELECT*INTO a FROM game_lynda_wedding_states WHERE character_id=actor.character_id FOR UPDATE;
 SELECT*INTO b FROM game_lynda_wedding_states WHERE character_id=partner.character_id FOR UPDATE;
 IF actor.character_id IS NULL OR partner.character_id IS NULL OR actor.character_revision IS DISTINCT FROM(p->>'original_revision')::numeric THEN
 RAISE EXCEPTION 'Lynda pair/revision changed' USING ERRCODE='23514';END IF;
 IF p->>'operation'='cancel' THEN
  IF a.status IS DISTINCT FROM 1 OR a.partner_character_id IS DISTINCT FROM partner.character_id THEN RAISE EXCEPTION 'no actual pending proposal to cancel' USING ERRCODE='23514';END IF;
  operation:='cancel';proposed:=a.last_transaction_id;
 ELSE
  IF coalesce(a.status,0)IN(1,2)OR coalesce(b.status,0)IN(2,3)THEN RAISE EXCEPTION 'Lynda participant is already committed' USING ERRCODE='23514';END IF;
  IF b.status=1 THEN
   IF b.partner_character_id IS DISTINCT FROM actor.character_id THEN RAISE EXCEPTION 'candidate proposed elsewhere' USING ERRCODE='23514';END IF;
   operation:='accept';proposed:=b.last_transaction_id;
  ELSE operation:='propose';END IF;
 END IF;
 IF operation IS DISTINCT FROM p->>'operation' OR octet_length(decode(p->>'binding','hex'))IS DISTINCT FROM 32
 OR EXISTS(SELECT 1 FROM game_lynda_wedding_context WHERE backend_pid=pg_backend_pid()AND transaction_xid=pg_current_xact_id())THEN
 RAISE EXCEPTION 'Lynda exact pair observation can only be sealed once' USING ERRCODE='23514';END IF;
 DELETE FROM game_lynda_wedding_context c WHERE c.backend_pid=pg_backend_pid()OR NOT EXISTS(SELECT 1 FROM pg_stat_activity s WHERE s.pid=c.backend_pid);
 INSERT INTO game_lynda_wedding_context VALUES(pg_backend_pid(),pg_current_xact_id(),p_node,p_registration,(p->>'world')::uuid,(p->>'channel')::uuid,
 (p->>'scope_generation')::numeric,actor.character_id,partner.character_id,actor.account_id,partner.account_id,(p->>'game_session')::uuid,(p->>'command')::numeric,
 (p->>'connection')::numeric,(p->>'lease')::numeric,actor.character_revision,(p->>'parent')::uuid,operation,decode(p->>'binding','hex'),proposed,NULL,progress_before);
 IF game_lynda_wedding_current()IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'Lynda stale current Character/session/scope' USING ERRCODE='23514';END IF;
END $$;
CREATE FUNCTION game_lynda_wedding_cost_admit()RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_lynda_wedding_context%ROWTYPE;BEGIN
 IF NEW.cause_kind<>'lynda_wedding'THEN RETURN NEW;END IF;
 SELECT*INTO c FROM game_lynda_wedding_context WHERE backend_pid=pg_backend_pid()AND transaction_xid=pg_current_xact_id();
 IF game_lynda_wedding_current()IS DISTINCT FROM TRUE OR c.operation NOT IN('propose','accept')OR c.cost_transaction IS NOT NULL
 OR(NEW.character_id,NEW.world_id,NEW.channel_id,NEW.game_session_id,NEW.command_id,NEW.source_key)IS DISTINCT FROM(c.character_id,c.world_id,c.channel_id,c.game_session,c.command_id,'oteryn:lynda.wedding.materials'::text)
 OR NEW.transaction_id=c.parent OR NEW.requirements IS DISTINCT FROM '[{"family":"Item","key":"oteryn:item.tibia.i3004","revision":"definition-r1","count":1},{"family":"Item","key":"oteryn:item.tibia.i9586","revision":"definition-r1","count":1}]'::jsonb THEN
 RAISE EXCEPTION 'Lynda consumes exactly own wedding ring and outfit box' USING ERRCODE='23514';END IF;
 UPDATE game_lynda_wedding_context SET cost_transaction=NEW.transaction_id WHERE backend_pid=pg_backend_pid();RETURN NEW;
END $$;
CREATE TRIGGER game_lynda_wedding_cost_admit BEFORE INSERT ON game_srv7_item_costs FOR EACH ROW EXECUTE FUNCTION game_lynda_wedding_cost_admit();
CREATE FUNCTION game_lynda_wedding_receipt_admit()RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_lynda_wedding_context%ROWTYPE;BEGIN
 SELECT*INTO c FROM game_lynda_wedding_context WHERE backend_pid=pg_backend_pid()AND transaction_xid=pg_current_xact_id();
 IF game_lynda_wedding_current()IS DISTINCT FROM TRUE OR(NEW.transaction_id,NEW.game_session_id,NEW.command_id,NEW.character_id,NEW.partner_character_id,NEW.world_id,NEW.operation,NEW.request_binding,NEW.cost_transaction_id,NEW.original_revision,NEW.committed_revision)
 IS DISTINCT FROM(c.parent,c.game_session,c.command_id,c.character_id,c.partner_id,c.world_id,c.operation,c.request_binding,c.cost_transaction,c.original_revision,c.original_revision+1)THEN
 RAISE EXCEPTION 'Lynda receipt lacks exact sealed reciprocal source' USING ERRCODE='23514';END IF;
 IF (c.progression_before->>'character_revision')::numeric IS DISTINCT FROM c.original_revision
 OR NEW.level_before IS DISTINCT FROM (c.progression_before->>'level')::bigint
 OR NEW.experience_before IS DISTINCT FROM (c.progression_before->>'total_experience')::bigint
 OR NEW.profile_revision IS DISTINCT FROM c.progression_before->>'profile_revision'
 OR NEW.ruleset_revision IS DISTINCT FROM c.progression_before->>'ruleset_revision'
 OR NEW.content_revision IS DISTINCT FROM c.progression_before->>'content_revision'
 OR NEW.simulation_revision IS DISTINCT FROM c.progression_before->>'simulation_revision'
 OR NEW.evidence_revision IS DISTINCT FROM c.progression_before->>'evidence_revision'
 OR NEW.declaration_revision IS DISTINCT FROM c.progression_before->>'declaration_revision'
 OR NEW.policy_revision IS DISTINCT FROM c.progression_before->>'policy_revision'
 OR NEW.reward_revision IS DISTINCT FROM c.progression_before->>'reward_revision' THEN RAISE EXCEPTION 'Wedding receipt changed its locked native progression stamps' USING ERRCODE='23514';END IF;
 NEW.actor_account:=c.actor_account;NEW.partner_account:=c.partner_account;NEW.prior_proposal_id:=c.prior_proposal;
 NEW.source_sha256:=decode('c02b3072ac121d52ccd9e4e6d911942633bddbd9489c9325f66e375e8f5207a9','hex');NEW.created_xact_id:=pg_current_xact_id();RETURN NEW;
END $$;
CREATE TRIGGER game_lynda_wedding_receipt_admit BEFORE INSERT ON game_lynda_wedding_receipts FOR EACH ROW EXECUTE FUNCTION game_lynda_wedding_receipt_admit();
CREATE TRIGGER game_lynda_wedding_receipt_immutable BEFORE UPDATE OR DELETE ON game_lynda_wedding_receipts FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_lynda_wedding_receipt_no_truncate BEFORE TRUNCATE ON game_lynda_wedding_receipts FOR EACH STATEMENT EXECUTE FUNCTION game_world_reset_history_immutable();
CREATE FUNCTION game_lynda_wedding_state_admit()RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_lynda_wedding_context%ROWTYPE;BEGIN
 SELECT*INTO c FROM game_lynda_wedding_context WHERE backend_pid=pg_backend_pid()AND transaction_xid=pg_current_xact_id();
 IF TG_OP='DELETE'OR game_lynda_wedding_current()IS DISTINCT FROM TRUE OR NEW.last_transaction_id IS DISTINCT FROM c.parent
 OR NOT EXISTS(SELECT 1 FROM game_lynda_wedding_receipts r WHERE r.transaction_id=c.parent AND r.created_xact_id=pg_current_xact_id())THEN
 RAISE EXCEPTION 'Lynda state requires actual current source receipt' USING ERRCODE='23514';END IF;
 IF NEW.character_id=c.character_id AND((c.operation='propose'AND NEW.status=1 AND NEW.partner_character_id=c.partner_id)
 OR(c.operation='accept'AND NEW.status=3 AND NEW.partner_character_id=c.partner_id)OR(c.operation='cancel'AND NEW.status=0 AND NEW.partner_character_id IS NULL))THEN RETURN NEW;END IF;
 IF c.operation='accept'AND NEW.character_id=c.partner_id AND NEW.status=3 AND NEW.partner_character_id=c.character_id AND OLD.status=1 AND OLD.partner_character_id=c.character_id THEN RETURN NEW;END IF;
 RAISE EXCEPTION 'Lynda source cannot change another pair/phase' USING ERRCODE='23514';
END $$;
CREATE TRIGGER game_lynda_wedding_state_admit BEFORE INSERT OR UPDATE OR DELETE ON game_lynda_wedding_states FOR EACH ROW EXECUTE FUNCTION game_lynda_wedding_state_admit();
CREATE TRIGGER game_lynda_wedding_state_no_truncate BEFORE TRUNCATE ON game_lynda_wedding_states FOR EACH STATEMENT EXECUTE FUNCTION game_world_reset_history_immutable();
CREATE FUNCTION game_lynda_wedding_complete()RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c game_lynda_wedding_context%ROWTYPE;BEGIN
 SELECT*INTO c FROM game_lynda_wedding_context WHERE backend_pid=pg_backend_pid()AND transaction_xid=pg_current_xact_id();
 IF game_lynda_wedding_current()IS DISTINCT FROM TRUE OR NEW.created_xact_id<>pg_current_xact_id()
 OR NOT EXISTS(SELECT 1 FROM game_character_roots r WHERE r.character_id=NEW.character_id AND r.character_revision=NEW.committed_revision AND r.xmin=pg_current_xact_id()::xid)
 OR NOT EXISTS(SELECT 1 FROM game_lynda_wedding_states s WHERE s.character_id=NEW.character_id AND s.last_transaction_id=NEW.transaction_id AND s.status=CASE NEW.operation WHEN'propose'THEN 1 WHEN'accept'THEN 3 ELSE 0 END)
 OR(NEW.operation<>'cancel'AND NOT EXISTS(SELECT 1 FROM game_srv7_item_costs k WHERE k.transaction_id=NEW.cost_transaction_id AND k.cause_kind='lynda_wedding'AND k.created_xact_id=pg_current_xact_id()AND k.character_id=NEW.character_id AND k.game_session_id=NEW.game_session_id AND k.command_id=NEW.command_id))THEN
 RAISE EXCEPTION 'Lynda source lacks one atomic cost/state/root result' USING ERRCODE='23514';END IF;
 IF NEW.operation IN('accept','cancel')AND NOT EXISTS(SELECT 1 FROM game_lynda_wedding_receipts p WHERE p.transaction_id=NEW.prior_proposal_id AND p.operation='propose'AND
 ((NEW.operation='accept'AND p.character_id=NEW.partner_character_id AND p.partner_character_id=NEW.character_id)OR(NEW.operation='cancel'AND p.character_id=NEW.character_id AND p.partner_character_id=NEW.partner_character_id)))THEN
 RAISE EXCEPTION 'Lynda requires actual earlier reciprocal/pending proposal' USING ERRCODE='23514';END IF;
 IF NEW.operation='accept'THEN
  IF NOT EXISTS(SELECT 1 FROM game_lynda_wedding_states s WHERE s.character_id=NEW.partner_character_id AND s.partner_character_id=NEW.character_id AND s.status=3 AND s.last_transaction_id=NEW.transaction_id)
  OR EXISTS(SELECT 1 FROM unnest(ARRAY[NEW.actor_account,NEW.partner_account])AS recipient(account_id) WHERE NOT EXISTS(SELECT 1 FROM game_account_appearance_unlocks u WHERE u.account_id=recipient.account_id AND u.unlock_key='oteryn:appearance-grant/npc/lynda/newly_wed/base'))THEN
  RAISE EXCEPTION 'Lynda acceptance must retain both actual Account outfits' USING ERRCODE='23514';END IF;
 END IF;
 IF NEW.operation='cancel'THEN
  IF NOT EXISTS(SELECT 1 FROM game_reward_claim_inbox_mint_receipts m WHERE m.transaction_id=NEW.transaction_id AND m.character_id=NEW.character_id AND m.game_session_id=NEW.game_session_id AND m.command_id=NEW.command_id AND m.item_count=2 AND m.source_binding=NEW.request_binding AND m.created_xact_id=pg_current_xact_id())
  OR(SELECT count(*)FROM game_reward_claim_inbox_mint_lines l JOIN game_item_instances i USING(item_instance_id)WHERE l.transaction_id=NEW.transaction_id AND l.created_xact_id=pg_current_xact_id()AND i.minted_transaction_id=NEW.transaction_id AND i.quantity=1 AND i.lifecycle=1 AND i.definition_family='Item'AND i.definition_production_key IN('oteryn:item.tibia.i3004','oteryn:item.tibia.i9586'))<>2
  OR(SELECT count(DISTINCT i.definition_production_key)FROM game_reward_claim_inbox_mint_lines l JOIN game_item_instances i USING(item_instance_id)WHERE l.transaction_id=NEW.transaction_id)<>2 THEN
  RAISE EXCEPTION 'Lynda pending cancellation requires exact one ring and box refund' USING ERRCODE='23514';END IF;
 END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_lynda_wedding_complete AFTER INSERT ON game_lynda_wedding_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_lynda_wedding_complete();
-- Exact reciprocal child of the general NPC entitlement namespace. A source_kind
-- label or a canonical key alone cannot confer any authority.
CREATE FUNCTION game_lynda_wedding_grant_current(proof JSONB)RETURNS BOOLEAN
LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT game_lynda_wedding_current() AND
 proof->>'unlock_key'='oteryn:appearance-grant/npc/lynda/newly_wed/base'
 AND proof->>'source_kind'='npc_wedding'
 AND proof->>'content_revision'='crystal-201189f-npc-cosmetics-v1'
 AND EXISTS(SELECT 1 FROM game_lynda_wedding_receipts r
  WHERE r.operation='accept' AND r.created_xact_id=pg_current_xact_id()
  AND (proof->>'source_event_id')::bytea=uuid_send(r.transaction_id)||uuid_send((proof->>'granting_character_id')::uuid)
  AND (((proof->>'granting_character_id')::uuid=r.character_id AND (proof->>'account_id')::uuid=r.actor_account)
   OR ((proof->>'granting_character_id')::uuid=r.partner_character_id AND (proof->>'account_id')::uuid=r.partner_account)))
$$;
DO $namespace_child$
DECLARE body TEXT;needle TEXT;
BEGIN
 body:=pg_get_functiondef('game_npc_grant_namespace_proven()'::regprocedure);
 needle:=' IF npc_namespace_proof IS NULL OR npc_namespace_proof->>''source_kind'' IS DISTINCT FROM ''npc''';
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'Wedding NPC namespace proof boundary changed';END IF;
 EXECUTE replace(body,needle,$child$
 IF NEW.unlock_key='oteryn:appearance-grant/npc/lynda/newly_wed/base' THEN
  IF game_lynda_wedding_grant_current(npc_namespace_proof) IS DISTINCT FROM TRUE THEN
   RAISE EXCEPTION 'Wedding grant requires its actual current reciprocal source child' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
 END IF;
 IF npc_namespace_proof IS NULL OR npc_namespace_proof->>'source_kind' IS DISTINCT FROM 'npc'$child$);
END $namespace_child$;
CREATE FUNCTION game_lynda_wedding_grant_guard()RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE entry game_account_appearance_unlock_receipts%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='game_account_appearance_unlocks'THEN
  SELECT*INTO entry FROM game_account_appearance_unlock_receipts WHERE grant_occurrence_id=NEW.grant_occurrence_id;
 ELSE entry:=NEW;END IF;
 IF entry.unlock_key='oteryn:appearance-grant/npc/lynda/newly_wed/base'OR entry.source_kind='npc_wedding'THEN
  IF entry.source_kind IS DISTINCT FROM'npc_wedding'OR entry.unlock_key IS DISTINCT FROM'oteryn:appearance-grant/npc/lynda/newly_wed/base'
  OR entry.content_revision IS DISTINCT FROM'crystal-201189f-npc-cosmetics-v1'
  OR NOT EXISTS(SELECT 1 FROM game_lynda_wedding_receipts r WHERE r.operation='accept'AND r.created_xact_id=pg_current_xact_id()
   AND entry.source_event_id=uuid_send(r.transaction_id)||uuid_send(entry.granting_character_id)
   AND((entry.granting_character_id=r.character_id AND entry.account_id=r.actor_account)OR(entry.granting_character_id=r.partner_character_id AND entry.account_id=r.partner_account)))THEN
   RAISE EXCEPTION 'Lynda outfit grant lacks actual reciprocal pair receipt' USING ERRCODE='23514';
  END IF;
 END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_lynda_wedding_grant_guard AFTER INSERT ON game_account_appearance_unlock_receipts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_lynda_wedding_grant_guard();
CREATE CONSTRAINT TRIGGER game_lynda_wedding_fact_guard AFTER INSERT ON game_account_appearance_unlocks DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_lynda_wedding_grant_guard();
-- Add only this source cost kind. All existing physical conservation/audit guards run.
DO $cause_kind$
DECLARE existing_check TEXT;
BEGIN
 SELECT pg_get_expr(c.conbin,c.conrelid) INTO STRICT existing_check
 FROM pg_constraint c WHERE c.conrelid='game_srv7_item_costs'::regclass
 AND c.conname='game_srv7_item_costs_cause_kind_check';
 ALTER TABLE game_srv7_item_costs DROP CONSTRAINT game_srv7_item_costs_cause_kind_check;
 EXECUTE format('ALTER TABLE game_srv7_item_costs ADD CONSTRAINT game_srv7_item_costs_cause_kind_check CHECK ((%s) OR cause_kind = %L)',existing_check,'lynda_wedding');
END $cause_kind$;
DO $cost$DECLARE body TEXT;needle TEXT;BEGIN
 body:=pg_get_functiondef('game_srv7_cost_complete()'::regprocedure);needle:=' IF NEW.cause_kind=''npc_cosmetic'' THEN';
 IF strpos(body,needle)=0 THEN RAISE EXCEPTION 'Lynda cost completion boundary changed';END IF;
 EXECUTE replace(body,needle,$new$
 IF NEW.cause_kind='lynda_wedding'THEN
  PERFORM 1 FROM game_lynda_wedding_receipts r WHERE r.cost_transaction_id=NEW.transaction_id AND r.created_xact_id=pg_current_xact_id()AND r.character_id=NEW.character_id AND r.game_session_id=NEW.game_session_id AND r.command_id=NEW.command_id;
 ELSIF NEW.cause_kind='npc_cosmetic' THEN$new$);
END $cost$;
REVOKE ALL ON game_lynda_wedding_receipts,game_lynda_wedding_states FROM PUBLIC;
GRANT SELECT,INSERT ON game_lynda_wedding_receipts TO oteryn_game_runtime;
GRANT SELECT,INSERT,UPDATE ON game_lynda_wedding_states TO oteryn_game_runtime;

DO $privileges$DECLARE signature TEXT;BEGIN
 FOREACH signature IN ARRAY ARRAY['game_lynda_wedding_current()','game_lynda_wedding_arm(uuid,numeric,bytea,jsonb)','game_lynda_wedding_grant_current(jsonb)']LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',signature);
  EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO oteryn_game_runtime',signature);
 END LOOP;
END $privileges$;

DO $wedding_chain$ DECLARE definition TEXT;BEGIN
 definition:=rtrim(pg_get_viewdef('game_character_hazard_revision_chain'::regclass,true),E';\n ');
 IF position('game_lynda_wedding_receipts' IN definition)>0 THEN RAISE EXCEPTION 'Wedding edge already installed';END IF;
 EXECUTE 'CREATE OR REPLACE VIEW game_character_hazard_revision_chain WITH (security_invoker=true) AS '
 ||definition||' UNION ALL SELECT character_id,original_revision,committed_revision,level_before,level_after,'
 ||'experience_before,experience_after,profile_revision,ruleset_revision,content_revision,simulation_revision,'
 ||'evidence_revision,declaration_revision,policy_revision,reward_revision FROM game_lynda_wedding_receipts';
END $wedding_chain$;
CREATE CONSTRAINT TRIGGER game_lynda_wedding_character_chain AFTER INSERT ON game_lynda_wedding_receipts
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_character_progression_consistency_guard();

-- Read-only permanent fact ancestry. Unlike current write admission this is
-- valid across reconnect and Character lifecycle changes; immutable reciprocal
-- consent and its exact Account/Character/source-event binding remain required.
CREATE FUNCTION game_lynda_wedding_grant_historical(p_account UUID,p_key TEXT,p_revision TEXT,p_character UUID,p_event BYTEA)
 RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT p_key='oteryn:appearance-grant/npc/lynda/newly_wed/base'
 AND p_revision='crystal-201189f-npc-cosmetics-v1'
 AND EXISTS(SELECT 1 FROM game_lynda_wedding_receipts accepted
 JOIN game_lynda_wedding_receipts proposal ON proposal.transaction_id=accepted.prior_proposal_id
 WHERE accepted.operation='accept' AND proposal.operation='propose'
 AND proposal.character_id=accepted.partner_character_id AND proposal.partner_character_id=accepted.character_id
 AND proposal.world_id=accepted.world_id AND proposal.actor_account=accepted.partner_account AND proposal.partner_account=accepted.actor_account
 AND p_event=uuid_send(accepted.transaction_id)||uuid_send(p_character)
 AND ((p_character=accepted.character_id AND p_account=accepted.actor_account)
   OR(p_character=accepted.partner_character_id AND p_account=accepted.partner_account)))
$$;
DO $history_path$ BEGIN
 EXECUTE format('ALTER FUNCTION game_lynda_wedding_grant_historical(uuid,text,text,uuid,bytea) SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $history_path$;
REVOKE ALL ON FUNCTION game_lynda_wedding_grant_historical(uuid,text,text,uuid,bytea) FROM PUBLIC,oteryn_game_control;
GRANT EXECUTE ON FUNCTION game_lynda_wedding_grant_historical(uuid,text,text,uuid,bytea) TO oteryn_game_runtime;

-- SRV7_SOURCE_COMPOSITION: npc-cash-audit-shape.sql
-- Incremental 0993 amendment; the full NPC cash template also owns these bytes.
-- The old generic, Gem, NPC trade and all other audit-shape ceilings are intact.
DO $npc_cash_audit_shape$
DECLARE definition TEXT; at INTEGER; arm TEXT;
BEGIN
 definition:=pg_get_functiondef('game_item_audit_envelope_size_proven()'::regprocedure);
 IF strpos(definition,'SRV7_CLOSED_NPC_CASH_AUDIT')>0 THEN RAISE EXCEPTION 'NPC cash audit shape already installed';END IF;
 arm:=$arm$
 -- SRV7_CLOSED_NPC_CASH_AUDIT: source-qualified 508-leaf fee proof only.
 IF NEW.created_xact_id=pg_current_xact_id()
  AND octet_length(NEW.envelope)<=262144
  AND EXISTS(SELECT 1 FROM game_item_fee_burns fee
   JOIN game_npc_fee_cash_records cash USING(transaction_id)
   WHERE fee.transaction_id=NEW.transaction_id AND fee.event_id=NEW.event_id
    AND fee.cause_kind IN(473,474) AND fee.created_xact_id=pg_current_xact_id()
    AND cash.created_xact_id=pg_current_xact_id() AND cash.character_id=fee.character_id
    AND cash.world_id=fee.world_id AND fee.envelope_sha256=NEW.envelope_sha256
    AND NEW.envelope_sha256=sha256(NEW.envelope)) THEN
  PERFORM game_npc_cash_complete(NEW.transaction_id);
  RETURN NULL;
 END IF;
$arm$;
 at:=regexp_instr(definition,E'\\mBEGIN\\M',1,1,0,'i');
 IF at=0 THEN RAISE EXCEPTION 'NPC cash audit shape boundary changed';END IF;
 EXECUTE overlay(definition placing E'BEGIN\n'||arm from at for 5);
END $npc_cash_audit_shape$;

-- SRV7_SOURCE_COMPOSITION: npc-cash-item-change-proof.sql
-- New closed fee473/474 owns its exact current-XID physical coin mutation.
-- Every older Item/House/Gem proof arm remains byte-for-byte below this arm.
DO $npc_cash_item_change$
DECLARE definition TEXT;at INTEGER;arm TEXT;
BEGIN
 definition:=pg_get_functiondef('game_item_instance_change_proven()'::regprocedure);
 IF strpos(definition,'SRV7_CLOSED_NPC_COIN_CHANGE')>0 THEN RAISE EXCEPTION 'NPC coin change proof already installed';END IF;
 arm:=$arm$
 -- SRV7_CLOSED_NPC_COIN_CHANGE: choose by the closed cause, never by a
 -- nullable proof predicate that could fall through to another owner.
 IF EXISTS(SELECT 1 FROM game_item_fee_burns fee
  WHERE fee.transaction_id=NEW.last_transaction_id AND fee.cause_kind IN(473,474)
   AND fee.created_xact_id=pg_current_xact_id()) THEN
  PERFORM game_npc_cash_complete(NEW.last_transaction_id);
  IF NOT EXISTS(SELECT 1 FROM game_npc_fee_cash_records cash,
    LATERAL jsonb_array_elements(cash.inputs) line
   WHERE cash.transaction_id=NEW.last_transaction_id AND cash.created_xact_id=pg_current_xact_id()
    AND line->>'item'=OLD.item_instance_id::text AND line->'before'=to_jsonb(OLD)
    AND (line->>'burned')::bigint>0
    AND NEW.item_instance_id=OLD.item_instance_id AND NEW.world_id=OLD.world_id
    AND NEW.quantity=OLD.quantity-(line->>'burned')::bigint
    AND NEW.lifecycle=CASE WHEN NEW.quantity=0 THEN 2 ELSE 1 END
    AND NEW.state_revision=OLD.state_revision+1
    AND (to_jsonb(NEW)-ARRAY['quantity','lifecycle','last_transaction_id','state_revision'])
       =(to_jsonb(OLD)-ARRAY['quantity','lifecycle','last_transaction_id','state_revision'])
    AND EXISTS(SELECT 1 FROM game_item_instances actual
      WHERE actual.item_instance_id=NEW.item_instance_id AND to_jsonb(actual)=to_jsonb(NEW))) THEN
   RAISE EXCEPTION 'NPC coin update lacks its exact sealed before/final successor' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
 END IF;
$arm$;
 at:=regexp_instr(definition,E'\\mBEGIN\\M',1,1,0,'i');
 IF at=0 THEN RAISE EXCEPTION 'NPC item change boundary changed';END IF;
 EXECUTE overlay(definition placing E'BEGIN\n'||arm from at for 5);
END $npc_cash_item_change$;

-- Six finite source-owned quantity-one NonStackable backpack outputs.
-- Mature RewardClaim MINT remains the only Item/custody/audit writer.
ALTER TABLE game_npc_source_context ADD COLUMN output_transaction_id UUID;
CREATE TABLE game_npc_source_item_outputs(
 parent_transaction_id UUID PRIMARY KEY REFERENCES game_npc_cosmetic_receipts(transaction_id),
 mint_transaction_id UUID NOT NULL UNIQUE REFERENCES game_reward_claim_mint_receipts(transaction_id),
 character_id UUID NOT NULL REFERENCES game_character_roots(character_id),
 source_key TEXT NOT NULL,item_instance_id UUID NOT NULL UNIQUE REFERENCES game_item_instances(item_instance_id),
 source_item_id INTEGER NOT NULL CHECK(source_item_id IN(5957,895,894,39546)),
 created_xact_id XID8 NOT NULL DEFAULT pg_current_xact_id()
);
REVOKE ALL ON game_npc_source_item_outputs FROM PUBLIC;
GRANT SELECT ON game_npc_source_item_outputs TO oteryn_game_runtime;
CREATE INDEX game_npc_source_item_outputs_character_xact ON game_npc_source_item_outputs(character_id,created_xact_id);
CREATE TRIGGER game_npc_source_output_immutable BEFORE UPDATE OR DELETE ON game_npc_source_item_outputs FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_npc_source_output_no_truncate BEFORE TRUNCATE ON game_npc_source_item_outputs FOR EACH STATEMENT EXECUTE FUNCTION game_character_reject_truncate();
CREATE FUNCTION game_npc_source_output_id(p_source TEXT) RETURNS INTEGER LANGUAGE sql IMMUTABLE AS $$
 SELECT CASE p_source
 WHEN 'oteryn:npc-cosmetic/sandra/belt-ticket-283' THEN 5957
 WHEN 'oteryn:npc-cosmetic/sandra/belt-ticket-284' THEN 5957
 WHEN 'oteryn:npc-cosmetic/sandra/belt-ticket-285' THEN 5957
 WHEN 'oteryn:npc-cosmetic/bozo/jester-addon-1' THEN 895
 WHEN 'oteryn:npc-cosmetic/bozo/jester-addon-2' THEN 894
 WHEN 'oteryn:npc-cosmetic/gnomadness/ripptor-prize' THEN 39546 END
$$;
CREATE FUNCTION game_npc_source_bind_output(p_mint UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_npc_source_context%ROWTYPE;reservation game_reward_claim_mint_reservations%ROWTYPE;expected_id INTEGER;
BEGIN
 SELECT * INTO c FROM game_npc_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 SELECT * INTO reservation FROM game_reward_claim_mint_reservations WHERE transaction_id=p_mint;
 expected_id:=game_npc_source_output_id(c.source_key);
 IF c.npc_transaction_id IS NULL OR c.captured OR c.output_transaction_id IS NOT NULL OR expected_id IS NULL
  OR p_mint IS NULL OR p_mint=c.npc_transaction_id OR p_mint IS NOT DISTINCT FROM c.cost_transaction_id OR p_mint IS NOT DISTINCT FROM c.fee_transaction_id
  OR game_npc_source_effect_current(c.npc_transaction_id,c.source_key,jsonb_build_object('kind','mint_item','item',expected_id,'count',1)) IS DISTINCT FROM TRUE
  OR reservation.transaction_id IS NULL OR NOT EXISTS(SELECT 1 FROM game_reward_claim_mint_reservations fresh_reservation WHERE fresh_reservation.transaction_id=p_mint AND fresh_reservation.xmin=pg_current_xact_id()::xid)
  OR reservation.character_id IS DISTINCT FROM c.character_id OR reservation.game_session_id IS DISTINCT FROM c.game_session_id OR reservation.command_id IS DISTINCT FROM c.command_id
  OR reservation.world_id IS DISTINCT FROM c.world_id OR reservation.channel_id IS DISTINCT FROM c.channel_id
  OR reservation.claim_family IS DISTINCT FROM 'NpcCosmetic'
  OR reservation.claim_revision_ref IS DISTINCT FROM 'npc-source-program.'||encode(c.program_sha256,'hex')
  OR reservation.claim_production_key IS DISTINCT FROM 'oteryn:npc-source-output.'||c.npc_transaction_id::text
  OR reservation.work_units_used<>1 THEN
  RAISE EXCEPTION 'NPC output requires one current reserved native MINT' USING ERRCODE='23514';END IF;
 UPDATE game_npc_source_context SET output_transaction_id=p_mint WHERE backend_pid=pg_backend_pid();
END $$;
CREATE FUNCTION game_npc_source_output_namespace() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_npc_source_context%ROWTYPE;expected_id INTEGER;actual_mint UUID;
BEGIN
 IF NEW.claim_production_key NOT LIKE 'oteryn:npc-source-output.%' THEN RETURN NEW;END IF;
 SELECT * INTO c FROM game_npc_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id();
 expected_id:=game_npc_source_output_id(c.source_key);
 -- All three tables share the claim/Character fields. Access the differently
 -- named transaction field only inside its exact row-type branch.
 IF TG_TABLE_NAME='game_reward_claims' THEN actual_mint:=NEW.claimed_transaction_id;
 ELSE actual_mint:=NEW.transaction_id;END IF;
 IF c.npc_transaction_id IS NULL OR expected_id IS NULL
  OR NEW.claim_family IS DISTINCT FROM 'NpcCosmetic'
  OR NEW.claim_revision_ref IS DISTINCT FROM 'npc-source-program.'||encode(c.program_sha256,'hex') OR NEW.character_id IS DISTINCT FROM c.character_id
  OR NEW.claim_production_key IS DISTINCT FROM 'oteryn:npc-source-output.'||c.npc_transaction_id::text
  OR game_npc_source_effect_current(c.npc_transaction_id,c.source_key,jsonb_build_object('kind','mint_item','item',expected_id,'count',1)) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'NPC output namespace requires its private current source' USING ERRCODE='23514';END IF;
 IF TG_TABLE_NAME<>'game_reward_claim_mint_reservations' THEN
  IF actual_mint IS DISTINCT FROM c.output_transaction_id OR NOT c.captured
   OR game_npc_source_parent_current(c.npc_transaction_id,c.source_key) IS DISTINCT FROM TRUE THEN
   RAISE EXCEPTION 'NPC output requires the exact immutable parent' USING ERRCODE='23514';END IF;
 END IF;
 RETURN NEW;
END $$;
DO $namespace$ DECLARE relation TEXT;BEGIN
 FOREACH relation IN ARRAY ARRAY['game_reward_claim_mint_reservations','game_reward_claim_mint_receipts','game_reward_claims'] LOOP
  EXECUTE format('CREATE TRIGGER game_npc_source_output_namespace BEFORE INSERT ON %I FOR EACH ROW EXECUTE FUNCTION game_npc_source_output_namespace()',relation);
 END LOOP;
END $namespace$;
CREATE FUNCTION game_npc_source_output_capture(p_parent UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c game_npc_source_context%ROWTYPE;minted game_reward_claim_mint_receipts%ROWTYPE;item game_item_instances%ROWTYPE;expected_id INTEGER;
BEGIN
 SELECT * INTO c FROM game_npc_source_context WHERE backend_pid=pg_backend_pid() AND transaction_xid=pg_current_xact_id() AND npc_transaction_id=p_parent;
 SELECT * INTO minted FROM game_reward_claim_mint_receipts WHERE transaction_id=c.output_transaction_id;
 SELECT * INTO item FROM game_item_instances WHERE item_instance_id=minted.item_instance_id;
 expected_id:=game_npc_source_output_id(c.source_key);
 IF expected_id IS NULL OR game_npc_source_parent_current(p_parent,c.source_key) IS DISTINCT FROM TRUE
  OR minted.transaction_id IS NULL OR minted.created_xact_id IS DISTINCT FROM pg_current_xact_id()
  OR minted.character_id IS DISTINCT FROM c.character_id OR minted.game_session_id IS DISTINCT FROM c.game_session_id OR minted.command_id IS DISTINCT FROM c.command_id
  OR minted.quantity<>1 OR item.quantity<>1 OR item.lifecycle<>1
  OR item.definition_family IS DISTINCT FROM 'Item' OR item.definition_production_key IS DISTINCT FROM 'oteryn:item.tibia.i'||expected_id
  OR item.definition_revision_ref IS DISTINCT FROM 'definition-r1' OR item.minted_transaction_id IS DISTINCT FROM minted.transaction_id
  OR NOT EXISTS(SELECT 1 FROM game_item_container_entries actual_entry WHERE actual_entry.item_instance_id=item.item_instance_id
   AND actual_entry.character_id=c.character_id AND actual_entry.world_id=c.world_id AND actual_entry.parent_item_instance_id=minted.destination_parent_item_instance_id
   AND actual_entry.placement_ordinal=minted.destination_ordinal AND actual_entry.placed_transaction_id=minted.transaction_id) THEN
  RAISE EXCEPTION 'NPC output lacks its exact fresh native item and custody' USING ERRCODE='23514';END IF;
 INSERT INTO game_npc_source_item_outputs VALUES(p_parent,minted.transaction_id,c.character_id,c.source_key,item.item_instance_id,expected_id,pg_current_xact_id());
END $$;
DO $paths$ DECLARE signature TEXT;BEGIN
 FOREACH signature IN ARRAY ARRAY['game_npc_source_output_id(text)','game_npc_source_bind_output(uuid)','game_npc_source_output_namespace()','game_npc_source_output_capture(uuid)'] LOOP
  EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',signature,current_schema());
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',signature);
 END LOOP;
END $paths$;
GRANT EXECUTE ON FUNCTION game_npc_source_bind_output(UUID),game_npc_source_output_capture(UUID) TO oteryn_game_runtime;

CREATE FUNCTION game_npc_source_output_complete(p_parent UUID) RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT EXISTS(SELECT 1 FROM game_npc_source_context c
 JOIN game_npc_source_item_outputs output ON output.parent_transaction_id=c.npc_transaction_id
 JOIN game_reward_claim_mint_receipts mint ON mint.transaction_id=output.mint_transaction_id
 JOIN game_item_instances item ON item.item_instance_id=output.item_instance_id
 JOIN game_item_container_entries custody ON custody.item_instance_id=item.item_instance_id
 JOIN game_reward_claims claim ON claim.claimed_transaction_id=mint.transaction_id
 WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id() AND c.npc_transaction_id=p_parent
 AND game_npc_source_parent_current(p_parent,c.source_key)
 AND game_npc_source_effect_current(p_parent,c.source_key,jsonb_build_object('kind','mint_item','item',output.source_item_id,'count',1))
 AND output.source_item_id=game_npc_source_output_id(c.source_key) AND output.source_key=c.source_key
 AND output.character_id=c.character_id AND output.created_xact_id=pg_current_xact_id()
 AND mint.transaction_id=c.output_transaction_id AND mint.created_xact_id=pg_current_xact_id()
 AND mint.game_session_id=c.game_session_id AND mint.command_id=c.command_id AND mint.character_id=c.character_id
 AND mint.item_instance_id=item.item_instance_id AND mint.quantity=1
 AND mint.claim_family='NpcCosmetic' AND mint.claim_production_key='oteryn:npc-source-output.'||p_parent::text
 AND mint.claim_revision_ref='npc-source-program.'||encode(c.program_sha256,'hex')
 AND claim.character_id=c.character_id AND claim.claim_family=mint.claim_family AND claim.claim_production_key=mint.claim_production_key
 AND claim.claim_revision_ref=mint.claim_revision_ref AND claim.next_allowed_at IS NULL
 AND item.world_id=c.world_id AND item.definition_family='Item'
 AND item.definition_production_key='oteryn:item.tibia.i'||output.source_item_id AND item.definition_revision_ref='definition-r1'
 AND item.quantity=1 AND item.lifecycle=1 AND item.state_revision=1 AND item.last_transaction_id IS NULL
 AND item.minted_transaction_id=mint.transaction_id
 AND custody.character_id=c.character_id AND custody.world_id=c.world_id
 AND custody.parent_item_instance_id=mint.destination_parent_item_instance_id AND custody.placement_ordinal=mint.destination_ordinal
 AND custody.placed_transaction_id=mint.transaction_id)
$$;
CREATE FUNCTION game_npc_source_output_required() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF NEW.program_sha256 IS NOT NULL AND EXISTS(SELECT 1 FROM game_npc_source_policies policy,
  LATERAL jsonb_array_elements(policy.effects) effect WHERE policy.program_sha256=NEW.program_sha256
  AND policy.source_key=NEW.source_key AND effect.value->>'kind'='mint_item') THEN
  IF game_npc_source_output_complete(NEW.transaction_id) IS DISTINCT FROM TRUE THEN
   RAISE EXCEPTION 'NPC physical reward requires its same-transaction native MINT child' USING ERRCODE='23514';END IF;
 END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_npc_source_output_required AFTER INSERT ON game_npc_cosmetic_receipts
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_source_output_required();
CREATE FUNCTION game_npc_source_output_successor() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE item_id UUID;parent_id UUID;
BEGIN
 IF TG_OP='DELETE' THEN item_id:=OLD.item_instance_id;ELSE item_id:=NEW.item_instance_id;END IF;
 FOR parent_id IN SELECT output.parent_transaction_id FROM game_npc_source_item_outputs output
  WHERE output.item_instance_id=item_id AND output.created_xact_id=pg_current_xact_id() LOOP
  IF game_npc_source_output_complete(parent_id) IS DISTINCT FROM TRUE THEN
   RAISE EXCEPTION 'NPC physical reward lost its exact native successor' USING ERRCODE='23514';END IF;
 END LOOP;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_npc_source_output_successor AFTER INSERT OR UPDATE OR DELETE ON game_item_instances
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_source_output_successor();
CREATE CONSTRAINT TRIGGER game_npc_source_output_successor AFTER INSERT OR UPDATE OR DELETE ON game_item_container_entries
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_source_output_successor();
CREATE CONSTRAINT TRIGGER game_npc_source_output_successor AFTER INSERT ON game_npc_source_item_outputs
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_source_output_successor();
CREATE FUNCTION game_npc_source_output_reservation_complete() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE parent_id UUID;
BEGIN
 IF NEW.claim_production_key NOT LIKE 'oteryn:npc-source-output.%' THEN RETURN NULL;END IF;
 SELECT c.npc_transaction_id INTO parent_id FROM game_npc_source_context c
 WHERE c.backend_pid=pg_backend_pid() AND c.transaction_xid=pg_current_xact_id() AND c.output_transaction_id=NEW.transaction_id;
 IF parent_id IS NULL OR game_npc_source_output_complete(parent_id) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'NPC physical reward cannot leave an orphan reservation' USING ERRCODE='23514';END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER game_npc_source_output_reservation_complete AFTER INSERT ON game_reward_claim_mint_reservations
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION game_npc_source_output_reservation_complete();
DO $completion_paths$ DECLARE signature TEXT;BEGIN
 FOREACH signature IN ARRAY ARRAY['game_npc_source_output_complete(uuid)','game_npc_source_output_required()',
 'game_npc_source_output_successor()','game_npc_source_output_reservation_complete()'] LOOP
 EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,%I,pg_temp',signature,current_schema());
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,oteryn_game_runtime,oteryn_game_control',signature);
 END LOOP;
END $completion_paths$;

-- Closed NPC coin custody indexes a successful full proof once per statement.
-- All29 existing footprint invalidations delete the parent memo and cascade
-- these tuples. These rows grant no authority without the fresh full-proof call.
CREATE TABLE game_npc_cash_verified_inputs(
 backend_pid INTEGER NOT NULL,fee_transaction_id UUID NOT NULL,item_instance_id UUID NOT NULL,
 transaction_xid XID8 NOT NULL,world_id UUID NOT NULL,parent_item_instance_id UUID,
 placement_ordinal NUMERIC NOT NULL,surface SMALLINT NOT NULL CHECK(surface IN(1,2,3)),
 slot SMALLINT NOT NULL,quantity_before BIGINT NOT NULL CHECK(quantity_before>0),
 burned BIGINT NOT NULL CHECK(burned>=0 AND burned<=quantity_before),
 coin_key TEXT NOT NULL,coin_worth BIGINT NOT NULL CHECK(coin_worth IN(1,100,10000)),
 item_before JSONB NOT NULL,item_after JSONB NOT NULL,
 PRIMARY KEY(backend_pid,fee_transaction_id,item_instance_id),
 FOREIGN KEY(backend_pid,fee_transaction_id) REFERENCES game_npc_cash_verified(backend_pid,fee_transaction_id) ON DELETE CASCADE
);
REVOKE ALL ON game_npc_cash_verified_inputs FROM PUBLIC,oteryn_game_runtime,oteryn_game_control;

DO $indexed_custody_capture$ DECLARE definition TEXT;marker TEXT;capture TEXT;BEGIN
 definition:=pg_get_functiondef('game_npc_cash_complete(uuid)'::regprocedure);
 marker:='SET transaction_xid=EXCLUDED.transaction_xid,statement_started=EXCLUDED.statement_started;';
 IF strpos(definition,marker)=0 OR strpos(definition,'game_npc_cash_verified_inputs')>0 THEN
  RAISE EXCEPTION 'NPC cash proof indexed-capture boundary changed';END IF;
 capture:=$capture$
 -- Index exact sealed custody facts only after every physical and source proof.
 DELETE FROM game_npc_cash_verified_inputs WHERE backend_pid=pg_backend_pid() AND fee_transaction_id=p_transaction;
 INSERT INTO game_npc_cash_verified_inputs(backend_pid,fee_transaction_id,item_instance_id,transaction_xid,world_id,
  parent_item_instance_id,placement_ordinal,surface,slot,quantity_before,burned,coin_key,coin_worth,item_before,item_after)
 SELECT pg_backend_pid(),p_transaction,(input->>'item')::uuid,pg_current_xact_id(),r.world_id,
  (input->>'parent')::uuid,(input->>'ordinal')::numeric,(input->>'surface')::smallint,(input->>'slot')::smallint,
  (input->'before'->>'quantity')::bigint,(input->>'burned')::bigint,input->'before'->>'definition_production_key',
  game_item_coin_worth(input->'before'->>'definition_production_key'),input->'before',
  (SELECT to_jsonb(actual) FROM game_item_instances actual WHERE actual.item_instance_id=(input->>'item')::uuid)
 FROM jsonb_array_elements(r.inputs) input;
$capture$;
 EXECUTE replace(definition,marker,marker||capture);
END $indexed_custody_capture$;

CREATE FUNCTION game_npc_cash_nested_delete_proven(p_item UUID,p_world UUID,p_parent UUID,p_ordinal NUMERIC)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE fee UUID;
BEGIN
 -- Select by actual closed fee cause, before any nullable proof predicate.
 SELECT f.transaction_id INTO fee FROM game_item_instances i JOIN game_item_fee_burns f ON f.transaction_id=i.last_transaction_id
 WHERE i.item_instance_id=p_item AND f.cause_kind IN(473,474) AND f.created_xact_id=pg_current_xact_id();
 IF NOT FOUND THEN RAISE EXCEPTION 'NPC nested custody requires its exact closed current fee' USING ERRCODE='23514';END IF;
 -- This ALWAYS reproves the current source/parent/Root; a private memo only
 -- eliminates repeated physical scans after that independently fresh admission.
 PERFORM game_npc_cash_complete(fee);
 IF NOT EXISTS(SELECT 1 FROM game_npc_cash_verified_inputs proof
  JOIN game_npc_cash_verified memo USING(backend_pid,fee_transaction_id)
  JOIN game_item_instances actual ON actual.item_instance_id=proof.item_instance_id
  WHERE proof.backend_pid=pg_backend_pid() AND proof.fee_transaction_id=fee AND proof.item_instance_id=p_item
  AND proof.transaction_xid=pg_current_xact_id() AND memo.transaction_xid=pg_current_xact_id()
  AND memo.statement_started=statement_timestamp() AND proof.world_id=p_world AND actual.world_id=p_world
  AND proof.surface=2 AND proof.parent_item_instance_id=p_parent AND proof.placement_ordinal=p_ordinal
  AND proof.burned=proof.quantity_before AND proof.burned>0
  AND actual.definition_family='Item' AND actual.definition_production_key=proof.coin_key
  AND game_item_coin_worth(actual.definition_production_key)=proof.coin_worth
  AND actual.last_transaction_id=fee AND actual.quantity=0 AND actual.lifecycle=2) THEN
  RAISE EXCEPTION 'NPC nested delete lacks its exact sealed OLD custody, full burn and coin class' USING ERRCODE='23514';END IF;
END $$;
ALTER FUNCTION game_npc_cash_nested_delete_proven(uuid,uuid,uuid,numeric) SET search_path=pg_catalog,public,pg_temp;
REVOKE ALL ON FUNCTION game_npc_cash_nested_delete_proven(uuid,uuid,uuid,numeric) FROM PUBLIC,oteryn_game_control;
GRANT EXECUTE ON FUNCTION game_npc_cash_nested_delete_proven(uuid,uuid,uuid,numeric) TO oteryn_game_runtime;

DO $indexed_custody_guard$ DECLARE definition TEXT;old TEXT;replacement TEXT;BEGIN
 definition:=pg_get_functiondef('game_item_nested_entry_proven()'::regprocedure);
 old:=$old$
 IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM game_npc_fee_cash_records r,LATERAL jsonb_array_elements(r.inputs) l
  WHERE r.created_xact_id=pg_current_xact_id() AND r.world_id=OLD.world_id AND (l->>'surface')::int=2 AND (l->>'item')::uuid=OLD.item_instance_id
   AND (l->>'parent')::uuid=OLD.parent_item_instance_id AND (l->>'ordinal')::numeric=OLD.placement_ordinal AND (l->>'burned')::bigint=(l->'before'->>'quantity')::bigint) THEN
  PERFORM game_npc_cash_complete(r.transaction_id) FROM game_npc_fee_cash_records r,LATERAL jsonb_array_elements(r.inputs) l
   WHERE r.created_xact_id=pg_current_xact_id() AND (l->>'item')::uuid=OLD.item_instance_id; RETURN NULL;
 END IF;
$old$;
 replacement:=$replacement$
 IF TG_OP='DELETE' AND EXISTS(SELECT 1 FROM game_item_instances i JOIN game_item_fee_burns fee ON fee.transaction_id=i.last_transaction_id
  WHERE i.item_instance_id=OLD.item_instance_id AND fee.cause_kind IN(473,474) AND fee.created_xact_id=pg_current_xact_id()) THEN
  PERFORM game_npc_cash_nested_delete_proven(OLD.item_instance_id,OLD.world_id,OLD.parent_item_instance_id,OLD.placement_ordinal);
  RETURN NULL;
 END IF;
$replacement$;
 IF strpos(definition,old)=0 THEN RAISE EXCEPTION 'NPC nested exact custody arm changed';END IF;
 EXECUTE replace(definition,old,replacement);
END $indexed_custody_guard$;

CREATE FUNCTION game_npc_cash_item_change_proven(p_before JSONB,p_after JSONB)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE fee UUID;
BEGIN
 SELECT f.transaction_id INTO fee FROM game_item_fee_burns f
 WHERE f.transaction_id=(p_after->>'last_transaction_id')::uuid AND f.cause_kind IN(473,474)
 AND f.created_xact_id=pg_current_xact_id();
 IF NOT FOUND THEN RAISE EXCEPTION 'NPC item change requires its exact current closed fee' USING ERRCODE='23514';END IF;
 PERFORM game_npc_cash_complete(fee);
 IF NOT EXISTS(SELECT 1 FROM game_npc_cash_verified_inputs proof
  JOIN game_npc_cash_verified memo USING(backend_pid,fee_transaction_id)
  JOIN game_item_instances actual ON actual.item_instance_id=proof.item_instance_id
  WHERE proof.backend_pid=pg_backend_pid() AND proof.fee_transaction_id=fee
  AND proof.item_instance_id=(p_before->>'item_instance_id')::uuid
  AND proof.transaction_xid=pg_current_xact_id() AND memo.transaction_xid=pg_current_xact_id()
  AND memo.statement_started=statement_timestamp() AND proof.burned>0
  AND proof.item_before=p_before AND proof.item_after=p_after AND to_jsonb(actual)=p_after
  AND actual.world_id=proof.world_id AND actual.definition_family='Item'
  AND actual.definition_production_key=proof.coin_key AND game_item_coin_worth(actual.definition_production_key)=proof.coin_worth
  AND actual.last_transaction_id=fee) THEN
  RAISE EXCEPTION 'NPC item change lacks its exact complete sealed OLD/NEW/class/world snapshot' USING ERRCODE='23514';END IF;
END $$;
ALTER FUNCTION game_npc_cash_item_change_proven(jsonb,jsonb) SET search_path=pg_catalog,public,pg_temp;
REVOKE ALL ON FUNCTION game_npc_cash_item_change_proven(jsonb,jsonb) FROM PUBLIC,oteryn_game_control;
GRANT EXECUTE ON FUNCTION game_npc_cash_item_change_proven(jsonb,jsonb) TO oteryn_game_runtime;

-- Replace only the already closed NPC arm. All recovery/exclusivity and all
-- older mutation owners remain untouched; whole Row OLD/NEW equality is retained.
DO $indexed_item_change$ DECLARE definition TEXT;old TEXT;replacement TEXT;BEGIN
 definition:=pg_get_functiondef('game_item_instance_change_proven()'::regprocedure);
 old:=$old$
 IF EXISTS(SELECT 1 FROM game_item_fee_burns fee
  WHERE fee.transaction_id=NEW.last_transaction_id AND fee.cause_kind IN(473,474)
   AND fee.created_xact_id=pg_current_xact_id()) THEN
  PERFORM game_npc_cash_complete(NEW.last_transaction_id);
  IF NOT EXISTS(SELECT 1 FROM game_npc_fee_cash_records cash,
    LATERAL jsonb_array_elements(cash.inputs) line
   WHERE cash.transaction_id=NEW.last_transaction_id AND cash.created_xact_id=pg_current_xact_id()
    AND line->>'item'=OLD.item_instance_id::text AND line->'before'=to_jsonb(OLD)
    AND (line->>'burned')::bigint>0
    AND NEW.item_instance_id=OLD.item_instance_id AND NEW.world_id=OLD.world_id
    AND NEW.quantity=OLD.quantity-(line->>'burned')::bigint
    AND NEW.lifecycle=CASE WHEN NEW.quantity=0 THEN 2 ELSE 1 END
    AND NEW.state_revision=OLD.state_revision+1
    AND (to_jsonb(NEW)-ARRAY['quantity','lifecycle','last_transaction_id','state_revision'])
       =(to_jsonb(OLD)-ARRAY['quantity','lifecycle','last_transaction_id','state_revision'])
    AND EXISTS(SELECT 1 FROM game_item_instances actual
      WHERE actual.item_instance_id=NEW.item_instance_id AND to_jsonb(actual)=to_jsonb(NEW))) THEN
   RAISE EXCEPTION 'NPC coin update lacks its exact sealed before/final successor' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
 END IF;
$old$;
 replacement:=$replacement$
 IF EXISTS(SELECT 1 FROM game_item_fee_burns fee
  WHERE fee.transaction_id=NEW.last_transaction_id AND fee.cause_kind IN(473,474)
   AND fee.created_xact_id=pg_current_xact_id()) THEN
  PERFORM game_npc_cash_item_change_proven(to_jsonb(OLD),to_jsonb(NEW));
  RETURN NULL;
 END IF;
$replacement$;
 IF strpos(definition,old)=0 THEN RAISE EXCEPTION 'NPC exact item before/after arm changed';END IF;
 EXECUTE replace(definition,old,replacement);
END $indexed_item_change$;

