-- BEGIN SRV7 FINAL34 npc-quest-claim-projection
-- DRAFT finite source observations for AvarTar; no quest/chest reward is minted here.
-- The actual generic chest claim/MINT owner remains the only producer of value1.
CREATE FUNCTION game_npc_final_claim_projection(p_character UUID,p_track TEXT)
 RETURNS TABLE(source_value BIGINT,claim_transaction_id UUID) LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE claim_key TEXT; stored_ack BIGINT; actual_claim UUID;
BEGIN
 claim_key:=CASE p_track
  WHEN 'oteryn:quest-progress/quest/u7_24/the_annihilator/reward'
   THEN 'oteryn:reward-claim.quest.u7_24.the_annihilator.reward'
  WHEN 'oteryn:quest-progress/quest/u6_4/demon_helmet/rewards/demon_helmet'
   THEN 'oteryn:reward-claim.quest.u6_4.demon_helmet.rewards.demon_helmet'
  ELSE NULL END;
 IF claim_key IS NULL THEN RETURN;END IF;
 SELECT claim.claimed_transaction_id INTO actual_claim FROM game_reward_claims claim
 JOIN game_reward_claim_mint_receipts minted ON minted.transaction_id=claim.claimed_transaction_id
  AND minted.character_id=claim.character_id AND minted.claim_family=claim.claim_family
  AND minted.claim_production_key=claim.claim_production_key AND minted.claim_revision_ref=claim.claim_revision_ref
 WHERE claim.character_id=p_character AND claim.claim_family='RewardClaim' AND claim.claim_production_key=claim_key
 ORDER BY claim.claimed_transaction_id LIMIT 1;
 SELECT value INTO stored_ack FROM game_character_quest_tracks WHERE character_id=p_character AND track_key=p_track;
 IF actual_claim IS NULL THEN
  IF stored_ack IS NOT NULL THEN
   RAISE EXCEPTION 'Final cosmetic acknowledgement lacks actual chest claim' USING ERRCODE='23514';END IF;
  source_value:=-1;claim_transaction_id:=NULL;RETURN NEXT;RETURN;
 END IF;
 IF stored_ack IS NOT NULL AND stored_ack<>2 THEN
 RAISE EXCEPTION 'Invalid final cosmetic acknowledgement value' USING ERRCODE='23514';END IF;
 source_value:=CASE WHEN stored_ack=2 THEN 2 ELSE 1 END;
 claim_transaction_id:=actual_claim;
 RETURN NEXT;
END $$;
REVOKE ALL ON FUNCTION game_npc_final_claim_projection(UUID,TEXT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION game_npc_final_claim_projection(UUID,TEXT) TO oteryn_game_runtime;

-- Before integration, source Snapshot and private arm must BOTH use this exact
-- projection for the two known bindings. A first acknowledgement stores native
-- component initial(-1)->2 while its source observation is actual claim1->2;
-- the typed Quest child must seal the actual claim_transaction_id and reprove
-- this projection. It is not an arbitrary source_before/owner_before exception.

DO $claim_projection_path$ BEGIN
 EXECUTE format('ALTER FUNCTION game_npc_final_claim_projection(uuid,text) SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $claim_projection_path$;

-- The child admission arm calls this only for an expected, Node-sealed native
-- operation. It does not admit a source delta or child by itself.
CREATE FUNCTION game_npc_final_claim_projection_current(p_character UUID,p_source TEXT,
 p_track TEXT,p_claim UUID,p_source_before BIGINT,p_owner_before BIGINT)
 RETURNS BOOLEAN LANGUAGE sql SECURITY DEFINER AS $$
 SELECT p_claim IS NOT NULL AND p_source_before=1 AND p_owner_before=-1
 AND ((p_source='oteryn:npc-cosmetic/avar_tar/demon-base'
   AND p_track='oteryn:quest-progress/quest/u7_24/the_annihilator/reward')
  OR(p_source='oteryn:npc-cosmetic/avar_tar/demon-shield'
   AND p_track='oteryn:quest-progress/quest/u6_4/demon_helmet/rewards/demon_helmet'))
 AND NOT EXISTS(SELECT 1 FROM game_character_quest_tracks actual_track
   WHERE actual_track.character_id=p_character AND actual_track.track_key=p_track)
 AND EXISTS(SELECT 1 FROM game_npc_final_claim_projection(p_character,p_track) actual_claim
   WHERE actual_claim.source_value=1 AND actual_claim.claim_transaction_id=p_claim)
$$;
REVOKE ALL ON FUNCTION game_npc_final_claim_projection_current(UUID,TEXT,TEXT,UUID,BIGINT,BIGINT) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION game_npc_final_claim_projection_current(UUID,TEXT,TEXT,UUID,BIGINT,BIGINT) TO oteryn_game_runtime;
DO $claim_projection_current_path$ BEGIN
 EXECUTE format('ALTER FUNCTION game_npc_final_claim_projection_current(uuid,text,text,uuid,bigint,bigint) SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $claim_projection_current_path$;

-- END SRV7 FINAL34 npc-quest-claim-projection

-- BEGIN SRV7 FINAL34 npc-quest-observation
-- Source-qualified: preserve raw tracks for old source arm; derive only two chest-backed
-- source values independently, with no stored acknowledgement fabricated.
CREATE FUNCTION game_npc_quest_observed_tracks(p_character UUID,p_source TEXT,p_before JSONB)
 RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE values_actual JSONB:='{}';claims_actual JSONB:='{}';key TEXT;projected RECORD;
BEGIN
 IF p_source IN('oteryn:npc-cosmetic/avar_tar/demon-base','oteryn:npc-cosmetic/avar_tar/demon-shield','oteryn:npc-cosmetic/avar_tar/demon-helmet') THEN
  FOREACH key IN ARRAY ARRAY[
   'oteryn:quest-progress/quest/u7_24/the_annihilator/reward',
   'oteryn:quest-progress/quest/u6_4/demon_helmet/rewards/demon_helmet'] LOOP
   SELECT * INTO projected FROM game_npc_final_claim_projection(p_character,key);
   IF NOT FOUND THEN RAISE EXCEPTION 'Missing closed chest projection' USING ERRCODE='23514';END IF;
   values_actual:=values_actual||jsonb_build_object(key,projected.source_value);
   IF projected.claim_transaction_id IS NOT NULL THEN
    claims_actual:=claims_actual||jsonb_build_object(key,projected.claim_transaction_id::text);
   END IF;
  END LOOP;
 END IF;
 IF p_before->'quest_source_values' IS DISTINCT FROM values_actual
  OR p_before->'quest_claims' IS DISTINCT FROM claims_actual THEN
 RAISE EXCEPTION 'Final source observation lacks actual claim ancestry' USING ERRCODE='23514';END IF;
 RETURN (p_before->'tracks')||values_actual;
END $$;
REVOKE ALL ON FUNCTION game_npc_quest_observed_tracks(UUID,TEXT,JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION game_npc_quest_observed_tracks(UUID,TEXT,JSONB) TO oteryn_game_runtime;
DO $path$ BEGIN
 EXECUTE format('ALTER FUNCTION game_npc_quest_observed_tracks(uuid,text,jsonb) SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $path$;

-- END SRV7 FINAL34 npc-quest-observation

-- BEGIN SRV7 FINAL34 npc-quest-plan-seal
-- Source-qualified: foreign source writes stay outside generic writable_tracks authority.
CREATE TABLE game_npc_source_quest_policies(
 program_sha256 BYTEA NOT NULL,
 source_key TEXT NOT NULL,
 foreign_tracks JSONB NOT NULL CHECK(jsonb_typeof(foreign_tracks)='object'),
 PRIMARY KEY(program_sha256,source_key),
 FOREIGN KEY(program_sha256,source_key) REFERENCES game_npc_source_policies(program_sha256,source_key)
);
REVOKE ALL ON game_npc_source_quest_policies FROM PUBLIC,oteryn_game_runtime;
GRANT SELECT ON game_npc_source_quest_policies TO oteryn_game_runtime;
CREATE TRIGGER game_npc_source_quest_policy_immutable BEFORE UPDATE OR DELETE ON game_npc_source_quest_policies
 FOR EACH ROW EXECUTE FUNCTION game_character_immutable();
CREATE TRIGGER game_npc_source_quest_policy_no_truncate BEFORE TRUNCATE ON game_npc_source_quest_policies
 FOR EACH STATEMENT EXECUTE FUNCTION game_character_reject_truncate();

-- Called by the already authenticated Node arm, after that arm independently
-- checked the locked actual source observation. Each foreign write is covered
-- once by one exact Quest child; it never enters the generic parent row proof.
CREATE FUNCTION game_npc_quest_plan_valid(p_program BYTEA,p_source TEXT,p_character UUID,p_before JSONB,p_plan JSONB)
 RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE policy game_npc_source_quest_policies%ROWTYPE; plan_delta JSONB; rule JSONB; source_tracks JSONB;
BEGIN
 SELECT * INTO policy FROM game_npc_source_quest_policies WHERE program_sha256=p_program AND source_key=p_source;
 IF NOT FOUND THEN RETURN FALSE;END IF;
 source_tracks:=game_npc_quest_observed_tracks(p_character,p_source,p_before);
 IF jsonb_typeof(p_plan->'quest_changes') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_plan->'quest_children') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p_plan->'quest_noops') IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_plan->'quest_changes')<>(SELECT count(*) FROM jsonb_object_keys(policy.foreign_tracks))
 OR jsonb_array_length(p_plan->'quest_changes') NOT BETWEEN 1 AND 8
 OR jsonb_array_length(p_plan->'quest_children') NOT BETWEEN 0 AND 8
 OR jsonb_array_length(p_plan->'quest_noops')>8
 OR (SELECT count(DISTINCT value->>'key') FROM jsonb_array_elements(p_plan->'quest_noops'))<>jsonb_array_length(p_plan->'quest_noops')
 OR (SELECT count(DISTINCT value->>'key') FROM jsonb_array_elements(p_plan->'quest_changes'))<>jsonb_array_length(p_plan->'quest_changes')
 OR (SELECT count(DISTINCT value->>'quest') FROM jsonb_array_elements(p_plan->'quest_children'))<>jsonb_array_length(p_plan->'quest_children') THEN RETURN FALSE;END IF;
 FOR plan_delta IN SELECT value FROM jsonb_array_elements(p_plan->'quest_changes') LOOP
  rule:=policy.foreign_tracks->(plan_delta->>'key');
  IF rule IS NULL OR plan_delta->>'quest' IS DISTINCT FROM rule->>'quest'
   OR (plan_delta->>'before')::bigint IS DISTINCT FROM coalesce((source_tracks->>(plan_delta->>'key'))::bigint,-1)
   OR (plan_delta->>'after')::bigint IS DISTINCT FROM game_npc_source_expression(rule->'value',source_tracks,(p_before->>'now')::bigint)
   OR (SELECT count(*) FROM jsonb_array_elements(p_plan->'quest_children') child,
      LATERAL jsonb_array_elements(child->'changes') child_delta
      WHERE child->>'quest'=plan_delta->>'quest' AND child_delta->>'key'=plan_delta->>'key'
       AND child_delta->'source_before'=plan_delta->'before' AND child_delta->'after'=plan_delta->'after')
      +(SELECT count(*) FROM jsonb_array_elements(p_plan->'quest_noops') noop
       JOIN game_character_quest_tracks actual ON actual.character_id=p_character
        AND actual.track_key=noop->>'key' AND actual.quest_key=noop->>'quest'
        AND actual.value=(noop->>'value')::bigint
       WHERE noop->>'key'=plan_delta->>'key' AND noop->>'quest'=plan_delta->>'quest'
        AND noop->'value'=plan_delta->'before' AND noop->'value'=plan_delta->'after')<>1 THEN RETURN FALSE;END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_plan->'quest_noops') noop
  WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_plan->'quest_changes') source_delta
   JOIN game_character_quest_tracks actual ON actual.character_id=p_character
    AND actual.track_key=noop->>'key' AND actual.quest_key=noop->>'quest'
    AND actual.value=(noop->>'value')::bigint
   WHERE source_delta->>'key'=noop->>'key' AND source_delta->>'quest'=noop->>'quest'
    AND source_delta->'before'=noop->'value' AND source_delta->'after'=noop->'value')) THEN RETURN FALSE;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_plan->'quest_children') child,
  LATERAL jsonb_array_elements(child->'changes') child_delta
  WHERE child->'writes_state' IS DISTINCT FROM to_jsonb(child->>'quest'<>'oteryn:quest.npc_cosmetic_final_acquisition')
   OR child_delta->>'quest' IS DISTINCT FROM child->>'quest'
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_plan->'quest_changes') source_delta
    WHERE source_delta->>'key'=child_delta->>'key' AND source_delta->>'quest'=child->>'quest'
     AND source_delta->'before'=child_delta->'source_before' AND source_delta->'after'=child_delta->'after')) THEN RETURN FALSE;END IF;
 RETURN TRUE;
END $$;
REVOKE ALL ON FUNCTION game_npc_quest_plan_valid(BYTEA,TEXT,UUID,JSONB,JSONB) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION game_npc_quest_plan_valid(BYTEA,TEXT,UUID,JSONB,JSONB) TO oteryn_game_runtime;
DO $path$ BEGIN
 EXECUTE format('ALTER FUNCTION game_npc_quest_plan_valid(bytea,text,uuid,jsonb,jsonb) SET search_path=pg_catalog,%I,pg_temp',current_schema());
END $path$;

-- END SRV7 FINAL34 npc-quest-plan-seal

